ClinicalChunks.register("data/templates-038.js",[{"id":"templates-93a579546c024c3995f5","key":"v1-c9ccc21dfe2a3058|templates-93a579546c024c3995f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心律失常","category":"门诊病历模板","raw":{"name":"心律失常","category":"门诊病历模板","case":{"case_name":"门诊病历103","templates":{"主诉":"心慌、心悸反复发作2年余，再发加重1天。","现病史":"患者2年来反复出现发作性心慌、心悸，突发突止，每次持续5分钟至2小时，发作时伴头晕、胸闷、出汗，无黑矇及晕厥，与劳累、情绪激动、饮酒、饮咖啡相关。近24小时再发，持续不缓解，自觉脉搏快而不规则。既往有无心脏病、甲状腺功能亢进史：无心脏病及甲状腺功能亢进史。有无类似发作及明确诊断：既往有类似发作，曾诊断为阵发性心房颤动。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P126次/分（脉率），R22次/分，BP130/78mmHg。神志清楚，查体合作。心率138次/分，律绝对不齐，心音强弱不等，各瓣膜听诊区未闻及病理性杂音。双肺呼吸音清。双下肢无水肿。","辅助检查":"【必做】心电图（发作时捕捉心律）、24小时动态心电图（发作不频繁时评估）、血常规、电解质（尤其血钾）、甲状腺功能、心肌损伤标志物；【其他】超声心动图（基础心脏结构功能）、食管电生理检查（疑阵发性室上速时）。","初步诊断":"1. 心律失常（类型待心电图明确：期前收缩/阵发性室上速/心房颤动/室性心动过速等）\n（注：根据心电图类型治疗：良性期前收缩无症状者观察；室上速可刺激迷走神经或静注腺苷/维拉帕米；房颤予控制心室率（β受体阻滞剂）或转复+抗凝（CHA2DS2-VASc评估）；若为持续性室速、伴血流动力学不稳定（血压下降、意识改变）属危急，需立即电复律并急诊处理。）","处理方案":"【药物治疗】\n1. β受体阻滞剂（首选，控制心室率、减少早搏）：琥珀酸美托洛尔缓释片47.5mg qd，口服，长期维持；服药前监测心率，静息心率<55次/分或血压偏低时减量或停药。\n2. 抗心律失常药物（无器质性心脏病、心功能正常者）：盐酸普罗帕酮片150mg tid，口服，餐后服用；用药期间注意复查心电图，出现QRS明显增宽或新发传导阻滞即停药。\n3. 房颤抗凝治疗（CHA2DS2-VASc评分≥2分男性/≥3分女性，无出血禁忌者）：利伐沙班片15mg qd，口服，与餐同服；或华法林钠片1.5~3mg qd，口服，监测INR维持在2.0~3.0。\n4. 房颤伴快速心室率且β受体阻滞剂禁忌者：地尔硫䓬缓释片90mg qd，口服；合并心力衰竭者可选用地高辛片0.125~0.25mg qd，口服。\n\n【一般治疗及生活指导】\n1. 注意休息，保证充足睡眠，避免劳累、熬夜及剧烈运动；控制稳定后可在医师指导下进行散步、太极拳等中等强度有氧活动，运动中出现心悸、头晕应立即停止。\n2. 低盐低脂饮食，戒烟限酒，避免浓茶、咖啡等刺激性饮品，避免暴饮暴食及饱餐后立即活动。\n3. 保持情绪平稳，避免紧张、焦虑、暴怒等情绪波动；避免自行服用含麻黄碱的感冒药、抗组胺药等可能诱发或加重心律失常的药物。\n4. 定期监测血压、血糖、血脂，积极纠正低钾、低镁等电解质紊乱及甲状腺功能异常等诱因。\n\n【随诊要求】\n1. 开始服药后1~2周复诊，复查心电图、动态心电图及血压，评估疗效与心率、心律变化，据此调整剂量。\n2. 长期服药者每3~6个月复查心电图、电解质（血钾、血镁）、肝肾功能；服胺碘酮者加查甲状腺功能及胸片，服华法林者定期监测INR（目标2.0~3.0）。\n3. 治疗期间如出现心悸明显加重、胸闷、黑矇、晕厥、呼吸困难或胸痛，应立即急诊就诊，不可自行增减或停用抗心律失常药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":238,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bdcce2cc37194f1f5bb0654ded1f06bb40d9cb7cbd147b63ba7aaa5b0151fa15","pinyin":"xinlvshichang","initials":"xlsc","setting":"out","caseName":"门诊病历103","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历103",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-01ec126ea31195e4d908","key":"v1-c9ccc21dfe2a3058|templates-01ec126ea31195e4d908","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心力衰竭","category":"门诊病历模板","raw":{"name":"心力衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历104","templates":{"主诉":"活动后气短、乏力6月，加重伴夜间不能平卧5天。","现病史":"患者6月来渐出现活动后气短、乏力、双下肢水肿，夜间阵发性呼吸困难、需高枕卧位。近5天症状加重，轻微活动即气促，夜间不能平卧，伴咳嗽、咳白色泡沫痰，尿量减少，体重增加约3kg，无胸痛、无发热。既往有无冠心病、高血压、心脏瓣膜病、心肌病等病史：无冠心病、高血压、心脏瓣膜病及心肌病病史。平素用药：未规律服药。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P98次/分，R22次/分，BP130/80mmHg。神志清楚，半卧位，口唇无明显发绀。颈静脉怒张。双肺底可闻及中量湿啰音，无干啰音。心率98次/分，律齐，心音低钝，可闻及奔马律。腹软，肝肋下未触及肿大，双下肢中度凹陷性水肿。","辅助检查":"检查计划：患者6个月来活动后气短、乏力、双下肢水肿，近5天加重，轻微活动即气促，夜间不能平卧伴夜间阵发性呼吸困难，咳白色泡沫痰，尿量减少、体重增加约3kg，考虑心力衰竭（射血分数降低型，心功能NYHAⅢ级），入院即刻完善心电图检查了解心率、心律及有无心肌缺血、心律失常，为病因判断提供依据；查血常规检查排除感染、贫血所致气短、乏力，贫血可加重心衰症状；查心肌损伤标志物（肌钙蛋白）排除急性心肌损伤、心肌梗死所致心功能急剧恶化；完善BNP或NT-proBNP检查明确心衰诊断并评估严重程度及治疗效果；患者需规范使用利尿剂、ACEI/ARB/ARNI、β受体阻滞剂及螺内酯，均经肝肾代谢并影响电解质，完善肝肾功能检查排除肝肾功能不全并作为用药基线，查电解质（尤其血钾、血钠）排除电解质紊乱所致心律失常并指导利尿剂用量；完善胸部X线片了解心影大小、肺淤血及有无胸腔积液，评估容量负荷状态；查超声心动图了解左室射血分数、心脏结构、室壁运动及瓣膜功能，明确心衰类型及病因；患者低氧、不能平卧，必要时完善血气分析评估氧合及酸碱平衡状态，指导氧疗及无创通气；病情稳定后定期复查心电图、电解质、肾功能、BNP或NT-proBNP及体重，评估心功能及药物耐受情况。\n\n（检查清单）\n【必做】心电图、胸部X线片（心影增大、肺淤血或胸腔积液）、血常规、肝肾功能、电解质、BNP或NT-proBNP（升高提示心衰）、心肌损伤标志物；【影像学】超声心动图（左室射血分数、心脏结构及瓣膜功能）；【其他】血气分析（重症时）。","初步诊断":"1. 心力衰竭（射血分数降低型，心功能NYHAⅢ级）\n（注：规范治疗：利尿剂（呋塞米20~40mg）减轻容量负荷、ACEI、ARB或ARNI、β受体阻滞剂（美托洛尔或比索洛尔，病情稳定后）、螺内酯；改善生活方式（限盐限水、监测体重）；若为急性加重（端坐呼吸、粉红色泡沫痰、静息低氧）属急症，需立即急诊（吸氧、静脉呋塞米、必要时无创通气）并住院。）","处理方案":"【药物治疗】\n1. 血管紧张素受体脑啡肽酶抑制剂（ARNI）：沙库巴曲缬沙坦钠片50mg bid起始，每2-4周评估血压、肾功能及血钾后递增剂量，逐渐加量至目标剂量200mg bid（不耐受或血压偏低者减量至50-100mg bid维持）；不能耐受ARNI者改用血管紧张素转换酶抑制剂（ACEI）如培哚普利片4mg qd或缬沙坦胶囊80mg qd，长期维持。\n2. β受体阻滞剂：琥珀酸美托洛尔缓释片23.75mg qd起始，每2-4周根据静息心率（55-60次/分）及血压逐渐加倍，目标剂量95mg qd，长期维持（心率<55次/分、血压偏低或心衰加重时暂缓加量）。\n3. 醛固酮受体拮抗剂（MRA）：螺内酯片20mg qd，监测血钾及肾功能，血钾>5.0mmol/L或肌酐进行性升高时减量或停用。\n4. 钠-葡萄糖协同转运蛋白2抑制剂（SGLT2i）：达格列净片10mg qd，晨服，长期服用（eGFR<25ml/min/1.73m²或反复泌尿生殖系感染时慎用或停用）。\n【一般治疗及生活指导】\n1. 严格限盐限水：每日钠盐摄入<2g（约半个啤酒瓶盖），液体入量控制在1500-2000ml/d（夏季高温或大量出汗时可适当增加）；每日晨起排空二便后称体重并记录，3日内体重增加>2kg提示液体潴留，需及时就诊调整利尿剂。\n2. 饮食与生活方式：低盐低脂易消化饮食，少量多餐、避免过饱；戒烟、严格限酒；保证充足睡眠，避免劳累、情绪激动、用力排便及久蹲。\n3. 活动指导：病情稳定期（NYHA Ⅱ-Ⅲ级）在医生指导下进行低-中强度有氧运动（如散步、太极拳，每次20-30分钟，每周3-5次），以运动后不感明显气促为宜；急性加重期以卧床休息为主，取半卧位减轻肺淤血。\n4. 预防诱因与自我监测：注意保暖、预防呼吸道感染，流感季节可接种疫苗；每日监测血压、心率并记录，注意有无夜间阵发性呼吸困难、端坐呼吸、下肢水肿、乏力加重等，出现上述症状及时就医，切勿自行停用或调整上述药物。\n【随诊要求】\n1. 药物调整期（启动或加量ARNI、β受体阻滞剂、MRA期间）每2-4周门诊复诊1次，复查血压、心率、体重、血电解质（尤其血钾）、肾功能（肌酐、eGFR）及BNP/NT-proBNP，评估耐受性后再行剂量调整。\n2. 病情稳定后每1-3个月复诊1次，监测心功能（NYHA分级）、6分钟步行试验、超声心动图（每3-6个月评估LVEF及心脏结构）及药物不良反应。\n3. 出现静息或夜间呼吸困难加重、端坐呼吸、3日内体重增加>2kg、水肿明显加重、晕厥或心悸、血压<90/60mmHg或心率<50次/分、血钾异常等情况，应立即复诊或急诊就诊，不可等待预定复诊时间。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":239,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bafa46150de794b771f015633542f1c6b80844c0f389f11e4df0cbe59fb15e1b","pinyin":"xinlishuaijie","initials":"xlsj","setting":"out","caseName":"门诊病历104","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历104",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b84f969af0857e913f79","key":"v1-c9ccc21dfe2a3058|templates-b84f969af0857e913f79","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心肌炎","category":"门诊病历模板","raw":{"name":"心肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历105","templates":{"主诉":"发热、乏力后出现胸闷、心悸、气短3天。","现病史":"患者于7天前出现上呼吸道感染症状（咽痛、流涕、发热，体温最高38.5℃），3天前出现胸闷、心悸、气短，活动后加重，伴乏力、多汗、肌肉酸痛，无胸痛、无晕厥、无黑矇。有无近期病毒感染、剧烈运动、饮酒等诱因：有近期上呼吸道病毒感染史，无剧烈运动及饮酒史。今日来我院门诊就诊。发病以来精神差，食欲减退，睡眠欠佳。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分，R20次/分，BP110/70mmHg。神志清楚，查体合作。双肺呼吸音清，无干湿啰音。心率96次/分，律齐，心音低钝，可闻及第三心音，各瓣膜听诊区未闻及明显病理性杂音。腹软，双下肢无水肿。","辅助检查":"【必做】心肌损伤标志物（肌钙蛋白升高，为心肌损伤证据）、心肌酶（CK、CK-MB）、心电图（ST-T改变、心律失常、传导阻滞）、血常规、血沉、CRP、肝肾功能、电解质；【影像学】超声心动图（室壁运动异常、心功能）、心脏MRI（心肌水肿或纤维化，诊断重要手段）；【其他】病毒抗体或核酸检测、24小时动态心电图（心律失常监测）。","初步诊断":"1. 病毒性心肌炎（疑诊）\n（注：诊断需结合病毒感染前驱史+心肌损伤标志物升高+心电图或超声异常；治疗：绝对卧床休息（急性期3~6个月避免剧烈运动）、营养心肌（辅酶Q10、维生素C）、抗病毒及对症；合并心律失常、心衰或血流动力学不稳定者需住院甚至ICU监护；警惕暴发性心肌炎（急剧心衰、心源性休克）。）","处理方案":"【药物治疗】\n1. 营养心肌、改善心肌代谢（基础治疗）：辅酶Q10胶囊 10mg 口服 每日3次，连用4周；维生素C片 0.2g 口服 每日3次，连用2周。\n2. 抗病毒治疗（起病2周内、有上呼吸道感染或腹泻等前驱症状者）：流感病毒感染者予奥司他韦胶囊 75mg 口服 每日2次×5天；柯萨奇等肠道病毒感染者予利巴韦林片 0.3g 口服 每日3次×7天，用药期间监测血常规及肝肾功能。\n3. 抗心律失常、控制心率（合并频发室性早搏或静息心率明显增快者）：琥珀酸美托洛尔缓释片 23.75mg 口服 每日1次，根据静息心率及耐受性调整，目标静息心率55～70次/分，不低于55次/分；心功能不全者从小剂量开始，在医师指导下缓慢加量。\n\n【一般治疗及生活指导】\n1. 休息：急性期充分卧床休息至少2～4周，减少心脏做功、避免劳累；待症状消失、心电图及心肌酶恢复正常后逐步恢复日常活动。\n2. 活动：起病后6个月内避免剧烈运动、竞技性体育活动及重体力劳动；恢复期循序渐进增加活动量（如散步），以不诱发胸闷、心悸、乏力为度。\n3. 饮食：清淡、易消化、富含维生素及优质蛋白饮食，少量多餐，避免暴饮暴食；合并心功能不全者每日钠盐摄入＜5g，并限制液体入量。\n4. 禁忌：戒烟、戒酒，避免浓茶、咖啡等刺激性饮品；注意保暖、预防呼吸道感染，避免使用对心肌有损害的药物。\n\n【随诊要求】\n1. 急性期每2～4周复诊1次，复查心电图、心肌酶（CK-MB、肌钙蛋白I）、血常规及肝肾功能；1～3个月复查超声心动图，评估心腔大小、室壁运动及心功能恢复情况。\n2. 合并心律失常者于用药调整后及恢复期复查24小时动态心电图，评估早搏负荷及心率控制情况。\n3. 心电图、心肌酶及心功能恢复正常后仍需门诊随访至少3～6个月，观察远期预后；期间如出现胸痛加重、明显心悸、呼吸困难、晕厥或血压下降，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":240,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c99993554c1b994a85d2660b0a87d96462a5be17a2dbbc86dde9092c6b68f030","pinyin":"xinjiyan","initials":"xjy","setting":"out","caseName":"门诊病历105","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历105",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2eacaf4d87dea587cf30","key":"v1-c9ccc21dfe2a3058|templates-2eacaf4d87dea587cf30","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性胃肠炎","category":"门诊病历模板","raw":{"name":"急性胃肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历106","templates":{"主诉":"恶心、呕吐、腹痛伴腹泻1天。","现病史":"患者于1天前进食不洁食物后出现上腹及脐周阵发性疼痛，伴恶心、呕吐4次（为胃内容物），腹泻水样便10次/日，量中-多，无黏液脓血，无里急后重，伴发热，体温最高38.3℃，乏力、口干、尿量减少。有无同餐者相似症状：有同餐者出现类似腹痛、腹泻症状。自服药物（药名不详）效果欠佳。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.3℃，P96次/分，R20次/分，BP110/70mmHg。神志清楚，皮肤弹性稍差，口唇干。心肺听诊未闻及明显异常。腹平软，脐周及上腹部轻-中度压痛，无反跳痛及肌紧张，肠鸣音活跃。神经系统检查未见异常。","辅助检查":"【必做】血常规（白细胞及中性粒细胞比例、有无血液浓缩）、大便常规+隐血、电解质、肾功能（评估脱水及酸碱紊乱）；【其他】大便培养（疑细菌性痢疾或沙门菌等感染、腹泻持续或发热明显时）、呕吐物培养。","初步诊断":"1. 急性胃肠炎\n（注：治疗以补液为主：轻中度脱水口服补液盐，呕吐频繁或中重度脱水静脉补液（5%葡萄糖氯化钠、平衡盐，注意补钾）；对症：腹痛明显者山莨菪碱10mg im/po，呕吐明显者甲氧氯普胺10mg im；不常规用止泻药（感染性腹泻）；抗菌药物仅用于高热、脓血便或病原学明确时（左氧氟沙星0.5g qd或头孢类）；进食清淡易消化，注意手卫生及隔离。）","处理方案":"【药物治疗】\n1. 口服补液盐Ⅲ（博叶）：1袋溶于250ml温水中，少量多次口服；每次稀便后补充200-300ml，按口渴程度及尿量调节，直至腹泻停止，用于纠正及预防脱水、电解质紊乱。\n2. 蒙脱石散（思密达）3g tid，餐前口服，首剂加倍；与抗菌药物、益生菌间隔2小时以上服用，疗程3-5天，至大便成形后停药。\n3. 双歧杆菌三联活菌胶囊（培菲康）420mg tid，餐后凉温开水送服，与抗菌药物间隔2小时以上，疗程5-7天，重建肠道菌群。\n4. 若伴发热（≥38.5℃）或明显痉挛性腹痛，可加用山莨菪碱片5-10mg tid解痉止痛，症状缓解即停；若粪便镜检见白细胞明显增多或粪培养阳性（细菌性肠炎），加用诺氟沙星胶囊0.2g tid（或左氧氟沙星片0.5g qd）口服，疗程3-5天。\n\n【一般治疗及生活指导】\n1. 卧床休息，注意腹部保暖；暂停工作学习，症状缓解后逐步恢复日常活动。\n2. 饮食：急性期可暂禁食4-6小时，少量多次饮用温糖盐水或口服补液盐；恢复期进食清淡易消化的流质、半流质（米汤、藕粉、烂面条），少量多餐，忌油腻、辛辣、生冷及乳制品、粗纤维食物，持续2-3天。\n3. 注意手卫生，便后、餐前洗手；患者餐具单独使用并煮沸消毒，与家人分餐，污染物及排泄物妥善处理，防止交叉感染。\n4. 避免自行服用止泻药（如洛哌丁胺）及解热镇痛药，以免掩盖病情或加重肠道感染。\n\n【随诊要求】\n1. 用药2-3天后腹泻、呕吐无明显缓解，或出现高热（>39℃）、脓血便、剧烈腹痛、明显脱水（口干、尿少、眼窝凹陷、皮肤弹性差）或精神萎靡，应立即复诊或急诊就诊。\n2. 症状缓解后建议门诊复诊复查粪便常规，评估感染控制情况；老年、糖尿病及肾病等基础病患者建议复查电解质、肾功能。\n3. 病程迁延超过2周仍间断腹泻或伴体重下降者，应门诊随访，必要时行肠镜检查排除炎症性肠病等其他肠道疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":241,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ddfcd2e33c825395cef98521545da037b62740313c8858ea10af195341f153a7","pinyin":"jixingweichangyan","initials":"jxwcy","setting":"out","caseName":"门诊病历106","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历106",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-08e998dfc756421588f2","key":"v1-c9ccc21dfe2a3058|templates-08e998dfc756421588f2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿路感染","category":"门诊病历模板","raw":{"name":"尿路感染","category":"门诊病历模板","case":{"case_name":"门诊病历107","templates":{"主诉":"尿频、尿急、尿痛伴下腹部不适2天。","现病史":"患者于2天前出现尿频（白天10余次、夜间3～4次）、尿急、尿痛（排尿时尿道烧灼感），伴下腹部坠胀不适，无肉眼血尿及终末血尿，无发热、寒战，无腰痛，无恶心呕吐。发病前有无憋尿、劳累、性生活等诱因：发病前有憋尿及劳累，无性生活相关诱因。如为女性患者，白带无异常。既往有无类似发作史、糖尿病史及留置导尿史：无类似发作史、糖尿病史及留置导尿史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP118/76mmHg。神志清楚，查体合作。双肾区无叩击痛。腹平软，下腹部轻压痛，无肌紧张及反跳痛。输尿管走行区无压痛。","辅助检查":"【必做】尿常规（白细胞酯酶、亚硝酸盐、白细胞及红细胞计数，提示感染）、尿培养+药敏（反复发作、复杂感染或抗菌治疗效果不佳时）；【其他】泌尿系超声（排除结石、梗阻、残余尿等）、肾功能。","初步诊断":"1. 尿路感染（下尿路感染：膀胱炎）\n（注：无并发症急性膀胱炎：口服磷霉素氨丁三醇3g单剂 或 呋喃妥因0.1g qid×5天 或 头孢克肟0.1g bid×3~5天；多饮水勤排尿；若伴发热寒战、腰痛提示肾盂肾炎（上尿路感染），需静脉或口服抗菌治疗7~14天并排查梗阻；反复发作者排除泌尿系结构异常。）","处理方案":"【药物治疗】\n1. 呋喃妥因肠溶片 0.1g 口服 bid×5天（餐后服，为急性单纯性膀胱炎首选之一）\n2. 磷霉素氨丁三醇散 3g 口服，睡前排空膀胱后一次顿服（单剂方案，适用于急性单纯性下尿路感染）\n3. 头孢克肟胶囊 0.1g 口服 bid×5-7天（对上述药物过敏、不耐受或疗效不佳时选用）\n4. 左氧氟沙星片 0.5g 口服 qd×3天（肾功能正常、无喹诺酮类药物禁忌者，作为备选方案；老年及糖尿病患者慎用）\n\n【一般治疗及生活指导】\n1. 多饮水，每日饮水量2000ml以上（心、肾功能正常者），勤排尿、不憋尿，使细菌随尿液及时冲刷排出\n2. 注意休息，避免劳累、熬夜及受凉；急性期避免剧烈运动和性生活\n3. 注意会阴部卫生：保持外阴清洁干燥，穿宽松透气的棉质内裤并勤更换，排便后从前向后擦拭，避免肛周细菌污染尿道口\n4. 清淡饮食，忌辛辣刺激食物及饮酒，少饮咖啡、浓茶，保证充足睡眠\n\n【随诊要求】\n1. 疗程结束后3-7天门诊复查尿常规，评估疗效\n2. 用药48-72小时症状无缓解或出现持续发热、寒战、腰痛加重，立即复诊，必要时行尿培养+药敏及泌尿系超声检查并调整抗菌药物\n3. 6个月内发作≥2次或1年内≥3次的反复发作患者，建议行尿培养+药敏及泌尿系影像学检查（泌尿系超声、残余尿测定等），寻找并处理诱因\n4. 糖尿病、老年或免疫力低下患者需同时控制基础疾病，规范随访"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":242,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e4efe24b3bf7e47f728ed28f9416313a7b49a50e8dbad21ef2b71ab895ccc3d7","pinyin":"niaoluganran","initials":"nlgr","setting":"out","caseName":"门诊病历107","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历107",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bdd48b6419e49839d66f","key":"v1-c9ccc21dfe2a3058|templates-bdd48b6419e49839d66f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性肾炎","category":"门诊病历模板","raw":{"name":"急性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历108","templates":{"主诉":"眼睑及双下肢水肿伴肉眼血尿、尿量减少1周。","现病史":"患者于2周前出现上呼吸道感染（咽痛、扁桃体炎等），7天前出现晨起眼睑水肿，渐及双下肢，伴尿量减少、尿色加深呈洗肉水样（肉眼血尿）、乏力，无发热、无尿频尿急尿痛，无关节痛及皮疹。自服药物（药名不详）效果欠佳。今日来我院门诊就诊。发病以来精神欠佳，食欲减退，血压情况：升高，最高150/95mmHg。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R18次/分，BP150/95mmHg（升高）。神志清楚，查体合作。眼睑及双下肢可见凹陷性水肿（程度中度），颜面部水肿。咽部充血（+），扁桃体Ⅱ度肿大。双肺呼吸音清。心率88次/分，律齐。腹平软，无压痛，移动性浊音（-）。双肾区无叩击痛。","辅助检查":"检查计划：患者2周前有上呼吸道感染（咽痛、扁桃体炎）前驱史，7天前出现晨起眼睑水肿渐及双下肢、尿色加深呈洗肉水样、尿量减少，门诊测血压最高150/95mmHg，临床考虑链球菌感染后急性肾小球肾炎，故入院即刻完善尿常规检查，了解有无蛋白尿、红细胞及红细胞管型，明确肾小球源性血尿；查尿蛋白定量（含24小时尿蛋白定量）评估蛋白尿程度，判断肾小球损伤轻重并指导限盐限水、利尿消肿方案；患者尿量减少伴血压升高，完善肾功能（血肌酐、尿素氮、eGFR）检查排除急性肾损伤及肾功能不全，为呋塞米利尿、硝苯地平或ACEI类降压用药的安全性提供依据，并于住院期间定期复查；完善血常规检查排除感染未控制及贫血，查血沉了解炎症活动程度；患者有明确链球菌前驱感染史，完善抗链球菌溶血素O（ASO）检查明确近期链球菌感染证据，查补体C3了解有无急性期下降（6~8周恢复）以支持诊断并鉴别其他肾炎；完善肾脏超声检查排除结石、梗阻、占位及双肾大小形态异常；若肾功能进行性恶化或病程迁延，完善肾穿刺活检明确病理类型以指导治疗与判断预后。\n\n（检查清单）\n【必做】尿常规（蛋白尿、红细胞及红细胞管型）、尿蛋白定量、肾功能（血肌酐、尿素氮）、血常规、血沉、抗链球菌溶血素O（ASO，链球菌感染后升高）、补体C3（急性期下降，6~8周恢复）；【其他】肾脏超声、24小时尿蛋白定量、肾穿刺活检（肾功能进行性恶化或病程迁延时）。","初步诊断":"1. 急性肾小球肾炎（链球菌感染后可能性大）\n（注：治疗以休息、限盐限水、对症为主：利尿消肿（呋塞米）、降压（硝苯地平/ACEI类）；清除感染灶用青霉素（如链球菌感染）；急性期出现少尿、高钾、心衰、高血压脑病等并发症需住院；多数预后良好，儿童尤佳。）","处理方案":"【药物治疗】\n1. 抗感染（针对链球菌感染灶）：阿莫西林胶囊 0.5g po tid，疗程10～14天（青霉素过敏者改用阿奇霉素片 0.5g po qd×5天）；咽拭子培养阴性、感染灶已消退者可不用。\n2. 利尿消肿：氢氯噻嗪片 25mg po bid×3～5天，水肿明显或利尿不佳时改呋塞米片 20mg po qd（必要时加量至40mg），水肿消退后即停，用药期间监测体重、尿量及电解质。\n3. 降压治疗：血压≥140/90mmHg时予硝苯地平控释片 30mg po qd；效果不佳加用卡托普利片 12.5mg po bid～tid（注意监测血钾及肌酐，高钾血症、血肌酐进行性升高者禁用）。\n4. 对症处理：肉眼血尿伴感染征象者可配合口服维生素C片 0.2g po tid；若出现少尿、血肌酐快速升高或明显氮质血症，及时转诊住院治疗。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息至肉眼血尿消失、水肿消退、血压恢复正常（一般需2～4周），之后逐渐恢复活动，避免剧烈运动和劳累。\n2. 饮食：低盐饮食（每日食盐<3g），水肿明显时限制入水量（每日约500ml+前一日尿量）；伴氮质血症者限制蛋白质摄入（每日0.6g/kg，以优质蛋白如蛋、奶、瘦肉为主），血尿素氮正常后可恢复常规蛋白摄入。\n3. 注意保暖，预防感冒及皮肤感染，保持口腔及会阴部清洁；避免使用肾毒性药物（如氨基糖苷类、非甾体抗炎药、含马兜铃酸的中草药）。\n4. 戒烟戒酒，监测每日体重、尿量及血压变化，如出现少尿（<400ml/日）、肉眼血尿加重、气促或水肿加重立即就医。\n\n【随诊要求】\n1. 门诊复诊每周1～2次，复查尿常规、血压、血肌酐及血电解质，直至血尿、蛋白尿及血压恢复正常。\n2. 恢复期每2～4周复查尿常规及肾功能1次，随访至少6个月；多数患者6～8周临床痊愈，若尿蛋白持续>1g/日或血肌酐持续升高超过3个月，转肾内科进一步诊治（必要时肾穿刺活检）。\n3. 随访期间注意监测血压，儿童及青少年患者建议随访观察1～2年以评估远期预后。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":243,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"52c8745b7a38f3d87dc69454d94f0151eea4968674aea22fdbeea4df4a3fed8e","pinyin":"jixingshenyan","initials":"jxsy","setting":"out","caseName":"门诊病历108","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历108",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c1411578410de6f4923f","key":"v1-c9ccc21dfe2a3058|templates-c1411578410de6f4923f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性肾炎","category":"门诊病历模板","raw":{"name":"慢性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历109","templates":{"主诉":"反复蛋白尿、水肿伴乏力5年，再发加重2周。","现病史":"患者5年前体检发现尿蛋白阳性，诊断为慢性肾小球肾炎，平素尿蛋白波动于+～++，未系统治疗，也未规律口服药物。近2周劳累后出现双下肢水肿、泡沫尿增多，乏力、腰酸，夜尿增多（夜间3～4次），无肉眼血尿，无发热，无关节痛。有无高血压史及血压控制情况：既往无高血压病史，平素未规律监测血压。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP134/86mmHg。神志清楚，查体合作，贫血貌（+）。眼睑及双下肢凹陷性水肿（程度中度）。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双肾区无叩击痛。","辅助检查":"【必做】尿常规、24小时尿蛋白定量、尿微量白蛋白与肌酐比值、肾功能（血肌酐、eGFR）、血常规（贫血评估）、电解质、血白蛋白、血脂；【影像学】肾脏超声（双肾大小、皮质厚度）；【其他】肾穿刺活检（明确病理类型以指导治疗及判断预后时）。","初步诊断":"1. 慢性肾小球肾炎\n（注：治疗核心为延缓肾功能进展：控制血压<130/80mmHg（首选ACEI/ARB，兼降尿蛋白）、低盐低蛋白饮食、避免肾毒性药物（NSAIDs、造影剂等）、控制蛋白尿；定期监测肾功能、尿蛋白；eGFR进行性下降或病理活动者请肾内科专科随访，必要时免疫抑制治疗，终末期行肾脏替代治疗评估。）","处理方案":"【药物治疗】\n1. 降压保肾首选血管紧张素转换酶抑制剂（ACEI）或血管紧张素Ⅱ受体拮抗剂（ARB）：如贝那普利片10mg qd po，或缬沙坦胶囊80mg qd po，根据血压及肾功能调整剂量，长期维持（疗程≥6个月），目标血压<130/80mmHg，注意监测血肌酐及血钾。\n2. 尿蛋白定量>1g/24h者，建议行肾穿刺活检明确病理类型后，在专科医师指导下使用糖皮质激素及免疫抑制剂，如泼尼松片0.8~1.0mg/kg·d晨顿服，8~12周后根据病情每2~4周减量5mg，总疗程6~12个月。\n3. 抗血小板聚集：双嘧达莫片50mg tid po，或阿司匹林肠溶片100mg qd po（无出血倾向及禁忌症者）。\n4. 对症治疗：明显水肿者予呋塞米片20mg qd~bid po；伴高尿酸血症者予别嘌醇片100mg qd po；必要时予他汀类调脂（如阿托伐他汀钙片10mg qn po）。\n\n【一般治疗及生活指导】\n1. 休息：急性发作期或水肿、蛋白尿明显者应卧床休息，避免劳累、熬夜及剧烈运动；病情稳定期可适当散步等轻度活动。\n2. 饮食：低盐饮食，每日食盐<5g；肾功能不全者予优质低蛋白饮食（0.6~0.8g/kg·d），以鸡蛋、牛奶、瘦肉为主，限制磷、钾摄入；水肿明显者限制每日液体入量（约1000~1500ml）。\n3. 禁忌：避免使用肾毒性药物（氨基糖苷类抗生素、非甾体抗炎药、含马兜铃酸的中草药及造影剂），避免受凉、感冒，戒烟限酒。\n4. 预防感染：注意个人卫生，防治呼吸道及泌尿道感染；女性注意会阴部清洁，预防尿路感染诱发病情加重。\n\n【随诊要求】\n1. 每1~2周复诊，监测血压、尿常规、24h尿蛋白定量、血肌酐及eGFR、电解质。\n2. 使用ACEI/ARB者起始2~4周复查血肌酐、血钾，若血肌酐较基线升高>30%或出现高钾血症应及时调整或停药；每月复查血常规、肝功能。\n3. 每3~6个月复查肾脏超声；若病情进展（尿蛋白持续增多、肾功能恶化），及时行肾穿刺活检明确病理类型并调整治疗方案；育龄期女性需避孕，避免妊娠加重肾损害。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":244,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b34ced015420dec82a9f8e5d804000bb038e14ad50df23dae6cc2896ae765801","pinyin":"manxingshenyan","initials":"mxsy","setting":"out","caseName":"门诊病历109","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历109",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e120ff9e0952e09edc1f","key":"v1-c9ccc21dfe2a3058|templates-e120ff9e0952e09edc1f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾病综合征","category":"门诊病历模板","raw":{"name":"肾病综合征","category":"门诊病历模板","case":{"case_name":"门诊病历110","templates":{"主诉":"双下肢水肿伴泡沫尿、乏力1个月。","现病史":"患者于4周前无明显诱因出现双下肢水肿，晨轻暮重，渐加重至全身水肿（颜面、腰骶、外生殖器），伴尿中泡沫增多（泡沫尿）、乏力、食欲减退，尿量减少（24小时约800ml），无肉眼血尿，无发热，无关节痛及皮疹。有无近期感染、药物过敏等诱因：无近期感染及药物过敏等诱因。有无高血压、糖尿病史：无高血压、糖尿病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R20次/分，BP130/84mmHg。神志清楚，查体合作，颜面及眼睑水肿。双肺呼吸音清，未闻及胸腔积液征象。心率88次/分，律齐。腹膨隆（+），移动性浊音（+）（腹水），肝脾肋下未触及。双下肢、腰骶部重度凹陷性水肿，外生殖器水肿（+）。","辅助检查":"【必做】尿常规及24小时尿蛋白定量（>3.5g/24h）、血白蛋白（<30g/L）、血脂（总胆固醇、甘油三酯升高）、肾功能、电解质；【影像学】肾脏超声；【其他】肾穿刺活检（明确病理类型，如微小病变、膜性肾病等，指导治疗）、凝血功能（高凝状态评估）。","初步诊断":"1. 肾病综合征（病理类型待定）\n（注：诊断标准：大量蛋白尿（>3.5g/24h）+低白蛋白血症（<30g/L）+水肿+高脂血症（前两项必备）；治疗：糖皮质激素（泼尼松1mg/kg/d，足量8~12周后渐减，需排除感染、结核、肿瘤等继发因素后使用）、他汀降脂、抗凝评估、利尿消肿；激素效果不佳或反复发作者加免疫抑制剂（环磷酰胺或他克莫司等）并请肾内科专科治疗，警惕感染、血栓栓塞等并发症。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选）：醋酸泼尼松片 1mg/kg·d（成人常规40mg～60mg，晨起顿服），足量诱导8～12周，有效后每2周减原剂量10%（约5mg），减至20mg/d后每4周减5mg，小剂量（10～15mg/d）维持6～12个月，总疗程1年以上；注意监测血压、血糖、血钾及有无感染。\n2. 利尿消肿（有水肿者）：呋塞米片 20mg～40mg bid口服，水肿明显时可短期静脉给药，注意监测血钾、血钠及肾功能，防止过度利尿致低血容量。\n3. 降低蛋白尿及控制血压（ACEI或ARB）：贝那普利片10mg qd或缬沙坦胶囊80mg qd口服，根据血压及肾功能调整剂量，长期维持；用药期间监测血肌酐、血钾。\n4. 降脂及抗凝（根据患者具体情况制定个体化方案）：阿托伐他汀钙片20mg qn口服降脂；血浆白蛋白<20g/L或有血栓栓塞高危因素者，加用低分子肝素皮下注射5000IU q12h（或遵医嘱口服华法林抗凝），监测凝血功能；长期激素者常规口服碳酸钙D3片600mg qd预防骨质疏松。\n【一般治疗及生活指导】\n1. 休息与活动：明显水肿、大量蛋白尿期以卧床休息为主，可取平卧位以减轻肾静脉受压；水肿消退、蛋白尿减少后可逐步下床活动，避免剧烈运动和劳累。\n2. 饮食：低盐饮食（每日食盐<3g，水肿明显时更严格）；肾功能正常者给予优质蛋白饮食0.8～1.0g/kg·d（如鸡蛋、瘦肉、牛奶），避免高蛋白加重蛋白尿；低脂饮食，水肿明显者限制液体入量（前一日尿量+500ml）。\n3. 预防感染：激素及免疫抑制剂治疗期间免疫力低下，注意保暖、避免受凉和去人群密集场所，注意口腔、皮肤及会阴卫生，如有感染及时就医，切勿自行停药。\n4. 监测与禁忌：每日晨起测体重、血压并记录24小时尿量，观察尿泡沫变化；禁用肾毒性药物（非甾体抗炎药、氨基糖苷类抗生素、含马兜铃酸中草药等），避免使用感冒药、止痛药等非处方药。\n【随诊要求】\n1. 治疗初期及减量期间每2～4周门诊复诊1次，病情稳定后每1～3个月复诊1次，随访至少1～2年。\n2. 每次复诊复查24小时尿蛋白定量、血白蛋白、血肌酐、尿素氮、电解质、血脂、血糖及肝肾功能，必要时查尿常规、凝血功能。\n3. 激素减量必须遵医嘱逐步进行，禁止自行增减或突然停药；长期激素者每3～6个月监测血糖、骨密度及眼底。\n4. 若出现发热、咳嗽等感染征象，或突发单侧下肢肿胀疼痛、胸闷胸痛、咯血（警惕深静脉血栓及肺栓塞），或水肿加重、尿量明显减少，应及时复诊或急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":245,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"acd721b5bc3707e22cf92306976334c09878e111b8c2f8f3b5f71934d7f99c4b","pinyin":"shenbingzonghezheng","initials":"sbzhz","setting":"out","caseName":"门诊病历110","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历110",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a585ee39eb178fd9bf7d","key":"v1-c9ccc21dfe2a3058|templates-a585ee39eb178fd9bf7d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾功能不全","category":"门诊病历模板","raw":{"name":"肾功能不全","category":"门诊病历模板","case":{"case_name":"门诊病历111","templates":{"主诉":"乏力、恶心、食欲减退伴尿量减少6月，加重2周。","现病史":"患者有慢性肾脏病病史8年，近6月渐出现乏力、纳差、恶心、皮肤瘙痒、夜尿增多，近2周症状加重，伴尿量减少（24小时约600ml）、泡沫尿增多，无发热，无肉眼血尿。有无服用肾毒性药物（NSAIDs、中草药等）史：无服用肾毒性药物（NSAIDs、中草药等）史。今日来我院门诊就诊。发病以来体重下降约3kg，睡眠差。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R20次/分，BP160/95mmHg（升高）。神志清楚，贫血貌，皮肤可见色素沉着及抓痕，双下肢水肿（程度轻度）。双肺呼吸音清。心率88次/分，律齐。腹平软。双肾区无叩击痛。","辅助检查":"【必做】肾功能（血肌酐、尿素氮、eGFR、血尿酸）、电解质（血钾、血磷、血钙、二氧化碳结合力）、血常规（肾性贫血）、尿常规及尿蛋白定量、血糖、血脂、肝功能；【影像学】肾脏超声（双肾大小、皮质厚度，鉴别急慢性肾病）；【其他】血气分析（代谢性酸中毒评估）、甲状旁腺激素及维生素D（肾性骨病筛查）。","初步诊断":"1. 慢性肾功能不全（CKD4期，eGFR22ml/min/1.73m²）\n（注：分期管理：控制血压（ACEI或ARB）、纠正贫血（促红细胞生成素+铁剂）、纠正酸中毒（碳酸氢钠）、降磷及活性维生素D（肾性骨病）、低蛋白饮食+复方α-酮酸；避免肾毒性药物；eGFR<15或出现尿毒症症状（严重酸中毒、高钾、心衰、消化道出血）者行肾脏替代治疗（血液透析、腹膜透析或肾移植）评估，请肾内科专科随访。）","处理方案":"【药物治疗】\n1. 血管紧张素Ⅱ受体拮抗剂（ARB）延缓肾功能进展、降低蛋白尿：缬沙坦胶囊80mg po qd（或厄贝沙坦片150mg po qd），长期服用；用药2周后复查血肌酐及血钾，血肌酐较基线升高＞30%或血钾＞5.5mmol/L时暂停并就诊调整。\n2. SGLT2抑制剂降低蛋白尿、延缓eGFR下降：达格列净片10mg po qd（适用于eGFR≥25ml/(min·1.73m²)者），长期服用；注意会阴部卫生，警惕泌尿系感染及酮症酸中毒。\n3. 纠正肾性贫血：罗沙司他胶囊100mg po 每周3次，或重组人促红素3000IU 皮下注射 每周2次；目标血红蛋白110~120g/L，如铁蛋白＜200μg/L或转铁蛋白饱和度＜20%时加用多糖铁复合物胶囊150mg po qd。\n4. 纠正钙磷代谢紊乱：合并低钙血症或继发性甲状旁腺功能亢进者予骨化三醇软胶囊0.25μg po qd；每1~3个月监测血钙、血磷及全段甲状旁腺激素（iPTH）调整剂量。\n\n【一般治疗及生活指导】\n1. 饮食：优质低蛋白饮食，每日蛋白质摄入0.6~0.8g/kg体重（以鸡蛋、牛奶、瘦肉等优质蛋白为主）；低盐（每日＜5g，伴水肿或高血压者＜3g）、低钾、低磷饮食，限制高钾食物（香蕉、橙子、土豆、坚果、菌菇及浓汤）和高磷食物（动物内脏、坚果、豆制品、碳酸饮料）。\n2. 休息与活动：保证充分休息，避免熬夜、过度劳累及剧烈运动；规律作息，可适度散步等有氧活动，控制体重。\n3. 避免肾损伤因素：慎用或避免非甾体抗炎药（布洛芬、双氯芬酸等）、氨基糖苷类抗生素及含马兜铃酸的中草药；腹泻、呕吐、大汗等失水情况及时补液，避免脱水及血压骤降；积极防治感染；戒烟限酒。\n4. 自我监测：每日自测血压、体重并记录24小时尿量；血压控制目标＜130/80mmHg（合并蛋白尿者），合并糖尿病者血糖达标。\n\n【随诊要求】\n1. 每1~3个月门诊复诊，复查血常规、肾功能（血肌酐、eGFR）、电解质（血钾、血钠、血磷）及血气分析（HCO₃⁻）；每3~6个月复查尿常规、24小时尿蛋白定量、血钙、血磷及iPTH，必要时行肾脏超声。\n2. 出现尿量明显减少、水肿加重、恶心呕吐、食欲减退、乏力加重、皮肤瘙痒、呼吸困难、血压明显升高或波动、血钾升高等情况时，及时就诊。\n3. 降压、降糖、排毒等药物调整需在医师指导下进行，不可自行增减；中重度肾功能不全（CKD 4~5期）患者建议转诊肾内科专科门诊规范管理，评估肾脏替代治疗时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":246,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"eba3da6e6c4c0dcc99265f22c06269c54110cf47b15e935e3e8b16080b5218c2","pinyin":"shengongnengbuquan","initials":"sgnbq","setting":"out","caseName":"门诊病历111","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历111",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-71824036ac62a1470554","key":"v1-c9ccc21dfe2a3058|templates-71824036ac62a1470554","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病","category":"门诊病历模板","raw":{"name":"糖尿病","category":"门诊病历模板","case":{"case_name":"门诊病历112","templates":{"主诉":"多饮、多食、多尿伴体重下降3月。","现病史":"患者于3月前无明显诱因出现口干、多饮（每日饮水约3000ml）、多尿（夜尿3～4次）、多食易饥，伴体重下降约5kg、乏力、视物模糊，无恶心呕吐，无腹痛。有无糖尿病家族史：无糖尿病家族史。有无高血压、冠心病史：无高血压、冠心病史。是否已确诊糖尿病及用药情况：既往未确诊糖尿病，未服用降糖药物。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分，R18次/分，BP126/80mmHg，BMI25.8kg/m²。神志清楚，查体合作。皮肤巩膜无黄染。心肺听诊未闻及明显异常。腹平软。双下肢无水肿，足背动脉搏动正常，足部皮肤无破溃。","辅助检查":"【必做】空腹血糖、餐后2小时血糖或OGTT（75g葡萄糖耐量试验）、糖化血红蛋白（HbA1c，评估近2~3月平均血糖）、尿常规（尿糖、尿酮体）、肝肾功能、血脂、电解质；【其他】胰岛功能（空腹及餐后C肽）、胰岛自身抗体（疑1型糖尿病时）、并发症筛查（眼底、尿微量白蛋白、神经病变）。","初步诊断":"1. 2型糖尿病（初诊）\n（注：诊断标准：空腹血糖≥7.0mmol/L 或 OGTT 2h血糖≥11.1mmol/L 或 HbA1c≥6.5% 或典型症状+随机血糖≥11.1mmol/L；治疗：生活方式干预（饮食控制、运动）+二甲双胍0.5g bid（一线，随餐服）起始，HbA1c不达标者联合其他降糖药（磺脲类、DPP-4i、SGLT2i、GLP-1RA等）；定期监测血糖及并发症；若出现恶心呕吐、呼吸深快、意识改变（酮症酸中毒或高渗状态）需急诊处理。）","处理方案":"【药物治疗】\n1. 二甲双胍片0.5g bid，餐中或餐后口服，为2型糖尿病首选一线用药（无明显禁忌者长期维持），起始0.25g bid、1周后渐增至0.5g bid，随餐服用以减少胃肠道反应。\n2. 阿卡波糖片50mg tid，与第一口饭同嚼服，适用于以餐后血糖升高为主者；服药期间如发生低血糖须用葡萄糖纠正，不能用蔗糖。\n3. 达格列净片10mg qd，晨服，适用于合并超重或肥胖、高血压或心衰者，兼具减重及心肾保护作用；用药期间注意多饮水、警惕泌尿生殖道感染。\n4. 阿托伐他汀钙片20mg qn，口服，适用于合并血脂异常者，防治动脉粥样硬化性心血管疾病，用药期间监测肝酶及肌酸激酶。\n\n【一般治疗及生活指导】\n1. 饮食：控制总热量，均衡营养，碳水化合物占50%~60%，定时定量、少食多餐，粗细粮搭配，限制精制糖、油炸食品及含糖饮料，每日食盐<5g。\n2. 运动：餐后1小时进行中等强度有氧运动（快走、慢跑、游泳等）30分钟，每周至少150分钟，量力而行；禁忌空腹剧烈运动及运动前不进食，以防低血糖。\n3. 自我监测：备血糖仪，每周至少监测3~4次空腹及餐后2小时血糖并记录，供复诊调整方案；外出随身携带糖果备用。\n4. 禁忌：戒烟限酒，避免久坐不动及熬夜；足部每日检查、穿宽松软底鞋，防止外伤感染；合并感染、手术或应激时及时复诊调整方案。\n\n【随诊要求】\n1. 用药调整期每周复诊1次，监测空腹及餐后2小时血糖，达标后可改为每1~3个月复诊1次。\n2. 每3个月复查糖化血红蛋白（HbA1c，目标<7.0%），每6~12个月复查肝肾功能、血脂、尿微量白蛋白与肌酐比值。\n3. 每年至少1次并发症筛查：眼底照相、足部检查、神经病变筛查及心血管风险评估。\n4. 出现低血糖（心慌、出冷汗、手抖）立即进食含糖食物，反复发作或血糖波动大时及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":247,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"91db5fc7cdf79ce0c3c163dc2b56c771346a8fc8b1dffdcfd8a344cef34f1057","pinyin":"tangniaobing","initials":"tnb","setting":"out","caseName":"门诊病历112","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历112",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d8070ad7e5af49a222fc","key":"v1-c9ccc21dfe2a3058|templates-d8070ad7e5af49a222fc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺功能亢进","category":"门诊病历模板","raw":{"name":"甲状腺功能亢进","category":"门诊病历模板","case":{"case_name":"门诊病历113","templates":{"主诉":"心悸、怕热、多汗、易饥伴体重下降、手抖2个月。","现病史":"患者于2月前无明显诱因出现心悸、怕热、多汗、易饥多食、大便次数增多、体重下降约8kg，伴手抖、急躁易怒、失眠，近2周症状加重，无突眼加重，无发热，无咽痛。有无甲状腺疾病家族史：无甲状腺疾病家族史。有无近期感染、精神应激等诱因：无明显近期感染及精神应激诱因。今日来我院门诊就诊。发病以来精神亢奋，睡眠差。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P108次/分（增快），R20次/分，BP140/70mmHg（脉压增大）。神志清楚，烦躁貌，双手细颤（+）。皮肤湿热。甲状腺弥漫性肿大（程度Ⅱ度），质地软，可闻及血管杂音。眼球突出（+，程度轻度），瞬目减少，上睑挛缩（+）。心率108次/分，律齐，心音增强。","辅助检查":"【必做】甲状腺功能（FT3、FT4升高，TSH降低）、甲状腺过氧化物酶抗体及促甲状腺激素受体抗体（TRAb，Graves病）、血常规（抗甲状腺药物前基线）、肝功能；【影像学】甲状腺彩超（血流丰富、甲状腺大小及结节）；【其他】甲状腺摄碘率或核素显像（甲状腺毒症病因鉴别：Graves病摄碘率增高、甲状腺炎降低）、心电图（房颤等心律失常）。","初步诊断":"1. 甲状腺功能亢进症（Graves病可能性大）\n（注：抗甲状腺药物（ATD）：甲巯咪唑10mg bid起始或丙硫氧嘧啶100mg tid，2~4周起效，需监测血常规（粒细胞缺乏，若出现发热咽痛立即停药就诊）、肝功能；配合β受体阻滞剂（普萘洛尔10mg tid）控制心率及症状；疗程一般1.5~2年，定期复查甲功调整剂量；药物不耐受或复发者考虑碘131或手术治疗；若高热、大汗、心动过速、意识改变提示甲状腺危象，立即急诊。）","处理方案":"【药物治疗】\n1. 甲巯咪唑片（赛治）10mg tid 口服起始，或30mg每日晨起顿服，用药前及用药第1、2周复查血常规、肝功能；约4-6周后甲状腺功能改善，每4-6周减量5-10mg，至维持量5-10mg qd，总疗程1.5-2年。\n2. 盐酸普萘洛尔片10mg tid 口服，用于控制心悸、手抖、多汗等交感神经兴奋症状，心率降至60次/分左右或症状缓解后逐渐减量至停用。\n3. 丙硫氧嘧啶片100mg tid 口服，为备选方案，适用于妊娠早期（孕1-3个月）、甲亢危象或甲巯咪唑不耐受者。\n【一般治疗及生活指导】\n1. 休息：症状明显期（心悸、多汗、体重明显下降）以卧床或减少活动为宜，保证充足睡眠，避免劳累、熬夜和精神紧张。\n2. 饮食：严格低碘饮食，禁食海带、紫菜、海鱼、海虾等海产品，使用无碘盐，避免含碘保健品及药物（如胺碘酮）；同时给予高热量、高蛋白、高维生素饮食，适当多饮水。\n3. 活动：症状控制后可恢复正常日常活动，避免剧烈运动及竞技性运动；合并Graves眼病者戒烟，外出佩戴墨镜防强光刺激，睡眠时垫高枕头减轻眼周水肿。\n4. 禁忌：禁烟酒及浓茶、咖啡等兴奋性饮料，避免情绪激动和过度紧张。\n【随诊要求】\n1. 用药初期每1-2周复查血常规（警惕粒细胞缺乏）及肝功能，每4-6周复查甲状腺功能（FT3、FT4、TSH）以调整药量。\n2. 维持治疗期每1-3个月复查甲状腺功能、肝功能，每半年复查血常规1次。\n3. 治疗期间若出现发热、咽痛、口腔溃疡等感染征象，立即停用抗甲状腺药物并急诊就诊（警惕粒细胞缺乏症）；出现皮疹、黄疸、关节痛、恶心呕吐等及时复诊。\n4. 总疗程一般1.5-2年，不可自行停药或减量；停药后每3-6个月复查甲状腺功能随访1年，以防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":248,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b18d5b6d147a987d6ceda2435593ea9a37047c643d5ab49c1136fb73d039d7e1","pinyin":"jiazhuangxiangongnengkangjin","initials":"jzxgnkj","setting":"out","caseName":"门诊病历113","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历113",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bb09fd59206fd3638759","key":"v1-c9ccc21dfe2a3058|templates-bb09fd59206fd3638759","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺功能减退","category":"门诊病历模板","raw":{"name":"甲状腺功能减退","category":"门诊病历模板","case":{"case_name":"门诊病历114","templates":{"主诉":"乏力、畏寒、嗜睡、颜面及下肢水肿伴反应迟钝3个月。","现病史":"患者于3个月前渐出现乏力、畏寒、嗜睡、反应迟钝、记忆力减退、体重增加约5kg、便秘、皮肤干燥、脱发，颜面及下肢水肿（非凹陷性），声嘶，无发热，无胸痛气短。既往无甲状腺手术、碘131治疗及桥本甲状腺炎病史，未服用左甲状腺素。无贫血及血脂异常史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P56次/分（减慢），R16次/分，BP110/70mmHg。神志清楚，反应稍迟钝，面色苍白，颜面水肿，皮肤干燥粗糙，毛发稀疏，眉毛外1/3脱落（+），声音嘶哑。甲状腺肿大，质韧。心率56次/分，律齐，心音低钝。双下肢非凹陷性水肿。腱反射松弛时间延长（+）。","辅助检查":"检查计划：患者近3个月渐出现乏力、畏寒、嗜睡、反应迟钝、记忆力减退、体重增加约5kg、便秘、皮肤干燥、脱发及声嘶，颜面及下肢非凹陷性水肿，临床疑诊原发性甲减（桥本甲状腺炎可能性大），故完善甲状腺功能（TSH、FT3、FT4）检查明确甲减诊断及病变部位——TSH升高伴FT3、FT4降低提示原发性甲减，TSH降低或正常而FT4降低提示中枢性甲减；患者考虑桥本甲状腺炎所致，完善甲状腺过氧化物酶抗体及甲状腺球蛋白抗体检查明确自身免疫性病因；查甲状腺彩超了解甲状腺大小、回声及有无结节，辅助判断桥本甲状腺炎；患者乏力、面色萎黄，完善血常规检查排除贫血所致乏力；甲减常继发脂代谢紊乱，查血脂了解血脂水平；患者需长期口服左甲状腺素替代治疗，药物代谢需经肝脏，完善肝功能检查排除肝功能不全并指导用药；甲减可致肌酶升高及肌病，完善肌酸激酶检查排除甲减性肌病及其他肌损伤；若上述检查提示中枢性甲减或伴头痛、视野缺损，完善垂体MRI检查明确垂体及下丘脑病变。左甲状腺素起始25~50μg qd（老年及冠心病者12.5~25μg起始），用药后每4~6周复查甲状腺功能调整剂量，达标后每6~12个月定期复查。\n\n（检查清单）\n【必做】甲状腺功能（TSH升高、FT3及FT4降低提示原发性甲减；TSH降低或正常、FT4降低提示中枢性甲减）、甲状腺过氧化物酶抗体及甲状腺球蛋白抗体（桥本甲状腺炎）、血常规（贫血）、血脂、肝功能、肌酸激酶；【影像学】甲状腺彩超；【其他】垂体MRI（疑中枢性甲减时）。","初步诊断":"1. 甲状腺功能减退症（原发性，桥本甲状腺炎可能性大）\n（注：治疗：左甲状腺素（优甲乐）替代治疗，起始25~50μg qd（晨起空腹），老年及冠心病患者小剂量起始（12.5~25μg），每4~6周复查TSH调整剂量，达标后每6~12个月复查；妊娠期甲减需内分泌科专科管理；黏液性水肿昏迷（低温、低通气、意识障碍）为急症需立即急诊。）","处理方案":"【药物治疗】\n1. 左甲状腺素钠片（优甲乐）50μg qd，早餐前30~60分钟空腹顿服，替代治疗起始剂量25~50μg/日，每4~6周复查甲状腺功能调整剂量，达标后维持剂量长期服用（成人常规维持量50~150μg/日），不可自行停药或改量。\n2. 老年患者及合并冠心病、心律失常者起始剂量宜减半（12.5~25μg/日），每6~8周缓慢加量，避免诱发心绞痛、心律失常及药物过量。\n3. 妊娠期甲减（TSH＞4.0mIU/L）在医师指导下将剂量增加约30%，每4周复查甲功并及时调整。\n\n【一般治疗及生活指导】\n1. 限制高碘食物（海带、紫菜、海鱼、海参等高碘海产品应少吃），避免过量碘摄入加重自身免疫性甲状腺损伤；日常使用加碘盐即可，无需额外补碘。\n2. 注意保暖、避免受凉感冒及过度劳累，保证充足睡眠，适度活动（如散步、太极），甲减患者基础代谢低、怕冷乏力，不宜剧烈运动。\n3. 给予高蛋白、高维生素、易消化饮食，限制脂肪及高胆固醇食物（甲减时脂代谢减慢易致高脂血症），多食新鲜蔬菜水果，多饮水，保持大便通畅（甲减易便秘）。\n4. 左甲状腺素需与含钙或铁制剂、豆制品、牛奶、咖啡等间隔4小时以上服用，以免影响药物吸收。\n\n【随诊要求】\n1. 开始服药或调整剂量后4~6周复查甲状腺功能（TSH、FT3、FT4），达标（TSH恢复至正常参考范围）后每6~12个月复查1次；老年或冠心病患者TSH可放宽至正常上限。\n2. 每年监测血脂、肝肾功能，必要时行心电图及心脏彩超检查，评估甲减性心脏病及血脂异常。\n3. 若出现心悸、多汗、消瘦、失眠等提示药物过量，或乏力、畏寒、水肿加重提示剂量不足，应及时复诊调整剂量。\n4. 育龄期女性备孕前应将TSH控制在2.5mIU/L以下再妊娠，孕期遵医嘱每4周复查甲功并调整剂量，产后仍需定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":249,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5c776be59f53869db41109965328afb4abcfa91e826547868639e0e9b6685a12","pinyin":"jiazhuangxiangongnengjiantui","initials":"jzxgnjt","setting":"out","caseName":"门诊病历114","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历114",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-09b39c4b1fa9ff613948","key":"v1-c9ccc21dfe2a3058|templates-09b39c4b1fa9ff613948","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛风","category":"门诊病历模板","raw":{"name":"痛风","category":"门诊病历模板","case":{"case_name":"门诊病历115","templates":{"主诉":"反复关节红肿热痛5年，急性发作2天。","现病史":"患者5年来反复出现第一跖趾关节红肿热痛，多于进食海鲜、饮酒、受凉后发作。本次于2天前饮酒或进食海鲜后夜间突发右第一跖趾关节剧痛，红肿灼热，不能触碰及行走，伴发热（体温最高38.2℃），无其他关节受累。既往血尿酸最高580μmol/L，无痛风石及肾结石；用药史：未规律服用降尿酸药物。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒15年，约2两/日。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP130/80mmHg。神志清楚，痛苦面容，跛行。右第一跖趾关节明显红肿、皮温升高、触痛剧烈（+++），关节活动受限，局部皮肤无破溃。耳廓及关节周围未触及痛风石。其他关节无红肿。","辅助检查":"检查计划：患者5年来反复第一跖趾关节红肿热痛，多于进食海鲜、饮酒、受凉后发作，2天前饮酒进食海鲜后夜间突发右第一跖趾关节剧痛、红肿灼热、不能触碰及行走，既往血尿酸最高580μmol/L，临床考虑痛风急性关节炎发作，故完善血尿酸检查评估当前血尿酸水平，作为缓解期启动降尿酸治疗（非布司他或别嘌醇）及目标值（<360μmol/L）设定的依据；急性期完善血常规检查了解白细胞有无升高，查血沉、CRP了解急性炎症反应程度；患者本次关节红肿灼热伴发热38.2℃，完善关节液穿刺检查（偏振光显微镜查尿酸盐结晶）明确痛风诊断并排除化脓性关节炎；完善肾功能检查了解肌酐、尿素氮及eGFR，为秋水仙碱、NSAIDs用药安全性提供依据并排除肾功能不全；患者需长期降尿酸且需多饮水，完善尿常规检查排除尿酸性肾结石及尿路感染；完善关节X线片检查了解有无穿凿样骨缺损等慢性痛风骨破坏改变；完善关节超声检查了解有无双轨征及痛风石形成。急性期暂不启动降尿酸治疗，缓解2周后复查血尿酸并启动降尿酸，此后每1~3个月定期复查血尿酸及肝肾功能。\n\n（检查清单）\n【必做】血尿酸、血常规（白细胞可升高）、血沉、CRP（急性炎症指标）、肾功能、尿常规；【影像学】关节X线片（急性期可正常，慢性期可见穿凿样骨缺损）、关节超声（双轨征、痛风石）；【其他】关节液穿刺检查（偏振光显微镜见尿酸盐结晶为确诊金标准，疑化脓性关节炎时）。","初步诊断":"1. 痛风（急性关节炎发作）\n（注：急性期治疗：尽早（24小时内）用秋水仙碱（首剂1.0mg，1小时后0.5mg，此后0.5mg bid，腹泻即停）或NSAIDs（依托考昔120mg qd或塞来昔布200mg bid）、糖皮质激素（秋水仙碱及NSAIDs禁忌时，泼尼松30mg/d×5天）；急性期暂不启动降尿酸（已规律用者不停）；缓解2周后启动降尿酸（非布司他20~40mg qd或别嘌醇，起始小剂量），目标血尿酸<360μmol/L（有痛风石<300）；低嘌呤饮食、多饮水（>2000ml/日）、戒酒。）","处理方案":"【药物治疗】\n1. 急性发作期抗炎镇痛：首选NSAIDs，如依托考昔片120mg po qd，症状缓解后减量，疗程3～7天（消化道溃疡、肾功能不全者慎用）；或秋水仙碱片，首剂1.0mg po，1小时后0.5mg，此后0.5mg po bid～tid，症状缓解或出现腹泻即停药，疗程3～5天（严重肝肾功能不全者禁用）；上述禁忌或不耐受者可用醋酸泼尼松片30mg po qd，症状缓解后逐渐减量，疗程5～7天。急性发作期不建议新启用降尿酸药物，已在规律服用者不停药。\n2. 降尿酸治疗：发作缓解2周后、血尿酸仍>480μmol/L（或>420μmol/L合并痛风石、尿酸性肾结石者）开始。首选别嘌醇片100mg po qd起始，每2～4周复查血尿酸并递增剂量，最大300mg/d（用药前检测HLA-B*5801，阳性者禁用）；或非布司他片40mg po qd起始，2～4周后血尿酸不达标可增至80mg qd；肾功能正常且尿酸排泄增多者可选用苯溴马隆片50mg po qd，晨起顿服。目标血尿酸<360μmol/L，有痛风石者<300μmol/L，达标后长期维持。\n3. 预防发作与碱化尿液：开始降尿酸治疗前2周起予秋水仙碱片0.5mg po qd～bid（或小剂量NSAIDs），持续至血尿酸达标后至少3～6个月，预防降尿酸初期发作；服用苯溴马隆或尿pH<6.0者，予碳酸氢钠片0.5～1.0g po tid，维持尿pH 6.2～6.9。\n【一般治疗及生活指导】\n1. 饮食：严格低嘌呤饮食，禁食动物内脏、沙丁鱼、贝类海鲜、浓肉汤，限制红肉及含果糖饮料；禁饮酒（尤其啤酒与白酒）；鼓励进食低脂奶制品、新鲜蔬菜、鸡蛋。\n2. 饮水：每日饮水量2000ml以上，保证尿量>2000ml/d，促进尿酸排泄；避免饮用浓茶、咖啡等利尿饮品代替白开水。\n3. 生活管理：急性期卧床休息、抬高患肢、关节制动，48小时内局部冰敷，避免负重与热敷、按摩；缓解期规律作息，控制体重（肥胖者减重但避免快速减重），避免剧烈运动、受凉、劳累、外伤及精神紧张等诱因。\n【随诊要求】\n1. 急性发作期患者1～2周复诊，评估症状缓解情况并复查血尿酸、肝肾功能；若治疗3天后疼痛无明显缓解或伴发热，及时复诊或就诊。\n2. 降尿酸治疗期间每2～4周复查血尿酸，根据结果调整剂量；血尿酸达标后每3～6个月复查一次。\n3. 长期服用降尿酸及秋水仙碱者，每3～6个月复查血常规、肝肾功能、尿常规；服用苯溴马隆者定期监测肝功能并注意多饮水。出现皮疹、发热、关节肿痛加重等异常，及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":250,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ab71dcf8dbb5ca04f45a974273dfb33ed5d7ea13b946e3657e483f6eb5da1021","pinyin":"tongfeng","initials":"tf","setting":"out","caseName":"门诊病历115","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历115",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6dcdae5494bf2104d836","key":"v1-c9ccc21dfe2a3058|templates-6dcdae5494bf2104d836","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"眩晕综合征","category":"门诊病历模板","raw":{"name":"眩晕综合征","category":"门诊病历模板","case":{"case_name":"门诊病历116","templates":{"主诉":"反复发作性眩晕、视物旋转，伴恶心呕吐，再发2小时。","现病史":"患者于2小时前无明显诱因突发眩晕，视物旋转，闭目减轻，动则加剧，伴恶心、呕吐3次，无耳鸣、无听力下降、无耳闷胀感，无头痛，无肢体麻木无力，无言语不清，无意识障碍。既往有类似眩晕发作史，无耳部疾病史。无高血压、糖尿病、心脏病史，无特殊用药史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P76次/分，R18次/分，BP120/76mmHg。神志清楚，痛苦面容，闭目平卧，查体合作。双侧瞳孔等大等圆，对光反射灵敏，眼球运动充分，可见旋转性眼震（快相向上），无复视，无面瘫。听力粗测正常。共济运动（指鼻、跟膝胫）稳准，Romberg征阴性。四肢肌力肌张力正常，病理征阴性。变位试验（Dix-Hallpike）阳性。","辅助检查":"【必做】一般依据病史及查体；【影像学】头颅CT/MRI（首次发作、伴神经系统症状体征或疑中枢性眩晕时，排除后循环缺血、颅内占位、出血）；【其他】耳内镜检查、纯音测听及前庭功能检查（疑耳源性眩晕时）、心电图。","初步诊断":"1. 眩晕综合征（周围性）\n（注：周围性眩晕（良性阵发性位置性眩晕、梅尼埃病、前庭神经炎等）多见剧烈旋转性眩晕+眼震+自主神经症状、无中枢神经体征；BPPV可行耳石复位治疗（Epley手法），前庭神经炎予激素+前庭抑制剂（倍他司汀或茶苯海明）；中枢性眩晕（脑干小脑病变）伴神经功能缺损，需急诊影像并神经科处理；眩晕伴新发头痛、肢体无力、言语不清、意识障碍者立即急诊。）","处理方案":"【药物治疗】\n1. 前庭微循环改善剂：甲磺酸倍他司汀片（敏使朗）6mg po tid，餐后服用，疗程7~14天。\n2. 前庭抑制剂（止晕止吐）：茶苯海明片（眩晕停）25~50mg po，眩晕发作时服用，必要时每6小时重复1次，24小时总量不超过200mg，症状缓解即停；恶心呕吐明显者可加用甲氧氯普胺片10mg po tid，餐前服用。\n3. 钙通道拮抗剂：盐酸氟桂利嗪胶囊（西比灵）5mg po qn，睡前服用，疗程不超过14天；老年患者根据患者具体情况制定个体化方案减量为5mg qod。\n4. 对症支持：维生素B6片10mg po tid，辅助缓解恶心等不适。\n【一般治疗及生活指导】\n1. 急性发作期卧床休息，保持环境安静、光线柔和，避免声光刺激及突然变动体位，起床、转身动作宜缓慢，防止跌倒。\n2. 清淡低盐饮食，忌烟酒，避免浓茶、咖啡等刺激性饮品及过饱饮食，规律进餐。\n3. 避免长时间低头、快速转头及颈部剧烈活动（如猛然回头、仰头），减少诱发因素。\n4. 保证充足睡眠，避免熬夜、劳累和情绪激动，精神放松，必要时配合前庭康复训练（平衡及眼动练习）。\n【随诊要求】\n1. 用药后3~5天门诊复诊，评估眩晕发作频率、程度及药物耐受情况，必要时调整用药或完善前庭功能、听力等检查。\n2. 若症状反复发作或持续不缓解，建议1周内复诊，进一步行影像学及前庭功能检查明确病因。\n3. 如出现突发剧烈眩晕、耳鸣耳聋、言语不清、口角歪斜、肢体麻木无力、行走不稳或剧烈头痛等新发症状，应立即急诊就诊，排除脑血管疾病等急危重症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":251,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"99d119313eea1089860e75c9afbfab19a9e3a9dce94693ffb563aadf69e44acb","pinyin":"xuanyunzonghezheng","initials":"xyzhz","setting":"out","caseName":"门诊病历116","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历116",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d0ee2761aa6eac2040a2","key":"v1-c9ccc21dfe2a3058|templates-d0ee2761aa6eac2040a2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"坐骨神经痛","category":"门诊病历模板","raw":{"name":"坐骨神经痛","category":"门诊病历模板","case":{"case_name":"门诊病历117","templates":{"主诉":"腰痛伴右下肢放射性疼痛、麻木3周，加重5天。","现病史":"患者于3周前弯腰搬重物后出现腰部疼痛，并向右臀部、大腿后侧、小腿后外侧放射性疼痛，呈电击样，咳嗽、打喷嚏、用力排便时加重，伴右小腿及足部麻木感，行走后加重、卧床减轻，无大小便功能障碍，无会阴区麻木。有长期久坐及弯腰负重职业因素，无外伤史。既往无腰椎间盘突出病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP126/78mmHg。神志清楚，查体合作，腰椎生理曲度变直，腰L4-5棘突旁压痛（+），伴向右下肢放射痛。直腿抬高试验：右40°（阳性<70°），加强试验（+），左70°。右小腿外侧针刺觉减退，右拇趾背伸肌力4级，跟腱反射正常。病理征阴性。","辅助检查":"【必做】腰椎X线片（正侧位，观察骨性结构）；【影像学】腰椎MRI（首选，可明确椎间盘突出部位、程度及神经根受压情况）；【其他】腰椎CT（MRI禁忌时）、肌电图或神经传导速度（评估神经根损害程度）。","初步诊断":"1. 坐骨神经痛（腰椎间盘突出症可能性大，右L5神经根受累）\n（注：急性期卧床休息1~2周、避免弯腰负重；药物：NSAIDs（塞来昔布200mg bid）、神经营养（甲钴胺0.5mg tid）、肌肉松弛剂（乙哌立松50mg tid）；保守治疗4~6周无效、进行性肌力下降或出现马尾综合征（大小便障碍、鞍区麻木）者需手术（椎间盘摘除），后者为急诊指征，需立即就诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（消炎镇痛）：塞来昔布胶囊 0.2g bid 饭后口服，或依托考昔片 60mg qd 口服，疗程5～7天（急性疼痛期）。\n2. 营养神经：甲钴胺片 0.5mg tid 口服，连用4周。\n3. 神经病理性疼痛药物（疼痛呈烧灼样、针刺样、电击样时选用）：普瑞巴林胶囊 75mg bid 口服（首日可自25mg qd 起始，渐加量），疗程2～4周；或加巴喷丁胶囊 0.3g tid 口服。\n4. 肌肉松弛剂（合并腰背肌痉挛、腰椎间盘突出明显者）：盐酸乙哌立松片 50mg tid 饭后口服，疗程7天。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息1～2周，建议睡硬板床，避免久坐、久站、弯腰及负重搬物。\n2. 注意腰骶部保暖，避免受凉受潮；仰卧时膝下垫枕、侧卧时屈髋屈膝，以减轻坐骨神经张力。\n3. 缓解期循序渐进加强腰背肌及核心肌群锻炼（如五点支撑、小燕飞、平板支撑），并保持正确坐姿，座椅加腰垫，避免跷二郎腿。\n4. 控制体重，戒烟限酒，避免穿高跟鞋及长时间驾车、久坐办公。\n\n【随诊要求】\n1. 治疗后7～10天复诊，评估疼痛缓解程度及下肢感觉、肌力情况，必要时调整用药。\n2. 治疗期间若出现进行性下肢肌力减退、足下垂、行走困难或鞍区麻木、大小便功能障碍（马尾综合征表现），应立即急诊就诊，必要时转骨科或神经外科评估手术指征。\n3. 症状反复或4周内无明显缓解者，建议完善腰椎MRI、肌电图等检查明确病因，转骨科、康复科或疼痛科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":252,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"677afd1bd742115b48356b4b572371ad571ab8a767a5037324bc576e7008d4f7","pinyin":"zuogushenjingtong","initials":"zgsjt","setting":"out","caseName":"门诊病历117","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历117",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7c8a6a02cbe5b83440eb","key":"v1-c9ccc21dfe2a3058|templates-7c8a6a02cbe5b83440eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"贫血","category":"门诊病历模板","raw":{"name":"贫血","category":"门诊病历模板","case":{"case_name":"门诊病历118","templates":{"主诉":"头晕、乏力、面色苍白伴活动后心慌气短1个月。","现病史":"患者于1个月前渐出现头晕、乏力、面色苍白，活动后心慌、气短，伴食欲减退、耳鸣，无发热，无出血倾向（牙龈出血、皮肤瘀斑），无黄疸，无黑便、血便及月经量增多等失血表现。无长期素食、偏食，无胃肠道疾病及手术史。大便颜色黄褐色。今日来我院门诊就诊。发病以来体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P96次/分（可增快），R20次/分，BP100/65mmHg。神志清楚，贫血貌，睑结膜、口唇、指甲床苍白（中度），皮肤无出血点及瘀斑，巩膜无黄染。心率96次/分，律齐，心尖区可闻及收缩期杂音。腹平软，肝脾肋下未触及。神经系统检查无阳性体征。","辅助检查":"检查计划：患者近1个月渐出现头晕、乏力、面色苍白，活动后心慌气短，伴食欲减退、耳鸣，无明显出血倾向及黑便血便，临床考虑贫血（缺铁性可能）而病因未明，故完善血常规+网织红细胞检查明确贫血程度、红细胞参数（MCV、MCH、MCHC）及骨髓造血代偿情况，据平均红细胞体积初步区分缺铁性、巨幼细胞性及溶血性贫血；完善外周血涂片检查观察红细胞形态及有无异常细胞，辅助鉴别缺铁性贫血、巨幼细胞贫血及血液系统恶性疾病；患者无出血倾向，完善凝血功能检查排除凝血因子缺乏及潜在出血性疾病所致贫血；患者食欲减退、需除外消化道慢性失血及腹腔占位，完善腹部超声（肝脾淋巴结）检查了解肝脾有无肿大、有无腹腔占位，完善淋巴结超声检查排除淋巴增殖性疾病；为明确贫血病因及骨髓造血功能，完善骨髓穿刺+活检，必要时完善流式细胞术、染色体核型分析以明确有无造血系统恶性疾病，上述有创检查安排在病情稳定后择期完成；结合初步诊断，补充铁代谢指标（血清铁、铁蛋白、总铁结合力）及叶酸、维生素B12水平检查，明确缺铁性还是巨幼细胞性贫血并指导补铁、补充造血原料方案，治疗期间定期复查血常规评估疗效。\n\n（检查清单）\n【必做检查】\n血常规+网织红细胞、外周血涂片、凝血功能\n\n【影像学检查】\n腹部超声（肝脾淋巴结）、淋巴结超声\n\n【其他检查】\n骨髓穿刺+活检、流式细胞术、染色体核型分析","初步诊断":"1. 贫血（性质待查，缺铁性可能）\n（注：需结合红细胞参数（MCV、MCH、MCHC）、网织红细胞、铁代谢指标（血清铁、铁蛋白、总铁结合力）及叶酸、维生素B12水平明确贫血类型及病因，必要时骨髓检查；病因治疗是根本（补铁、补充造血原料或治疗原发病）。）","处理方案":"【药物治疗】\n1. 铁剂（缺铁性贫血首选）：琥珀酸亚铁片0.1g tid（餐后服），或硫酸亚铁片0.3g tid；同时口服维生素C 0.1g tid促进铁吸收。疗程：服至血红蛋白恢复正常后继续用药3~6个月，以补足储存铁。\n2. 叶酸（叶酸缺乏性巨幼细胞贫血）：叶酸片5mg tid，口服，疗程4~6周，血象恢复正常后停用。\n3. 维生素B12（维生素B12缺乏性巨幼细胞贫血）：甲钴胺片0.5mg tid口服，或甲钴胺注射液0.5mg im 隔日1次，疗程2~4周，血象恢复后可根据患者具体情况制定个体化方案维持；注意B12缺乏者不可单用叶酸，以免加重神经损害。\n4. 口服铁剂不耐受或吸收不良者：蔗糖铁注射液0.1g ivdrip，每周2~3次，补铁总量遵医嘱计算（患者医疗机构内输注，首次需观察过敏反应）。\n\n【一般治疗及生活指导】\n1. 饮食：增加富含血红素铁食物，如动物肝脏、动物血、瘦猪肉、牛肉等，每日1~2份；搭配富含维生素C的新鲜蔬果（橙子、猕猴桃、青椒）促进铁吸收；浓茶、咖啡、牛奶应与铁剂间隔2小时以上服用。\n2. 休息与活动：血红蛋白<70g/L或伴头晕、乏力、心慌者应适当卧床静养，避免剧烈运动、重体力劳动及长时间站立；血红蛋白≥90g/L且症状缓解后可循序渐进恢复日常活动。\n3. 病因管理：月经量过多者转妇科排查功能性子宫出血、子宫肌瘤等；长期素食、胃肠手术史、慢性腹泻者注意营养缺乏；停用可能引起贫血的药物（如非甾体抗炎药），必要时行胃镜或肠镜排查消化道隐性失血。\n4. 禁忌：避免自行长期服用含铁\"补血保健品\"掩盖病情、延误诊断；铁剂避免与抑酸药（PPI）、钙剂、四环素类药物同服；避免接触铅、苯等毒物。\n\n【随诊要求】\n1. 补铁治疗2周复查网织红细胞计数（应较治疗前明显升高），4周复查血常规及网织红细胞评估疗效。\n2. 血红蛋白恢复正常后每4~8周复查血常规及血清铁蛋白，待血清铁蛋白≥50μg/L后方可停用铁剂。\n3. 规范治疗4周血红蛋白升高不足10g/L或无明显上升者，应转血液科行骨髓穿刺等检查进一步明确病因。\n4. 巨幼细胞贫血患者血象恢复后每3~6个月复查血常规，有神经症状者需随访至症状改善；病因未除者（如持续失血）长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":253,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5330449c90dc3f737446e5c2978c8e8b3f205b85289cb7ecee6d915f9f1ebacb","pinyin":"pinxue","initials":"px","setting":"out","caseName":"门诊病历118","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历118",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0700a15eab1537fab906","key":"v1-c9ccc21dfe2a3058|templates-0700a15eab1537fab906","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血小板减少性紫癜","category":"门诊病历模板","raw":{"name":"血小板减少性紫癜","category":"门诊病历模板","case":{"case_name":"门诊病历119","templates":{"主诉":"皮肤瘀点、瘀斑反复出现，伴牙龈出血1周。","现病史":"患者于1周前无明显诱因出现皮肤散在瘀点、瘀斑，以四肢为著，伴牙龈出血、鼻出血，无呕血黑便、无肉眼血尿，无发热、无关节痛。发病前无病毒感染、疫苗接种及药物（肝素、奎宁等）服用史。无肝病、自身免疫病史及家族出血史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P80次/分，R18次/分，BP116/74mmHg。神志清楚，查体合作。四肢及躯干可见散在针尖样瘀点及大小不等瘀斑，无高出皮面，压之不褪色，口腔黏膜可见出血点。浅表淋巴结未触及肿大。心肺听诊未见异常。腹平软，肝脾肋下未触及。","辅助检查":"检查计划：患者1周前无明显诱因出现四肢散在皮肤瘀点、瘀斑，伴牙龈出血、鼻出血，无发热、无关节痛，发病前无病毒感染、疫苗接种及肝素、奎宁等药物服用史，无肝病及自身免疫病史，临床考虑免疫性血小板减少症可能，故完善血常规+网织红细胞检查明确血小板计数及骨髓代偿情况，据血小板<100×10⁹/L确定血小板减少并评估出血风险；完善外周血涂片检查排除假性血小板减少（EDTA依赖性聚集）并观察有无异常细胞，鉴别白血病等血液系统疾病；完善凝血功能检查排除凝血功能障碍所致出血；完善腹部超声（肝脾淋巴结）、淋巴结超声检查排除脾功能亢进、肝病及淋巴增殖性疾病等继发因素；为明确骨髓巨核细胞数量及成熟障碍情况、排除再生障碍性贫血及骨髓增生异常综合征，完善骨髓穿刺+活检，必要时完善流式细胞术及染色体核型分析明确有无血液系统恶性疾病，上述检查安排在血小板相对安全、病情稳定后完成；补充免疫球蛋白、抗核抗体及甲状腺功能检查，排除自身免疫性疾病及感染相关继发性血小板减少。血小板<20×10⁹/L或急性出血明显者需立即收住院，警惕颅内出血等严重并发症，住院期间每日复查血常规监测血小板变化。\n\n（检查清单）\n【必做检查】\n血常规+网织红细胞、外周血涂片、凝血功能\n\n【影像学检查】\n腹部超声（肝脾淋巴结）、淋巴结超声\n\n【其他检查】\n骨髓穿刺+活检、流式细胞术、染色体核型分析","初步诊断":"1. 血小板减少性紫癜（免疫性血小板减少症可能性大，需结合血常规确诊）\n（注：血常规示血小板减少（<100×10⁹/L），需排除假性血小板减少、白血病、再障、脾亢、药物及感染相关等继发原因；急性出血明显或血小板<20×10⁹/L者收住院治疗（糖皮质激素、静脉丙种球蛋白）；警惕颅内出血等严重出血并发症。）","处理方案":"【药物治疗】\n1. 糖皮质激素（一线首选）：醋酸泼尼松片1mg/(kg·d)晨起顿服，成人常规剂量30-60mg/d，用药2-4周后血小板升至50×10⁹/L以上时开始减量，每周递减5mg，总疗程3-6个月，不可骤然停药，减量过程中血小板下降时恢复原剂量。\n2. 血小板生成素受体激动剂（激素疗效不佳、依赖或复发时）：艾曲泊帕乙醇胺片25mg qd，空腹（餐前1小时或餐后2小时）口服，用药2周后复查血常规，根据血小板计数调整剂量，最大75mg/d，血小板稳定≥50×10⁹/L后逐步减至最小维持量。\n3. 重度血小板减少（PLT<20×10⁹/L）伴出血风险增高时：重组人血小板生成素（rhTPO）300U/kg皮下注射qd，连用14天；若出现活动性出血或黏膜出血，立即转急诊给予静脉注射用人免疫球蛋白（IVIG）400mg/(kg·d)×5天，必要时输注血小板。\n【一般治疗及生活指导】\n1. 休息与活动：血小板<30×10⁹/L或有活动性出血时卧床休息，避免剧烈运动、重体力劳动及骑车、对抗性运动等易致外伤的活动。\n2. 饮食：进温凉软食，避免坚硬、带骨刺、过烫及粗糙食物，禁饮酒，适当增加富含维生素C及优质蛋白的饮食（瘦肉、蛋、奶、新鲜蔬果）。\n3. 禁忌与防护：禁用阿司匹林、布洛芬等抗血小板及非甾体抗炎药；避免肌内注射及不必要的有创操作；使用软毛牙刷，刷牙动作轻柔，避免用力擤鼻、抠鼻、掏耳；保持大便通畅，避免用力排便。\n4. 自我观察：每日注意皮肤瘀点瘀斑、牙龈出血、鼻腔出血情况，女性患者注意月经量变化，出现异常及时就医。\n【随诊要求】\n1. 治疗初期每1-2周复查血常规（血小板计数）及出血倾向评估；激素减量期间每2-4周复查，直至停药后稳定。\n2. 长期使用糖皮质激素者每1-3个月监测血糖、血压、血脂、电解质及骨密度，常规补充钙剂和维生素D，注意预防感染。\n3. 使用艾曲泊帕期间定期监测血常规及肝功能，稳定后每月复查1次。\n4. 如出现鼻出血不止、口腔血疱、黑便、血尿、剧烈头痛伴呕吐或意识改变，立即急诊就诊，不可等待门诊复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":254,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"40420cded20b211f7dd5e89586389436825cc5a8df3d0012049eab976c5cecfc","pinyin":"xuexiaobanjianshaoxingzidian","initials":"xxbjsxzd","setting":"out","caseName":"门诊病历119","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历119",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f179173a6265bb54ab78","key":"v1-c9ccc21dfe2a3058|templates-f179173a6265bb54ab78","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"过敏性紫癜","category":"门诊病历模板","raw":{"name":"过敏性紫癜","category":"门诊病历模板","case":{"case_name":"门诊病历120","templates":{"主诉":"双下肢皮肤紫癜伴腹痛、关节痛5天。","现病史":"患者于2周前有上呼吸道感染史，5天前出现双下肢及臀部对称性紫癜，呈鲜红色后转暗红色，略高出皮面，压之不褪色，伴腹痛、恶心呕吐及踝、膝关节肿痛，无发热，无便血及黑便。发病前无进食海鲜及服用药物（抗生素等）等诱因。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P88次/分，R18次/分，BP112/70mmHg。神志清楚，查体合作。双下肢及臀部可见对称分布、大小不等的紫红色斑丘疹，高出皮面，压之不褪色，部分融合，无破溃。腹平软，脐周压痛（+），无反跳痛及肌紧张。踝关节肿胀、压痛、活动受限（+）。双肾区无叩击痛。","辅助检查":"检查计划：患者2周前有上呼吸道感染史，5天前出现双下肢及臀部对称性紫癜、略高出皮面、压之不褪色，伴腹痛、恶心呕吐及踝膝关节肿痛，临床诊断过敏性紫癜（混合型：腹型合并关节型，即IgA血管炎），故完善血常规检查明确血小板计数及有无感染征象，排除血小板减少性紫癜等出血性疾病；本病易累及肾脏，完善尿常规检查明确有无血尿、蛋白尿以判断有无肾型受累，并作为基线长期随访（至少6个月）；患者有腹痛、恶心呕吐，完善便常规（含隐血）检查明确有无消化道出血，鉴别腹型紫癜所致；患者需用糖皮质激素及NSAIDs治疗，完善肝肾功能、血糖、血脂、电解质检查排除肝肾功能不全、糖代谢异常及电解质紊乱，为用药安全性提供依据；完善心电图检查排除心律失常及心肌受累；完善胸部X线片检查排除肺部感染及结核等感染灶；完善腹部超声检查了解腹腔及肠管情况，若腹痛剧烈伴血便需警惕肠套叠、肠穿孔，及时完善立位腹部平片或腹部CT检查明确急腹症；按病情需要选择相应检查，治疗期间定期复查尿常规、便常规及肾功能评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 过敏性紫癜（混合型：腹型合并关节型）\n（注：本病为IgA血管炎；轻症皮肤型可观察或予抗组胺药、维生素C；伴明显关节痛予NSAIDs；腹型（腹痛、消化道出血）或肾型（血尿、蛋白尿）及重症者需住院，予糖皮质激素（泼尼松1~2mg/kg/d）治疗并随访尿常规至少6个月；腹痛剧烈伴血便者警惕肠套叠、肠穿孔等急腹症。）","处理方案":"【药物治疗】\n1. 抗组胺药（缓解皮肤瘙痒、减轻过敏反应）：氯雷他定片10mg qd×7天，或西替利嗪片10mg qd×7天。\n2. 改善血管通透性药物（降低毛细血管脆性）：维生素C片0.2g tid×14天，联合曲克芦丁片60mg tid×14天。\n3. 糖皮质激素（关节肿痛、明显腹痛或肾脏受累者）：醋酸泼尼松片30mg qd晨起顿服（按0.5-1mg/kg/d折算），症状缓解后每1-2周减量5mg，总疗程4-8周，不可骤然停药。\n4. 感染诱因处理：伴上呼吸道感染等明确诱因者加用阿莫西林胶囊0.5g tid×5天；青霉素过敏者改用头孢呋辛酯片0.25g bid×5天。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，避免剧烈活动及劳累，一般休息2-4周，待皮疹消退、症状缓解后逐渐恢复日常活动。\n2. 饮食：急性期予清淡易消化饮食，避免鱼虾蟹、蛋、牛奶、花生等高致敏食物及辛辣刺激性食物；腹痛明显者暂进流质或半流质饮食、少食多餐；出现肉眼血尿或肾功能异常者限制蛋白质及盐的摄入。\n3. 皮肤护理：保持皮肤清洁干燥，穿宽松棉质衣物，避免搔抓、热水烫洗及外伤，防止皮损破溃继发感染。\n4. 去除诱因：注意保暖、预防上呼吸道感染；停用并避免再次接触可疑致敏药物或食物，避免蚊虫叮咬及花粉等过敏原刺激。\n\n【随诊要求】\n1. 每周复诊1次，观察皮疹消长、有无新发瘀点及关节肿痛、腹痛变化，评估疗效与药物不良反应。\n2. 病程中每1-2周复查尿常规及尿沉渣镜检，至少监测随访6个月，以便及早发现紫癜性肾炎；出现肉眼血尿、蛋白尿、水肿或血压升高时随时就诊。\n3. 泼尼松减量期间遵医嘱按时复诊调整剂量，不可自行增减或骤停；出现黑便、呕血、剧烈腹痛或发热等紧急情况立即就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":255,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1fdff07c60a0f830beecda48e087b77611e9e34aa06e599877dd0d8d2fedf8a3","pinyin":"guominxingzidian","initials":"gmxzd","setting":"out","caseName":"门诊病历120","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历120",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3f56da4d7612ac0c8009","key":"v1-c9ccc21dfe2a3058|templates-3f56da4d7612ac0c8009","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋巴瘤","category":"门诊病历模板","raw":{"name":"淋巴瘤","category":"门诊病历模板","case":{"case_name":"门诊病历121","templates":{"主诉":"颈部淋巴结无痛性肿大2月，伴发热、盗汗4周","现病史":"患者于2月前无意中发现颈部淋巴结肿大，无疼痛，进行性增大，可融合，4周前出现发热（体温最高38.5℃，多为间断低-中度热）、夜间盗汗、皮肤瘙痒、体重下降约6kg（6个月内下降超过10%）。无饮酒后淋巴结疼痛，无咳嗽气促、腹痛腹胀等压迫症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P92次/分，R20次/分，BP118/72mmHg。神志清楚，慢性病容。颈部可触及多发肿大淋巴结，最大约3cm×2.5cm，质韧，活动度差，无压痛，可融合。心肺听诊未见明显异常。腹平软，肝脾肋下未触及肿大。双下肢无水肿。","辅助检查":"【必做】血常规、血沉、乳酸脱氢酶（LDH）、肝肾功能、β2微球蛋白；【影像学】颈部、胸部、腹部、盆腔CT（评估肿大淋巴结及纵隔、腹膜后等深部病灶）、PET-CT（分期及疗效评估）；【确诊】淋巴结完整切除活检+病理及免疫组化（金标准，切勿行细针穿刺诊断）、骨髓穿刺及活检（分期）。","初步诊断":"1. 淋巴瘤？（待病理确诊及分型）\n（注：淋巴瘤诊断依赖病理（淋巴结完整切除活检），分型（霍奇金或非霍奇金及亚型）决定治疗方案；确诊后按分期（Ann Arbor分期）及预后分层选择化疗（如弥漫大B细胞淋巴瘤R-CHOP）、放疗、靶向或免疫治疗，转血液科或肿瘤科专科治疗；出现上腔静脉压迫、脊髓压迫、高肿瘤负荷综合征者需急诊处理。）","处理方案":"【药物治疗】\n1. 靶向治疗：利妥昔单抗注射液375mg/m²，静脉滴注，d1，每21天为1周期，联合CHOP方案（R-CHOP）作为CD20阳性弥漫大B细胞淋巴瘤一线标准方案，共6-8周期；用药前予对乙酰氨基酚0.5g、苯海拉明20mg肌注及地塞米松5mg静注预防输注反应。\n2. 化疗（CHOP方案）：环磷酰胺750mg/m²静脉滴注d1；多柔比星50mg/m²静脉滴注d1；长春新碱1.4mg/m²（单次总量≤2mg）静脉推注d1；泼尼松100mg口服d1-5。每21天重复，化疗前后予托烷司琼5mg或昂丹司琼8mg静脉止吐。\n3. 预防肿瘤溶解综合征：别嘌醇片0.1g口服tid，化疗前3天开始，连用至化疗结束后1周，化疗期间每日复查尿酸、血钾、血磷、血钙及肌酐；水化2000-3000ml/日。\n4. 支持治疗：化疗后第7-14天骨髓抑制期若中性粒细胞<1.0×10⁹/L，予重组人粒细胞集落刺激因子150μg皮下注射qd，至中性粒细胞≥2.0×10⁹/L；HB<70g/L或PLT<20×10⁹/L时予成分输血。\n\n【一般治疗及生活指导】\n1. 休息：化疗期间及化疗后2周内注意休息、保证充足睡眠，避免熬夜及过度劳累；发热、乏力明显或粒细胞缺乏时卧床休息。\n2. 饮食：高蛋白、高维生素、易消化饮食（鸡蛋、鱼肉、瘦肉、豆制品及新鲜蔬果），少量多餐；化疗期间禁食生冷、辛辣刺激食物；粒细胞缺乏期注意饮食卫生，禁食生鱼片、凉拌菜及未彻底加热食物，水果削皮食用。\n3. 活动：缓解期可适度进行散步、太极拳等有氧运动，循序渐进；避免剧烈运动及磕碰挤压，注意皮肤黏膜护理，刷牙用软毛牙刷防出血；纵隔或腹腔巨大肿块者减少活动，出现胸闷、呼吸困难、腹痛腹胀立即就诊。\n4. 禁忌：戒烟戒酒；化疗及免疫抑制期间避免接种活疫苗（麻疹、水痘、带状疱疹等）；避免去人群密集场所，外出佩戴口罩，减少呼吸道及皮肤感染风险；避免染发及接触苯等化学物质。\n\n【随诊要求】\n1. 按R-CHOP方案每21天返院行下一周期化疗，勿自行推迟或中断；每周期化疗前复查血常规、肝肾功能、心电图及心肌酶（监测多柔比星心脏毒性，累积剂量>450mg/m²时慎用）。\n2. 每2-3周期行疗效评估：颈部/胸/腹/盆腔增强CT或PET-CT、血清LDH及β2-微球蛋白；评估达CR后完成既定周期数并定期巩固随访。\n3. 治疗结束后第1-2年每3个月复诊1次，第3年每6个月1次，以后每年1次，复查血常规、LDH、β2-微球蛋白及影像学；若出现不明原因发热、盗汗、体重下降、浅表淋巴结进行性肿大或压迫症状，随时就诊。\n4. 长期随访监测远期毒性：含蒽环类药物者每年复查超声心动图；曾行放疗者监测甲状腺功能及第二肿瘤风险；同时监测乙肝病毒再激活（利妥昔单抗治疗后每3-6个月复查HBsAg/HBV-DNA）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":256,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d346dfecc14359c2db36461d9bdc53195b5072149ba8a272bd2dc622d09afef6","pinyin":"linbaliu","initials":"lbl","setting":"out","caseName":"门诊病历121","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历121",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bb3fdd31c25ebe84001f","key":"v1-c9ccc21dfe2a3058|templates-bb3fdd31c25ebe84001f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"系统性红斑狼疮","category":"门诊病历模板","raw":{"name":"系统性红斑狼疮","category":"门诊病历模板","case":{"case_name":"门诊病历122","templates":{"主诉":"面部红斑、多关节肿痛伴发热、脱发2个月。","现病史":"患者于2月前渐出现面部蝶形红斑、对称性多关节肿痛（双手近端指间、掌指、腕、膝等），伴发热（多为低-中度热）、脱发、口腔溃疡、光过敏，无胸痛气短、血尿水肿、精神异常及抽搐等脏器受累表现。无长期服用肼苯哒嗪、普鲁卡因胺等药物史。无类似疾病家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P88次/分，R18次/分，BP112/70mmHg。神志清楚。面部可见蝶形红斑（两侧颧部跨鼻梁，界清），口腔黏膜溃疡，脱发（+）。双手关节肿胀压痛，无畸形。心肺听诊未见异常。腹平软。双下肢无水肿。","辅助检查":"检查计划：患者2个月前渐出现面部蝶形红斑、对称性多关节肿痛（双手近端指间、掌指、腕、膝），伴发热、脱发、口腔溃疡及光过敏，无长期服用肼苯哒嗪、普鲁卡因胺等药物史，临床疑诊系统性红斑狼疮、活动度待评估，故完善抗核抗体谱（ANA、抗dsDNA、抗Sm等）检查明确诊断并评估疾病活动度，符合2019年EULAR/ACR分类标准；患者有发热，完善血常规、血沉、CRP检查鉴别感染与疾病活动，并了解有无血液系统受累（白细胞、血小板减少及溶血性贫血）；患者对称性多关节肿痛需与其他关节病鉴别，完善类风湿因子、抗CCP抗体检查除外类风湿关节炎，完善HLA-B27检查鉴别脊柱关节病；完善关节X线或超声检查了解关节滑膜炎、关节积液及骨破坏情况，必要时完善关节MRI检查早期发现关节及骨病变；完善免疫球蛋白及补体（C3、C4）检查反映疾病活动度及免疫复合物消耗情况；患者为育龄女性且有血栓风险，完善抗磷脂抗体检查评估抗磷脂综合征及血栓、病态妊娠风险；补充尿常规及肾功能检查筛查狼疮性肾炎，必要时完善24小时尿蛋白定量及肾活检，明确脏器受累并指导糖皮质激素与免疫抑制剂方案。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、类风湿因子、抗CCP抗体、抗核抗体谱\n\n【影像学检查】\n关节X线或超声、关节MRI（必要时）\n\n【其他检查】\n免疫球蛋白、补体、抗磷脂抗体、HLA-B27","初步诊断":"1. 系统性红斑狼疮（疑诊，活动度待评估）\n（注：诊断需结合临床表现+自身抗体（抗核抗体ANA、抗dsDNA、抗Sm等）+脏器受累评估（2019年EULAR/ACR分类标准）；轻症（皮疹、关节痛）：羟氯喹0.2g bid+NSAIDs；中重度（肾炎、血液系统、神经精神受累）：糖皮质激素（泼尼松0.5~1mg/kg/d）+免疫抑制剂（环磷酰胺/吗替麦考酚酯/硫唑嘌呤等）；强调防晒、避免感染，请风湿免疫科专科管理，妊娠需计划并在专科指导下方可。）","处理方案":"【药物治疗】\n1. 糖皮质激素（基础用药）：泼尼松片0.5~1mg/kg/d（成人常用30~60mg/d）晨起顿服，病情缓解后每1~2周递减5mg，减至维持量5~10mg/d长期口服，疗程至少1年以上，切忌自行骤停。\n2. 羟氯喹（所有无禁忌SLE患者均建议使用）：硫酸羟氯喹片0.2g bid（或0.4g qd）餐后口服，长期维持（疗程≥1年），服药期间每6~12个月行眼科检查（眼底+视野）监测视网膜毒性。\n3. 免疫抑制剂（中重度活动性狼疮、激素疗效不佳或减量复发时加用）：霉酚酸酯胶囊0.5g bid口服，或硫唑嘌呤片50mg bid口服，维持6~12个月；或环磷酰胺静脉冲击0.5~1.0g/m²，每月1次，连用6个月后评估。\n4. 对症治疗：狼疮性肾炎伴蛋白尿者加用贝那普利片10mg qd口服（ACEI/ARB降尿蛋白）；关节炎明显者可短期加用布洛芬缓释胶囊0.3g bid（活动期慎用，肾功能不全者禁用）。\n\n【一般治疗及生活指导】\n1. 严格防晒：避免阳光及紫外线直接照射，外出穿长袖衣裤、戴宽檐帽、涂SPF≥50防晒霜，避免去高原、海边等强紫外线环境。\n2. 休息与活动：疾病活动期卧床休息，避免劳累及精神紧张；缓解期可进行散步、太极等温和运动，注意劳逸结合，保证充足睡眠。\n3. 饮食：清淡均衡饮食，多摄入优质蛋白和维生素；少食芹菜、香菜、无花果、蘑菇等光敏性食物，避免辛辣刺激及烟酒；合并肾损害者低盐（<5g/d）及限制蛋白摄入。\n4. 禁忌：避免使用可诱发或加重狼疮的药物（磺胺类、肼苯哒嗪、普鲁卡因胺、米诺环素等）；活动期严格避孕（禁用含雌激素避孕药），备孕患者病情稳定≥6个月后由风湿免疫科和产科共同评估；避免染发、纹眉等化学刺激，预防感染。\n\n【随诊要求】\n1. 复诊频率：疾病活动期每2~4周复诊1次，缓解期每1~3个月复诊1次；病情稳定后可延长至每3~6个月1次，长期随访。\n2. 复查项目：每次复诊查血尿常规、肝肾功能、血沉、CRP、补体C3/C4、抗ds-DNA抗体，狼疮性肾炎者定期查24小时尿蛋白定量、尿沉渣镜检及血压。\n3. 用药监测：长期服激素者监测血压、血糖、血脂、电解质及骨密度，注意预防感染和骨质疏松；服免疫抑制剂者每1~3个月复查肝肾功能和血常规。\n4. 出现发热、皮疹加重、关节肿痛、脱发、口腔溃疡、胸闷气促、肉眼血尿、抽搐或精神异常等新症状时，须立即就诊，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":257,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"398f4e396d4c44fb08b0f3ecff8edddc53541fc2baed642a396c6de04474816c","pinyin":"xitongxinghongbanlangchuang","initials":"xtxhblc","setting":"out","caseName":"门诊病历122","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历122",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4bdaffe7304d445d5222","key":"v1-c9ccc21dfe2a3058|templates-4bdaffe7304d445d5222","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"干燥综合征","category":"门诊病历模板","raw":{"name":"干燥综合征","category":"门诊病历模板","case":{"case_name":"门诊病历123","templates":{"主诉":"口干、眼干伴双侧腮腺肿痛6月","现病史":"患者于6月来渐出现眼干（眼内砂砾感、异物感、畏光）、口干（需频繁饮水、进干食困难、龋齿增多），反复双侧腮腺肿痛，无关节痛、皮疹、咳嗽气短及肾小管酸中毒表现，无夜尿增多、低钾乏力。无类风湿关节炎、系统性红斑狼疮等病史，无抗胆碱能药物用药史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP110/70mmHg。神志清楚，查体合作。双侧腮腺肿大，质软，无压痛，挤压腮腺导管口分泌物减少。口腔黏膜干燥，舌面干裂、光滑（镜面舌），龋齿增多。双眼球结膜充血，泪液分泌减少。关节无红肿。心肺听诊未见异常。","辅助检查":"检查计划：患者6个月来渐出现眼干（眼内砂砾感、异物感、畏光）、口干（需频繁饮水、进干食困难、龋齿增多），反复双侧腮腺肿痛，无关节痛、皮疹、咳嗽气短及肾小管酸中毒表现，临床疑诊原发性干燥综合征，故完善抗核抗体、抗SSA及抗SSB抗体检查明确诊断依据，并完善类风湿因子检查辅助判断有无继发于类风湿关节炎及淋巴增殖风险；完善血常规、血沉、CRP检查了解有无贫血、白细胞及血小板减少和炎症活动程度；患者反复腮腺肿痛，完善免疫球蛋白（IgG升高常见）检查了解免疫球蛋白水平及有无高球蛋白血症，辅助评估病情活动与淋巴瘤风险；眼部症状明显，完善泪液分泌试验（Schirmer试验）及角膜染色检查客观评估眼干程度与角膜上皮损伤；口干明显，完善唾液流率测定评估唾液腺分泌功能；为确诊并判断腺体淋巴细胞浸润程度，完善唇腺活检明确有无灶性淋巴细胞浸润（诊断金标准），该项有创检查安排在病情稳定后择期完成；本病可累及肾小管，完善尿常规及血气检查筛查有无肾小管酸中毒及间质病变。腮腺持续肿大者需定期复查并警惕淋巴瘤，请风湿免疫科专科随访。\n\n（检查清单）\n【必做】血常规、血沉、CRP、免疫球蛋白（IgG升高常见）、抗核抗体、抗SSA及抗SSB抗体（阳性支持诊断）、类风湿因子；【其他】泪液分泌试验（Schirmer试验）、角膜染色、唾液流率测定、唇腺活检（灶性淋巴细胞浸润，为诊断金标准）、尿常规及血气（肾小管受累筛查）。","初步诊断":"1. 干燥综合征（原发性，疑诊）\n（注：诊断依据口干眼干症状+客观检查（Schirmer、唇腺活检）+抗SSA及抗SSB；对症治疗：人工泪液（玻璃酸钠滴眼液）、毛果芸香碱促分泌；羟氯喹用于关节痛等系统表现；需筛查及处理内脏受累（肺间质病变、肾小管酸中毒、淋巴瘤风险，腮腺持续肿大需警惕）；请风湿免疫科专科随访。）","处理方案":"【药物治疗】\n1. 改善眼干：玻璃酸钠滴眼液（0.1%）1滴 每日4～6次，睡前加用卡波姆眼用凝胶1次；症状重者可联合环孢素A滴眼液（0.05%）1滴 bid。\n2. 改善口干：毛果芸香碱片5mg tid，进餐时服用，疗程3～6个月；或环戊硫酮片25mg tid。\n3. 免疫调节（伴关节痛、乏力、腮腺肿大等系统表现者）：羟氯喹片0.2g bid，连用3～6个月后评估疗效，病情稳定可减至0.2g/d长期维持。\n4. 关节或肌肉疼痛明显者：洛索洛芬钠片60mg tid，或塞来昔布胶囊0.2g qd，症状缓解即停，总疗程不超过2周。\n\n【一般治疗及生活指导】\n1. 饮食：清淡易消化，多饮水，以流质、半流质或湿润食物辅助吞咽，细嚼慢咽，避免辛辣、过烫及干硬粗糙食物。\n2. 口腔护理：早晚用含氟牙膏刷牙，餐后及时漱口，定期口腔科检查，预防龋齿及口腔念珠菌感染。\n3. 生活起居：避免长时间用眼及空调、干燥环境，居室保持湿度（可用加湿器）；外出佩戴防风镜或防护眼镜；注意眼部卫生，勿揉眼。\n4. 禁忌：戒烟限酒；避免患者抗胆碱能药物（阿托品类）及加重口干的药物（部分抗组胺药、利尿剂等）；育龄期女性用药前咨询医生（羟氯喹孕期患者需评估）。\n\n【随诊要求】\n1. 每1～3个月门诊复诊1次，评估眼干、口干、关节痛等症状改善及药物耐受情况；服用羟氯喹者每6～12个月行眼底及视野检查，监测视网膜毒性。\n2. 每6～12个月复查血常规、肝肾功能、免疫球蛋白、血沉、C反应蛋白及抗SSA及抗SSB抗体等免疫指标，监测病情活动度。\n3. 警惕系统受累，出现持续发热、腮腺快速肿大、干咳气短、紫癜、下肢水肿或不明原因血尿等，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":258,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"be158e82802a408d9a5c30dc5edd12e701bc3efceea75809ae06a8e53af62ee5","pinyin":"ganzaozonghezheng","initials":"gzzhz","setting":"out","caseName":"门诊病历123","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历123",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c079f9eeb58a0bfc57bf","key":"v1-c9ccc21dfe2a3058|templates-c079f9eeb58a0bfc57bf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨关节炎","category":"门诊病历模板","raw":{"name":"骨关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历124","templates":{"主诉":"双膝关节疼痛、僵硬、活动受限5年，加重2周。","现病史":"患者于5年前渐出现双膝关节疼痛，活动（上下楼、下蹲、久行）后加重，休息后减轻，晨僵（持续时间<30分钟），3月来出现关节摩擦感、弹响，活动受限，上下楼困难，无关节红肿热、无发热。无外伤史，无长期负重职业史，无肥胖及家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP124/76mmHg，BMI23.5kg/m²。神志清楚，查体合作。双膝关节骨性膨大，皮温正常，无红斑，关节压痛（+），屈伸活动受限（屈曲约110°），活动时摩擦感，浮髌试验阴性，无关节积液，膝内翻畸形（晚期），双下肢肌力正常，足背动脉搏动正常。","辅助检查":"检查计划：患者双膝关节疼痛、僵硬、活动受限5年，近2周加重，上下楼及下蹲后疼痛明显、休息可减轻，晨僵不足30分钟，近3月出现关节摩擦感、弹响，初步诊断为双膝骨关节炎Ⅲ期，检查以明确诊断、评估病情程度并排除其他关节疾病为目的。完善血常规检查排除感染性关节炎及贫血所致乏力；完善血沉、CRP检查了解有无全身炎症活动，排除类风湿关节炎等炎症性关节病；患者下肢负重关节长期疼痛，完善双膝关节正侧位X线片了解关节间隙狭窄、软骨下骨硬化、骨赘形成及力线情况，作为分期与疗效随访的基线；患者以骨摩擦感、弹响及活动受限为主要表现，必要时完善膝关节CT检查明确关节内游离体、软骨下骨囊变，必要时完善膝关节MRI检查明确半月板、交叉韧带及软骨损伤，鉴别半月板损伤所致机械性症状；因关节退变常伴骨代谢异常，完善血钙、磷及碱性磷酸酶检查了解骨代谢状况，排除甲状旁腺功能异常及骨软化症；患者为绝经后女性，完善骨密度检查评估有无骨质疏松，指导抗骨质疏松治疗及补钙方案；关节肿胀明显时完善关节超声检查了解滑膜增厚、关节积液及软骨表面情况；若出现下肢麻木、放射痛等神经症状，完善肌电图检查排除腰椎间盘突出所致周围神经损害；患者为多关节受累，完善类风湿因子检查鉴别类风湿关节炎，完善HLA-B27检查鉴别脊柱关节炎。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙、磷、碱性磷酸酶\n\n【影像学检查】\n双膝关节正侧位X线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 骨关节炎（双膝，Ⅲ期）\n（注：基础治疗：控制体重、股四头肌锻炼、物理治疗、避免爬山爬楼等加重活动；药物：外用药（双氯芬酸二乙胺乳胶剂）首选，疼痛明显口服对乙酰氨基酚或NSAIDs（塞来昔布200mg qd，短期）；关节腔注射玻璃酸钠（润滑）或糖皮质激素（急性积液）；终末期严重影响生活者关节置换术评估。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（外用首选）：双氯芬酸二乙胺乳胶剂（扶他林）外用涂患处，每次约3-5cm膏体，轻揉至吸收，每日2-3次，疗程1-2周；疼痛明显影响活动时加用口服塞来昔布胶囊0.2g qd，餐后服，连续不超过1周，用药前评估胃肠道及心血管风险。\n2. 镇痛药：对乙酰氨基酚片0.5g 按需口服，每日不超过2g，连续使用不超过5天，用于轻中度疼痛的短期缓解。\n3. 延缓进展类药物：硫酸氨基葡萄糖胶囊0.75g bid 餐后服，疗程6周-3个月，每年可重复2-3个疗程；伴明显炎症表现者可加用双醋瑞因胶囊50mg bid 餐后服。\n4. 关节腔注射（中重度疼痛或关节积液明显者）：玻璃酸钠注射液2ml 关节腔注射，每周1次，连用3-5周为1疗程；注射当日避免负重及剧烈活动。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性疼痛期适当减少负重活动，避免长时间站立、上下楼梯、爬山、深蹲及跪姿；疼痛缓解后循序渐进恢复日常活动。\n2. 运动疗法：每日进行股四头肌等长收缩及直腿抬高训练，每次10-15分钟、每日2-3次；推荐游泳、散步、骑固定自行车等低冲击有氧运动，避免跑跳等冲击性运动。\n3. 体重与饮食：超重或肥胖者应积极减重（体重每下降1kg可显著减轻膝关节负荷）；均衡饮食，适量摄入奶制品、豆制品等富钙食物，必要时口服钙剂及维生素D补充。\n4. 禁忌与防护：避免关节受凉、受潮；避免关节过度劳损及外伤；行走时可使用手杖、护膝等辅助器具以减轻关节负荷。\n\n【随诊要求】\n1. 用药后1-2周复诊，评估疼痛缓解程度及药物耐受情况；症状无改善或进行性加重者及时复诊。\n2. 需长期口服非甾体抗炎药者，每1-3个月监测肝肾功能、血压及消化道症状；出现黑便、呕血、上腹痛等立即就诊。\n3. 关节腔注射后出现关节红肿、发热、剧痛或活动受限加重者，立即复诊。\n4. 每3-6个月复诊评估关节功能、疼痛评分及病情进展，必要时复查膝关节X线或MRI以评估关节结构变化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":259,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"45200d275822c537112214f8dc47b9089aca032b9ecd184e3ddd0162cd802f0e","pinyin":"guguanjieyan","initials":"ggjy","setting":"out","caseName":"门诊病历124","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历124",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-de372b54ebaf5863e652","key":"v1-c9ccc21dfe2a3058|templates-de372b54ebaf5863e652","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性扁桃体炎","category":"门诊病历模板","raw":{"name":"急性扁桃体炎","category":"门诊病历模板","case":{"case_name":"门诊病历125","templates":{"主诉":"咽痛伴发热3天，吞咽时加重。","现病史":"患者于3天前受凉后出现咽痛，吞咽时加重，伴发热，体温最高39.0℃，畏寒，乏力，无咳嗽咳痰，无呼吸困难，无张口受限。无反复扁桃体炎发作史。自服感冒药（药名不详）效果欠佳。今日来我院门诊就诊。发病以来精神差，食欲减退，睡眠欠佳，大小便正常。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.0℃，P104次/分，R22次/分，BP110/70mmHg。神志清楚，急性病容。咽部黏膜充血明显，双侧扁桃体Ⅱ度肿大，表面可见黄白色脓点，腭弓充血，下颌角淋巴结肿大、压痛。心肺听诊未见明显异常。","辅助检查":"【必做】血常规（白细胞及中性粒细胞比例升高提示细菌感染）、CRP；【其他】咽拭子培养（明确病原菌及药敏，反复发作或治疗无效时）。","初步诊断":"1. 急性扁桃体炎（急性化脓性扁桃体炎）\n（注：细菌性（链球菌多见）予青霉素（阿莫西林0.5g tid×5~7天，需皮试）、头孢类或阿奇霉素；对症：解热镇痛（对乙酰氨基酚或布洛芬）、温盐水漱口、多饮水休息；若出现一侧咽痛加剧、张口受限、语音含糊提示扁桃体周围脓肿，需耳鼻喉科穿刺或切开引流；反复发作（每年≥5次）考虑扁桃体切除。）","处理方案":"【药物治疗】\n1. 阿莫西林胶囊 0.5g 口服 tid×5～7天（用药前须青霉素皮试阴性）；对青霉素过敏者改用阿奇霉素片 0.5g 口服 qd×3天，或头孢呋辛酯片 0.25g 口服 bid×5～7天。\n2. 布洛芬缓释胶囊 0.3g 口服 bid（体温≥38.5℃或咽痛明显影响进食时临时服用，退热镇痛，餐后服，疗程一般3天以内）。\n3. 复方氯己定含漱液 10ml 含漱 bid～tid，含漱1分钟后吐出，漱后30分钟内勿饮水进食。\n4. 蓝芩口服液 10ml 口服 tid×5天，或西瓜霜润喉片 含服 1～2片 qid，缓解咽痛。\n\n【一般治疗及生活指导】\n1. 注意休息，保证充足睡眠，避免劳累；急性期适当居家休息，减少工作及体力活动。\n2. 多饮水，每日1500～2000ml温开水；饮食清淡易消化，进食流质或半流质（米粥、烂面条、蛋羹等），忌辛辣刺激、过烫、过硬及油炸食物，戒烟酒。\n3. 保持口腔清洁，餐后以温淡盐水或清水漱口；避免长时间大声说话及用力咳嗽，减少对咽部刺激。\n4. 注意呼吸道隔离，勤洗手，居室通风，与家人分餐、分用毛巾，避免交叉感染；发热期间注意保暖、及时擦干汗液。\n\n【随诊要求】\n1. 用药3天后症状无好转或加重（持续高热不退、咽痛加剧、吞咽困难、张口受限、一侧咽痛剧烈、呼吸不畅、流涎等），应尽快复诊，必要时查血常规及CRP、咽拭子培养调整治疗。\n2. 症状缓解、停药后仍出现关节疼痛、眼睑或下肢水肿、血尿、心悸、皮疹等情况，及时复诊排除风湿热、急性肾小球肾炎等并发症。\n3. 疗程结束（5～7天）后复诊评估扁桃体炎症消退情况；反复发作（1年内≥3次或连续2年内≥5次急性扁桃体炎）者，建议至耳鼻喉科进一步评估是否需要手术干预。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":260,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"059934e6335e5d43fa29523a1303cb14262a5f3c446c0a4813aa5ba525c1669f","pinyin":"jixingbiantaotiyan","initials":"jxbtty","setting":"out","caseName":"门诊病历125","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历125",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1985f57749bfc4c12eb1","key":"v1-c9ccc21dfe2a3058|templates-1985f57749bfc4c12eb1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性咽炎","category":"门诊病历模板","raw":{"name":"急性咽炎","category":"门诊病历模板","case":{"case_name":"门诊病历126","templates":{"主诉":"咽痛、吞咽痛伴咽干、灼热感2天。","现病史":"患者于2天前受凉后出现咽部干燥、灼热感，继而咽痛，吞咽时加重，低热（体温最高37.8℃），无声音嘶哑，无咳嗽咳痰，无呼吸困难。无吸烟、饮酒史，无粉尘及刺激性气体接触史。自服感冒药（药名不详）效果欠佳。今日来我院门诊就诊。发病以来精神可，食欲稍差。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P84次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。咽部黏膜急性弥漫性充血、水肿，咽后壁淋巴滤泡增生，腭弓充血，扁桃体无肿大，无脓性渗出物。下颌角淋巴结轻度肿大。心肺听诊未见明显异常。","辅助检查":"【必做】一般以临床表现为主；【其他】血常规（鉴别病毒或细菌感染）、咽拭子培养（疑链球菌感染时）。","初步诊断":"1. 急性咽炎\n（注：多为病毒感染，以对症治疗为主：休息、多饮水、温盐水漱口、含片（西地碘或西瓜霜）；咽痛明显用对乙酰氨基酚或布洛芬；仅在咽拭子证实链球菌感染或脓性分泌物明显时用抗菌药物（阿莫西林0.5g tid×5天）；戒烟酒及辛辣刺激。）","处理方案":"【药物治疗】\n1. 抗感染治疗：本病多为病毒感染，一般无需常规使用抗菌药物。若伴发热、脓性分泌物或咽拭子提示链球菌感染，可选用阿莫西林胶囊 0.5g 口服 tid×5天；青霉素过敏者改用阿奇霉素片 0.5g 口服 qd×3天。\n2. 对症退热镇痛：对乙酰氨基酚片 0.5g 口服，体温≥38.5℃或咽痛明显时临时服用，间隔4～6小时一次，24小时内不超过4次，疗程≤3天。\n3. 局部用药：西地碘含片（华素片）1.5mg 含服 tid，含服后半小时内不饮水、不进食；复方硼砂溶液含漱 tid～qid。\n4. 中成药辅助：蓝芩口服液 10ml 口服 tid×5～7天，或蒲地蓝消炎口服液 10ml 口服 tid×5天。\n\n【一般治疗及生活指导】\n1. 休息：急性期适当休息，避免劳累、熬夜及过度用声，保证充足睡眠。\n2. 饮食：清淡、易消化饮食，多饮温水（每日1500～2000ml），忌辛辣刺激、过烫、油腻食物，戒烟戒酒。\n3. 防护：保持室内空气流通、湿度适宜；外出佩戴口罩，避免粉尘及刺激性气体，勤洗手，减少呼吸道传播。\n\n【随诊要求】\n1. 若治疗3天后咽痛、发热无缓解或加重，或出现持续高热、呼吸困难、吞咽困难、张口受限、颈部淋巴结肿大等，应及时复诊。\n2. 使用抗菌药物者应足疗程（5天）用药，疗程结束后复诊评估疗效，不可自行停药。\n3. 症状反复发作（1年内≥3次）或病程超过2周者，建议转耳鼻喉科进一步检查，排除慢性咽炎、扁桃体周围脓肿及其他病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":261,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"46186036fe9a96cd07a35ab15398fbaa2575b5e3740c49af2192aa5272ac0f92","pinyin":"jixingyanyan","initials":"jxyy","setting":"out","caseName":"门诊病历126","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历126",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-55e432e03534f268a1c0","key":"v1-c9ccc21dfe2a3058|templates-55e432e03534f268a1c0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性喉炎","category":"门诊病历模板","raw":{"name":"急性喉炎","category":"门诊病历模板","case":{"case_name":"门诊病历127","templates":{"主诉":"声音嘶哑、喉部疼痛伴干咳2天。","现病史":"患者于2天前受凉、用声过度或吸入刺激性气体后出现声音嘶哑，进行性加重，伴喉部干痒、疼痛、刺激性干咳，无发热，体温正常，无呼吸困难、无犬吠样咳嗽、无喘鸣。职业用声（教师、销售等）史：无；烟酒史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P82次/分，R18次/分，BP118/76mmHg。神志清楚，查体合作，发音嘶哑。间接喉镜或电子喉镜检查：喉黏膜弥漫性充血、水肿，声带充血、边缘水肿，闭合欠佳，运动正常，无新生物。咽部轻度充血。心肺听诊未见明显异常。","辅助检查":"【必做】一般以喉镜检查为主；【其他】血常规（发热或疑感染时）、喉动态镜（声音嘶哑迁延不愈时评估声带运动）。","初步诊断":"1. 急性喉炎\n（注：治疗核心为声带休息（禁声、少语）、雾化吸入（布地奈德混悬液1mg bid，减轻声带水肿）、祛痰、抗感染（病毒为主，一般不用抗菌药物；细菌感染征象时阿莫西林0.5g tid）；多饮温水、戒烟酒、避免辛辣；若出现呼吸困难、吸气性喉鸣提示喉梗阻，需急诊处理；声音嘶哑超过2周建议喉镜复查排除声带病变。）","处理方案":"【药物治疗】\n1. 糖皮质激素（缓解喉黏膜水肿，本病核心用药）：布地奈德混悬液1mg（2ml）雾化吸入，每日2次，疗程3-5天；喉水肿明显或声音嘶哑严重者，加用醋酸泼尼松片30mg，每日1次晨起顿服，连用3-5天，症状缓解后逐渐减停。\n2. 抗生素（有脓性分泌物、发热、血白细胞升高等细菌感染证据时使用）：阿莫西林克拉维酸钾片0.625g，每8小时1次，疗程5-7天；青霉素过敏者改用阿奇霉素片0.5g，每日1次，连服3天。\n3. 对症止咳祛痰：干咳明显者予氢溴酸右美沙芬片15mg，每日3次；痰黏难咳者予盐酸氨溴索片30mg，每日3次，疗程5天。\n\n【一般治疗及生活指导】\n1. 严格声带休息：急性期禁声、少语，避免耳语及用力喊叫（耳语更易损伤声带），禁声3-5天，缓解后循序渐进恢复用声。\n2. 饮食：进食清淡、温凉的流质或半流质，多饮温水，忌辛辣、过烫、过冷及油腻食物，戒烟戒酒。\n3. 环境与防护：保持居室空气湿润（湿度50%-60%），避免粉尘、烟雾及刺激性气体刺激，外出可佩戴口罩；避免用力咳嗽和频繁清嗓，防止声带二次损伤。\n\n【随诊要求】\n1. 用药3天后声音嘶哑无明显好转或出现发热持续不退、咳脓痰增多，及时复诊调整治疗方案。\n2. 治疗期间若出现呼吸困难、吸气性喉鸣、喘鸣加重或犬吠样咳嗽加剧，提示喉梗阻风险，须立即就医。\n3. 声音嘶哑持续超过2周不缓解者，建议行电子喉镜检查，排除声带息肉、小结及其他喉部病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":262,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b2d9b22e03aea18ffb7e9f52d3a44e4c74e78e9b477a03c9757353386c4a5c6d","pinyin":"jixinghouyan","initials":"jxhy","setting":"out","caseName":"门诊病历127","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历127",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f935504a2c8662534943","key":"v1-c9ccc21dfe2a3058|templates-f935504a2c8662534943","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中耳炎","category":"门诊病历模板","raw":{"name":"中耳炎","category":"门诊病历模板","case":{"case_name":"门诊病历128","templates":{"主诉":"耳痛伴耳内闷胀感3天。","现病史":"患者于3天前受凉或游泳进水后出现右耳痛，为跳痛，夜间加重，伴耳内闷胀感、听力下降、耳鸣，无耳流脓（如有鼓膜穿孔则出现），低热，体温最高37.8℃，无眩晕。既往无反复中耳炎、鼻炎鼻窦炎及鼓膜穿孔史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P88次/分，R20次/分，BP120/76mmHg。神志清楚，查体合作。右外耳道无分泌物，鼓膜充血、膨隆，乳突区压痛（-）。音叉试验提示传导性听力下降。鼻黏膜充血。","辅助检查":"检查计划：患者3天前受凉或游泳进水后出现右耳跳痛，夜间加重，伴耳内闷胀感、听力下降及耳鸣，低热37.8℃，无声嘶咽痛，初步诊断为急性中耳炎（右），检查以明确感染程度、病原学、并发症及听力损害为目的。完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染并评估炎症程度；行耳镜检查了解鼓膜充血、膨隆、有无穿孔及流脓，为鼓膜切开引流提供依据；患者有鼻塞流涕等上呼吸道感染诱因，完善鼻内镜检查明确鼻咽部及咽鼓管咽口有无肿胀、分泌物及腺样体肥大，评估咽鼓管功能；完善喉镜检查排除咽喉部炎症及分泌物倒流所致耳部症状；完善鼻窦CT检查明确有无鼻窦炎，排除鼻窦炎作为中耳感染的病灶来源；完善颞骨CT检查明确乳突气房及鼓室有无积液、骨质破坏，排除急性乳突炎及胆脂瘤；完善颈部超声检查了解颈部淋巴结有无肿大，评估感染有无扩散；患者伴听力下降、耳鸣，完善纯音测听检查明确听力损失的类型与程度，并作为治疗后复查的基线；完善声导抗检查了解鼓室压及中耳积液情况，判断咽鼓管功能恢复；因患者目前无眩晕，前庭功能检查暂缓，若出现眩晕、平衡障碍时完善以排除前庭功能损害；抗感染治疗5～7天后复查耳镜、纯音测听及声导抗，评估感染控制及听力恢复情况；根据病情需要选择相应检查，必要时留取鼓膜穿刺液行细菌培养及药敏试验，指导抗生素选择。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 急性中耳炎（右）\n（注：细菌性者予阿莫西林克拉维酸0.625g tid×5~7天或头孢类；鼻用减充血剂（羟甲唑啉，不超过7天）改善咽鼓管引流；止痛（对乙酰氨基酚或布洛芬）；鼓膜膨隆剧痛或穿孔流脓不畅者行鼓膜切开引流；治疗后复查听力及鼓膜，迁延不愈或反复发作者耳鼻喉科随访，儿童注意腺样体肥大因素。）","处理方案":"【药物治疗】\n1. 阿莫西林胶囊 0.5g 口服 tid×7天（青霉素过敏者改头孢呋辛酯片 0.25g 口服 bid×7天；用药前询问过敏史）\n2. 盐酸羟甲唑啉滴鼻液 1喷 喷鼻 bid×5天（不超过7天，减轻咽鼓管口黏膜肿胀、改善引流）\n3. 耳痛明显者：布洛芬缓释胶囊 0.3g 口服 必要时q12h，疗程≤3天\n\n【一般治疗及生活指导】\n1. 保持外耳道干燥清洁，洗头、沐浴时以干棉球堵塞耳道，避免污水入耳；禁止游泳、潜水，避免乘坐飞机及气压骤变环境\n2. 勿用力擤鼻及捏住双鼻同时擤涕（应单侧交替），避免感冒、呛奶时感染经咽鼓管逆行扩散至中耳；禁挖耳，忌耳内滴入不洁液体\n3. 充分休息，保证睡眠，多饮水，清淡饮食；戒烟，避免烟雾刺激\n\n【随诊要求】\n用药3天后症状无缓解或出现高热、耳痛加剧、耳后红肿压痛、耳流脓或脓性分泌物增多、面瘫、眩晕者，及时复诊或转耳鼻喉科；急性中耳炎疗程结束后2周复查耳内镜评估鼓膜及中耳腔恢复情况，反复发作或听力下降者行纯音测听及声导抗检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":263,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3a468c4e457f07a43a2dc93bc5448cc96ce940f10b01f5e163ef3750fa5cb3a7","pinyin":"zhongeryan","initials":"zey","setting":"out","caseName":"门诊病历128","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历128",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f102d9ff8879a71f9e82","key":"v1-c9ccc21dfe2a3058|templates-f102d9ff8879a71f9e82","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"鼻窦炎","category":"门诊病历模板","raw":{"name":"鼻窦炎","category":"门诊病历模板","case":{"case_name":"门诊病历129","templates":{"主诉":"鼻塞、流脓涕伴面部胀痛、头痛2周。","现病史":"患者于2周前受凉后出现鼻塞、流涕，初为清涕后转黏脓性，量多，伴面颊部胀痛及头痛，低头、用力时加重，嗅觉减退，伴咽后壁分泌物倒流感，低热，体温最高37.6℃，无视力下降、无复视。既往无鼻炎、鼻息肉、牙痛及过敏史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.4℃，P84次/分，R18次/分，BP118/74mmHg。神志清楚，查体合作。鼻黏膜充血、肿胀，中鼻道可见黏脓性分泌物，上颌窦前壁压痛及叩击痛（+）。咽后壁可见黏脓性分泌物附着。双肺呼吸音清。","辅助检查":"检查计划：患者2周前受凉后出现鼻塞、流脓涕，伴面颊部胀痛及头痛，低头用力时加重，嗅觉减退并有咽后壁分泌物倒流感，低热37.6℃，病程已超过10天，初步诊断为急性细菌性鼻窦炎（双侧），检查以明确感染程度、病变范围、致病菌及有无眶内颅内并发症为目的。完善血常规检查了解白细胞及中性粒细胞比例，排除细菌感染并评估炎症程度；行鼻内镜检查了解中鼻道、嗅裂有无脓性分泌物及黏膜水肿、息肉，判断窦口引流情况，并可在内镜引导下留取分泌物培养；完善耳镜检查明确鼓膜有无充血、内陷及鼓室积液，排除鼻窦炎经咽鼓管累及中耳；完善喉镜检查排除咽喉部炎症及鼻后滴漏所致咽部症状；完善鼻窦CT检查明确各窦腔黏膜增厚、积液及窦口鼻道复合体阻塞情况，作为诊断及疗效评估依据；完善颞骨CT检查了解中耳乳突有无继发炎症，排除鼻窦炎经咽鼓管累及中耳所致耳部症状；患者有颈部不适及鼻后滴漏，完善颈部超声检查了解颈部淋巴结有无肿大，评估感染有无扩散；患者目前无耳闷、耳痛及眩晕，纯音测听、声导抗及前庭功能检查暂缓，若出现耳部症状或听力下降时完善，排除鼻窦炎继发分泌性中耳炎；因患者有嗅觉减退，完善嗅觉功能检查了解嗅觉损害程度；出现眼睑肿胀、眼球突出、复视或剧烈头痛等眶内、颅内并发症征象时，急诊完善眼眶CT或头颅MRI检查，明确有无眶内脓肿及颅内感染。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 鼻窦炎（急性，双侧）\n（注：急性细菌性鼻窦炎（症状持续>10天或双相加重，伴脓涕、发热）予阿莫西林克拉维酸0.625g tid×10~14天，辅以鼻用糖皮质激素（糠酸莫米松鼻喷剂）及生理盐水鼻腔冲洗；慢性鼻窦炎以控制炎症、通畅引流为主；若出现眼睑肿胀、眼球突出、复视、剧烈头痛或意识改变提示眶内或颅内并发症，需急诊。）","处理方案":"【药物治疗】\n1. 抗菌药物（急性细菌性鼻窦炎首选）：阿莫西林克拉维酸钾片0.625g（阿莫西林0.5g/克拉维酸0.125g）口服bid×7天；青霉素过敏者改用头孢呋辛酯片0.25g口服bid×7天。\n2. 鼻用糖皮质激素（一线局部用药）：糠酸莫米松鼻喷雾剂（内舒拿）每侧鼻孔各1喷（50μg/喷），qd晨起使用，连用2-4周；慢性鼻窦炎疗程可达12周。\n3. 黏液促排剂：桉柠蒎肠溶软胶囊0.3g口服tid，餐前30分钟凉开水整粒吞服，疗程7-14天。\n4. 鼻腔冲洗：生理盐水（或高渗海水）鼻腔冲洗，每侧20-40ml，bid；鼻塞严重时可短期加用盐酸羟甲唑啉鼻喷雾剂每侧1-2喷，bid，连续使用不超过7天。\n【一般治疗及生活指导】\n1. 注意休息，保证充足睡眠，避免熬夜、劳累及受凉，防止上呼吸道感染诱发或加重鼻窦炎。\n2. 清淡饮食，多饮水，忌辛辣刺激、生冷油腻食物，戒烟限酒。\n3. 注意保暖防感冒，适度有氧运动（如快走、慢跑）增强体质；感冒后及早治疗，避免反复发作。\n4. 正确擤鼻：单侧交替、轻柔擤鼻，避免双侧用力同时擤鼻或强行擤鼻，以防感染经咽鼓管扩散；避免长期处于干燥、粉尘、烟雾等污染环境，外出可佩戴口罩，保持室内湿度适宜。\n【随诊要求】\n1. 治疗后7天复诊评估疗效，症状明显缓解可继续完成疗程并指导减量；若症状无改善或加重需复诊调整治疗方案。\n2. 出现以下情况须立即就诊：持续高热、面部或眶周剧烈胀痛、视力下降或复视、剧烈头痛、恶心呕吐，警惕眶内及颅内并发症。\n3. 疗程结束后复查，急性鼻窦炎症状完全缓解者可不复查；症状迁延超过12周或反复发作（1年内≥4次）者，建议行鼻内镜及鼻窦CT检查，评估是否合并鼻息肉、解剖异常等，并转耳鼻喉科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":264,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9027550a00645ae3df238e59c5c7fc59f16dd5c32773901dbbc3a1d00a59631a","pinyin":"bidouyan","initials":"bdy","setting":"out","caseName":"门诊病历129","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历129",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ed9a4750ac97f8089462","key":"v1-c9ccc21dfe2a3058|templates-ed9a4750ac97f8089462","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结膜炎","category":"门诊病历模板","raw":{"name":"结膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历130","templates":{"主诉":"双眼异物感、烧灼感伴分泌物增多3天。","现病史":"患者于3天前接触可疑传染源后出现双眼异物感、烧灼感、眼痒，分泌物增多，为黏液脓性，晨起眼睑粘连，无视力下降，无畏光流泪（如有角膜受累则出现）。有家人及学校接触史，无过敏史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P80次/分，R18次/分，BP115/72mmHg。视力：右1.0，左1.0。眼睑正常，睑结膜及球结膜充血，分泌物黏液脓性，角膜透明，荧光素染色（-），前房清晰。耳前淋巴结未触及肿大。","辅助检查":"检查计划：患者3天前接触可疑传染源后出现双眼异物感、烧灼感、眼痒，分泌物增多为黏液脓性，晨起眼睑粘连，有家人及学校接触史，无过敏史，初步诊断为急性细菌性结膜炎，检查以明确病原学、指导用药并排除角膜受累为目的。结膜分泌物涂片及细菌培养在脓性分泌物提示细菌性时完善，明确致病菌种类并指导抗生素滴眼液选择；若周边出现类似病例、怀疑病毒性结膜炎暴发时，完善病毒核酸检测明确病原，指导隔离与防控措施；患者有眼痒及接触史，必要时完善过敏原检测，鉴别过敏性结膜炎；因患者目前无眼痛、畏光及视力下降，角膜受累依据不足，若出现上述表现时完善裂隙灯检查，明确有无角膜炎并及时转诊眼科；治疗5～7天后复诊，复查结膜及分泌物情况，评估疗效并调整用药；一般依据临床即可诊断，无需常规全身辅助检查，注意手卫生及毛巾隔离，避免交叉感染。\n\n（检查清单）\n【必做】一般依据临床即可诊断；【其他】结膜分泌物涂片及细菌培养（脓性分泌物提示细菌性时）、病毒核酸检测（疑病毒性结膜炎暴发时）。","初步诊断":"1. 结膜炎（急性细菌性）\n（注：细菌性：抗生素滴眼液（左氧氟沙星滴眼液1滴 qid×5~7天）；病毒性：以对症为主（人工泪液、冷敷），传染性强需注意隔离、勤洗手；过敏性：抗过敏滴眼液（奥洛他定滴眼液bid）+冷敷，脱离过敏原；若出现眼痛、畏光、视力下降提示角膜炎等，需裂隙灯检查并转眼科。）","处理方案":"【药物治疗】\n1. 抗菌药物（细菌性结膜炎首选）：左氧氟沙星滴眼液0.5%每次1滴，每日4次，疗程5-7天；睡前加用妥布霉素眼膏涂入结膜囊1次，晨起分泌物多时可加用1次。\n2. 抗病毒药物（病毒性结膜炎首选）：更昔洛韦滴眼液每次1滴，每日4次，疗程7-10天；分泌物明显时可联合玻璃酸钠滴眼液每次1滴，每日4次以缓解干涩。\n3. 抗过敏药物（过敏性结膜炎首选）：盐酸奥洛他定滴眼液每次1滴，每日2次，疗程1-2周；瘙痒及眼睑水肿明显者加用氯雷他定片10mg每日1次，疗程5-7天。\n4. 人工泪液辅助：玻璃酸钠滴眼液每次1滴，每日4次，适用于各型结膜炎缓解眼干、异物感等不适。\n【一般治疗及生活指导】\n1. 注意用眼卫生：勤洗手，严禁用手揉眼，毛巾、脸盆、枕巾专人专用并每日煮沸消毒或阳光暴晒，避免交叉传染家人；传染性结膜炎发病期建议居家隔离1-2周，不共用化妆品及眼药水。\n2. 注意休息与用眼：保证充足睡眠，减少长时间看手机、电脑等近距离用眼，避免熬夜及强光、风沙、烟尘刺激，外出可戴太阳镜防风防尘。\n3. 饮食指导：忌辛辣刺激、海鲜、牛羊肉及酒类，多饮水，多食新鲜蔬菜水果，适当补充富含维生素A、维生素C的食物（如胡萝卜、菠菜、柑橘）。\n4. 禁忌事项：禁止热敷及包扎患眼，禁止用不洁水洗眼；眼部分泌物多时用无菌棉签蘸生理盐水由内眦向外眦轻轻擦拭，每只眼用独立棉签。\n【随诊要求】\n用药3天后症状无缓解或加重，或出现明显眼痛、视力下降、畏光、流泪加重等情况时及时复诊；过敏性结膜炎反复发作者症状控制后1周复诊以排查过敏原；治愈后建议复查1次，确认炎症完全消退。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":265,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e1b4e06875fe2f5c263c57410434a49264eb80902801144844c16b1c10355d76","pinyin":"jiemoyan","initials":"jmy","setting":"out","caseName":"门诊病历130","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历130",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5cd1a4aeffcd20c18ea3","key":"v1-c9ccc21dfe2a3058|templates-5cd1a4aeffcd20c18ea3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"角膜炎","category":"门诊病历模板","raw":{"name":"角膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历131","templates":{"主诉":"眼痛、畏光、流泪伴视力下降3天。","现病史":"患者于3天前出现眼痛、畏光、流泪、异物感，伴视力下降，分泌物多，呈脓性，无发热。发病前有角膜异物史，无佩戴隐形眼镜、眼外伤、感冒发热史。既往无角膜炎发作史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P78次/分，R18次/分，BP116/74mmHg。视力：右0.3（下降），左1.0。患眼睫状充血（+），角膜可见溃疡面，荧光素染色（+），前房清晰，瞳孔圆，直径约3mm，对光反射灵敏。","辅助检查":"【必做】角膜刮片涂片（Gram染色找细菌或真菌菌丝）、分泌物及角膜刮取物细菌或真菌培养+药敏（明确病原）；【其他】共焦显微镜（真菌感染诊断）、裂隙灯照相。","初步诊断":"1. 角膜炎（细菌性，角膜溃疡）\n（注：角膜溃疡是眼科急症，可致角膜穿孔、眼内炎、失明，建议转眼科急诊处理；经验性治疗：细菌性用广谱抗生素滴眼液频繁滴眼（左氧氟沙星+妥布霉素，急性期每15~30分钟1次），病毒性用更昔洛韦眼用凝胶，真菌性用那他霉素或两性霉素B滴眼；禁戴隐形眼镜、禁揉眼、禁自行用药，需频繁复查。）","处理方案":"【药物治疗】\n1. 抗菌药物：细菌性角膜炎首选喹诺酮类，如0.5%左氧氟沙星滴眼液，每次1滴 qid×7～14天；重症（角膜溃疡扩大、前房积脓）首日每1小时1次，病情好转后逐渐延长间隔，夜间加用左氧氟沙星眼膏涂眼1次，维持夜间药物浓度。\n2. 抗病毒药物：病毒性角膜炎（单纯疱疹性）选用更昔洛韦眼用凝胶，每次1滴 qid×7～14天，可联合阿昔洛韦片0.2g po tid×7天口服。\n3. 抗真菌药物：真菌性角膜炎选用5%那他霉素滴眼液，每次1滴 q1h×48～72小时，病情稳定后改为qid，疗程≥4周，切忌自行停药。\n4. 促角膜修复及散瞳：重组人表皮生长因子滴眼液每次1滴 qid促进角膜上皮修复；若伴前房反应或虹膜睫状体炎，加用1%阿托品眼用凝胶每次1滴 bid散瞳，预防虹膜后粘连。\n【一般治疗及生活指导】\n1. 充分休息，保证充足睡眠，避免熬夜及长时间近距离用眼，减轻眼疲劳，利于角膜修复。\n2. 清淡饮食，多食富含维生素A、C及蛋白质食物（胡萝卜、动物肝脏、深色蔬菜、水果、蛋类），忌辛辣刺激饮食，戒烟戒酒。\n3. 勿用手揉眼，注意手卫生；毛巾、枕巾、脸盆专人专用，用后煮沸或日光暴晒消毒，避免交叉感染及传染他人。\n4. 外出佩戴防护镜或墨镜，避免强光、风沙及异物刺激；滴眼前洗净双手，瓶口勿接触眼睑及睫毛，防止药液污染。\n【随诊要求】\n1. 用药后2～3天复诊行裂隙灯检查，评估角膜浸润、水肿及溃疡愈合情况。\n2. 若出现眼痛加重、视力明显下降、溃疡扩大或加深、畏光流泪加剧等，应立即急诊复诊。\n3. 细菌性角膜炎疗程7～14天，症状缓解后仍需足疗程用药，不可自行减量或停药；真菌性角膜炎疗程长（≥4周），需遵医嘱定期复查至角膜病灶完全愈合。\n4. 病毒性角膜炎易复发，治愈后每1～3个月复查角膜情况，出现眼红、异物感时及时就诊；痊愈后复查角膜瘢痕及视力，防治角膜白斑、新生血管等后遗症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":266,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e6a524684f7fdb253a9ee5c3aad9f8c697a0005719c12c1899de529f7e831a68","pinyin":"jiaomoyan","initials":"jmy","setting":"out","caseName":"门诊病历131","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历131",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-95b40ded0481cb77d7de","key":"v1-c9ccc21dfe2a3058|templates-95b40ded0481cb77d7de","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"青光眼","category":"门诊病历模板","raw":{"name":"青光眼","category":"门诊病历模板","case":{"case_name":"门诊病历132","templates":{"主诉":"眼胀痛、视物模糊伴同侧头痛、恶心呕吐6小时。","现病史":"患者于6小时前在情绪激动、暗室久留或散瞳等诱因下突发右眼剧烈胀痛、视力骤降、视物模糊（虹视），伴同侧头痛、恶心呕吐2次，畏光流泪，无发热。既往无青光眼病史及类似发作。无远视、白内障等易患因素，家族史阴性。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P76次/分，R18次/分，BP130/82mmHg。神志清楚，痛苦面容。右眼混合充血（+），角膜雾状水肿，前房变浅，瞳孔散大（约5mm），对光反射消失，指测眼压T+3（坚硬如石）。对侧眼前房也浅（+）。","辅助检查":"【必做】眼压测量（正常10~21mmHg，急性发作常>40~50mmHg）、裂隙灯检查（前房、角膜、瞳孔）、前房角镜检查（房角关闭）；【影像学】眼底检查（视盘C/D比）；【其他】视野、OCT（视神经纤维层，缓解期评估）。","初步诊断":"1. 急性闭角型青光眼（右眼急性发作）\n（注：眼科急症，高眼压可致视神经不可逆损害，需立即急诊降眼压治疗：全身（20%甘露醇250ml快速静滴、乙酰唑胺0.25g口服）及局部（毛果芸香碱1~2%滴眼、β受体阻滞剂噻吗洛尔滴眼、碳酸酐酶抑制剂布林佐胺）联合用药，眼压控制后行激光周边虹膜切开术或小梁切除术；对侧眼也需预防性激光治疗。）","处理方案":"【药物治疗】\n1. 前列腺素衍生物类（一线首选）：拉坦前列素滴眼液（适利达）0.005%，每次1滴，每晚睡前1次（qn），长期维持。\n2. β受体阻滞剂：盐酸卡替洛尔滴眼液（美开朗）0.5%或马来酸噻吗洛尔滴眼液0.5%，每次1滴，每日2次（bid）。\n3. α2受体激动剂：酒石酸溴莫尼定滴眼液（阿法根）0.2%，每次1滴，每日2次（bid）。\n4. 碳酸酐酶抑制剂：布林佐胺滴眼液（派立明）1%，每次1滴，每日2次（bid）；口服醋甲唑胺片25mg，每日2次，短期使用，需监测血电解质及肾功能。\n\n【一般治疗及生活指导】\n1. 饮水：避免一次性大量饮水，每次饮水不超过300ml，全天分次少量饮用，以防房水生成骤增致眼压升高。\n2. 活动与体位：避免长时间低头、倒立及头低位姿势，避免剧烈运动和重体力劳动；衣领、领带不宜过紧，避免长时间压迫眼球。\n3. 生活起居：保持情绪平稳，避免激动、焦虑、暴怒；规律作息，保证充足睡眠，避免熬夜及暗处久留（尤其闭角型青光眼）。\n4. 饮食与禁忌：清淡低盐饮食，少饮浓茶、咖啡及含酒精饮品，戒烟；闭角型青光眼患者禁用阿托品、山莨菪碱等散瞳药物，慎用抗胆碱能药物。\n\n【随诊要求】\n1. 用药后1～2周复诊，复查眼压，评估降眼压疗效及药物不良反应。\n2. 眼压控制稳定后，每1～3个月复查眼压，每3～6个月复查眼底视盘形态及OCT视盘RNFL厚度，每6～12个月复查视野，评估病情进展。\n3. 调整或更换用药方案患者医生指导下进行，不可自行停药、减量或加量。\n4. 如出现眼胀、眼痛、视力骤降、虹视、恶心呕吐等，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":267,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"083c552859b6ba3ac23721d906cfa713381d5db0fa929016dd53fc8fcb48ade7","pinyin":"qingguangyan","initials":"qgy","setting":"out","caseName":"门诊病历132","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历132",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5ecfa5faf2dfc0d48b9e","key":"v1-c9ccc21dfe2a3058|templates-5ecfa5faf2dfc0d48b9e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"白内障","category":"门诊病历模板","raw":{"name":"白内障","category":"门诊病历模板","case":{"case_name":"门诊病历133","templates":{"主诉":"双眼渐进性、无痛性视力下降伴视物模糊1年。","现病史":"患者于1年前渐出现双眼无痛性、进行性视力下降，视物模糊、怕光、看物体颜色发黄，无眼红眼痛，无复视，戴镜矫正效果不佳。无糖尿病、长期使用糖皮质激素、眼外伤、紫外线暴露史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"视力：右0.4，左0.3，矫正不提高。裂隙灯检查：双眼晶状体核混浊（程度：初发期），眼底窥不清。眼压正常。","辅助检查":"【必做】视力、裂隙灯检查（明确晶状体混浊部位及程度）、眼压、眼底检查（排除其他致盲眼病）；【影像学】眼科超声（晶状体混浊重眼底窥不清时评估玻璃体视网膜）、角膜内皮计数及眼部生物测量（术前评估）；【其他】血糖（糖尿病患者评估控制情况）。","初步诊断":"1. 白内障（双眼，核型）\n（注：早期可观察、矫正屈光、防紫外线；影响生活时手术是唯一有效治疗（白内障超声乳化+人工晶状体植入术），手术时机由视力影响程度决定，无需等成熟期；术前控制血糖、血压，停用抗凝药评估；术后按医嘱抗感染抗炎滴眼（左氧氟沙星+糖皮质激素滴眼液），定期复查。）","处理方案":"【药物治疗】白内障早期或未达手术指征者，可选用以下药物延缓进展（均不能逆转混浊，视力明显下降者仍以手术为主）：\n1. 吡诺克辛钠滴眼液（白内停）1滴 滴眼 qid，长期使用至术前；\n2. 苄达赖氨酸滴眼液 1滴 滴眼 tid，每疗程1个月，可间隔1-2周重复疗程；\n3. 谷胱甘肽滴眼液 1-2滴 滴眼 tid-qid，与上述药物可联合；\n4. 维生素C片 0.2g po tid、维生素E软胶囊 100mg po qd，作为辅助抗氧化支持，长期服用。\n\n【一般治疗及生活指导】\n1. 外出佩戴防紫外线太阳镜，避免强光及紫外线长期直接照射眼部；\n2. 均衡饮食，多食富含维生素C、E及叶黄素的深色蔬菜水果（如菠菜、胡萝卜、柑橘、蓝莓等），控制高糖高脂饮食；\n3. 积极控制全身基础病，糖尿病患者血糖控制达标（空腹<7.0mmol/L、餐后2h<10.0mmol/L），高血压者规律降压；\n4. 避免长期或大剂量使用糖皮质激素、氯丙嗪、缩瞳剂等可能诱发或加重白内障的药物；视力下降明显时避免驾车、操作精密仪器，注意防跌倒。\n\n【随诊要求】\n1. 每3-6个月复查裸眼及矫正视力、裂隙灯检查晶状体混浊程度、眼压，动态评估病情进展；\n2. 合并糖尿病者每3个月复查血糖及眼底，全身情况变化随时复诊；\n3. 矫正视力<0.3或影响日常生活时，转诊行眼压、眼底、角膜内皮细胞计数、眼轴长度及人工晶状体度数测算等术前检查，评估白内障手术时机；\n4. 若出现眼红、眼痛、视力突然下降、恶心呕吐等，立即到眼科急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":268,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cee9da995923c1892f45f33d96e1be13e89b767e7981184907dcc44478350066","pinyin":"baineizhang","initials":"bnz","setting":"out","caseName":"门诊病历133","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历133",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-759b9e56ef7ff36ddb00","key":"v1-c9ccc21dfe2a3058|templates-759b9e56ef7ff36ddb00","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"麦粒肿","category":"门诊病历模板","raw":{"name":"麦粒肿","category":"门诊病历模板","case":{"case_name":"门诊病历134","templates":{"主诉":"眼睑红肿、疼痛伴局部硬结2天。","现病史":"患者于2天前出现右上眼睑局限性红肿、胀痛，可触及硬结，触痛明显，无分泌物，无视力下降，无发热。无反复发作史、无睑缘炎及糖尿病史，平素有揉眼习惯。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P76次/分，R18次/分，BP118/72mmHg。视力正常。右上眼睑局部红肿，可见硬结，压痛（+），相应睑结膜面充血。耳前淋巴结未触及。角膜透明。","辅助检查":"检查计划：患者2天前出现右上眼睑局限性红肿、胀痛，可触及硬结，触痛明显，无分泌物、无视力下降及发热，平素喜揉眼，初步诊断为外睑腺炎（麦粒肿），一般依据临床表现即可诊断。因患者局部红肿明显、触痛较重，完善血常规检查了解白细胞及中性粒细胞比例，排除全身感染及炎症反应程度；患者有揉眼习惯且睑腺炎易反复发作，完善血糖检查筛查糖尿病，排除糖尿病所致抵抗力下降及反复感染；因患者既往体健、无反复发作史，暂不常规完善糖化血红蛋白及口服葡萄糖耐量试验，若血糖异常或日后反复发作时完善，明确有无糖代谢异常并指导基础病控制；若出现眼睑高度肿胀、眼球突出、活动受限、视力下降或发热，提示眶蜂窝织炎、海绵窦血栓等并发症，需急诊完善眼眶CT或头颅MRI检查，明确感染范围；切忌挤压硬结，热敷及抗生素滴眼液治疗3～5天后复诊，若有脓头波动由眼科切开排脓；反复发作时注意睑缘清洁并复查血糖。\n\n（检查清单）\n【必做】一般临床诊断即可；【其他】血常规（反复发作或伴全身症状时）、血糖（反复发作者筛查糖尿病）。","初步诊断":"1. 麦粒肿（外睑腺炎）\n（注：早期（未化脓）：热敷（每日3~4次，每次10~15分钟）+抗生素滴眼液（左氧氟沙星或妥布霉素滴眼液qid）+眼膏睡前；切忌挤压（可致眶蜂窝织炎、海绵窦血栓）；脓肿成熟（有脓头波动）时由眼科切开排脓；反复发作注意睑缘清洁（婴儿洗发水稀释洗睑缘）及控制糖尿病等基础病。）","处理方案":"【药物治疗】\n1. 抗生素滴眼液：左氧氟沙星滴眼液（0.5%）滴患眼，每次1滴，每日4次，连用5～7天。\n2. 抗生素眼膏：红霉素眼膏（或氧氟沙星眼膏）涂患眼，每晚睡前1次，连用5～7天，注意白天加用滴眼液、夜间用眼膏以维持药效。\n3. 炎症较重、睑腺红肿明显或伴耳前淋巴结肿大、全身症状者，可口服抗生素：头孢呋辛酯片0.25g，每日2次，连用5天（青霉素过敏者改用阿奇霉素片0.25g，每日1次，连用3天）。\n【一般治疗及生活指导】\n1. 早期局部热敷：每日3～4次，每次10～15分钟，促进炎症吸收或脓肿成熟，脓肿形成后可自行破溃排脓。\n2. 注意眼部卫生，勤洗手，切忌用手揉眼、挤压或挑刺病灶，防止感染经血行扩散引起眶蜂窝织炎或海绵窦血栓。\n3. 清淡饮食，忌辛辣刺激及烟酒，多饮水，保持大便通畅；规律作息，避免熬夜及视疲劳，减少睑板腺分泌物淤积。\n4. 单独使用毛巾、枕巾并勤换洗，避免交叉感染；如反复发作，应排查屈光不正、睑缘炎、糖尿病等诱因。\n【随诊要求】\n用药3天症状无好转或加重、眼睑红肿范围扩大、出现发热、头痛或视力下降者，应立即复诊；脓肿成熟未破溃者由医生行切开排脓引流，切勿自行处理。疗程结束后复诊评估炎症消退情况，反复发作者建议定期复查并治疗原发病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":269,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d0b3527315290b39220188661036cea9f149678e5db1faedde949788d2e8dba7","pinyin":"mailizhong","initials":"mlz","setting":"out","caseName":"门诊病历134","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历134",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-aeab8ee38db16262b668","key":"v1-c9ccc21dfe2a3058|templates-aeab8ee38db16262b668","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痤疮","category":"门诊病历模板","raw":{"name":"痤疮","category":"门诊病历模板","case":{"case_name":"门诊病历135","templates":{"主诉":"面部、胸背部反复丘疹、脓疱、结节3年，加重2周。","现病史":"患者于3年前青春期起出现面部、胸背部痤疮，表现为粉刺、炎性丘疹、脓疱，有结节、囊肿，无瘢痕，月经前、进食辛辣油腻及熬夜后加重。是否用过维A酸类、抗生素或激素及效果：曾外用维A酸类及抗生素，效果欠佳。女性月经规律，无多毛等雄激素过多表现。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP112/70mmHg。面部（额、颊、下颌）及胸背部可见散在炎性丘疹、脓疱、结节及囊肿，部分遗留色素沉着。未见其他部位皮损。","辅助检查":"检查计划：患者青春期起面部、胸背部反复丘疹、脓疱、结节3年，近2周加重，曾外用维A酸类及抗生素效果欠佳，女性月经规律、无多毛等雄激素过多表现，初步诊断为重度痤疮，一般依据临床表现即可诊断，检查以评估有无内分泌异常及用药安全性为目的。患者曾规范外用治疗效果欠佳，拟口服异维A酸，完善肝功能检查了解转氨酶及胆红素水平，排除肝功能不全并作为用药期间监测的基线；完善血脂检查了解甘油三酯及胆固醇水平，排除高脂血症，因异维A酸可致血脂升高，需指导用药与随访；因患者为育龄期女性，用药前完善妊娠试验排除妊娠，并强调避孕至少1个月经周期前启动；患者月经规律、无雄激素过多表现，性激素六项暂不作为常规，若出现月经不调、多毛或疑多囊卵巢综合征时完善，明确有无内分泌异常；游离睾酮在疑雄激素水平升高时完善，进一步明确病因；口服异维A酸期间每4～8周复查肝功能及血脂，评估药物不良反应并指导剂量调整；皮损广泛且为结节囊肿型，必要时完善皮损分泌物涂片及细菌培养，明确有无继发细菌感染，指导抗生素选择；顽固难治者皮肤科专科随诊，必要时完善痤疮丙酸杆菌耐药相关检测。\n\n（检查清单）\n【必做】一般临床诊断；【其他】性激素六项（女性伴月经不调、多毛疑多囊卵巢综合征时）、游离睾酮。","初步诊断":"1. 痤疮（重度）\n（注：分级治疗：轻度以外用药为主（过氧化苯甲酰凝胶或维A酸类（阿达帕林凝胶qn））；中重度加口服（多西环素100mg qd×6~8周或米诺环素）；重度结节囊肿型口服异维A酸（10mg bid~tid，需避孕、监测肝功血脂，育龄期女性避孕至少1个月经周期前启动）；忌挤压、清淡饮食、规律作息，顽固者皮肤科专科随访。）","处理方案":"【药物治疗】\n1. 外用维A酸类：阿达帕林凝胶0.1%，每晚1次，薄涂于皮损处，避开眼口鼻周，连用8-12周，初期可能出现局部干燥、脱屑、红斑，属正常反应，可配合保湿剂使用。\n2. 外用抗菌药（炎症性丘疹、脓疱）：夫西地酸乳膏2%，每日2次涂于炎性皮损，疗程2周；或克林霉素凝胶1%，每日2次，与维A酸类分时段（早用抗菌药、晚用维A酸）交替使用。\n3. 系统抗菌药（中重度炎性痤疮）：盐酸米诺环素胶囊50mg，每日2次，餐后服用，疗程6-8周（不超过8周）；或盐酸多西环素片100mg，每日1次，疗程6-8周。\n4. 重度结节囊肿型痤疮：异维A酸软胶囊10mg，每日2次（按体重0.5-1mg/kg/d），餐后顿服，疗程16-24周；用药期间及停药后3个月内严格避孕，定期监测肝肾功能及血脂。\n\n【一般治疗及生活指导】\n1. 饮食：清淡饮食，减少高糖、高脂食物及脱脂牛奶等乳制品的摄入，少食辛辣刺激食物，多饮水。\n2. 皮肤护理：温水轻柔洁面，每日1-2次，避免过度清洗、搔抓及挤压皮损，以免加重炎症、遗留色素沉着或瘢痕。\n3. 生活作息：规律作息，避免熬夜，保证充足睡眠；减轻精神压力，保持情绪稳定。\n4. 禁忌：避免使用油性化妆品及含致粉刺成分的护肤品，选用非致粉刺性（非comedogenic）产品，外出注意防晒。\n\n【随诊要求】\n1. 外用维A酸类或系统抗菌药治疗者，2-4周复诊评估疗效及不良反应。\n2. 系统抗菌药疗程一般不超过8周，疗程结束后复诊，评估是否需要序贯或维持治疗。\n3. 服用异维A酸者每4周复查肝功能、血脂，育龄期女性用药期间及停药后3个月内必须避孕，并每月复诊监测。\n4. 如出现皮损加重、大面积化脓或药物不良反应（如米诺环素头晕、色素沉着，异维A酸口唇干裂、眼干等），及时复诊调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":270,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"628a9e462b65177fde429c2f1dcff88c531b74c8bf115c3dc3be1cc34c979512","pinyin":"cuochuang","initials":"cc","setting":"out","caseName":"门诊病历135","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历135",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0088c6ba1830b2c01ede","key":"v1-c9ccc21dfe2a3058|templates-0088c6ba1830b2c01ede","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂溢性皮炎","category":"门诊病历模板","raw":{"name":"脂溢性皮炎","category":"门诊病历模板","case":{"case_name":"门诊病历136","templates":{"主诉":"头皮、面颊部红斑伴油腻性鳞屑、瘙痒3个月。","现病史":"患者1周前无明显诱因出现脂溢性皮炎相关不适，症状逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者头皮、面颊部红斑伴油腻性鳞屑、瘙痒3个月，症状逐渐加重并伴轻度乏力，无明显发热，自服药物效果欠佳，初步诊断为脂溢性皮炎，检查以鉴别头皮其他鳞屑性皮肤病、寻找诱发因素并排除系统性疾病为目的。完善血常规检查了解有无感染及贫血，评估乏力原因并排除贫血、感染所致皮肤表现；因头皮鳞屑性皮损需与头癣、银屑病鉴别，完善真菌镜检+培养检查，明确有无马拉色菌或皮肤癣菌感染，指导抗真菌治疗；患者有面颊部及头皮红斑，完善皮肤镜（毛发镜）检查了解头皮血管形态、毛发及鳞屑特征，鉴别脂溢性皮炎、银屑病及头癣；患者瘙痒明显且有接触史不明，完善过敏原检测明确有无食物及吸入性过敏原，排除过敏因素加重皮损，必要时完善斑贴试验排除接触性皮炎；若皮损不典型、疗效不佳或疑淋巴瘤样丘疹病等，完善皮肤活检（必要时）及免疫荧光检查，明确病理诊断；因患者无生殖器皮损及不洁接触史，性病相关检测（必要时）暂不作为常规，必要时完善以排除梅毒等所致类似皮损；患者为中老年男性，若伴乏力、体重下降，完善血糖及甲状腺功能检查，排除糖尿病、甲状腺疾病等系统性疾病所致皮肤改变。\n\n（检查清单）\n【必做检查】\n血常规、过敏原检测、真菌镜检+培养\n\n【影像学检查】\n皮肤镜、皮肤活检（必要时）\n\n【其他检查】\n免疫荧光、斑贴试验、性病相关检测（必要时）","初步诊断":"1. 脂溢性皮炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗真菌药：2%酮康唑洗剂洗头或洗浴，每次5ml涂于头皮及患处，揉搓保留3～5分钟后清水冲净，每周2次，连续使用4周；面部及躯干部皮损可加用2%酮康唑乳膏，每日1次，疗程2～4周。\n2. 糖皮质激素：丁酸氢化可的松乳膏（尤卓尔）外用患处，每日2次，连续7天，症状缓解后改为每日1次再巩固7天，面部及皮肤薄嫩处短期使用（≤2周），避免长期使用。\n3. 非激素免疫调节剂：他克莫司软膏0.03%或吡美莫司乳膏1%外用于面部、眼周等敏感部位，每日2次×2周，皮损消退后改为每周2次维持2～4周，用于防止复发及避免激素依赖。\n4. 角质溶解剂：对鳞屑较厚者先用2%～5%水杨酸软膏或5%硫黄软膏，每晚1次，待鳞屑软化脱落后再行抗真菌及激素治疗。\n【一般治疗及生活指导】\n1. 生活规律，保证充足睡眠，避免熬夜、精神紧张及焦虑，保持情绪平稳，因精神应激可诱发或加重本病。\n2. 饮食清淡，限制高糖、高脂、辛辣刺激性食物，戒酒，多食富含B族维生素的食物（如粗粮、豆类、新鲜蔬菜水果）。\n3. 保持皮肤及头皮清洁干爽，洗头水温不宜过高，避免过度洗涤、搔抓、烫洗及使用碱性强的洗护用品，勿用力梳刮头皮；避免滥用护发及化妆品。\n4. 面部皮损避免长期外用糖皮质激素，防止激素依赖性皮炎；皮损处避免暴晒及刺激性护肤品。\n【随诊要求】\n治疗2周后复诊评估疗效；皮损消退后继续维持治疗2～4周以防复发；若出现瘙痒加重、皮损泛发、红肿渗液或继发感染（脓疱、结痂），应及时复诊；反复发作者建议每1～2个月随访1次，必要时行HIV、血糖等检查排除系统性疾病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":271,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2f7952a54be83db106be17896233f217f926feabbd50cb4fc7978fe7235eb298","pinyin":"zhiyixingpiyan","initials":"zyxpy","setting":"out","caseName":"门诊病历136","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历136",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a6abaf30fd9d513ab8fd","key":"v1-c9ccc21dfe2a3058|templates-a6abaf30fd9d513ab8fd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"玫瑰糠疹","category":"门诊病历模板","raw":{"name":"玫瑰糠疹","category":"门诊病历模板","case":{"case_name":"门诊病历137","templates":{"主诉":"躯干、四肢近端红斑、鳞屑伴轻度瘙痒2周。","现病史":"患者于2周前躯干出现单个椭圆形淡红斑（母斑，直径约2cm），此后1~2周躯干、四肢近端相继出现多数较小的椭圆形斑疹，长轴与皮纹方向一致，表面覆细薄糠状鳞屑，伴轻度瘙痒，无发热，无关节痛。发病前有上呼吸道感染史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP114/70mmHg。躯干、四肢近端可见多数椭圆形淡红-黄褐色斑疹，长轴与皮纹平行，边缘覆细薄鳞屑（领圈状），未见母斑（可能已消退），面部及四肢远端无皮损。口腔黏膜无异常。","辅助检查":"【必做】一般临床诊断；【其他】真菌镜检（排除体癣）、梅毒血清学（不典型皮损需排除二期梅毒，尤其掌跖受累或黏膜损害时）。","初步诊断":"1. 玫瑰糠疹\n（注：本病有自限性（一般6~8周自愈），以对症为主：瘙痒明显口服抗组胺药（氯雷他定10mg qd）、外涂炉甘石洗剂或弱效糖皮质激素（氢化可的松乳膏）；避免热水烫洗及刺激性外用；反复不愈或皮损不典型者皮肤科随访并复查排除其他疾病。）","处理方案":"【药物治疗】\n1. 口服抗组胺药止痒：氯雷他定片10mg 口服 每日1次，或西替利嗪片10mg 口服 每日1次，连用7~14天，瘙痒明显者睡前加用酮替芬片1mg。\n2. 外用糖皮质激素抗炎：丁酸氢化可的松乳膏（尤卓尔）外用 每日2次，薄涂于红斑丘疹处，连用7天，症状缓解后可减至每日1次。\n3. 收敛止痒：炉甘石洗剂 外用 每日3次，摇匀后涂于瘙痒明显或渗出倾向处。\n4. 辅助治疗：维生素C片0.2g 口服 每日3次，联合钙剂（如葡萄糖酸钙片0.5g 每日3次）口服，连用14天，减少血管炎症反应。\n\n【一般治疗及生活指导】\n1. 避免搔抓及热水烫洗，洗澡水温以37℃左右为宜，避免使用碱性肥皂及刺激性沐浴产品，防止继发感染及色素沉着。\n2. 清淡饮食，忌辛辣、油腻刺激食物及饮酒，减少海鲜、牛羊肉等易致敏食物摄入，多饮水、多吃新鲜蔬菜水果。\n3. 穿宽松纯棉衣物，避免化纤、毛织品摩擦刺激皮损；保持皮损区清洁干燥，避免剧烈运动及大量出汗。\n4. 注意休息，保证充足睡眠，规律作息，避免熬夜及精神紧张；本病有自限性，多数患者6~8周可自行消退，避免过度焦虑。\n\n【随诊要求】\n用药2周后复诊，评估皮疹消退及瘙痒缓解情况；如瘙痒剧烈影响睡眠、皮疹短期内迅速增多泛发，或出现水疱、糜烂、渗出、继发感染等新发皮损，应及时复诊；若4周后皮疹仍无消退趋势或反复加重，需复诊调整治疗方案（可考虑窄谱中波紫外线光疗）。皮损完全消退后无需长期用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":272,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3a44adc6aa2a64106ffc9650bdef537153359422c9c53dd0a158f437bdbc30b0","pinyin":"meiguikangzhen","initials":"mgkz","setting":"out","caseName":"门诊病历137","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历137",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3bb6ff4c839007a11c63","key":"v1-c9ccc21dfe2a3058|templates-3bb6ff4c839007a11c63","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疥疮","category":"门诊病历模板","raw":{"name":"疥疮","category":"门诊病历模板","case":{"case_name":"门诊病历138","templates":{"主诉":"全身皮肤瘙痒，夜间为甚，伴指缝、腕部丘疹水疱2周。","现病史":"患者1周前无明显诱因出现疥疮相关不适，症状逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者全身皮肤瘙痒，夜间为甚，伴指缝、腕部丘疹、水疱2周，症状逐渐加重并伴轻度乏力，初步诊断为疥疮，检查以明确诊断、评估全身状况及用药安全性为目的。完善血常规检查排除感染及贫血所致乏力，了解嗜酸性粒细胞水平；完善尿常规检查排除泌尿系统感染及肾损害，作为用药前常规；完善便常规检查排除肠道寄生虫感染所致全身瘙痒，鉴别其他寄生虫病；完善肝肾功能检查了解肝肾代谢能力，为外用硫磺软膏、口服抗组胺药及可能的伊维菌素治疗提供安全依据；完善血糖、血脂检查了解代谢状况，排除糖尿病所致皮肤瘙痒；完善电解质检查排除电解质紊乱；完善心电图检查了解心脏电活动，排除心律失常，评估用药安全性；完善胸部X线片检查排除肺部感染及结核等疾病；完善腹部超声检查了解肝胆胰脾情况，排除胆汁淤积等所致全身瘙痒；完善皮肤镜检查观察指缝、腕部有无疥螨隧道及虫卵，明确诊断；必要时完善皮肤活检及疥螨镜检，与其他丘疹性皮肤病鉴别；根据病情需要选择相应检查，并对密切接触者同时筛查、同步治疗及开展衣物消毒宣教。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 疥疮\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选外用杀疥：10%硫软膏，自颈部以下全身皮肤均匀涂搽（含指缝、腋窝、腹股沟、臀部、趾间及甲缝等皱褶部位），每日1次，睡前涂搽，连用3日为1疗程；疗程期间不洗澡、不更衣，第4日洗澡并更换全部衣物、床单及被褥。1周后如皮疹未愈或瘙痒仍著，可重复1疗程。亦可选用5%氯菊酯乳膏自颈部以下全身涂搽，保留8-12小时后洗去，7日后重复1次。\n2. 止痒：瘙痒明显者口服氯雷他定片10mg qd×7-14天，或西替利嗪片10mg qn；夜间瘙痒影响睡眠者加用赛庚啶片2mg qn。\n3. 继发感染：皮损抓破、脓疱明显者外用莫匹罗星软膏，每日2-3次涂于患处×3-5天；伴发热等全身症状者加口服阿莫西林胶囊0.5g tid×5-7天（青霉素过敏者改用阿奇霉素片0.5g qd×3天）。\n4. 重症/结痂性疥疮或外用疗效不佳者：口服伊维菌素片200μg/kg单次顿服，1-2周后重复1次。\n\n【一般治疗及生活指导】\n1. 同治与隔离：与患者同住的家庭成员及性伴侣应同时接受治疗；治疗期间避免与家人密切接触及性接触，防止交叉感染。\n2. 衣物消毒：患者内衣、床单、被褥、毛巾等煮沸10分钟或≥60℃热水烫洗消毒，不能煮沸者可熨烫或装入密封袋放置72小时以上再使用，更换下来的衣物在疗程结束前集中处理。\n3. 起居护理：剪短指甲，避免搔抓以防继发感染；勤换衣被，保持皮肤清洁干燥；清淡饮食，忌辛辣刺激及海鲜、牛羊肉等易致敏食物；保证休息，避免劳累。\n4. 用药注意：涂药须自颈部以下全身均匀涂搽，皱褶及甲缝部位不得遗漏；疗程期间不洗澡、不更衣，疗程结束后方彻底清洗；孕妇、婴幼儿及大面积皮损者避免使用林旦乳膏，首选10%硫软膏。\n\n【随诊要求】\n1. 疗程结束后1-2周复诊，评估皮疹消退及瘙痒改善情况；若瘙痒持续或出现新发丘疹、水疱，提示治疗失败或再感染，应及时复诊。\n2. 疥疮治疗后瘙痒可延续1-2周（疥疮后瘙痒），若超过4周仍不缓解或出现新皮疹，需复诊排除复发、继发感染或药物不良反应。\n3. 家庭成员或密切接触者出现类似瘙痒性皮疹者，应一并就诊同治，避免\"治疗-再感染\"循环；复诊时携带所用药物及用药记录，便于评估调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":273,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f8e54b06be17e637a7b1dda2b78ec92688e0230a15244a8ac3bce4c05dc8e767","pinyin":"jiechuang","initials":"jc","setting":"out","caseName":"门诊病历138","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历138",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f90a7cf5fd5d50b56d71","key":"v1-c9ccc21dfe2a3058|templates-f90a7cf5fd5d50b56d71","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"月经不调","category":"门诊病历模板","raw":{"name":"月经不调","category":"门诊病历模板","case":{"case_name":"门诊病历139","templates":{"主诉":"月经周期紊乱伴经量异常6月。","现病史":"患者于6月来出现月经周期不规则（周期20~35天），经期7~10天，经量增多，经色暗红，有血块，伴经前乳房胀痛、下腹痛及腰酸，末次月经15天前。近期精神压力大、作息不规律，体重无明显变化，无停经后出血，无宫内节育器，未服用紧急避孕药等药物。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P84次/分，R18次/分，BP110/70mmHg。神志清楚。妇科检查（如需要）：外阴、阴道发育正常，黏膜无充血，宫颈光滑，无举痛，子宫前位，正常大小，活动度好，无压痛，双附件未触及包块，无压痛。一般情况良好，无贫血貌（如有出血多：面色苍白）。","辅助检查":"【必做】血常规（评估失血性贫血）、尿或血人绒毛膜促性腺激素（排除妊娠相关出血，育龄期必查）、性激素六项（月经周期第2~4天查基础值）、甲状腺功能；【影像学】盆腔超声（子宫内膜厚度、有无肌瘤、息肉或卵巢囊肿）；【其他】诊断性刮宫或宫腔镜（异常子宫出血、疑内膜病变时）。","初步诊断":"1. 月经不调（异常子宫出血-排卵障碍性）\n（注：根据年龄段及病因处理：青春期或围绝经期功血可予激素止血（雌孕激素序贯或复方口服避孕药）、氨甲环酸；育龄期需排除妊娠、器质性疾病；周期调整可口服避孕药或孕激素后半周期（地屈孕酮10mg bid×10天/周期）；经量多伴贫血者补铁；持续异常或药物治疗无效者妇科专科进一步检查（宫腔镜等）。）","处理方案":"【药物治疗】\n1. 雌孕激素序贯疗法（人工周期）：戊酸雌二醇片（补佳乐）1mg qd，于月经周期第5天起连服21天，后10天加用地屈孕酮片10mg bid，两药同时停药后等待撤药性出血，连续3-6个周期，适用于月经稀发、闭经及周期紊乱者。\n2. 地屈孕酮片（达芙通）10mg bid，于月经周期第11-25天口服，共14天，适用于黄体功能不足所致周期缩短、经前点滴出血者。\n3. 中成药调理：乌鸡白凤丸（水蜜丸）6g bid，或加味逍遥丸6g bid，适用于肝郁血虚、气血两虚型月经先后无定期、经量异常者，连服1-3个月经周期。\n4. 若合并月经过多伴缺铁性贫血：琥珀酸亚铁片0.1g tid饭后口服，同时加用维生素C片0.1g tid以促进铁吸收，贫血纠正后维持1-2个月。\n【一般治疗及生活指导】\n1. 规律作息，保证每日7-8小时睡眠，避免熬夜、精神紧张及过度劳累，保持情绪平稳，避免情志波动影响月经周期。\n2. 经期注意保暖，避免受凉、冒雨涉水及冷水浴，忌食生冷、寒凉及辛辣刺激之品，经期避免剧烈运动、游泳及重体力劳动。\n3. 均衡营养，适当增加瘦肉、蛋类、动物肝脏、豆制品及新鲜蔬果等富含蛋白质、铁质和维生素的食物，将体重控制在正常范围（BMI 18.5-23.9），避免过度节食减肥。\n4. 经期保持外阴清洁，勤换卫生巾及内裤，禁止经期性生活和盆浴，预防上行感染。\n【随诊要求】\n用药期间每1-2个月复诊1次，评估月经周期、经期及经量恢复情况，必要时复查性激素六项、甲状腺功能及妇科B超；人工周期治疗3-6个周期后停药观察自然月经恢复情况；若出现经期明显延长、经量过多、非经期异常出血、腹痛加重或闭经超过3个月，应及时复诊；有备孕需求者建议监测基础体温及排卵，转诊生殖内分泌专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":274,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6d916d58e3bf1205a3e32d87caad3d58470f7f5184435a29e796b369dd8105dd","pinyin":"yuejingbudiao","initials":"yjbd","setting":"out","caseName":"门诊病历139","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历139",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5e0ce05519cf568c72a9","key":"v1-c9ccc21dfe2a3058|templates-5e0ce05519cf568c72a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"盆腔炎","category":"门诊病历模板","raw":{"name":"盆腔炎","category":"门诊病历模板","case":{"case_name":"门诊病历140","templates":{"主诉":"下腹持续性疼痛伴白带增多、发热3天。","现病史":"患者于3天前出现下腹持续性疼痛，劳累或性交后加重，伴白带增多（脓性、有异味）、发热（体温最高38.5℃）、腰骶部酸痛，无恶心呕吐，无尿频尿急。发病前无宫腔操作（人流、上环）、经期性交及多个性伴侣等诱因。末次月经15天前。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.4℃，P96次/分，R20次/分，BP112/70mmHg。神志清楚，急性病容。下腹压痛（+），反跳痛（-），肌紧张（-）。妇科检查：阴道及宫颈充血，宫颈口可见脓性分泌物，宫颈举痛（+），子宫压痛（+），双附件区增厚、压痛，未触及包块。","辅助检查":"【必做】血常规、CRP、血沉、宫颈管分泌物涂片及淋球菌或衣原体核酸检测（明确病原）、白带常规；【影像学】盆腔超声（附件区包块、盆腔积液、输卵管卵巢脓肿）；【其他】尿或血人绒毛膜促性腺激素（排除异位妊娠）、后穹隆穿刺（疑盆腔脓肿时）。","初步诊断":"1. 盆腔炎性疾病（急性）\n（注：尽早规范抗感染：头孢曲松1g肌注或静滴单剂（覆盖淋球菌）+多西环素100mg bid×14天+甲硝唑0.4g bid×14天；症状重、妊娠、脓肿、高热或门诊治疗无效者住院静滴广谱抗生素（头孢西丁或哌拉西林他唑巴坦+多西环素）；急性期禁性生活及宫腔操作；处理性伴侣；疗程不足易转为慢性盆腔炎导致不孕、宫外孕，务必足疗程并随访。）","处理方案":"【药物治疗】\n1. 抗感染治疗（门诊口服联合方案，疗程14天）：头孢克肟分散片 0.1g po bid ×14天（或头孢地尼胶囊 0.1g po tid）；多西环素片 0.1g po bid，饭后服用以减少胃肠刺激 ×14天；甲硝唑片 0.4g po bid，服药期间及停药7天内禁酒 ×14天。\n2. 抗感染替代方案（对头孢过敏或不能耐受者）：左氧氟沙星片 0.5g po qd ×14天，联合甲硝唑片 0.4g po bid ×14天。\n3. 对症止痛：布洛芬缓释胶囊 0.3g po bid，疼痛明显时服用，疗程3~5天（或双氯芬酸钠肠溶片 50mg po bid）。\n4. 辅助治疗：康妇炎胶囊 3粒 po tid ×2周，或妇科千金片 6片 po tid ×2周，用药前需排除妊娠。\n\n【一般治疗及生活指导】\n1. 卧床休息，取半卧位以利于盆腔炎性渗出物局限及引流；避免剧烈运动、久站久坐及负重。\n2. 高蛋白、高维生素、易消化饮食，多饮水，保持大便通畅；忌辛辣刺激、生冷油腻及甜腻食物。\n3. 治疗期间及症状完全消失前禁止性生活、盆浴及游泳，避免阴道冲洗及不必要的宫腔操作。\n4. 注意经期及性生活卫生，勤换内裤及卫生巾，保持外阴清洁干燥；规律作息、充分睡眠，增强机体抵抗力，避免受凉劳累。\n\n【随诊要求】\n1. 用药3~5天后复诊，评估腹痛、发热、阴道分泌物等症状体征改善情况；如高热不退、腹痛加剧或出现包块增大，应及时就诊，必要时住院静脉抗感染治疗。\n2. 完成14天疗程后复查妇科检查及妇科超声，评估炎症消退及有无输卵管卵巢脓肿、盆腔粘连等并发症。\n3. 治愈后1~2个月复诊1次，确认无复发及远期并发症；如出现恶心、呕吐、皮疹、腹泻等药物不良反应，随时就诊调整用药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":275,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9b405e62de8d88930fc9c9bcc21b13d5a24c4dfbc0d55c37d286fa530b69de7c","pinyin":"penqiangyan","initials":"pqy","setting":"out","caseName":"门诊病历140","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历140",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-de118444bbb6228b0e5d","key":"v1-c9ccc21dfe2a3058|templates-de118444bbb6228b0e5d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴道炎","category":"门诊病历模板","raw":{"name":"阴道炎","category":"门诊病历模板","case":{"case_name":"门诊病历141","templates":{"主诉":"白带增多、外阴瘙痒伴异味1周。","现病史":"患者1周前无明显诱因出现阴道炎相关不适，症状逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者白带增多、外阴瘙痒伴异味1周，自服药物效果欠佳，为明确阴道炎类型并指导针对性用药，首先完善白带常规检查，通过阴道分泌物pH、胺试验及镜下菌群、滴虫、假丝酵母菌孢子菌丝观察，明确病原体种类；查血常规了解白细胞及中性粒细胞比例，排除合并细菌感染或血液系统异常所致乏力；查尿常规排除尿路感染、糖尿病所致的外阴瘙痒，并了解有无尿糖干扰。患者为育龄女性，本次以阴道分泌物异常起病，需查血HCG排除妊娠，以避免妊娠期用药风险；查性激素六项了解卵巢功能及内分泌水平，排除内分泌失调所致阴道菌群紊乱。宫颈TCT与HPV联合筛查用于排除宫颈上皮内病变及人乳头瘤病毒感染，明确异常分泌物是否源于宫颈病变，必要时转阴道镜检查。完善妇科超声了解子宫、附件及盆腔情况，排除子宫肌瘤、子宫内膜病变、附件肿物等引起的分泌物增多；同时完善乳腺超声，了解乳腺有无占位性病变，排除乳腺疾病相关的内分泌异常。若症状反复或治疗效果不佳，加查肿瘤标志物（CA125、CEA等）以鉴别盆腔恶性肿瘤所致异常排液。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 阴道炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 滴虫性阴道炎或细菌性阴道病：甲硝唑片0.4g 口服 bid×7天（滴虫性阴道炎性伴侣需同步口服治疗）；或奥硝唑片0.5g 口服 bid×5天。\n2. 外阴阴道假丝酵母菌病（单纯性VVC）：氟康唑胶囊150mg 单次顿服；或克霉唑阴道栓500mg 睡前置入阴道深部，每晚1粒，连用3晚（顽固病例可延长至6晚）。\n3. 混合感染或局部症状明显者：甲硝唑阴道泡腾片0.2g 每晚睡前阴道给药×7天，配合外洗治疗。\n4. 外阴瘙痒灼痛明显者：加用咪康唑软膏或克霉唑乳膏外涂外阴 bid，连用7天。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，每日温水清洗外阴1次，避免使用肥皂、沐浴液及各类洗液反复冲洗阴道及外阴，以免破坏阴道正常菌群。\n2. 勤换纯棉内裤，内裤单独手洗后用开水烫洗或阳光下暴晒；浴巾、毛巾、浴盆专用，滴虫性阴道炎患者浴具需煮沸消毒。\n3. 治疗期间禁止性生活，避免盆浴、游泳及泡温泉，直至复查白带转阴；必要时性伴使用避孕套隔离。\n4. 清淡饮食，忌辛辣刺激、油腻食物，忌饮酒；VVC患者同时减少甜食及含糖饮料摄入；注意规律作息，避免劳累，增强免疫力。\n\n【随诊要求】\n1. 治疗结束后停药3～7天复诊复查白带常规，评估疗效；症状未缓解或加重者随时复诊。\n2. 滴虫性阴道炎需连续3次月经干净后复查白带均阴性方为治愈，治疗期间禁饮酒以防双硫仑样反应。\n3. 反复发作（1年内≥4次）者建议行病原体培养及药敏检查，必要时延长疗程或阴道局部维持治疗。\n4. 妊娠期、哺乳期及合并糖尿病、免疫抑制者用药方案需专科调整，遵医嘱复诊，不可自行停药或换药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":276,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"66d00565c1e884cf01efd7b15a5763dafe2e562ff63613ad2dde5db69272810a","pinyin":"yindaoyan","initials":"ydy","setting":"out","caseName":"门诊病历141","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历141",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2cb0fd5ec2d39f7235eb","key":"v1-c9ccc21dfe2a3058|templates-2cb0fd5ec2d39f7235eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"更年期综合征","category":"门诊病历模板","raw":{"name":"更年期综合征","category":"门诊病历模板","case":{"case_name":"门诊病历142","templates":{"主诉":"潮热、出汗、烦躁失眠伴月经紊乱6月。","现病史":"患者于6月前（围绝经期）渐出现阵发性潮热、盗汗（每日5次，夜间为著），伴烦躁易怒、情绪低落、失眠、乏力、心悸、关节酸痛，月经周期紊乱（周期延长，经量改变），末次月经3个月前。无阴道异常出血（如有需排除器质性疾病）。无子宫及卵巢手术史，无激素替代治疗史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP124/76mmHg。神志清楚，查体合作，面色潮红（+）。心肺听诊未见明显异常。腹平软。妇科检查（如需要）：外阴阴道黏膜萎缩，子宫附件未触及异常。","辅助检查":"【必做】性激素六项（FSH升高、雌二醇降低，提示卵巢功能减退）、血常规；【影像学】盆腔超声（排除子宫肌瘤、卵巢囊肿等器质性疾病）；【其他】甲状腺功能（排除甲亢或甲减所致症状）、骨密度（绝经后骨质疏松筛查）、血脂血糖。","初步诊断":"1. 更年期综合征（围绝经期）\n（注：健康指导为主（生活方式、运动、补钙及维生素D）；症状明显影响生活者考虑绝经激素治疗（MHT）：雌激素+孕激素（有子宫者联合，如雌二醇屈孕酮片每日1片），需评估禁忌（乳腺癌、血栓史等）；也可用非激素治疗（植物药黑升麻、SSRIs类如帕罗西汀改善潮热）；阴道干涩用局部雌激素软膏；定期随访。）","处理方案":"【药物治疗】\n1.激素补充治疗（HRT，首选）：有子宫者采用雌孕激素连续联合方案，如雌二醇屈孕酮片（芬吗通）1片 qd 口服，或戊酸雌二醇片或雌二醇环丙孕酮片（克龄蒙）1片 qd 口服，连用3-6个月后评估疗效并个体化调整；无子宫者可单用雌激素（如戊酸雌二醇片1mg qd）。用药前须排除乳腺癌、子宫内膜癌、血栓性疾病及严重肝肾疾病等禁忌证。\n2.自主神经功能紊乱及情绪症状：谷维素片10mg tid 口服，疗程2-3个月；情绪低落、焦虑明显者可用中成药坤泰胶囊4粒 tid 口服，或必要时转诊心理科评估是否加用抗焦虑药物（如帕罗西汀20mg qd）。\n3.骨质疏松防治：碳酸钙D3片（钙尔奇D）600mg qd 口服＋维生素D3滴剂800IU qd，长期服用；骨密度检查提示骨质疏松者加用双膦酸盐，如阿仑膦酸钠70mg 每周1次，晨起空腹以白水送服，服后保持直立至少30分钟。\n\n【一般治疗及生活指导】\n1.规律作息，保证每日7-8小时睡眠；适度有氧运动（快走、慢跑、游泳、瑜伽等）每周至少150分钟，并进行适量负重运动以增强骨密度，避免久坐。\n2.均衡饮食：增加奶制品、豆制品（含大豆异黄酮）、鱼虾、绿叶蔬菜及坚果摄入以补充钙和优质蛋白；限制咖啡、浓茶、酒精及辛辣刺激食物，戒烟。\n3.心理调适：正确认识更年期生理变化，保持情绪稳定，多与家人朋友交流，培养兴趣爱好；潮热发作时注意环境通风、穿着宽松透气的衣物。\n4.坚持盆底肌锻炼（凯格尔运动），每日2-3组，每组10-15次，预防及改善尿失禁、阴道干涩等不适。\n\n【随诊要求】\n1.使用激素补充治疗者每3-6个月复诊，评估症状改善程度及用药依从性，动态调整方案；若出现异常阴道出血、乳房胀痛或触及肿块、下肢肿胀疼痛等，应立即就诊。\n2.每年复查妇科超声、乳腺超声、性激素六项、肝肾功能、血糖血脂及血压，定期监测体重；每年行骨密度检测筛查骨质疏松。\n3.更年期症状持续加重或出现严重情绪障碍、失眠影响生活者，建议1-2个月复诊或转诊专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":277,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"576f61667f658e511acee9ee5bc55a55873e8445b15374ee1992c8dffad493ff","pinyin":"gengnianqizonghezheng","initials":"gnqzhz","setting":"out","caseName":"门诊病历142","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历142",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cd8d6f26b23858ae8a05","key":"v1-c9ccc21dfe2a3058|templates-cd8d6f26b23858ae8a05","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿感冒","category":"门诊病历模板","raw":{"name":"小儿感冒","category":"门诊病历模板","case":{"case_name":"门诊病历143","templates":{"主诉":"发热、鼻塞、流涕、咳嗽2天。","现病史":"患儿于2天前受凉后出现发热，体温最高38.6℃，鼻塞、流清涕，咳嗽（干咳），食欲下降，精神尚可，无抽搐，无呕吐腹泻，无皮疹。大小便正常。病前有感冒患者接触史，无食物药物过敏史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育同同龄儿童。","体格检查":"T38.6℃，P120次/分，R28次/分。神志清，精神尚可。咽部充血（+），扁桃体肿大，无脓点，双肺呼吸音清，未闻及干湿啰音。耳部检查：鼓膜正常。心肺腹未见异常。","辅助检查":"【必做】一般临床诊断为主；【其他】血常规+CRP（发热>3天或疑细菌感染时，鉴别病毒或细菌）、流感病毒或呼吸道合胞病毒抗原检测（流行季节）。","初步诊断":"1. 急性上呼吸道感染（小儿感冒）\n（注：多为病毒感染，对症治疗：发热>38.5℃用布洛芬混悬液5~10mg/kg/次或对乙酰氨基酚10~15mg/kg/次（间隔≥4~6小时，24小时内不超过4次）、鼻塞用生理盐水滴鼻；抗生素仅在明确细菌感染时使用；多饮水、清淡饮食、休息；若出现持续高热>3天、精神差、呼吸急促、抽搐或皮疹，需复诊排除并发症（肺炎、脑炎等）；注意与流感、麻疹、手足口病等早期鉴别。）","处理方案":"【药物治疗】\n1. 退热对症：体温≥38.5℃或伴明显不适时，选用布洛芬混悬液（如美林）5-10mg/kg/次，q6-8h口服；或对乙酰氨基酚口服液（如泰诺林）10-15mg/kg/次，q4-6h口服。两种退热药不联合使用、不常规交替，即使交替亦须间隔≥4小时，24小时内各不超过4次，热退即停，总疗程≤3天；3月龄以下婴儿发热须立即就诊，不自行用药。\n2. 缓解鼻塞流涕：生理性海水鼻腔喷雾剂喷鼻，每侧1-2喷/次，tid，疗程≤1周；鼻塞严重影响哺乳或睡眠时，可加用0.5%盐酸麻黄碱滴鼻液，每侧1滴/次，bid，连续使用≤5天，滴鼻后30分钟再哺乳，2岁以下慎用。\n3. 化痰止咳：咳嗽伴痰多者口服盐酸氨溴索口服溶液（如沐舒坦），按体重每日30mg折算（2-5岁2.5ml/次、6-12岁5ml/次），tid，疗程5-7天；剧烈干咳影响睡眠者，6岁以上可短期口服氢溴酸右美沙芬糖浆5-10mg/次，tid，疗程≤3天，2岁以下禁用镇咳药。\n4. 抗感染：普通感冒多为病毒感染，具有自限性，不预防性使用抗生素及抗病毒药；仅当出现明确继发细菌感染证据（如急性化脓性中耳炎、化脓性扁桃体炎）时，口服阿莫西林克拉维酸钾干混悬剂，按阿莫西林计20-40mg/kg/日，分3次（q8h），疗程5-7天，用药前须确认无青霉素过敏史。\n\n【一般治疗及生活指导】\n1. 休息：急性期居家休息，保证充足睡眠，暂停剧烈活动和体育课；发热期间卧床休息，热退后2-3天再逐步恢复日常活动。\n2. 饮食：多饮温开水，少量多餐，进食清淡易消化的流质或半流质（米汤、烂粥、菜泥、蒸蛋羹），保证足够奶量；忌生冷、油腻、甜腻及辛辣刺激食物；婴幼儿按需哺乳，少量多次喂水。\n3. 环境与防护：保持居室通风，室温20-24℃、湿度50%-60%；患儿餐具、毛巾、玩具单独使用并定期消毒，家长护理前后洗手；避免带患儿去人群密集场所，外出佩戴口罩，减少交叉感染。\n4. 禁忌：禁用阿司匹林退热（警惕瑞氏综合征），禁用酒精或冷水擦浴，2岁以下禁用含薄荷脑、樟脑、桉油成分的外用制剂及含镇咳成分的复方感冒药；不自行合用多种复方感冒药，防止重复成分超量。\n\n【随诊要求】\n1. 常规复诊：一般情况良好、无并发症者，3-5天后复诊评估恢复情况；体温正常48小时、咳嗽流涕明显好转后即可恢复正常生活，无需再复诊。\n2. 及时复诊或急诊指征：发热≥38.5℃持续3天以上不退或退热后再次发热；精神萎靡、嗜睡、烦躁不安或惊厥；拒食、脱水表现（婴幼儿24小时尿布少于6块）；呼吸急促、鼻翼扇动、三凹征、口唇发绀；出现耳痛、耳流脓、脓涕持续超过10天或咳嗽进行性加重，出现任一情况请随时复诊或急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":278,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b460f6fd4c3d46502ce574bb2d2651202763b14989b3ed2b497b7e5a0db22bbb","pinyin":"xiaoerganmao","initials":"xegm","setting":"out","caseName":"门诊病历143","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历143",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-13dd98294dd10eaf773a","key":"v1-c9ccc21dfe2a3058|templates-13dd98294dd10eaf773a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿腹泻","category":"门诊病历模板","raw":{"name":"小儿腹泻","category":"门诊病历模板","case":{"case_name":"门诊病历144","templates":{"主诉":"腹泻、呕吐伴发热2天。","现病史":"患儿于2天前出现腹泻，大便每日10次，为蛋花汤样便，量较多，伴呕吐4次（为胃内容物），发热（体温最高38.5℃），食欲减退，精神尚可，尿量减少，有轻度脱水表现（眼窝稍凹陷、口唇干燥、哭时泪少、皮肤弹性稍差）。无不洁饮食史，无明确腹泻患儿接触史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P120次/分，R28次/分。神志清，精神可，皮肤弹性稍差，前囟、眼窝稍凹陷，口唇干燥。心肺听诊未见明显异常。腹平软，无压痛反跳痛，肠鸣音活跃。四肢末梢温。","辅助检查":"【必做】大便常规（白细胞、红细胞，可鉴别细菌性肠炎）、轮状病毒或诺如病毒抗原检测（秋冬流行）；【其他】血常规、电解质及血气分析（中重度脱水、酸中毒评估）、大便培养（黏液脓血便或病程迁延者）。","初步诊断":"1. 急性腹泻病（小儿肠炎，轻度脱水）\n（注：核心是预防和纠正脱水：轻度口服补液盐（ORSⅢ，按50~75ml/kg分次，每腹泻1次加10ml/kg），中重度脱水静脉补液（2:3:1液或生理盐水20ml/kg快速扩容）；继续喂养（母乳、稀粥）；补锌（元素锌10~20mg/d×10~14天）缩短病程；益生菌（双歧杆菌等）；黏液脓血便或高热疑细菌性用抗生素（三代头孢）；不用止泻药（蒙脱石散可用）；若出现精神萎靡加重、尿少、抽搐、腹胀提示重症或并发症，需急诊住院。）","处理方案":"【药物治疗】\n1. 口服补液盐Ⅲ（ORSⅢ）：轻、中度脱水首选口服补液，按50～100ml/kg于4小时内分次服完，其后每次稀便后追加（<6月龄50ml、6月龄～2岁100ml、>2岁150ml），用于预防和纠正脱水、维持水电解质平衡，持续补液至腹泻停止。\n2. 蒙脱石散（思密达）：<1岁每次1g、1～2岁每次1.5g、>2岁每次3g，均每日3次；于两餐之间空腹服用，每袋（3g）以50ml温水调匀，首剂可加倍，与其他药物间隔1～2小时服用，疗程3～5天或至大便成形后停用。\n3. 益生菌制剂：双歧杆菌三联活菌散（培菲康）每次1袋，每日3次，以<40℃温水冲服，连用5～7天；或布拉氏酵母菌散（亿活）每次1袋（0.25g），每日2次，调节肠道菌群、缩短病程。\n4. 补锌：<6月龄每日10mg，≥6月龄每日20mg（如葡萄糖酸锌口服液或硫酸锌颗粒），连用10～14天，可缩短腹泻病程、减少复发及后续2～3个月内再发腹泻。\n\n【一般治疗及生活指导】\n1. 继续合理喂养：母乳喂养儿继续哺乳，人工喂养儿继续原配方奶；6月龄以上可进食稀粥、烂面条、蒸蛋羹等易消化食物，少量多餐；腹泻期暂不添加新辅食，避免高糖、高脂、生冷及含乳糖过多的饮食。\n2. 卫生防护：护理者及患儿勤洗手，奶瓶、餐具煮沸消毒，患儿粪便及污染衣物及时清洗消毒；勤换尿布，便后温水清洗臀部并涂护臀霜，预防尿布皮炎。\n3. 休息与护理：保证充足休息，避免剧烈活动、受凉及腹部受冷；密切观察大便性状、次数、尿量及精神状态。\n4. 禁忌：严禁自行使用止泻药（如洛哌丁胺）及含阿托品类药物；仅对脓血便或粪便镜检提示细菌感染者遵医嘱使用抗生素（如头孢克肟颗粒3～6mg/(kg·d)，分2次口服，疗程3～5天），避免抗生素滥用。\n\n【随诊要求】\n1. 口服补液后4～6小时复评脱水状况，若脱水未纠正或加重需及时复诊，必要时静脉补液；用药3天内腹泻无好转或加重者复诊。\n2. 出现以下情况立即复诊或急诊：发热持续不退（>38.5℃）、脓血便、频繁呕吐不能进食进水、精神萎靡或烦躁、尿量明显减少、哭时少泪、口唇干燥等中重度脱水征象。\n3. 腹泻缓解后遵医嘱完成补锌10～14天疗程，并于1～2周后复诊评估营养及生长发育状况，随访至大便性状完全恢复正常。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":279,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8aff73d8167859e54b35454c4d1b32f5c6db22e45fa8b8b27bcf1d34e57d34f3","pinyin":"xiaoerfuxie","initials":"xefx","setting":"out","caseName":"门诊病历144","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历144",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6a4b9f25874c39ee185b","key":"v1-c9ccc21dfe2a3058|templates-6a4b9f25874c39ee185b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿肺炎","category":"门诊病历模板","raw":{"name":"小儿肺炎","category":"门诊病历模板","case":{"case_name":"门诊病历145","templates":{"主诉":"发热、咳嗽伴气促3天。","现病史":"患儿于3天前受凉后出现发热（体温最高39.0℃）、咳嗽（初为干咳后转为有痰咳嗽），3天来出现气促、呼吸费力，无发绀（口周无发绀），食欲下降，精神可，睡眠差，无抽搐，无呕吐。无呛咳异物史，无反复呼吸道感染史，无哮喘史，无食物药物过敏史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T38.8℃，P126次/分，R32次/分（增快）。神志清，精神可，口周无发绀，鼻翼扇动（+），三凹征（-）。双肺呼吸音粗糙，可闻及固定中细湿啰音，叩诊浊音。心率126次/分，律齐。","辅助检查":"【必做】血常规、CRP、降钙素原、胸部X线片（斑片状阴影，可确诊及评估病变范围）；【其他】肺炎支原体或衣原体抗体及核酸（学龄期儿童常见）、痰培养（有痰时）、血气分析（气促明显或低氧时）。","初步诊断":"1. 支气管肺炎（小儿，双侧）\n（注：根据年龄及病原经验治疗：<5岁常见病毒及肺炎链球菌（阿莫西林克拉维酸或头孢类）；学龄儿童疑支原体用阿奇霉素10mg/kg/d×3~5天；雾化（布地奈德+沙丁胺醇）缓解咳喘；退热、祛痰、多饮水；重症（呼吸急促明显、低氧、拒食、精神萎靡）或<3月龄患儿需住院治疗；治疗48~72小时无好转或加重需复诊调整方案。）","处理方案":"【药物治疗】\n1.抗感染治疗（首选）：轻症细菌性肺炎首选阿莫西林克拉维酸钾干混悬剂（7:1或14:1剂型），按阿莫西林计25~45mg/kg/日，分2~3次口服，疗程7~10天；青霉素过敏者选用头孢克肟颗粒3~6mg/kg/日，分2次口服；考虑支原体/衣原体感染者改用阿奇霉素颗粒10mg/kg/日（单次最大0.5g），每日1次口服，连服3天，必要时停药4天后再服1疗程。\n2.退热治疗：体温≥38.5℃伴明显不适时，予布洛芬混悬液5~10mg/kg/次（间隔≥6小时）或对乙酰氨基酚混悬液10~15mg/kg/次（间隔≥4~6小时）口服，24小时内不超过4次，两药不交替使用。\n3.祛痰及雾化治疗：予氨溴索口服液，按年龄每次1.5~3ml（<2岁1.5ml，2~6岁2.5ml，>6岁3ml），每日2~3次；咳嗽痰多或喘息明显者予布地奈德混悬液0.5~1mg+特布他林雾化液2.5~5mg加入生理盐水2ml雾化吸入，每日2次，连用3~5天。\n【一般治疗及生活指导】\n1.充分休息：急性期卧床休息，避免跑跳及剧烈活动，保证充足睡眠，减少耗氧。\n2.饮食护理：给予清淡、易消化、富含蛋白质和维生素的流质或半流质饮食（如米粥、烂面条、蛋羹、蔬菜泥），少量多餐，鼓励多饮温开水，保证液体摄入充足。\n3.环境护理：居室定时开窗通风，保持空气新鲜及适宜温湿度，避免烟雾、粉尘及刺激性气味刺激呼吸道。\n4.日常防护：注意保暖、避免受凉，家长及患儿勤洗手，避免去人多拥挤的公共场所，防止交叉感染；密切观察患儿精神状态、呼吸频率及有无口唇发绀。\n【随诊要求】\n1.用药后3天复诊，评估体温、咳嗽、精神状态及肺部体征改善情况，必要时调整治疗方案。\n2.若用药48~72小时仍持续高热不退、咳嗽加重，或出现呼吸急促、呼吸困难、口唇发绀、精神萎靡、拒食等情况，应立即复诊或急诊就诊。\n3.完成疗程后复查血常规、CRP等炎症指标，必要时复查胸部影像学；有喘息或反复感染倾向者，建议至儿科专科门诊随诊评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":280,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"28f1237403956716643c8345d39725e6c43976fceb45a50913f67269b6df65ff","pinyin":"xiaoerfeiyan","initials":"xefy","setting":"out","caseName":"门诊病历145","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历145",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7d991520ad59350902bd","key":"v1-c9ccc21dfe2a3058|templates-7d991520ad59350902bd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿贫血","category":"门诊病历模板","raw":{"name":"小儿贫血","category":"门诊病历模板","case":{"case_name":"门诊病历146","templates":{"主诉":"面色苍白、乏力、食欲减退3月。","现病史":"患儿于3月来渐出现面色苍白、口唇及甲床苍白、乏力、活动后心慌气短、食欲减退、易激惹，无异食癖（无进食泥土、墙皮等表现），无发热，无皮肤瘀斑及出血点，无黄疸，大便颜色正常。喂养史：母乳喂养至6月龄，后改配方奶喂养，按时添加辅食，偏食，少食肉类、蛋类及绿叶蔬菜。无慢性腹泻史，无寄生虫感染史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P124次/分（可增快），R28次/分。神志清，贫血貌，睑结膜、口唇、甲床苍白（程度中度），巩膜无黄染，皮肤无出血点。心率124次/分，律齐，心尖区可闻及1～2级收缩期杂音。腹平软，肝脾肋下未触及。","辅助检查":"【必做】血常规+网织红细胞（血红蛋白、MCV、MCH降低，呈小细胞低色素改变，提示缺铁）、血清铁蛋白（降低，为缺铁诊断金标准）、总铁结合力；【其他】大便常规+隐血及虫卵（排除消化道失血及寄生虫）、血红蛋白电泳（疑地中海贫血时，表现为小细胞低色素但铁蛋白正常）。","初步诊断":"1. 营养性缺铁性贫血（小儿）\n（注：病因治疗+补铁：口服铁剂（硫酸亚铁或富马酸亚铁，元素铁3~6mg/kg/d，分2~3次，两餐间服，同服维生素C促吸收），疗程至血红蛋白正常后继续6~8周补足储存铁；合理添加辅食（富含铁：肝泥、红肉、强化铁米粉）；定期复查血常规；重度贫血（Hb<60g/L）伴心功能不全者输血；铁剂治疗2周网织红细胞应上升，否则查找原因。）","处理方案":"【药物治疗】\n1. 首选补铁治疗（缺铁性贫血占小儿贫血90%以上）：蛋白琥珀酸铁口服溶液或右旋糖酐铁口服液，按元素铁 2~6mg/(kg·d) 分 2~3 次餐间口服（如右旋糖酐铁口服液25mg/支，按体重折算，bid）。疗程：血红蛋白恢复正常后继续补铁 1~2 个月，以补足储存铁（血清铁蛋白恢复正常）。\n2. 维生素C 50~100mg tid 口服，与铁剂同服促进铁吸收；忌与牛奶、茶、咖啡同服。\n3. 营养性巨幼细胞性贫血（大细胞性，叶酸或维生素B12缺乏）：叶酸 5mg tid 口服，维生素B12 100μg 肌注 qd 或隔日 1 次，连用 2~4 周至血象恢复正常。\n4. 重症贫血（Hb<60g/L）伴气促、心力衰竭表现者：输注浓缩红细胞 5~10ml/kg，缓慢滴注（在急诊或住院观察下执行）。\n\n【一般治疗及生活指导】\n1. 合理喂养：及时添加富铁辅食（动物肝脏、红肉、血制品、蛋黄），4~6月龄婴儿首选强化铁米粉；母乳喂养儿满6个月后需额外补铁，早产儿自2~4月龄开始预防性补铁。\n2. 搭配维生素C：进餐时同食橙子、猕猴桃、番茄等富含维生素C的果蔬促进铁吸收；铁剂与牛奶、茶水间隔1小时以上服用。\n3. 活动管理：轻中度贫血可正常日常活动，避免剧烈运动及劳累；重度贫血（Hb<70g/L）应卧床休息，减少耗氧，避免晕厥跌倒。\n4. 防治感染与病因：注意手卫生，避免去人群密集场所；反复感染或确诊钩虫等寄生虫感染者，需同时抗感染、驱虫治疗并加强营养。\n\n【随诊要求】\n1. 补铁治疗2周后复诊复查血常规，观察网织红细胞上升及血红蛋白回升情况；此后每4周复查1次直至血红蛋白正常。\n2. 血红蛋白正常后继续补铁1~2个月，复诊复查血清铁蛋白，确认储存铁已补足后方可停药。\n3. 规范补铁4周血红蛋白无回升或反而下降者，及时复诊查明原因（依从性、吸收障碍、持续失血、合并其他类型贫血），必要时行血清铁、铁蛋白、叶酸、维生素B12、网织红细胞及地中海贫血基因筛查。\n4. 治疗3个月仍未愈、贫血反复或伴不明原因发热、出血者，转血液专科进一步诊治，必要时行骨髓检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":281,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9b6b78db93fdf068baf0c94105ad402006bb840273385bb3ca0c68f60cb13536","pinyin":"xiaoerpinxue","initials":"xepx","setting":"out","caseName":"门诊病历146","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历146",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7cecf871b86230fa1d77","key":"v1-c9ccc21dfe2a3058|templates-7cecf871b86230fa1d77","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小儿佝偻病","category":"门诊病历模板","raw":{"name":"小儿佝偻病","category":"门诊病历模板","case":{"case_name":"门诊病历147","templates":{"主诉":"多汗、易激惹、夜惊2月，伴骨骼改变1月。","现病史":"患儿为足月儿，生后母乳喂养，未规律补充维生素D（未补充维生素D制剂），户外活动少。于6月龄出现易激惹、夜惊、多汗（与季节无关），枕秃，1月来出现方颅、肋串珠等骨骼改变，运动发育延迟（8月龄尚不能独坐），无抽搐。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第1胎第1产，足月顺产，出生体重3.2kg，无窒息抢救史。母乳喂养，按时添加辅食，预防接种按国家计划进行。生长发育较同龄儿童稍落后，运动发育延迟。","体格检查":"T36.8℃，P118次/分，R30次/分。神志清，精神可。前囟2.5cm×2.5cm、未闭合，方颅（+），可见肋串珠，腕踝部手镯样增厚，双下肢无O型腿畸形，肌张力偏低。心肺听诊未见明显异常。","辅助检查":"检查计划：患儿为足月儿，生后母乳喂养、未规律补充维生素D、户外活动少，6月龄起出现多汗、易激惹、夜惊伴枕秃，近1月出现方颅、肋串珠及运动发育延迟，为明确活动期营养性维生素D缺乏性佝偻病诊断，完善血清25-(OH)D检查，其水平降低为确诊依据，并可评估维生素D缺乏程度；查血钙磷（血钙、血磷）了解钙磷代谢紊乱程度，活动期常见血钙、血磷降低及钙磷乘积下降；查碱性磷酸酶，活动期因成骨活跃多明显升高，用于评估骨转换水平并作为疗效随访指标；查血甲状旁腺激素（PTH），了解有无继发性甲状旁腺功能亢进及其对钙磷代谢的调节影响。完善腕部X线片检查，观察干骺端有无毛刷样、杯口样改变及临时钙化带消失，为活动期佝偻病的影像学诊断依据，并作为治疗前后对比。上述指标在维生素D及钙剂治疗后定期复查，评估疗效并指导剂量调整。\n\n（检查清单）\n【必做】血钙磷、碱性磷酸酶（升高）、血清25-(OH)D（降低，为确诊依据）；【影像学】腕部X线片（干骺端毛刷样或杯口样改变，见于活动期）；【其他】血甲状旁腺激素（继发性甲旁亢）。","初步诊断":"1. 营养性维生素D缺乏性佝偻病（活动期）\n（注：治疗：口服维生素D（活动早期2000~4000IU/d×1个月，后改预防量400~800IU/d维持），同时补钙（元素钙100~200mg/d，尤其小婴儿或饮食钙不足时）；增加户外日照（每日1~2小时）；畸形（O型腿）矫正在佝偻病治愈后进行；预防：新生儿生后2周起补充维生素D400IU/d至2岁；早产儿或低出生体重儿800IU/d×3个月后改400IU。）","处理方案":"【药物治疗】\n1. 维生素D滴剂（胆骨化醇，每粒400IU）：每日2000～4000IU，顿服，疗程1～3个月，待血25-(OH)D恢复正常后改为预防量每日400～800IU维持至2～3岁。\n2. 钙剂：葡萄糖酸钙口服液（10ml:1g）每日10～20ml，分2～3次口服，或碳酸钙颗粒（每袋含元素钙300mg）每日1袋，与维生素D同步服用，奶量充足（每日≥500ml）者剂量酌减，疗程2～3个月。\n3. 重症佝偻病或吸收不良患儿可短期加用活性维生素D（骨化三醇胶囊0.25μg）每日1次口服，用药期间监测血钙、尿钙，症状改善后即停用。\n【一般治疗及生活指导】\n1. 每日户外活动2小时以上，暴露四肢皮肤接受日光照射（宜上午9～10点或下午3～4点，避开正午强光），注意保暖、防暑。\n2. 饮食：坚持母乳或配方奶喂养，及时添加富含维生素D和钙的辅食（蛋黄、动物肝脏、鱼虾、奶制品、豆制品），保证每日奶量≥500ml。\n3. 活动：鼓励俯卧、爬行、翻身等主动运动，避免久坐久站；已出现下肢弯曲畸形者减少负重行走，勿强行按压矫正，可穿矫形鞋辅助。\n4. 禁忌：忌过量补钙和长期大剂量服用维生素D（防止中毒）；避免过早让患儿站立、行走或学步车练习，以免加重O型腿畸形。\n【随诊要求】\n1. 用药1～2个月后复诊，复查血25-(OH)D、血钙、血磷及碱性磷酸酶以评估疗效并调整剂量；若夜惊、多汗、烦躁等症状无缓解，或出现厌食、呕吐、便秘、尿频等维生素D过量表现，应随时复诊。\n2. 治疗期每3～6个月复诊1次，监测腕骨X线片及身高、体重、头围等生长发育指标，直至预防量维持期结束；遗留骨骼畸形者转儿童保健科或骨科进一步评估矫治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":282,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"802e8ee3b19c3d96fbff6ff16b5944f4f2411086598e8d45f427af62dcc4145f","pinyin":"xiaoergouloubing","initials":"xeglb","setting":"out","caseName":"门诊病历147","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历147",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-56918bbc7e63b25bc786","key":"v1-c9ccc21dfe2a3058|templates-56918bbc7e63b25bc786","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"前列腺炎","category":"门诊病历模板","raw":{"name":"前列腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历148","templates":{"主诉":"尿频、尿急、尿痛伴会阴部坠胀不适6月。","现病史":"患者于6月前渐出现尿频（日间8次、夜间2次）、尿急、尿不尽感、排尿痛，伴会阴部、小腹及腰骶部坠胀隐痛，久坐后加重，可向腹股沟区放射，尿道口可有滴白，无发热，无肉眼血尿。有久坐、饮酒及进食辛辣刺激食物等诱因，无不洁性生活史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP122/76mmHg。神志清楚，查体合作。腹平软，无压痛。直肠指检：前列腺大小正常，质地稍韧，中央沟存在，压痛（+），表面光滑，未触及硬结。外生殖器未见异常。","辅助检查":"【必做】尿常规（排除尿路感染）、前列腺液常规（白细胞>10个/HP、卵磷脂小体减少，提示慢性前列腺炎）；【其他】前列腺液细菌培养+药敏（慢性细菌性）、前列腺超声（前列腺大小及回声）、残余尿测定、性传播疾病筛查（疑淋球菌或衣原体感染时）。","初步诊断":"1. 慢性前列腺炎（Ⅲ型）\n（注：治疗以综合为主：抗菌药物（慢性细菌性：氟喹诺酮类左氧氟沙星0.5g qd×4~6周）、α受体阻滞剂（坦索罗辛0.2mg qd）改善排尿症状、植物制剂（普乐安或舍尼通）；热水坐浴、规律排精、避免久坐及辛辣刺激、多饮水；急性细菌性前列腺炎（高热、会阴剧痛）需住院静脉抗感染；疗程足够、避免滥用抗生素，反复发作者泌尿外科随访。）","处理方案":"【药物治疗】\n1. α1受体阻滞剂（首选缓解排尿症状）：盐酸坦索罗辛缓释胶囊0.2mg po qn，或甲磺酸多沙唑嗪控释片4mg po qd，疗程4-6周。\n2. 抗生素（慢性细菌性前列腺炎，选用脂溶性高、易透入前列腺的品种）：左氧氟沙星片0.5g po qd，或盐酸米诺环素胶囊0.1g po bid，疗程4-6周，症状缓解后应足疗程。\n3. 植物制剂（改善症状、辅助抗炎）：普乐安片3-4片 po tid，或舍尼通片1片 po bid，疗程4-8周。\n4. 非甾体抗炎药（前列腺液白细胞增高、会阴部疼痛明显时）：塞来昔布胶囊0.2g po bid，或布洛芬缓释胶囊0.3g po bid，饭后服，疗程7-14天，疼痛缓解后停药。\n\n【一般治疗及生活指导】\n1. 温水坐浴：40℃左右温水坐浴，每日1-2次，每次15-20分钟，促进前列腺血液循环、减轻局部炎症。\n2. 饮食：忌酒及辛辣刺激性食物（辣椒、生蒜、浓茶、咖啡），多饮水（每日2000ml以上），保持尿路通畅。\n3. 生活方式：避免久坐及长时间骑车，每小时起身活动；注意局部保暖，避免受凉、憋尿。\n4. 规律排精：保持适度规律的性生活或定期排精，避免忍精不射及频繁手淫，利于前列腺液引流。\n\n【随诊要求】\n1. 治疗2-4周后门诊复诊，评估排尿症状及会阴部疼痛改善情况。\n2. 复诊复查尿常规、前列腺液常规（白细胞计数及卵磷脂小体），必要时行尿培养及药敏试验。\n3. 抗生素疗程结束后复查评估疗效，细菌性前列腺炎需足疗程后复查培养，防止复发。\n4. 慢性病程者建议症状复发时及时就诊，不宜自行长期服用抗生素。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":283,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8e05aeccddc9cebd3ed4a539b41e48233e291db0aa2ba6b4258cf60161c412b5","pinyin":"qianliexianyan","initials":"qlxy","setting":"out","caseName":"门诊病历148","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历148",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f9a27fe2a3b5304a99eb","key":"v1-c9ccc21dfe2a3058|templates-f9a27fe2a3b5304a99eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"前列腺增生","category":"门诊病历模板","raw":{"name":"前列腺增生","category":"门诊病历模板","case":{"case_name":"门诊病历149","templates":{"主诉":"进行性排尿困难、尿频、夜尿增多2年。","现病史":"患者1周前无明显诱因出现前列腺增生相关不适，症状逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者进行性排尿困难、尿频、夜尿增多2年，为明确前列腺增生诊断、评估下尿路梗阻程度及有无并发症，完善泌尿系超声检查，了解前列腺体积与形态、残余尿量及有无膀胱结石、上尿路积水；查尿常规了解有无血尿、脓尿及尿糖，排除尿路感染、泌尿系结石及糖尿病所致排尿异常；查尿培养明确有无合并尿路感染并指导抗生素选择；查肾功能（血肌酐、尿素氮）评估长期梗阻是否已造成肾功能损害；查电解质了解有无梗阻性肾病或合并用药引起的电解质紊乱。患者属前列腺癌高危人群，查前列腺特异性抗原（PSA）排除前列腺癌，并为是否需前列腺穿刺活检提供依据。完善KUB平片了解有无泌尿系结石及膀胱区钙化；若超声与平片仍不能明确上尿路情况及梗阻部位，完善CT尿路成像进一步明确解剖结构与病变范围。对排尿困难明显、拟行手术治疗者，完善尿流动力学检查，了解膀胱逼尿肌功能及有无膀胱出口梗阻，评估手术获益；必要时行膀胱镜检查，明确膀胱内有无结石、肿瘤及前列腺中叶增生情况。查前列腺液常规以鉴别前列腺炎所致排尿症状。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 前列腺增生\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. α1受体阻滞剂（一线首选，改善排尿症状）：盐酸坦索罗辛缓释胶囊0.2mg qd 睡前口服（或0.4mg qn），连用4周评估疗效，症状改善后长期维持。\n2. 5α还原酶抑制剂（缩小前列腺体积，延缓疾病进展，适用于前列腺体积>40ml者）：非那雄胺片5mg qd，口服，疗程至少6个月（一般3-6个月起效），长期服用维持疗效。\n3. 合并膀胱过度活动症状（尿频尿急明显）者：可加用M受体拮抗剂，如琥珀酸索利那新片5mg qd，口服，连用4-8周评估症状改善情况。\n4. 如无高血压、心律失常等禁忌，可短期联合α1受体阻滞剂与M受体拮抗剂以增强疗效；用药期间注意体位性低血压及口干、便秘等不良反应。\n\n【一般治疗及生活指导】\n1. 生活指导：避免久坐、久站、受凉及过度劳累，避免憋尿，有尿意及时排尿；每晚睡前减少液体摄入量，减少夜尿。\n2. 饮食指导：忌辛辣刺激性食物，戒烟限酒，避免浓茶、咖啡等刺激性饮品；适当多饮水（日间），保持大便通畅，避免用力排便。\n3. 活动指导：适当进行散步、太极拳等温和运动；避免长时间骑车、骑马等骑跨动作，以免压迫会阴部加重症状。\n4. 注意事项：避免使用含抗胆碱成分的感冒药、抗组胺药及拟交感神经药物，以免诱发急性尿潴留；注意会阴部保暖。\n\n【随诊要求】\n1. 服药后2-4周门诊复诊，评估症状改善情况及药物耐受性，必要时调整用药。\n2. 长期服药者每3-6个月复诊一次，复查国际前列腺症状评分（IPSS）、生活质量评分（QOL）、残余尿量及尿流率。\n3. 50岁以上患者每年复查血清PSA及泌尿系超声（前列腺大小、残余尿），动态监测病情进展。\n4. 如出现急性尿潴留、反复肉眼血尿、泌尿系感染伴发热、肾功能损害或药物治疗无效，及时返院就诊，评估手术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":284,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5db9a107cd592718ea3213383fb3164a4ccc306c530a0d01f788bad34baa26a1","pinyin":"qianliexianzengsheng","initials":"qlxzs","setting":"out","caseName":"门诊病历149","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历149",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6fe54eb6c68ea6bc8e37","key":"v1-c9ccc21dfe2a3058|templates-6fe54eb6c68ea6bc8e37","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泌尿系结石","category":"门诊病历模板","raw":{"name":"泌尿系结石","category":"门诊病历模板","case":{"case_name":"门诊病历150","templates":{"主诉":"突发右侧腰痛伴血尿6小时。","现病史":"患者于6小时前无明显诱因突发右侧腰部剧烈绞痛，呈阵发性，向下腹部及会阴部放射，伴恶心、呕吐2次，肉眼血尿（洗肉水样），尿频尿急，无发热，无排尿中断。既往无泌尿系结石病史及排石史。平日饮水少，常有高嘌呤饮食。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P92次/分，R20次/分，BP138/86mmHg。神志清楚，痛苦面容，辗转不安。右肾区叩击痛（+），右输尿管走行区压痛（+），腹平软，无肌紧张反跳痛，肠鸣音正常。外生殖器未见异常。","辅助检查":"【必做】尿常规（红细胞明显增多，提示血尿）、泌尿系超声（肾积水、结石位置及大小）、肾功能、血常规；【影像学】泌尿系CT平扫（阴性结石及输尿管中下段结石，为诊断金标准，疑诊且超声阴性时）；【其他】血尿酸钙磷、24小时尿分析（代谢评估，适用于复发者）。","初步诊断":"1. 输尿管结石（右侧，伴肾积水）\n（注：急性肾绞痛处理：镇痛（双氯芬酸钠75mg im或吲哚美辛栓纳肛）+解痉（山莨菪碱10mg im）+大量饮水；结石<0.6cm且无梗阻感染可保守排石（坦索罗辛0.4mg qd扩张输尿管+多饮水），0.6~2cm行体外冲击波碎石，>2cm或保守无效行输尿管镜碎石；若伴发热（梗阻合并感染）为急症，需急诊引流（双J管或经皮肾造瘘）+抗感染；反复发作查代谢因素。）","处理方案":"【药物治疗】\n1. 解痉镇痛：肾绞痛急性发作时首选非甾体抗炎药，双氯芬酸钠缓释胶囊75mg qd po，或塞来昔布胶囊200mg qd po；疼痛剧烈者可联合盐酸消旋山莨菪碱注射液10mg im 解痉，或间苯三酚注射液80mg 稀释后静脉滴注。\n2. 排石治疗：结石直径≤0.6cm且无明显梗阻、感染者，予坦索罗辛缓释胶囊0.4mg qn po×2-4周，松弛输尿管平滑肌促进排石；尿酸结石或伴高尿酸血症者加用枸橼酸氢钾钠颗粒2.5g tid po，碱化尿液、溶解结石，期间监测尿pH，维持尿pH 6.2-6.9（尿酸结石疗程2-3个月，据复查调整）。\n3. 抗感染：合并尿路感染（尿常规白细胞升高、发热或寒战）者，选用敏感抗菌药物，如左氧氟沙星片0.5g qd po×7天，或头孢呋辛酯片0.25g bid po×7天；无感染证据者不常规使用抗菌药物。\n4. 对症支持：伴恶心、呕吐或进食差者予静脉补液维持尿量并止吐处理；高尿酸血症者加用别嘌醇片起始0.1g qd po，据血尿酸水平调整至0.1g tid po。\n【一般治疗及生活指导】\n1. 大量饮水：每日饮水量2000-3000ml，保持24小时尿量≥2000ml，分次均匀饮用，睡前适量饮水以稀释夜间尿液，避免饮用浓茶、咖啡及含糖饮料。\n2. 饮食调整：限制高草酸食物（菠菜、苋菜、浓茶、坚果、巧克力、甜菜）及高嘌呤食物（动物内脏、海鲜、肉汤、啤酒）摄入；控制钠盐及动物蛋白，草酸钙结石者避免高钙与高草酸食物同餐服用。\n3. 适当活动：结石较小者可适度活动（跳绳、爬楼梯、快走等）配合排石药物促进结石排出；肾绞痛急性发作期应卧床休息、减少活动，避免剧烈运动加重疼痛。\n4. 禁忌：避免久坐憋尿，避免长期过量服用维生素C、钙剂及磺胺类药物；尿酸结石者严禁啤酒及高嘌呤饮食；梗阻合并感染时勿自行服用排石中成药，以免延误解除梗阻的时机。\n【随诊要求】\n1. 治疗1-2周后门诊复诊，复查泌尿系超声（或腹部平片KUB）及尿常规，评估结石排出及感染控制情况。\n2. 出现肾绞痛反复发作、发热伴寒战、血尿加重、尿量明显减少或无尿时，应立即急诊就诊。\n3. 结石排出后3-6个月复诊，复查泌尿系超声及肾功能，行结石成分分析，据此制定个体化饮食与药物预防方案。\n4. 长期随访：每年复查泌尿系超声1次，监测结石复发；有复发倾向者定期复查血尿酸、血钙、尿常规及24小时尿成分分析。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":285,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bf3dc49272ebf7a60877dba51ae869a90fd9c98dd8b3eaa36e9c44295a710782","pinyin":"miniaoxijieshi","initials":"mnxjs","setting":"out","caseName":"门诊病历150","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历150",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6dcadeaef578b8b84c09","key":"v1-c9ccc21dfe2a3058|templates-6dcadeaef578b8b84c09","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"附睾炎","category":"门诊病历模板","raw":{"name":"附睾炎","category":"门诊病历模板","case":{"case_name":"门诊病历151","templates":{"主诉":"阴囊坠胀、疼痛伴肿大1周。","现病史":"患者1周前无明显诱因出现附睾炎相关不适，症状逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者阴囊坠胀、疼痛伴肿大1周，为明确附睾炎诊断并鉴别睾丸扭转、附睾结核及肿瘤，完善泌尿系超声检查，观察附睾体积、形态、血流信号及有无鞘膜积液、睾丸血供情况；查尿常规了解有无白细胞、脓细胞及血尿，明确有无合并尿路感染；查尿培养及药物敏感试验明确致病菌并指导抗生素选择；查肾功能评估感染及抗感染用药对肾脏的影响；查电解质了解有无因疼痛、进食差或发热所致电解质紊乱。患者需与前列腺疾病所致逆行感染相鉴别，查前列腺特异性抗原（PSA）排除前列腺癌并评估前列腺情况。完善KUB平片排除泌尿系结石等感染诱因；若症状不典型或疑合并脓肿、肿瘤，完善CT尿路成像进一步明确病变范围及有无脓肿形成。查前列腺液常规了解有无合并前列腺炎，明确感染来源；对反复发作、疗效不佳者，必要时行尿流动力学检查评估有无排尿功能障碍所致尿液反流；必要时行膀胱镜检查排除膀胱及后尿道病变。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 附睾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 左氧氟沙星片 0.5g po qd×14天：成人首选，覆盖大肠埃希菌等肠杆菌科细菌及部分性传播病原体，服药期间多饮水。\n2. 头孢呋辛酯片 0.5g po bid×14天：可与左氧氟沙星联用增强覆盖，或作为左氧氟沙星禁忌或过敏者的替代方案。\n3. 布洛芬缓释胶囊 0.3g po bid×5-7天：缓解阴囊疼痛、减轻局部炎症，餐后服用；或塞来昔布胶囊 0.2g po qd×5-7天。\n4. 性活跃、疑性传播感染者（合并尿道炎表现）加用多西环素片 0.1g po bid×10天，覆盖沙眼衣原体。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，用阴囊托或毛巾卷将阴囊抬高托起，减轻坠胀与疼痛，避免久站、久坐及剧烈运动。\n2. 发病48小时内局部冷敷（每次15-20分钟、每日3-4次）以减轻水肿，48小时后改温热敷促进炎症吸收。\n3. 清淡饮食，多饮水，忌烟酒及辛辣刺激食物，保持大便通畅。\n4. 治疗期间及症状完全消退前禁性生活及手淫，注意会阴部清洁，穿宽松透气内裤。\n\n【随诊要求】\n1. 用药3-5天后复诊，评估疼痛及肿胀消退情况，必要时调整抗生素方案。\n2. 若发热不退、阴囊红肿加重或疼痛剧烈，须立即就诊，警惕附睾脓肿形成。\n3. 疗程结束后复查血常规、尿常规及阴囊彩超，确认炎症完全消退后再停药。\n4. 反复发作或迁延不愈者，需排除结核性附睾炎、睾丸肿瘤等，转泌尿外科专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":286,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"42c68e51fa09771d9f815a97c3ed45fc5169f775d3c86baadefb9849f70f8d3b","pinyin":"fugaoyan","initials":"fgy","setting":"out","caseName":"门诊病历151","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历151",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0fb33d1ecb18578af55f","key":"v1-c9ccc21dfe2a3058|templates-0fb33d1ecb18578af55f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"精索静脉曲张","category":"门诊病历模板","raw":{"name":"精索静脉曲张","category":"门诊病历模板","case":{"case_name":"门诊病历152","templates":{"主诉":"左侧阴囊坠胀、疼痛不适2年，加重3月。","现病史":"患者于2年前渐出现左侧阴囊坠胀感及隐痛，久站或行走后加重，平卧休息后减轻或消失，3月来症状加重，目前未发现对生育功能的影响，无发热，无尿频尿急，无肉眼血尿。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P72次/分，R18次/分，BP118/74mmHg。站立位检查：左侧阴囊下垂，可触及蚯蚓状迂曲扩张的静脉团（+），平卧后缩小，Valsalva试验（+）。左侧睾丸大小正常。右侧阴囊未见异常。","辅助检查":"【必做】阴囊彩色多普勒超声（精索静脉内径>2mm及反流，可确诊及分级）；【其他】精液常规（不育或拟手术者）、性激素（睾丸功能评估）。","初步诊断":"1. 精索静脉曲张（左侧，Ⅱ度）\n（注：无症状或轻度不影响精液者可保守（阴囊托、避免久站、定期随访）；伴疼痛明显、睾丸萎缩或精液异常（不育）者手术（精索静脉高位结扎术、腹腔镜或显微镜下结扎术）；青少年曲张伴同侧睾丸发育滞后也建议手术；术后随访精液质量改善情况。）","处理方案":"【药物治疗】\n1. 静脉活性药物（改善静脉张力、减轻阴囊坠胀不适）：七叶皂苷钠类：迈之灵片（马栗种子提取物）300mg po bid，餐后服用，疗程4~8周。\n2. 黄酮类静脉活性药物（改善静脉回流）：地奥司明片0.5g po bid，餐后服用，疗程4~8周。\n3. 抗氧化治疗（合并精液质量异常或备孕者）：左卡尼汀口服液1g po tid，疗程3~6个月；可联合维生素E 100mg po bid。\n【一般治疗及生活指导】\n1. 避免久站、久坐及负重、剧烈运动（如举重、长时间骑行），每站立或静坐1小时起身活动5~10分钟，减少腹压增高加重反流。\n2. 穿紧身内裤或使用阴囊托带托高阴囊以减轻坠胀感；卧床休息时可适当垫高阴囊。\n3. 清淡饮食，多食富含维生素C、维生素E及膳食纤维的食物，戒烟限酒，避免辛辣刺激饮食，保持大便通畅，避免用力排便。\n4. 规律作息，避免熬夜及桑拿、热水浴等高温环境（高温可影响生精功能），合并坠胀疼痛明显者可局部冷敷缓解。\n【随诊要求】\n1. 无症状或轻度患者：每3~6个月门诊复查阴囊彩色多普勒超声（测量精索静脉最大内径及Valsalva试验反流情况），动态评估病情。\n2. 阴囊坠胀疼痛明显、体检发现患侧睾丸体积缩小或质地变软者，及时就诊评估手术指征。\n3. 备孕或精液检查异常者：治疗后3~6个月复查精液常规，评估精子质量改善情况；无改善且符合手术指征者建议泌尿外科手术（精索静脉结扎术）治疗。\n4. 手术患者：术后1个月复查阴囊彩超，术后3~6个月复查精液常规及随访症状缓解情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":287,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bc9e201f1b49b7f702ae03b4350e258d3c576849eebdf632b266ef1c0b29aa0b","pinyin":"jingsuojingmaiquzhang","initials":"jsjmqz","setting":"out","caseName":"门诊病历152","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历152",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-56dea087fa2816c89089","key":"v1-c9ccc21dfe2a3058|templates-56dea087fa2816c89089","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痔疮","category":"门诊病历模板","raw":{"name":"痔疮","category":"门诊病历模板","case":{"case_name":"门诊病历153","templates":{"主诉":"便血伴肛内肿物脱出、疼痛3天。","现病史":"患者于3天前出现排便时滴血（鲜血，附着于粪便表面或手纸染血），量少，有肛内肿物脱出，便后可自行回纳，伴肛门坠胀、疼痛（排便时及便后），便秘、久坐、饮酒及进食辛辣刺激食物后加重，无黏液脓血便，无里急后重，无发热。无肝硬化及妊娠等相关病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P78次/分，R18次/分，BP122/78mmHg。神志清楚。肛门视诊：痔核脱出于肛门外，可自行回纳，肛缘未见暗紫色肿物。指诊：齿状线上方可触及柔软痔核，未触及直肠肿物，指套无染血。镜检可见内痔核，齿状线上黏膜隆起。","辅助检查":"【必做】直肠指诊（排除直肠肿瘤，便血患者必做）、肛门镜检查；【其他】结肠镜（便血反复、年龄>40岁或疑结直肠病变时）、血常规（出血多致贫血者）。","初步诊断":"1. 痔（内痔，Ⅱ期）\n（注：保守治疗：调整饮食（高纤维、多饮水）、温水坐浴（每日2~3次）、痔疮膏或痔疮栓（复方角菜酸酯栓、马应龙麝香痔疮膏）、口服静脉活性药物（地奥司明0.5g bid）；嵌顿痔或血栓性外痔疼痛剧烈可手术（痔切除术、PPH或套扎术）；出血量大或反复出血需排除结直肠肿瘤；若疼痛剧烈伴发热提示感染，需急诊处理。）","处理方案":"【药物治疗】\n1. 局部用药（首选）：复方角菜酸酯栓（太宁栓）1枚 纳肛 bid×7天；外用马应龙麝香痔疮膏 适量涂于肛周及痔核表面 bid×7天，便后使用。\n2. 口服静脉活性药物：地奥司明片（爱脉朗）0.9g（2片）bid，餐中服用，共7天，减轻水肿、改善静脉张力。\n3. 便后坐浴：1:5000高锰酸钾溶液温水坐浴（或温水坐浴）每次15分钟，bid，共7天，清洁创面、消肿止痛。\n4. 通便治疗（伴便秘者）：乳果糖口服溶液15ml qd 晨起口服，软化粪便、保持大便通畅，按需连用7天。\n\n【一般治疗及生活指导】\n1. 避免久坐久站，每坐1小时起身活动5-10分钟；排便时间控制在5分钟以内，勿用力屏气、勿久蹲。\n2. 饮食清淡，多饮水（每日1500-2000ml），多食富含膳食纤维的食物（绿叶蔬菜、水果、全谷物、粗粮），忌辛辣刺激食物，戒烟限酒。\n3. 养成定时排便习惯，每日晨起或餐后规律排便，避免憋便；便后温水清洗肛周，保持局部清洁干燥。\n4. 适度活动，每日坚持做提肛运动（收缩肛门3-5秒后放松，每次10-15下，每日2-3组），促进局部血液循环。\n\n【随诊要求】\n1. 用药后1周门诊复诊，评估便血、疼痛、脱出等症状缓解情况，必要时调整治疗方案。\n2. 若出现便血增多、大量鲜血便、剧烈疼痛、痔核脱出嵌顿不能回纳或伴发热，请立即急诊就诊。\n3. 反复便血或症状持续不缓解者，建议行肛门指检及结肠镜检查，排除结直肠其他病变。\n4. 保守治疗4周无效或症状反复发作、影响生活者，转肛肠外科评估手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":288,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"286e446c0da6759899d6b5418f6149aa93725f0bb7208ca77f015c21abf38f18","pinyin":"zhichuang","initials":"zc","setting":"out","caseName":"门诊病历153","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历153",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-69fd88ccf9eeff458dda","key":"v1-c9ccc21dfe2a3058|templates-69fd88ccf9eeff458dda","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肛裂","category":"门诊病历模板","raw":{"name":"肛裂","category":"门诊病历模板","case":{"case_name":"门诊病历154","templates":{"主诉":"排便时肛门剧痛伴便后滴血2周。","现病史":"患者于2周前（便秘后）出现排便时肛门刀割样剧痛，便后疼痛持续30分钟至数小时（疼痛间歇期），伴手纸染血（鲜血、量少），粪便表面带血，因惧怕疼痛而有意减少排便致便秘加重，无发热，无黏液脓便。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P76次/分，R18次/分，BP120/76mmHg。神志清楚。肛门视诊（嘱患者放松并轻牵肛缘）：肛管后正中可见纵行裂口，溃疡面新鲜，边缘整齐。指诊（动作轻柔）：肛门括约肌紧张，裂口处触痛明显，无前哨痔及肛乳头肥大，指套无染血。","辅助检查":"【必做】以视诊及指诊为主；【其他】肛门镜（急性期疼痛重可暂缓）、结肠镜（慢性或不典型裂口需排除克罗恩病、结核等，如肛裂位置不在正中线或呈多发时）。","初步诊断":"1. 肛裂（急性）\n（注：治疗以解除括约肌痉挛、软化大便、促进愈合为原则：温水坐浴（便后及睡前，每日2~3次，每次15分钟）、高纤维饮食+多饮水、缓泻剂（乳果糖15ml qd）软化大便；局部药物：硝酸甘油软膏（解除痉挛）、利多卡因凝胶（止痛）；慢性肛裂（>6周）或保守无效者可手术（肛裂切除术或内括约肌侧切术）；反复发作伴不典型部位裂口需进一步检查排除炎症性肠病。）","处理方案":"【药物治疗】\n1. 硝酸甘油软膏（0.4%）：每次取约1g（约1cm膏体）涂于肛管内齿状线下方，每日2次，疗程4-8周，可缓解内括约肌痉挛、改善局部血供、促进创面愈合。\n2. 复方角菜酸酯栓（太宁栓）：每次1枚纳肛，每日2次，便后使用，疗程7-14天，保护创面、润滑止痛、促进上皮修复。\n3. 乳果糖口服溶液：每次15ml，每日1-2次，晨起空腹服用，疗程视便秘改善情况而定（通常1-2周），软化大便、减少排便时对肛管创面的机械损伤。\n4. 仅在明确合并局部感染（红肿、脓性分泌物、发热）时加用头孢克肟胶囊0.1g bid×5-7天或左氧氟沙星片0.5g qd×5天，无感染证据者不常规使用抗生素。\n\n【一般治疗及生活指导】\n1. 温水坐浴：每日2-3次，便后加做1次，用40-45℃温水坐浴10-15分钟，松弛括约肌、减轻疼痛、清洁创面、促进局部血液循环。\n2. 饮食调护：每日饮水1500-2000ml，多食富含膳食纤维的食物（新鲜蔬菜、水果、全谷物、粗粮），忌辛辣刺激食物，戒烟酒，避免煎炸及过干过燥饮食。\n3. 保持大便通畅：养成定时排便习惯（晨起或餐后），每次排便控制在5分钟以内，避免久蹲久坐、用力努挣；排便困难时勿强行屏气用力。\n4. 禁忌事项：避免长期使用番泻叶、大黄、酚酞等刺激性泻药（以免产生依赖及加重括约肌痉挛）；避免坐浴水温过高烫伤；避免骑自行车、骑马等久坐压迫肛周的活动。\n\n【随诊要求】\n1. 用药2周后复诊，评估疼痛、便血及创面愈合情况，调整用药方案。\n2. 若规范保守治疗4-6周症状无明显缓解或创面不愈合，复诊评估是否需行肛管括约肌切开术等进一步治疗。\n3. 治疗期间若出现剧烈肛周疼痛、出血量增多、脓性分泌物、发热等，及时随诊或急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":289,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"76534d2114ddbd2dff7929b5b65bb39e0b925baa83721898e924fbf3ee0a24bd","pinyin":"ganglie","initials":"gl","setting":"out","caseName":"门诊病历154","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历154",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3c01d0050bf21a74dc68","key":"v1-c9ccc21dfe2a3058|templates-3c01d0050bf21a74dc68","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肛瘘","category":"门诊病历模板","raw":{"name":"肛瘘","category":"门诊病历模板","case":{"case_name":"门诊病历155","templates":{"主诉":"肛周反复肿痛、流脓6月，再发加重3天。","现病史":"患者6月前肛周肿痛后破溃流脓，此后反复出现肛周肿痛、流脓，脓液为黄白色，量时多时少，可自行破溃或需挤压排脓，破溃后疼痛减轻，3天前再次肿痛加重，伴发热（体温最高38.5℃），无排便习惯改变，无黏液脓血便。既往无肛周脓肿切开引流史、结核病及克罗恩病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P96次/分，R20次/分，BP118/74mmHg。神志清楚，查体合作。肛门视诊：肛周5点钟方向可见外口，红肿，挤压见脓性分泌物；指诊：可触及索条状瘘管，内口在齿状线上可触及凹陷，肛门括约肌张力正常。","辅助检查":"【必做】直肠指诊（明确瘘管走行及内口）；【影像学】肛周超声或盆腔MRI（复杂瘘、高位瘘或反复手术者，用以明确瘘管与括约肌关系）；【其他】瘘管造影（必要时）、脓液细菌培养（疑结核等特殊感染时）。","初步诊断":"1. 肛瘘（低位，括约肌间型）\n（注：肛瘘不能自愈，手术是唯一根治方法（瘘管切开术或挂线疗法，适用于高位复杂瘘），急性感染期先抗感染（甲硝唑0.4g bid+头孢类）及切开引流；反复发作、多发性或不典型位置肛瘘需排查克罗恩病、结核等病因；术后保持引流通畅、温水坐浴，遵医嘱换药，防止假性愈合复发。）","处理方案":"【药物治疗】\n1. 抗感染治疗（急性炎症期首选）：头孢克肟胶囊0.1g po bid，连用5~7天；或左氧氟沙星片0.5g po qd，连用5天（18岁以上、无喹诺酮过敏史者）。若疼痛明显伴发热，可联合甲硝唑片0.4g po tid×7天，覆盖厌氧菌。\n2. 局部坐浴：高锰酸钾溶液（1:5000，约半盆温水加1/3片）温水坐浴，每次15~20分钟，bid~tid，便后及睡前各1次，连用1~2周，清洁引流、减轻水肿疼痛。\n3. 局部外用：马应龙麝香痔疮膏外用涂于肛患者肿处，或太宁栓（复方角菜酸酯栓）1粒纳肛 bid，连用7天，缓解局部肿痛。\n4. 对症止痛：双氯芬酸钠缓释片75mg po qd，疼痛明显时口服，一般不超过3天。\n\n【一般治疗及生活指导】\n1. 注意休息，避免久坐久站及长时间骑自行车等压迫会阴部的活动；保持肛周清洁干燥，每日温水清洗，便后坐浴。\n2. 饮食清淡易消化，多饮水（每日1500~2000ml），多吃富含膳食纤维的蔬菜、水果（如香蕉、芹菜），保持大便通畅柔软，忌辛辣、油腻及酒类刺激。\n3. 养成规律排便习惯，避免用力排便、久蹲，同时防治腹泻，避免稀便反复刺激瘘口。\n4. 控制血糖、戒烟；如有糖尿病、慢性腹泻等基础病需同步治疗，否则易复发。\n\n【随诊要求】\n1. 门诊治疗1周后复诊，评估红肿、疼痛及分泌物情况；肛瘘根治以手术为主，保守治疗仅为控制急性感染，应转肛肠外科评估手术时机（肛瘘切开术或挂线术）。\n2. 若出现畏寒发热、肛患者肿范围扩大、疼痛剧烈或触及波动感（提示脓肿形成），立即急诊就诊。\n3. 若症状反复发作或保守治疗2周无效，需进一步行肛周MRI或肛管超声明确瘘管走行后择期手术。\n4. 术后需遵医嘱定期换药复查，观察创面愈合情况，防止假性愈合及复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":290,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6d0794695f28ed6a649110abee75e132e31b2a2696a3df1009644b10aec2dd5e","pinyin":"ganglou","initials":"gl","setting":"out","caseName":"门诊病历155","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历155",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2a1bb0a165affb356280","key":"v1-c9ccc21dfe2a3058|templates-2a1bb0a165affb356280","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肛周脓肿","category":"门诊病历模板","raw":{"name":"肛周脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历156","templates":{"主诉":"肛患者肿、剧痛伴发热3天。","现病史":"患者于3天前出现肛周持续性跳痛，坐立及排便时加重，渐出现肛患者肿、灼热，可触及肿块，伴发热（体温最高38.7℃），畏寒，无恶心呕吐，无排尿困难。无糖尿病、免疫力低下及肛周感染史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.7℃，P98次/分，R20次/分，BP120/76mmHg。神志清楚，急性痛苦面容。肛周3点钟方向可见局限性红肿，范围约3cm×4cm，皮温升高，触痛明显（+++），可及波动感，穿刺可抽出脓液。直肠指诊：肛管直肠环及坐骨直肠窝压痛及隆起。","辅助检查":"【必做】血常规（白细胞及中性粒细胞显著升高）、CRP；【影像学】肛周超声（脓腔定位、大小及深度，用于术前评估）；【其他】血糖（排查糖尿病）、脓液细菌培养（切开后）。","初步诊断":"1. 肛周脓肿（肛周皮下）\n（注：肛周脓肿一旦形成应尽早切开引流（在波动最明显处，脓腔充分打开），延误可致脓腔蔓延（坐骨直肠窝、骨盆直肠窝脓肿）、全身感染甚至坏死性筋膜炎；术后换药保持引流通畅、温水坐浴，配合抗感染（甲硝唑+头孢类）；糖尿病患者控制血糖；约半数日后形成肛瘘，需二期处理。）","处理方案":"【药物治疗】\n1. 抗感染治疗：首选覆盖需氧菌与厌氧菌的广谱方案，甲硝唑片0.4g tid×7天，联合头孢克肟胶囊0.1g bid×7天；或阿莫西林克拉维酸钾片0.457g tid×7天。青霉素过敏者改用甲硝唑片0.4g tid联合左氧氟沙星片0.5g qd，疗程7天。\n2. 镇痛对症：布洛芬缓释胶囊0.3g bid po，疼痛缓解后即停，一般用3~5天；或对乙酰氨基酚片0.5g prn。\n3. 通便处理：乳果糖口服溶液15ml qd，或聚乙二醇4000散10g qd~bid，保持大便通畅柔软，避免排便用力加重局部充血。\n4. 局部治疗：温水坐浴，每日2~3次，每次15~20分钟（水温40℃左右，可加1:5000高锰酸钾溶液）；坐浴后肛周涂莫匹罗星软膏或鱼石脂软膏外用。\n\n【一般治疗及生活指导】\n1. 休息与体位：急性期注意休息，避免久坐、久站、久蹲及骑自行车等增加肛周受压的活动，坐位时可用中空坐垫减轻压迫。\n2. 饮食指导：清淡饮食，多饮水，多食富含膳食纤维的蔬菜、水果（如芹菜、香蕉、火龙果），忌辛辣刺激及油腻食物，忌烟酒。\n3. 局部护理：保持肛周清洁干燥，便后用温水清洗或坐浴，勤换宽松透气的棉质内裤，勿搔抓挤压局部。\n4. 基础病控制：合并糖尿病者应严格控制血糖（监测空腹及餐后血糖），血糖波动可致感染迁延不愈；避免自行挤压、热敷过度或乱用偏方。\n\n【随诊要求】\n1. 用药后3天复诊评估疗效；若治疗期间红肿范围扩大、疼痛加重、出现发热或波动感，应立即复诊，勿自行延误。\n2. 脓肿一旦形成波动感，需及时行切开引流术；术后每周复诊换药，观察创面引流及愈合情况，直至创口完全愈合。\n3. 反复发作或术后持续流脓、瘙痒、经久不愈者，提示可能形成肛瘘，建议转肛肠外科进一步检查，必要时行肛瘘根治术。\n4. 一般2~4周内门诊复查，确认炎症消退、创面愈合良好后结束随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":291,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"635e63ae9f2b74eda1c3aa9a368db6c824c055fd470349f7fc4227d0b16d1d6d","pinyin":"gangzhounongzhong","initials":"gznz","setting":"out","caseName":"门诊病历156","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历156",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cf42e128f7280ba028e2","key":"v1-c9ccc21dfe2a3058|templates-cf42e128f7280ba028e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阑尾炎","category":"门诊病历模板","raw":{"name":"阑尾炎","category":"门诊病历模板","case":{"case_name":"门诊病历157","templates":{"主诉":"转移性右下腹痛1天，伴恶心。","现病史":"患者于12小时前无明显诱因出现脐周隐痛，呈持续性，6小时前疼痛转移并固定于右下腹，呈持续性胀痛、阵发性加重，伴恶心、呕吐2次（胃内容物），发热（体温最高38.3℃），食欲减退，无腹泻便秘（大便正常），无尿频尿急。今日来我院急诊就诊。发病以来精神差。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.3℃，P96次/分，R20次/分，BP118/74mmHg。神志清楚，痛苦面容，屈曲体位。腹平坦，右下腹麦氏点压痛（+），有反跳痛，局部肌紧张，结肠充气试验（Rovsing征）（+），腰大肌试验（+），闭孔内肌试验（+），肠鸣音减弱。","辅助检查":"【必做】血常规（白细胞及中性粒细胞升高）、CRP、尿常规（排除泌尿系结石或感染）；【影像学】腹部超声（阑尾肿大、周围积液，早期可阴性）、腹部CT（诊断不明确或老年或肥胖者，显示阑尾增粗、周围脂肪间隙模糊）；【其他】血淀粉酶（与胰腺炎鉴别）。","初步诊断":"1. 急性阑尾炎（化脓性）\n（注：诊断明确后应尽早行阑尾切除术（腹腔镜或开腹），术前禁食、补液、抗感染（头孢+甲硝唑）；单纯性早期可考虑保守（抗感染48~72小时，观察病情），但复发率高；若疼痛扩散至全腹、高热、腹膜炎体征加重提示穿孔，需急诊手术；育龄女性需与异位妊娠、黄体破裂、附件炎鉴别（必要时HCG及妇科超声）。）","处理方案":"【药物治疗】\n1. 抗感染（覆盖肠道需氧菌及厌氧菌，保守治疗首选方案）：头孢呋辛酯片0.25g bid×5天，联合甲硝唑片0.4g tid×5天，均餐后口服。\n2. 青霉素或头孢菌素过敏者换用：左氧氟沙星片0.5g qd×5天，联合甲硝唑片0.4g tid×5天。\n3. 解痉对症：山莨菪碱片10mg tid×3天（腹痛明显时口服，青光眼、前列腺肥大者禁用；诊断未明确前禁用镇痛药）。\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，避免剧烈运动、跑跳及腹部挤压，保持情绪平稳。\n2. 饮食：暂进流质或半流质清淡饮食（米汤、稀粥、烂面条），忌油腻、生冷、辛辣刺激及产气食物（牛奶、豆类、碳酸饮料），治疗期间禁饮酒、禁暴饮暴食。\n3. 观察：密切注意腹痛变化，若腹痛由脐周转移至右下腹并固定、进行性加重，或伴发热、恶心呕吐、腹泻，提示病情进展，须立即急诊就医。\n【随诊要求】\n1. 用药3天后复诊，评估腹痛缓解情况、体温及血常规变化。\n2. 保守治疗期间若腹痛持续加重、出现高热（≥38.5℃）、右下腹压痛反跳痛明显等腹膜刺激征，须立即急诊行外科评估，必要时中转手术治疗。\n3. 症状缓解后5～7天复查血常规、腹部超声，排除阑尾周围脓肿；症状消失后1个月门诊复诊，评估有无复发或脓肿形成。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":292,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8c7c0820d03c94e58f39cd235d621bc18f2be32fdaa55bd58246146e51870752","pinyin":"lanweiyan","initials":"lwy","setting":"out","caseName":"门诊病历157","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历157",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-36d949fdd9e94b4cdf19","key":"v1-c9ccc21dfe2a3058|templates-36d949fdd9e94b4cdf19","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆囊炎","category":"门诊病历模板","raw":{"name":"胆囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历158","templates":{"主诉":"右上腹疼痛反复发作3年，再发伴发热2天。","现病史":"患者于3年前反复出现右上腹疼痛，多于进食油腻后发作，可向右肩背部放射，伴恶心，无发热，需就医缓解。本次于2天前再发右上腹持续性胀痛，阵发性加重，向右肩背放射，伴恶心、呕吐2次，发热（体温最高38.5℃），无黄疸，无呕血黑便。既往有胆囊结石病史（超声证实）。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P96次/分，R20次/分，BP124/78mmHg。神志清楚，急性病容。皮肤巩膜无黄染。腹平，右上腹压痛（+），Murphy征（+），有肌紧张及反跳痛，未触及肿大之胆囊，肝区叩击痛（+），肠鸣音正常。","辅助检查":"检查计划：患者右上腹疼痛反复发作3年，多于进食油腻后诱发，本次再发持续性胀痛并向右肩背放射，伴恶心、呕吐及发热（体温最高38.5℃），既往有胆囊结石病史，为明确急性胆囊炎诊断、评估炎症程度及有无胆道梗阻，急诊完善血常规了解白细胞及中性粒细胞升高程度，评估感染与炎症反应；查CRP了解炎症活动度，与血常规联合判断病情及疗效；查肝功能（ALT、AST、ALP、胆红素）判断有无肝细胞损伤及胆道梗阻，为是否继发急性胆管炎提供依据；查血淀粉酶、脂肪酶排除胆源性胰腺炎。完善腹部超声检查，了解胆囊壁增厚、胆囊结石、胆囊周围积液及胆总管有无扩张，为诊断依据并可排除胆总管结石。若出现高热寒战、黄疸或腹膜炎体征，疑胆总管结石、胆囊穿孔或Mirizzi综合征时，完善腹部CT或MRCP进一步明确胆道解剖与梗阻部位，为急诊手术或ERCP+EST治疗提供依据。\n\n（检查清单）\n【必做】血常规、CRP、肝功能（ALT/AST/ALP/胆红素，用以判断有无胆道梗阻）、血淀粉酶脂肪酶；【影像学】腹部超声（胆囊壁增厚、胆囊结石、胆囊周围积液，为诊断依据）；【其他】腹部CT或MRCP（疑胆总管结石、胆囊穿孔或Mirizzi综合征时）。","初步诊断":"1. 胆囊炎（急性，伴胆囊结石）\n（注：急性发作：禁食、补液、抗感染（三代头孢+甲硝唑）、解痉镇痛（山莨菪碱），症状缓解后择期腹腔镜胆囊切除；慢性胆囊炎伴症状反复发作或结石>2cm者也建议择期手术；若出现高热寒战、黄疸、腹膜炎体征提示坏疽穿孔或继发胆管炎，需急诊处理（手术/ERCP+EST）。）","处理方案":"【药物治疗】\n1. 抗感染（急性发作首选方案）：头孢呋辛酯片0.25g bid×5～7天＋甲硝唑片0.4g tid×5～7天；对青霉素类过敏者改用左氧氟沙星片0.5g qd×5～7天＋甲硝唑片0.4g tid×5～7天。\n2. 解痉镇痛：山莨菪碱片（654-2）10mg tid，餐后服，腹痛缓解后停用（青光眼、前列腺增生、尿潴留者禁用）。\n3. 利胆（慢性胆囊炎、胆泥沉积）：熊去氧胆酸胶囊250mg tid，饭后服，疗程4～8周。\n4. 助消化：复方阿嗪米特肠溶片（泌特）2片 tid，餐后服，用于胆汁分泌不足所致腹胀、消化不良。\n【一般治疗及生活指导】\n1. 急性发作期卧床休息，发作24～48小时内暂禁食或仅进清淡流质（米汤、稀藕粉），必要时需静脉补液支持；症状缓解后渐进恢复饮食。\n2. 坚持低脂、低胆固醇饮食：忌肥肉、油炸食品、动物内脏、蛋黄、浓肉汤、奶油糕点；少食多餐，定时定量，避免暴饮暴食及过饱。\n3. 禁酒，避免辛辣刺激及产气食物（洋葱、豆类）；规律作息，保证充足睡眠，避免熬夜及过度劳累。\n4. 缓解期适当运动（散步、慢跑等），控制体重，避免快速减重（快速减肥可诱发胆泥形成）。\n【随诊要求】\n1. 用药3天后腹痛、发热、恶心等症状无缓解或加重，或出现寒战高热、皮肤巩膜黄染、右上腹压痛反跳痛加剧，应立即急诊就诊。\n2. 完成疗程后1周复查血常规、肝功能、腹部超声，评估炎症消退及胆系情况。\n3. 慢性胆囊炎每3～6个月复查腹部超声；若症状反复发作，或超声提示胆囊结石＞2cm、胆囊壁增厚＞4mm、胆囊萎缩或结石嵌顿者，建议肝胆外科会诊评估择期胆囊切除术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":293,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3f933f3c57ff1eff49c7d404eedf8ab7acc371b0bf9977eb1728ecb49eefbd15","pinyin":"dannangyan","initials":"dny","setting":"out","caseName":"门诊病历158","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历158",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2b5470b5ec1e056321a1","key":"v1-c9ccc21dfe2a3058|templates-2b5470b5ec1e056321a1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆石症","category":"门诊病历模板","raw":{"name":"胆石症","category":"门诊病历模板","case":{"case_name":"门诊病历159","templates":{"主诉":"右上腹绞痛反复发作2年，再发6小时。","现病史":"患者于2年前出现右上腹阵发性绞痛，多于进食油腻食物、饱餐后夜间发作，向右肩背部放射，伴恶心、呕吐，持续2小时后自行缓解，反复发作。本次于6小时前进食油腻后再次发作，疼痛剧烈，伴恶心，呕吐2次，无发热寒战，无黄疸，无呕血黑便。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P84次/分，R18次/分，BP120/76mmHg。神志清楚，痛苦面容。皮肤巩膜无黄染。腹软，右上腹压痛（+），Murphy征（+），无反跳痛肌紧张，肝区叩击痛（+），肠鸣音正常。","辅助检查":"【必做】腹部超声（胆囊结石（数量、大小）、胆管结石、胆囊壁及胆管扩张情况，为首选检查）、血常规、肝功能（胆红素、ALP、ALT/AST）、血淀粉酶脂肪酶；【影像学】MRCP（疑胆总管结石）、腹部CT；【其他】心电图（老年患者排除心绞痛，下壁心梗可表现为上腹痛）。","初步诊断":"1. 胆囊结石（伴急性胆囊炎发作）\n（注：发作期对症（禁食、解痉镇痛，如间苯三酚或山莨菪碱、抗感染）；症状反复或有并发症风险者择期腹腔镜胆囊切除；无症状结石（>2cm、合并糖尿病、胆囊息肉等）可择期手术或定期随访；若出现高热寒战+黄疸（Charcot三联征）提示急性胆管炎，属急症需急诊ERCP或手术引流；胆源性胰腺炎风险者尽早手术。）","处理方案":"【药物治疗】\n1. 利胆溶石：熊去氧胆酸胶囊（优思弗）250mg bid 饭后口服（10~13mg/kg/d分2次），疗程6~12个月，适用于胆囊功能良好、胆固醇型结石且结石直径＜1.5cm者。\n2. 解痉镇痛：间苯三酚片40mg tid po 或 山莨菪碱片10mg tid po，用于缓解胆绞痛；疼痛剧烈者可临时予间苯三酚注射液80mg im 或 布桂嗪注射液100mg im，必要时4~6小时重复，注意排除急性胆管炎及急性胰腺炎。\n3. 抗感染（合并胆系感染时）：头孢曲松钠2.0g ivdrip qd×5~7天，或 左氧氟沙星片0.5g qd po×5~7天；伴高热、黄疸、寒战者按急性胆管炎处理并转急诊。\n4. 辅助消化：复方消化酶胶囊1粒 tid 饭后口服，改善脂肪消化不良及腹胀。\n【一般治疗及生活指导】\n1. 低脂低胆固醇饮食，规律三餐、忌暴饮暴食和长期空腹，避免油炸肥腻食物、动物内脏、蛋黄、浓肉汤等高脂高胆固醇食物，晚餐不宜过饱。\n2. 急性发作期卧床休息，暂禁食或予流质（米汤、稀粥），疼痛缓解后逐步过渡至低脂半流质饮食。\n3. 控制体重，坚持适度有氧运动（快走、游泳、骑车等），避免久坐；合并糖尿病、高脂血症者积极控制血糖、血脂，避免快速减重（每周体重下降不宜超过0.5~1kg）。\n4. 避免长期服用雌激素、降脂药（贝特类）及反复快速减肥等易促发结石形成的因素；禁烟限酒。\n【随诊要求】\n1. 每3~6个月门诊复查腹部超声，观察结石大小、数目及胆囊壁厚度变化。\n2. 定期复查肝功能、血脂、空腹血糖；随访期间若出现右上腹或上腹持续性剧痛、发热寒战、皮肤巩膜黄染、呕吐等，立即急诊就诊，警惕急性胆囊炎、急性胆管炎及急性胰腺炎。\n3. 反复发作胆绞痛、结石直径＞2cm、胆囊壁增厚＞3mm、合并胆囊息肉或胆囊萎缩、瓷化胆囊者，建议转肝胆外科评估择期胆囊切除术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":294,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f8826f23a65264a2def9dd7efaef975069d8346ff40286cbeb621e3dd6cec51f","pinyin":"danshizheng","initials":"dsz","setting":"out","caseName":"门诊病历159","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历159",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ef7fc95233be0b416324","key":"v1-c9ccc21dfe2a3058|templates-ef7fc95233be0b416324","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性胰腺炎","category":"门诊病历模板","raw":{"name":"急性胰腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历160","templates":{"主诉":"中上腹持续剧痛伴恶心呕吐半天","现病史":"患者于12小时前暴饮暴食后突发上腹部持续性剧烈疼痛，呈束带样向腰背部放射，弯腰抱膝位稍缓解，伴恶心、呕吐3次（呕吐后腹痛不缓解），发热（体温最高38.2℃），腹胀，无腹泻便血。既往无胆石症、高脂血症、饮酒史及胰腺炎发作史。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒20年，约2两/日。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P104次/分，R22次/分，BP118/74mmHg。神志清楚，急性痛苦面容。腹膨隆，上腹部压痛明显（+），有反跳痛及肌紧张，移动性浊音阴性，肠鸣音减弱。脐周及腰部皮肤无瘀斑，Cullen征及Grey-Turner征阴性（不支持重症）。","辅助检查":"【必做】血淀粉酶及脂肪酶（超过正常上限3倍，为诊断依据；脂肪酶特异性更高）、血常规、CRP、肝功能、血糖、血钙、肾功能、电解质、血气分析、血脂；【影像学】腹部CT（增强，可见胰腺肿胀、坏死、渗出，用以评估严重程度及并发症）、腹部超声（胆源性，可见胆囊结石、胆总管扩张）；【其他】心电图。","初步诊断":"1. 急性胰腺炎（轻型，酒精性）\n诊断依据：①突发上腹部持续性剧烈疼痛，呈束带样向腰背部放射，弯腰抱膝位稍缓解，伴恶心、呕吐，呕吐后腹痛不缓解，伴腹胀及发热；②查体上腹部压痛明显、有反跳痛及肌紧张，肠鸣音减弱；③血淀粉酶及脂肪酶超过正常上限3倍；④腹部CT增强可见胰腺肿胀、渗出等改变。\n（注：轻型：禁食水、胃肠减压、抑制胰酶分泌（生长抑素/奥曲肽）、补液、镇痛、抗感染（胆源性）；重症（持续器官功能衰竭、胰腺坏死感染、假性囊肿）需ICU监护、积极液体复苏、营养支持（肠内营养）、必要时介入/手术清创；高脂血症性者降脂（血浆置换指征）；病愈后去除病因（胆囊切除、戒酒、控制血脂）以防复发。）","处理方案":"【药物治疗】\n1. 抑制胰酶分泌：奥曲肽注射液0.1mg 皮下注射，每8小时1次，疗程3～5天。\n2. 抑酸护胃：奥美拉唑肠溶胶囊20mg 每日1次口服（症状重者可增至每日2次），疗程5～7天，减少胃酸刺激并预防应激性溃疡。\n3. 解痉止痛：山莨菪碱片10mg 每日3次口服，腹痛剧烈时予间苯三酚注射液80mg 肌注；禁用吗啡（以免诱发Oddi括约肌痉挛加重病情）。\n4. 补充胰酶：胰酶肠溶胶囊0.3g 每日3次餐中服用，自恢复进食后开始，疗程1～2周，改善消化吸收功能。\n【一般治疗及生活指导】\n1. 急性期（腹痛明显、血淀粉酶/脂肪酶升高期间）暂禁食水，注意休息，疼痛发作时卧床并取屈膝侧卧位以减轻腹痛；腹痛缓解、肠鸣音恢复后逐步过渡为低脂流质→低脂半流质→低脂软食，少量多餐。\n2. 严格禁酒、戒烟，避免暴饮暴食及高脂高蛋白饮食（如油炸食品、肥肉、动物内脏、浓肉汤、蛋黄），康复后长期保持低脂饮食。\n3. 避免劳累、剧烈运动和腹部挤压外伤；若为高脂血症性胰腺炎，需同时控制甘油三酯及血糖，规律服用降脂药，避免使用可能诱发胰腺炎的药物（如噻嗪类利尿剂、糖皮质激素等）。\n【随诊要求】\n建议3～5天后复诊，复查血常规、血淀粉酶/脂肪酶、肝肾功能、血糖、血脂及腹部超声；若腹痛持续加重、发热、腹胀明显或出现呼吸困难，须立即急诊就诊。反复发作者建议完善腹部增强CT、胆道MRCP等检查明确病因（胆源性、高脂血症性、酒精性等），并至消化内科专科门诊规律随诊，每1～3个月复查血脂、血糖及腹部影像学，评估复发风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":295,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4c072fb8b3175b019399ab3bae41995dafde4cdc7d0290775077d2538c6ea201","pinyin":"jixingyixianyan","initials":"jxyxy","setting":"out","caseName":"门诊病历160","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历160",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-af3430c0ae051eae8c41","key":"v1-c9ccc21dfe2a3058|templates-af3430c0ae051eae8c41","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠梗阻","category":"门诊病历模板","raw":{"name":"肠梗阻","category":"门诊病历模板","case":{"case_name":"门诊病历161","templates":{"主诉":"腹痛、腹胀伴停止排气排便2天。","现病史":"患者于2天前出现腹部阵发性绞痛，渐加重，伴腹胀，恶心、呕吐3次（呕吐物：初为胃内容物后为粪样，提示低位梗阻），停止排气排便24小时，无发热。既往无腹部手术史（粘连性肠梗阻最常见）、疝、肿瘤、便秘史。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P96次/分，R20次/分，BP118/74mmHg。神志清楚，痛苦面容。腹膨隆，可见肠型及蠕动波，腹壁未见手术瘢痕，腹部压痛（+），无反跳痛及肌紧张（绞窄时出现），叩诊鼓音，移动性浊音阴性，肠鸣音亢进、可闻及气过水声，疝口无嵌顿。","辅助检查":"【必做】腹部立位X线片（阶梯状液气平面，为梗阻征象）、血常规、电解质、肾功能、血气分析、血淀粉酶脂肪酶；【影像学】腹部CT平扫+增强（明确梗阻原因（粘连或肿瘤或疝）、部位及有无绞窄缺血，诊断敏感度高）；【其他】肿瘤标志物（疑肿瘤性梗阻）。","初步诊断":"1. 肠梗阻（机械性，小肠部位，单纯性）\n（注：基础治疗：禁食水、胃肠减压、纠正水电解质酸碱紊乱、抗感染（肠源性感染）；单纯性粘连性肠梗阻可保守治疗24~48小时观察；出现绞窄征象（持续剧烈腹痛、腹膜炎体征、发热、血性腹水、CT提示肠壁缺血）或保守无效者需急诊手术；肿瘤性梗阻择期根治手术；老年患者注意排除结肠肿瘤所致梗阻。）","处理方案":"【药物治疗】\n1. 抗感染：头孢呋辛酯片0.25g po bid×5天，联合甲硝唑片0.4g po tid×5天，餐后服用（用于炎性肠梗阻或疑有绞窄、腹膜炎征象者；青霉素或头孢过敏者改用左氧氟沙星片0.5g po qd×5天）。\n2. 解痉止痛：山莨菪碱片（654-2）10mg po tid×3天，疼痛缓解后停用（青光眼、前列腺肥大及肠麻痹者禁用）。\n3. 润滑通便（仅限单纯性不全性肠梗阻，完全性梗阻及疑绞窄者禁用）：液状石蜡油30ml po qn×3天，或甘油灌肠剂（开塞露）20ml纳肛 qd×3天，排便后即停。\n4. 补充益生菌及调节肠道菌群：双歧杆菌三联活菌胶囊0.42g po tid×7天，配合温开水送服，与抗菌药物间隔2小时以上服用。\n【一般治疗及生活指导】\n1. 禁食禁水，卧床休息，取半卧位以减轻腹胀；密切观察腹痛、腹胀、呕吐及排气排便情况，梗阻缓解前严禁进食。\n2. 饮食：排气排便恢复后先进清流质（米汤、藕粉、去油肉汤），少食多餐，逐步过渡至半流质、软食；禁食产气食物（豆类、红薯、碳酸饮料）、粗纤维（韭菜、芹菜、竹笋）、生冷油腻及黏性食物（糯米、年糕、柿饼、山楂），细嚼慢咽。\n3. 活动：症状缓解后可室内缓步活动，避免剧烈运动、腹部受压及突然扭转体位；平时养成规律排便习惯，避免便秘。\n4. 禁忌：禁用强泻药（硫酸镁、番泻叶、酚酞等）及促胃肠动力药，忌自行反复灌肠，以免诱发肠套叠、绞窄或穿孔。\n【随诊要求】\n1. 若腹痛转为持续性剧烈绞痛、腹胀进行性加重、呕吐频繁、发热、血便或停止排气排便超过48小时，须立即急诊就诊。\n2. 症状缓解后3~5天门诊复诊，复查立位腹部平片；既往有腹部手术史或肿瘤病史者，建议1~2周内完善腹部CT明确梗阻病因。\n3. 反复发作的粘连性肠梗阻或怀疑肿瘤所致梗阻者，及时转胃肠外科/普外科就诊，评估手术或内镜治疗指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":296,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"65b6d35114a4c01f6d31b87e64db44b256d99024442195ba96773874794ebd8d","pinyin":"changgengzu","initials":"cgz","setting":"out","caseName":"门诊病历161","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历161",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-75fb4c9a6eb267cd0748","key":"v1-c9ccc21dfe2a3058|templates-75fb4c9a6eb267cd0748","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疝气","category":"门诊病历模板","raw":{"name":"疝气","category":"门诊病历模板","case":{"case_name":"门诊病历162","templates":{"主诉":"腹股沟区包块2年，不能回纳伴腹痛6小时","现病史":"患者于2年前发现腹股沟区可复性包块，站立、咳嗽、用力时突出，平卧或用手推送后可回纳，偶有坠胀感，无疼痛。6小时前包块突出后不能回纳，伴腹痛、恶心、呕吐2次，包块胀痛明显，无发热。无慢性咳嗽、便秘、前列腺增生等腹压增高因素。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P84次/分，R18次/分，BP122/78mmHg。神志清楚，查体合作。右侧腹股沟区可见梨形包块，站立位突出明显，平卧可自行回纳，包块质软、张力不高、无明显触痛，咳嗽冲击试验（+），压迫内环后嘱患者咳嗽包块不再突出，为可复性。","辅助检查":"【必做】一般临床诊断为主；【影像学】腹股沟区超声（鉴别腹股沟疝与鞘膜积液、精索静脉曲张等，评估疝内容物）；【其他】术前常规（血常规、凝血、心电图等，拟手术时）。","初步诊断":"1. 腹股沟疝（斜疝，右侧）\n（注：可复性疝建议择期行疝修补术（无张力补片修补/腹腔镜TAPP/TEP），避免嵌顿风险；若包块不能回纳伴疼痛加重、恶心呕吐（嵌顿疝）或出现腹膜炎体征（绞窄疝，可致肠坏死），需立即急诊手术，嵌顿时间过长可致肠坏死；控制慢性咳嗽、便秘等腹压增高因素以降低复发。）","处理方案":"【药物治疗】\n1.缓泻剂（防治便秘、降低腹内压，减少疝复发及嵌顿诱因）：乳果糖口服溶液10ml po qd～bid，连用至大便通畅（一般3～7天），必要时睡前加用开塞露20ml纳肛。\n2.镇咳药（合并上呼吸道感染咳嗽者，避免剧烈咳嗽诱发嵌顿）：氢溴酸右美沙芬片15mg po tid，连用3～5天，咳嗽缓解即停；咳痰明显者改用盐酸氨溴索片30mg po tid。\n3.抗生素（仅用于疝块局部红肿、压痛明显或手法复位后疑有感染时）：头孢呋辛酯片0.25g po bid×5天；对头孢类过敏者改用阿莫西林克拉维酸钾片0.457g po bid×5天。\n\n【一般治疗及生活指导】\n1.休息与活动：避免久站、久坐、负重及剧烈运动（如提重物、屏气用力），症状明显时可平卧休息，抬高下肢以利疝块回纳。\n2.饮食指导：多饮水（每日1500～2000ml），多食富含膳食纤维的食物（新鲜蔬菜、水果、粗粮），保持大便通畅；少食辛辣刺激及易产气食物（如豆类、碳酸饮料）。\n3.禁忌：戒烟，积极治疗慢性咳嗽、慢性便秘、前列腺增生所致排尿困难等增加腹压的疾病；避免用力排便、用力排尿及大声咳嗽等屏气动作。\n4.辅助措施：腹股沟疝及股疝者可日间佩戴疝气带压迫内环口、防止疝内容物突出（仅作临时缓解，不能根治，睡眠及卧床时取下）。\n\n【随诊要求】\n1.成人腹股沟疝原则上应择期行疝修补术根治，建议1～2周内门诊复诊预约手术，并进行术前评估。\n2.保守治疗及等待手术期间，若出现疝块突然增大、变硬、疼痛加剧，伴恶心、呕吐、腹胀或停止排气排便等疑似嵌顿或绞窄表现，应立即急诊就医，切勿自行手法还纳。\n3.择期手术者术后1周门诊复查切口愈合情况，术后1个月复查1次，此后如无特殊可每年体检随诊；小儿疝（如腹股沟斜疝）观察至1岁仍不自愈者，应及时转小儿外科评估手术时机。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":297,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c348fbacf9702d4018fd377f9c0dc46264c84fa76fac11fd3a5d569ed426c04f","pinyin":"shanqi","initials":"sq","setting":"out","caseName":"门诊病历162","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历162",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3d2c9dc37774477dead5","key":"v1-c9ccc21dfe2a3058|templates-3d2c9dc37774477dead5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腰椎间盘突出","category":"门诊病历模板","raw":{"name":"腰椎间盘突出","category":"门诊病历模板","case":{"case_name":"门诊病历163","templates":{"主诉":"腰痛伴下肢放射性疼痛、麻木1个月，近1周加重。","现病史":"患者于4周前弯腰搬物后出现腰部疼痛，伴向右下肢放射性疼痛（沿臀部、大腿后侧、小腿后外侧至足部），呈电击样，咳嗽、打喷嚏、用力排便时加重，站立行走加重、平卧减轻，伴小腿及足部麻木，无会阴区麻木及大小便功能障碍。无外伤史、长期弯腰负重职业史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP120/76mmHg。神志清楚，查体合作。腰椎生理曲度变直，腰L4-5棘突旁压痛（+）并向患肢放射，腰椎活动受限（前屈为著）。直腿抬高试验：患肢40°（阳性<70°），加强试验（+），健肢70°。患肢小腿外侧针刺觉减退，拇趾背伸（L5）肌力4级，跟腱反射减弱。病理征阴性。","辅助检查":"【必做】腰椎MRI（首选，用以明确椎间盘突出节段、程度、神经根及马尾受压情况）；【影像学】腰椎X线片（正侧位，排除骨折、滑脱等骨性病变）；【其他】腰椎CT（MRI禁忌时）、肌电图（神经根损害定位）。","初步诊断":"1. 腰椎间盘突出症（L4/5，向右L5神经根受压）\n（注：急性期卧床休息（硬板床，1~2周）、避免弯腰负重；药物：NSAIDs（塞来昔布200mg bid）、神经营养（甲钴胺0.5mg tid）、肌松剂（乙哌立松50mg tid）；理疗、牵引；保守4~6周无效或反复发作者行微创（椎间孔镜髓核摘除）；出现马尾综合征（大小便障碍、鞍区麻木）或进行性肌力下降（足下垂）属急诊手术指征，需立即就诊；缓解期加强腰背肌锻炼（小燕飞、五点支撑）。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药：塞来昔布胶囊0.2g qd～bid，饭后口服，疗程5～7天，缓解神经根炎性疼痛（对COX-2抑制剂过敏或心血管高危者改选双氯芬酸钠缓释片75mg qd，饭后口服，疗程5～7天）。\n2. 肌肉松弛剂：盐酸乙哌立松片50mg tid，饭后口服，疗程7～14天，缓解椎旁肌及腰背肌痉挛。\n3. 神经营养修复药：甲钴胺片0.5mg tid，口服，疗程4周，促进受压神经根修复。\n4. 消肿脱水药（急性期神经根水肿明显者）：七叶皂苷钠片30mg bid，饭后口服，疗程7天。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息1～2周，睡硬板床，下床活动时佩戴腰围；症状缓解后避免久坐久站（每30～40分钟起身活动），避免弯腰提重物、搬抬重物及剧烈腰部扭转动作。\n2. 活动：缓解期循序渐进进行腰背肌功能锻炼（五点支撑法、小燕飞训练），每次10～15分钟，每日2次，以不诱发腰腿痛为度。\n3. 饮食：均衡营养，适当增加富含钙及维生素D的食物（牛奶、豆制品、绿叶蔬菜），多饮水，保持大便通畅，避免排便用力增加腹压而加重椎间盘负荷。\n4. 禁忌：避免睡过软床垫、避免腰部受凉，戒烟限酒，避免长时间驾驶及颠簸路段。\n\n【随诊要求】\n1. 用药后1～2周门诊复诊，评估疗效及药物不良反应（胃肠道不适、肝肾功能等）。\n2. 如出现下肢进行性肌力下降、足下垂、会阴部（鞍区）麻木或大小便功能障碍等马尾综合征征象，须立即急诊就医。\n3. 症状缓解后建议每3～6个月复查腰椎MRI观察变化；经正规保守治疗4～6周无效或症状进行性加重者，及时返院复诊评估手术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":298,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4fc109cb05d56fc11ea97a16185e5ec26c4d9b99c45a4955fd5d4dbfbd31a91f","pinyin":"yaozhuijianpantuchu","initials":"yzjptc","setting":"out","caseName":"门诊病历163","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历163",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-cf07de8647d7c49c1fd6","key":"v1-c9ccc21dfe2a3058|templates-cf07de8647d7c49c1fd6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肩周炎","category":"门诊病历模板","raw":{"name":"肩周炎","category":"门诊病历模板","case":{"case_name":"门诊病历164","templates":{"主诉":"肩关节疼痛伴活动受限6月，加重2周。","现病史":"患者于6月前无明显诱因出现右肩关节疼痛，为钝痛，夜间加重（常痛醒），不能患侧卧，梳头、穿衣、摸背等动作受限并诱发疼痛，渐出现关节僵硬、活动范围缩小，无发热，无外伤史。有无糖尿病、颈椎病、冠心病等病史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP122/76mmHg。神志清楚，查体合作。右肩关节无明显红肿，肩前、外侧及后侧压痛（+）（肱二头肌长头腱、冈上肌止点等），主动及被动活动均受限：前屈约90°，外展约70°，后伸约30°，内旋外旋受限，耸肩无力（-）。颈椎活动正常，无明显上肢放射痛。","辅助检查":"【必做】肩关节X线片（正位，用于排除钙化性肌腱炎、骨性病变）；【影像学】肩关节超声或MRI（疑肩袖损伤、滑囊炎时选用，粘连性肩关节炎MRI可见关节囊增厚）；【其他】血糖（肩周炎与糖尿病相关，反复双侧发病者筛查）。","初步诊断":"1. 肩关节周围炎（粘连性肩关节炎，右/左）\n（注：治疗以功能锻炼为核心（爬墙、钟摆运动、拉轮等，每日坚持）+NSAIDs（塞来昔布200mg qd）止痛+局部封闭（肩峰下/关节腔注射糖皮质激素+利多卡因，急性疼痛期）；病程有自限性（约1~2年）但需主动锻炼防关节囊粘连加重；保守无效或冻结期长者可麻醉下手法松解/关节镜松解；鉴别肩袖损伤、颈椎病、肩峰撞击等。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（首选）：塞来昔布胶囊 200mg qd 口服，餐后服用，疗程 7～14 天；或布洛芬缓释胶囊 0.3g bid 口服，疗程 7～14 天，注意胃肠道及心血管不良反应，消化性溃疡活动期禁用。\n2. 外用非甾体抗炎药：双氯芬酸二乙胺乳胶剂（扶他林）适量涂于患肩疼痛处，tid，疗程 1～2 周，与口服 NSAIDs 同用可加强镇痛、减少口服剂量。\n3. 肌肉松弛剂：盐酸乙哌立松片 50mg tid 口服，疗程 1～2 周，用于缓解肩周肌群痉挛、改善活动受限；用药期间避免驾驶及高空作业。\n4. 顽固性疼痛（口服药物无效、夜间痛明显）者，可于门诊行肩关节腔或肩峰下滑囊注射：醋酸曲安奈德注射液 20～40mg 加 1% 利多卡因 2～3ml 关节腔注射，单次，间隔 2～4 周可重复 1 次，总计不超过 3 次；糖尿病患者慎用并监测血糖，注射后 24 小时内避免肩部过度活动。\n\n【一般治疗及生活指导】\n1. 坚持每日功能锻炼：爬墙运动（面对墙壁，患侧手指沿墙逐渐上爬至疼痛可耐受极限）、钟摆运动（弯腰健手扶桌，患肩放松下垂做前后、左右画圈摆动）、双手背后拉毛巾练习，每项每次 10～15 分钟，每日 2～3 次，以轻度牵拉感为度，忌暴力猛拉。\n2. 疼痛明显期（急性期）可局部热敷（每日 2～3 次，每次 15～20 分钟）或红外线、超短波等理疗；夜间疼痛影响睡眠者，宜健侧卧位，患侧肩下垫枕支撑，避免患肩受压。\n3. 注意肩部保暖，避免空调、风扇直吹及受凉；急性疼痛期避免提重物、患侧手臂过顶甩动及剧烈运动，但不宜完全制动，以免加重粘连。\n4. 饮食无特殊禁忌，建议均衡饮食、适量补充钙剂及维生素 D，戒烟；保持规律作息，避免长时间固定姿势（如久坐伏案、单肩背包）。\n\n【随诊要求】\n1. 用药后 2 周复诊，评估疼痛缓解程度及肩关节活动度改善情况。\n2. 行关节腔注射者于注射后 2～4 周复诊，评估疗效并决定是否重复注射。\n3. 若出现肩部外伤、剧烈疼痛加重、夜间痛持续不缓解或伴发热、上肢麻木无力，应及时复诊或急诊就诊。\n4. 治疗 4～6 周症状仍无改善或活动受限明显者，复诊评估是否需麻醉下手法松解或转康复科行系统康复治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":299,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4219398102f61fd2ebb7f050eabe17e7cdcec4b6fff5041a44ceb24e1cd8f8c8","pinyin":"jianzhouyan","initials":"jzy","setting":"out","caseName":"门诊病历164","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历164",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d83aa7a2b8366dd3c180","key":"v1-c9ccc21dfe2a3058|templates-d83aa7a2b8366dd3c180","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腱鞘炎","category":"门诊病历模板","raw":{"name":"腱鞘炎","category":"门诊病历模板","case":{"case_name":"门诊病历165","templates":{"主诉":"手腕部疼痛伴活动受限、弹响3周。","现病史":"患者于3周前因长期重复性手部劳动（打字、洗刷、抱孩子等）渐出现右腕桡侧（拇指侧）疼痛，拇指活动时加重，伴晨僵，有拇指屈伸时弹响及卡顿（扳机指），活动后缓解，局部可及硬结，无红肿发热（如有红肿需考虑感染性腱鞘炎）。有无类风湿关节炎、糖尿病史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP120/75mmHg。神志清楚，查体合作。右桡骨茎突处压痛（+），可及硬结，Finkelstein试验（+）（握拳尺偏时桡骨茎突剧痛，符合狭窄性腱鞘炎），拇指屈伸活动受限，局部无红肿。","辅助检查":"【必做】一般临床诊断为主；【影像学】腕部超声（腱鞘增厚、积液）；【其他】血尿酸（排除痛风）、类风湿因子（多关节受累时）。","初步诊断":"1. 狭窄性腱鞘炎（右桡骨茎突）\n（注：保守：休息制动（护腕或夹板）、局部热敷、NSAIDs外用或口服、局部封闭（糖皮质激素+利多卡因注射入腱鞘，效果良好，注意勿注入肌腱）；反复发作或封闭无效者行腱鞘切开松解术；避免诱发动作（减少重复性手腕活动），早期治疗预后好；红肿热痛明显者需警惕化脓性腱鞘炎（外科急症，需急诊切开引流）。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（首选）：塞来昔布胶囊 0.2g qd 口服，餐后服×7～10天；或布洛芬缓释胶囊 0.3g bid 口服×7～10天，症状缓解后停药。\n2. 外用抗炎镇痛药：双氯芬酸二乙胺乳胶剂（扶他林）适量涂擦患处，tid×7～10天，可与口服药联合使用。\n3. 局部封闭治疗（疼痛明显或口服药物疗效不佳时）：醋酸曲安奈德注射液 5～10mg 加 2%利多卡因注射液 0.5～1ml 腱鞘内注射，1次；间隔2～4周可重复1次，共不超过2～3次。\n\n【一般治疗及生活指导】\n1. 患肢制动休息：急性期佩戴护腕或拇指夹板固定1～2周，减少腕部及拇指活动。\n2. 避免诱发动作：减少反复屈伸腕关节、抓握及拇指外展用力等活动（如长时间打字、操作手机、洗衣拧物、抱孩子等），工作中注意劳逸结合，每工作1小时休息5～10分钟。\n3. 局部理疗：每日局部热敷或温水浸泡患处15～20分钟，bid～tid；可配合红外线、超声波等物理治疗。\n4. 缓解期锻炼：症状缓解后循序渐进进行腕关节及手指主动屈伸、伸展功能锻炼，避免突然剧烈活动。\n\n【随诊要求】\n1. 用药及制动治疗后1～2周门诊复诊，评估疼痛、肿胀及活动受限改善情况。\n2. 封闭治疗后2周复诊；若症状反复，或出现注射部位红肿、疼痛加重、发热等异常，及时复诊。\n3. 保守治疗4～6周无效或症状加重（弹响、卡顿明显、活动受限加重），复诊评估是否需行腱鞘切开松解术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":300,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5e654e8ff4a15f02c16042e3dca56c4e10eade4bd65f64c5cd5221ce615d737b","pinyin":"jianqiaoyan","initials":"jqy","setting":"out","caseName":"门诊病历165","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历165",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d99890bd571a59e328cc","key":"v1-c9ccc21dfe2a3058|templates-d99890bd571a59e328cc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨质疏松","category":"门诊病历模板","raw":{"name":"骨质疏松","category":"门诊病历模板","case":{"case_name":"门诊病历166","templates":{"主诉":"腰背痛、身高变矮伴易骨折3年。","现病史":"患者于3年前渐出现腰背部酸痛，劳累后加重，身高较年轻时缩短约4cm，有驼背畸形，无轻微外力即骨折史，近3月疼痛加重。有无绝经（女性）、长期激素使用、吸烟饮酒、缺乏运动、钙及维生素D摄入不足等危险因素：有绝经、缺乏运动，无长期激素使用、吸烟饮酒，钙及维生素D摄入不足。有无甲亢、糖尿病、肝肾疾病等继发因素：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/72mmHg。神志清楚，查体合作。身高154cm，脊柱后凸畸形，棘突及椎旁压痛（+），双下肢肌力肌张力正常，无感觉异常。步态缓慢。","辅助检查":"【必做】骨密度测定（DXA，T值≤-2.5确诊骨质疏松，-1~-2.5为骨量减少）、血钙磷、碱性磷酸酶、肾功能、25-(OH)D、甲状旁腺激素；【影像学】胸腰椎X线片（用于椎体压缩性骨折评估，腰背痛明显者必查）；【其他】骨转换标志物（治疗监测）、血清蛋白电泳（排除多发性骨髓瘤，适用于中老年新发骨痛）。","初步诊断":"1. 骨质疏松症（原发性）\n（注：基础治疗：钙剂（元素钙500~1000mg/d）+维生素D（普通维生素D800~1000IU/d或活性维生素D（骨化三醇0.25μg bid））+负重运动+防跌倒；抗骨吸收药物：双膦酸盐（阿仑膦酸钠70mg每周1次，晨起空腹清水送服后保持直立30分钟）、地舒单抗60mg每半年皮下注射（肾功不全可用）、选择性雌激素受体调节剂（雷洛昔芬60mg qd，适用于绝经后）；椎体压缩骨折急性期卧床+镇痛+支具，必要时椎体成形术；治疗1~2年复查骨密度评估疗效。）","处理方案":"【药物治疗】\n1. 钙剂联合维生素D（基础治疗，贯穿始终）：碳酸钙D3片（钙尔奇D）0.6g（元素钙600mg+维生素D3 125IU）po qd；骨化三醇软胶囊0.25μg po qd，或维生素D滴剂800IU po qd。长期服用。\n2. 双膦酸盐类（一线抗骨吸收药物，首选）：阿仑膦酸钠片70mg po qw，晨起空腹以200-300ml白开水送服，服后保持上半身直立至少30分钟、30分钟内不进餐不躺卧；或唑来膦酸注射液5mg ivgtt（滴注≥15分钟，输注前查肾功能及血钙，纠正低钙血症）每年1次。口服疗程3-5年，静脉疗程连续3年，用药期间每日补充钙剂及维生素D。\n3. 绝经后妇女或不能耐受双膦酸盐者：雷洛昔芬片60mg po qd（预防椎体骨折）；或鲑降钙素鼻喷剂200IU qd（镇痛、抑制骨吸收，短期使用，同时补充钙剂）。\n4. 高骨折风险或严重骨质疏松（T值＜-3.0或已有脆性骨折）且抗骨吸收治疗无效者：特立帕肽注射液20μg ih qd，疗程不超过24个月，疗程结束后序贯双膦酸盐治疗。\n【一般治疗及生活指导】\n1. 生活方式：戒烟、限酒，避免过量饮用浓茶、咖啡及碳酸饮料；每日上午9-11时或下午3-5时晒太阳15-30分钟，促进维生素D合成。\n2. 饮食：均衡营养，保证足量钙摄入（成人每日元素钙800-1000mg），多食牛奶（每日300ml以上）、酸奶、豆制品、深绿色蔬菜、虾皮、芝麻酱等富钙食物，适量摄入优质蛋白及富含维生素K食物。\n3. 运动：坚持负重运动与肌肉力量锻炼，如快走、慢跑、太极拳、跳舞、爬楼梯等，每周3-5次、每次30-40分钟；加强平衡训练（如单腿站立、靠墙深蹲）及核心肌群锻炼，增强肌力与稳定性。\n4. 预防跌倒：改善居家环境（地面防滑、走廊及卫生间安装扶手、夜间照明充足），穿防滑鞋，避免搬抬重物、弯腰提物及登高，防止跌倒引发骨折。\n【随诊要求】\n1. 每3-6个月复诊，评估用药依从性及不良反应（口服双膦酸盐注意上腹不适、食管刺激症状，长期用药者行口腔检查评估下颌骨坏死风险）；每年复查双能X线骨密度（DXA），评估疗效。\n2. 定期检测血钙、血磷、25-(OH)D、肝肾功能、碱性磷酸酶，必要时检测骨转换标志物（β-CTX、P1NP）判断骨转换水平；唑来膦酸输注后1-3日内监测急性期反应（发热、肌痛、流感样症状，可对症处理）。\n3. 出现新发腰背痛、身高变矮、驼背，或跌倒后疑有骨折者及时就诊；连续规范治疗3年以上疗效不佳者，复诊评估是否更换抗骨质疏松药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":301,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"565f04ea013a9b6f2ea7f2fe424c68b7d77ffd0097dcfc1bc3993b8e26e7b79c","pinyin":"guzhishusong","initials":"gzss","setting":"out","caseName":"门诊病历166","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历166",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8c095ed97fd555f0ae47","key":"v1-c9ccc21dfe2a3058|templates-8c095ed97fd555f0ae47","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑震荡","category":"门诊病历模板","raw":{"name":"脑震荡","category":"门诊病历模板","case":{"case_name":"门诊病历167","templates":{"主诉":"头部外伤后短暂意识不清伴头痛、头晕2小时。","现病史":"患者于2小时前头部外伤（撞击/摔伤），当即出现短暂意识丧失（持续约2分钟），清醒后不能回忆受伤经过（逆行性遗忘），伴头痛、头晕、恶心，呕吐2次（胃内容物），无抽搐，无耳鼻流血性液体，无肢体麻木无力。伤后有无再次意识丧失：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP124/78mmHg。神志清楚，GCS 15分，定向力正常。双侧瞳孔等大等圆，对光反射灵敏。头部左额部可见头皮血肿，无活动性出血。颈软，无抵抗。四肢肌力Ⅴ级，肌张力正常，病理征阴性。共济运动稳准。","辅助检查":"【必做】头颅CT平扫（排除颅内出血，脑震荡CT通常无阳性发现，但伤后应常规排除迟发血肿）、生命体征监测；【其他】伤后症状持续者复查头颅CT。","初步诊断":"1. 脑震荡\n（注：脑震荡为轻型颅脑损伤，多数预后良好；处理：休息1~2周（减少用脑、避免剧烈运动及驾车）、对症（头痛用对乙酰氨基酚，避免用阿司匹林等影响凝血药物）；密切观察：若出现剧烈头痛、频繁呕吐、意识障碍加重、抽搐、肢体无力或言语不清，提示迟发颅内血肿，需立即急诊复查头颅CT；多次脑震荡者建议神经科随访。）","处理方案":"【药物治疗】\n1. 营养神经：甲钴胺片0.5mg tid po，配合维生素B1片10mg tid po，疗程2~4周。\n2. 头痛对症：头痛明显时予布洛芬缓释胶囊0.3g bid po（饭后服），疗程3~5天，症状缓解即停；若头痛进行性加重伴呕吐及时就医。\n3. 头晕对症：盐酸倍他司汀片6mg tid po，头晕明显时服用，疗程5~7天。\n4. 睡眠障碍、焦虑对症：谷维素片10mg tid po，必要时睡前口服艾司唑仑片1mg（不超过1周，症状缓解即停，避免长期使用掩盖病情变化）。\n【一般治疗及生活指导】\n1. 充分休息：伤后24~72小时卧床或半卧位休息，减少脑力活动，避免长时间使用手机、电脑、电视等视屏活动，保证每日睡眠7~8小时。\n2. 合理饮食：清淡易消化饮食，少量多餐，多饮水，避免辛辣刺激食物及咖啡、浓茶、酒精等兴奋性饮品；伴恶心者宜少食多餐。\n3. 限制活动：伤后1~2周避免剧烈运动、重体力劳动及对抗性体育活动，避免驾车、高空作业、游泳等危险活动，待头痛、头晕等症状完全消失后再逐步恢复日常活动和运动。\n4. 密切观察：伤后24~48小时内禁用镇静催眠类药物以免掩盖病情变化；如出现头痛进行性加重、频繁呕吐、意识模糊、抽搐、瞳孔不等大、肢体麻木无力等，立即急诊就诊。\n【随诊要求】\n1. 伤后1~2周门诊复查，评估头痛、头晕、记忆力及睡眠恢复情况，指导恢复日常活动与学习工作。\n2. 症状（头痛、头晕、注意力不集中、记忆力减退、失眠等）持续超过4周者，建议神经内科门诊进一步评估，必要时行头颅MRI、神经心理量表评估及前庭功能检查。\n3. 症状完全缓解前避免驾驶、高空作业等危险活动；任何时间出现剧烈头痛、呕吐、偏瘫、言语不清、癫痫发作等迟发性颅内出血征象，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":302,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"803f930e4add33219cfc969dc327390d42ca325666744302625b974084258f65","pinyin":"naozhendang","initials":"nzd","setting":"out","caseName":"门诊病历167","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历167",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-74259f94b8638d063d66","key":"v1-c9ccc21dfe2a3058|templates-74259f94b8638d063d66","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"头皮血肿","category":"门诊病历模板","raw":{"name":"头皮血肿","category":"门诊病历模板","case":{"case_name":"门诊病历168","templates":{"主诉":"头部外伤后头皮肿胀、疼痛2小时。","现病史":"患者于2小时前头部外伤（撞击硬物），伤后局部头皮渐肿胀，呈包块，疼痛，无皮肤破口（有则注明），无意识丧失，无头痛呕吐，无耳鼻流血。伤后有无头晕、视物模糊：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP120/76mmHg。神志清楚。头部前额部可见3cm×3cm半球形隆起包块，质地较硬；帽状腱膜下血肿可有波动感，本例未及波动，压痛（+），表面皮肤完整，无活动性出血。双侧瞳孔等大等圆，对光反射灵敏。四肢肌力正常，病理征阴性。","辅助检查":"检查计划：患者2小时前头部撞击硬物后出现局部头皮肿胀、疼痛，形成帽状腱膜下包块，虽目前无意识丧失、无头痛呕吐及耳鼻流血，但帽状腱膜下血肿可沿疏松间隙广泛蔓延，且外伤早期颅内出血可无典型症状，故急诊完善头颅CT平扫，明确血肿范围、有无颅骨骨折、颅内出血及脑挫裂伤，为是否留观或收住院提供依据，婴幼儿、老年人及血肿较大者颅内损伤风险更高，更应尽早完成；查凝血功能（PT、APTT、纤维蛋白原、D-二聚体）了解凝血状态，排除凝血功能障碍所致持续出血；若血肿进行性增大或伴贫血，需加查血常规了解有无失血性贫血并复查凝血功能；嘱伤后24~48小时内冷敷、加压包扎，避免揉搓；若出现头痛加剧、呕吐、意识改变或血肿持续增大，立即复查头颅CT，并请神经外科会诊。\n\n（检查清单）\n【必做】头颅CT平扫（帽状腱膜下或骨膜下血肿较大、婴幼儿或伴可疑颅骨骨折/颅内损伤时）；【其他】凝血功能（血肿明显增大或疑凝血异常时）。","初步诊断":"1. 头皮血肿（帽状腱膜下）\n（注：小血肿多自行吸收：伤后24~48小时内冷敷（每次15~20分钟，每日数次）减少继续出血，48小时后改热敷促进吸收；较大帽状腱膜下血肿可加压包扎或穿刺抽吸（严格无菌）后加压包扎；观察有无头痛呕吐等颅内症状；婴幼儿及血肿持续不吸收者需CT复查排除颅骨骨折；若血肿进行性增大或伴贫血，需检查凝血功能并就诊。）","处理方案":"【药物治疗】\n1. 疼痛明显者：布洛芬缓释胶囊 0.3g po bid，疼痛缓解后停用，一般不超过5天；或对乙酰氨基酚片 0.5g po，疼痛时口服，间隔不少于4-6小时，每日不超过4次。\n2. 单纯性头皮血肿、皮肤完整无破损者无需常规使用抗生素；合并头皮裂伤、皮肤破损或伤口污染者：头孢呋辛酯片 0.25g po bid×5天（用药前确认无头孢类药物过敏史；青霉素过敏者慎用并咨询医师）。\n3. 血肿较大、吸收缓慢或瘀肿明显者：云南白药胶囊 0.25g po tid×5-7天，活血化瘀、促进血肿消散（用药期间忌食蚕豆及鱼类）。\n\n【一般治疗及生活指导】\n1. 伤后48小时内局部冷敷（毛巾包裹冰袋敷于血肿处，每次15-20分钟，间隔2-3小时），以减少继续出血、减轻肿胀疼痛；48小时后改为温热敷（每日2-3次，每次15-20分钟），促进血肿吸收。\n2. 注意休息，避免剧烈运动、重体力劳动及头部再次碰撞；睡眠及活动时避免压迫血肿部位，保持头部平稳。\n3. 保持血肿表面皮肤清洁干燥，勿揉搓、挤压血肿部位；若皮肤破损，避免沾水，防止感染。\n4. 饮食宜清淡，忌烟酒及辛辣刺激性食物；适当增加优质蛋白及富含维生素C的食物（如瘦肉、鸡蛋、新鲜蔬果），促进组织修复。\n\n【随诊要求】\n1. 伤后48小时内密切观察，若血肿进行性增大、张力明显增高，或出现剧烈头痛、恶心呕吐、意识改变、肢体无力等，须立即就医行头颅CT检查，排除颅骨骨折及颅内出血。\n2. 一般血肿于2-3周内逐渐机化吸收；若超过3周仍未消退或局部出现波动感、硬结，应及时复诊，必要时行B超或头颅CT检查，考虑穿刺抽吸加压包扎或手术清除。\n3. 婴幼儿、老年人及跌倒等撞击所致者，建议伤后尽早完善头颅CT以排除颅骨骨折及颅内血肿。\n4. 若血肿处出现红、肿、热、痛加重或伴发热等感染征象，及时复诊抗感染处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":303,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"993311bfeeec156369b51ac4f7c9bd464b0cd8745d843187118e8a3d175360b4","pinyin":"toupixuezhong","initials":"tpxz","setting":"out","caseName":"门诊病历168","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历168",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-84349a1388e1e03ecfab","key":"v1-c9ccc21dfe2a3058|templates-84349a1388e1e03ecfab","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"软组织损伤","category":"门诊病历模板","raw":{"name":"软组织损伤","category":"门诊病历模板","case":{"case_name":"门诊病历169","templates":{"主诉":"右踝肿痛、活动受限6小时","现病史":"患者于6小时前行走时不慎扭伤右踝部位，当即疼痛，渐肿胀、皮下瘀斑，活动受限，不能负重（踝），无皮肤破口，无骨擦感及畸形，无麻木。伤后自行冷敷（注：伤后早期禁忌热敷按摩），疼痛无明显缓解。有无反复扭伤史、韧带松弛史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P82次/分，R18次/分，BP116/74mmHg。神志清楚，查体合作。右踝关节肿胀（+），皮肤瘀斑（+），局部压痛（+），内翻应力试验（+），抽屉试验（+），关节活动受限，末梢血运、感觉正常。负重试验不能。","辅助检查":"【必做】X线片（排除骨折，踝关节扭伤按渥太华规则评估是否需拍片：外踝或内踝或足背压痛、不能负重者）；【影像学】MRI（疑韧带完全断裂、软骨损伤时）；【其他】超声（韧带及软组织评估）。","初步诊断":"1. 软组织损伤（右踝关节扭伤，韧带损伤Ⅱ度）\n（注：急性期RICE原则：休息制动、冰敷（48小时内，每次15~20分钟，每日4~6次）、加压包扎、抬高患肢；48小时后热敷；疼痛明显用NSAIDs（塞来昔布200mg qd或外用双氯芬酸）；轻度扭伤制动1~2周渐负重，中度（韧带部分断裂）支具制动3~4周，重度（完全断裂）需专科（石膏固定或手术）；肿胀消退后进行康复锻炼（肌力、平衡训练），防习惯性扭伤。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（首选消炎镇痛）：塞来昔布胶囊 0.2g po bid×5天，或布洛芬缓释胶囊 0.3g po bid×5-7天，餐后服，疼痛缓解后停药；有胃溃疡病史或肾功能不全者慎用。\n2. 外用消肿止痛药：双氯芬酸二乙胺乳胶剂（扶他林）适量外涂患处 tid，轻揉至吸收，连用3-5天；皮肤破损处禁用。\n3. 活血化瘀中成药：云南白药胶囊 0.25g po tid×3天，或三七伤药片 3片 po tid×3天，孕妇禁用。\n4. 消肿药物：迈之灵片（马栗种子提取物）0.15g po bid×7天，配合抬高患肢以促进肿胀消退。\n\n【一般治疗及生活指导】\n1. 急性期（伤后48小时内）按RICE原则处理：患处制动休息（Rest），冰敷每次15-20分钟、每日3-4次（Ice），弹力绷带适度加压包扎（Compression），患肢抬高高于心脏水平（Elevation），以减轻肿胀和出血。\n2. 伤后48小时起改为局部热敷或理疗，每次20分钟、每日2次，促进淤血吸收和组织修复；受伤1周内避免热酒揉搓、强力按摩及拔罐，以免加重出血。\n3. 活动指导：损伤肢体充分休息制动，避免负重、剧烈运动和牵拉动作，疼痛缓解后循序渐进行关节功能锻炼，防止关节僵硬及肌肉萎缩。\n4. 饮食与禁忌：忌辛辣刺激、油炸及饮酒，戒烟；适当增加优质蛋白（鸡蛋、瘦肉、鱼虾）及富含维生素C的食物（新鲜蔬果）摄入，促进软组织修复。\n\n【随诊要求】\n1. 伤后3-5天复诊，评估疼痛、肿胀消退情况及关节活动度恢复程度。\n2. 若疼痛持续加重、局部肿胀明显、不能负重或活动受限无改善，应及时复诊，必要时行X线检查排除骨折、行MRI检查排除韧带完全断裂或半月板损伤。\n3. 若局部出现皮肤破溃、红肿发热、脓性分泌物或发热等感染征象，立即就诊处理。\n4. 功能恢复期遵医嘱逐步增加活动量，症状完全消失后仍需复诊1次确认可恢复日常运动。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":304,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c5c929df88b90e5167d88d9a7729124034664d649854d1831724a27b907045da","pinyin":"ruanzuzhisunshang","initials":"rzzss","setting":"out","caseName":"门诊病历169","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历169",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-216d30e438475af96169","key":"v1-c9ccc21dfe2a3058|templates-216d30e438475af96169","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"烧伤","category":"门诊病历模板","raw":{"name":"烧伤","category":"门诊病历模板","case":{"case_name":"门诊病历170","templates":{"主诉":"躯干及双前臂烫伤后肿痛、水疱4小时","现病史":"患者于4小时前被热液烫伤躯干及双前臂部位（如双手、前臂、躯干、下肢），伤后局部即感剧痛，皮肤水疱，水疱6个（大小约1cm×1cm至2cm×2cm），无创面污染。烧伤后有无口渴、尿少、心慌（休克早期表现）、呼吸困难（吸入性损伤，面部烧伤、密闭空间火灾史）：无。伤后未行冷水冲洗，自行涂药：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P92次/分，R20次/分，BP118/74mmHg。神志清楚，查体合作。创面位于躯干及双前臂，总面积约12%（按中国九分法估算），深度浅Ⅱ度（分度标准：Ⅰ度表现为红斑；浅Ⅱ度表现为水疱、创底红润；深Ⅱ度表现为水疱、创底红白相间；Ⅲ度表现为焦痂、蜡白；本例表现为水疱、创底红润），创患者肿，水疱壁完整，渗出液少。有无吸入性损伤体征（鼻毛烧焦、声音嘶哑、呼吸困难）：无。","辅助检查":"检查计划：患者躯干及双前臂热液烫伤4小时，面积约12%浅Ⅱ度，创面有水疱，为评估烧伤后全身反应、有无休克倾向及感染风险，急诊完善血常规了解有无血液浓缩、白细胞升高及感染征象；查电解质了解有无因创面渗出、补液不当导致的钠钾紊乱；查肾功能（血肌酐、尿素氮）评估有效循环血量与肾灌注情况，为补液方案提供依据；查血糖了解有无应激性高血糖及隐性糖尿病；患者面部烧伤可能并有密闭空间火灾史，查血气分析评估氧合与酸碱平衡，排除吸入性损伤及代谢性酸中毒；查尿常规了解尿量、尿比重及有无肌红蛋白尿，警惕肌红蛋白所致急性肾损伤。创面感染期完善创面分泌物培养及药敏，明确病原菌并指导抗生素使用。查心电图了解有无心律失常及心肌损伤；疑吸入性损伤时查胸部X线片了解肺部情况；有密闭空间火灾史者查碳氧血红蛋白排除一氧化碳中毒。同时按规范预防破伤风。\n\n（检查清单）\n【必做】血常规、电解质、肾功能、血糖、血气分析（大面积或吸入性损伤）、尿常规（尿量、尿比重、有无肌红蛋白尿，电击或挤压伤）；【其他】创面分泌物培养（感染期）、心电图、胸部X线片（疑吸入性损伤时）、碳氧血红蛋白（密闭空间火灾时）。","初步诊断":"1. 烧伤（12%浅Ⅱ度，躯干及双前臂）\n（注：急救与门诊处理：小面积浅度（<10%浅Ⅱ度）：创面冷疗（流动冷水冲洗20~30分钟，伤后6小时内有效）、清创、水疱处理（小水疱保留，大水疱低位剪破引流）、磺胺嘧啶银霜或湿润烧伤膏外涂+无菌敷料包扎；补液（大面积需住院按公式补液，成人II、III度面积×体重×1.5ml+2000ml基础量，晶体为主）；破伤风预防（TAT或TIG）；镇痛；抗生素仅用于感染征象；≥深Ⅱ度、特殊部位（面颈手足会阴）、婴幼儿及老年人、吸入性损伤者应转烧伤专科住院治疗。）","处理方案":"【药物治疗】\n1. 抗感染：浅Ⅱ度以上、污染或面积较大的烧伤创面预防性抗感染，门诊成人常用阿莫西林克拉维酸钾片0.625g bid×5-7天；对青霉素过敏者改用头孢呋辛酯片0.25g bid×5-7天，或克林霉素胶囊0.3g tid×5-7天。\n2. 创面外用药：磺胺嘧啶银乳膏外涂清创后创面，厚约1-2mm，每日1-2次换药，持续至创面上皮化；浅Ⅱ度小面积创面亦可选用湿润烧伤膏外涂，厚约1mm，每日2-4次。\n3. 止痛：疼痛明显者予布洛芬缓释胶囊0.3g bid口服，饭后服用，按需使用不超过5天。\n4. 破伤风预防：污染创面或深度烧伤者，伤后24小时内肌注破伤风抗毒素1500IU（用前皮试），或破伤风人免疫球蛋白250IU单次肌注。\n\n【一般治疗及生活指导】\n1. 创面护理：保持创面清洁干燥，避免抓挠、摩擦及沾水；小水疱尽量保留疱皮，大水疱由医护人员无菌操作下低位引流，切勿自行挑破或撕脱表皮。\n2. 饮食：加强高蛋白、高维生素、高热量饮食（瘦肉、蛋、奶、鱼、新鲜蔬果），保证充足饮水量，促进创面愈合；避免辛辣刺激食物，戒烟戒酒。\n3. 休息与体位：充分休息，烧伤肢体抬高制动以减轻肿胀；避免创面长时间受压，注意保暖，防止局部受冷热刺激及日光暴晒。\n4. 禁忌：创面愈合期禁用化妆品、不明成分药膏及偏方外敷，避免感染和瘢痕增生；瘢痕增生期避免剧烈运动及过度牵拉创面。\n\n【随诊要求】\n1. 换药与观察：门诊换药每1-2天1次，注意观察创面有无红肿、渗出增多、异味等感染征象。\n2. 定期复诊：浅Ⅱ度烧伤每3-5天复诊评估创面愈合情况，直至创面完全上皮化；深Ⅱ度以上、面积较大或位于关节、面部等重要部位创面，及时转烧伤专科处理。\n3. 紧急复诊：出现发热、创面疼痛加剧、脓性分泌物或周围红肿范围扩大等感染征象时，立即复诊。\n4. 远期随访：创面愈合后1-3个月复诊评估瘢痕增生情况，必要时行硅酮凝胶、弹力加压等抗瘢痕治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":305,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6e13335ad93f2d428d239acdcc743a321accb1aa3afa5b451812b2076f8934ce","pinyin":"shaoshang","initials":"ss","setting":"out","caseName":"门诊病历170","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历170",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ba60616a8cd3cfe896cd","key":"v1-c9ccc21dfe2a3058|templates-ba60616a8cd3cfe896cd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"冻伤","category":"门诊病历模板","raw":{"name":"冻伤","category":"门诊病历模板","case":{"case_name":"门诊病历171","templates":{"主诉":"双手足红肿、灼痛伴水疱3天。","现病史":"患者于3天前在寒冷户外作业（气温约-15℃，持续暴露约2小时）后出现双手、双足皮肤苍白、麻木，复温后渐转为红肿、灼痛，伴瘙痒，次日足趾、手指出现水疱2~3个，疱液清亮，无破溃渗液。否认昏迷、饥饿、饮酒后受冻等诱因。自行以温水浸泡、涂抹冻疮膏处理，症状缓解不明显，今日来我院门诊就诊。发病以来精神、食欲可，睡眠因疼痛欠佳，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 78次/分，R 18次/分，BP 120/78mmHg。神志清楚，查体合作。双手掌指及手指、双足趾皮肤可见散在暗红色斑片，触之皮温偏低，局部肿胀，指（趾）末端感觉减退，痛觉存在；足趾、食指末端可见2~3个（1~2）cm×（1~2）cm张力性水疱，疱壁完整，疱液清亮，周围红晕，无破溃、无脓性分泌物，末梢毛细血管充盈时间约2秒，桡动脉、足背动脉搏动正常。心肺听诊未闻及明显异常。","辅助检查":"检查计划：患者于约-15℃寒冷户外持续暴露约2小时后出现双手、双足苍白麻木，复温后转为红肿、灼痛并出现水疱，为评估冻伤程度及全身影响，完善血常规了解有无血液浓缩、白细胞升高及感染征象，冻伤后血液黏稠度增高、微血栓形成常伴血细胞变化；查凝血功能（PT、APTT、纤维蛋白原、D-二聚体）了解有无凝血激活与高凝状态，为抗凝、改善微循环治疗提供依据；水疱破溃疑感染者，完善创面分泌物培养及药敏，明确病原菌并指导抗生素选择；局部X线片检查用于疑合并骨关节损伤或深部组织坏死时，了解指（趾）骨有无骨质破坏、骨质疏松或坏死，评估是否需要外科清创或截指（趾）；嘱复温后保持创面清洁、避免揉搓与再次受冻，若指（趾）端发黑、感觉丧失需及时复诊，必要时请烧伤科或普外科会诊。\n\n（检查清单）\n【必做检查】血常规、凝血功能；【影像学检查】局部X线片（疑骨关节损伤或深部组织坏死时）；【其他】创面分泌物培养（水疱破溃疑感染时）。","初步诊断":"1. 冻伤（Ⅱ度，双手、双足）\n（注：冻伤程度按复温后临床表现分度，必要时请烧伤科/普外科会诊。）","处理方案":"【药物治疗】\n1. 复温后改善微循环、扩张血管：硝苯地平缓释片10mg po bid，疗程2~4周；重度冻伤（Ⅱ度以上）可加用前列地尔注射液10μg 加入0.9%氯化钠注射液100ml中静脉滴注 qd，疗程7~14天。\n2. 镇痛：布洛芬缓释胶囊0.3g po bid，疼痛缓解后停用；疼痛剧烈可短期联用对乙酰氨基酚片0.5g po prn（间隔≥6小时）。\n3. 局部用药：冻伤部位外涂冻疮膏或复方肝素钠尿囊素凝胶 bid；创面有水疱破溃者，外用莫匹罗星软膏涂抹创面 bid。\n4. 抗感染与破伤风预防：创面破损、污染或伴感染者，阿莫西林克拉维酸钾片0.457g po tid，疗程5~7天；深部冻伤伴污染伤口予破伤风抗毒素1500IU 肌注（用前皮试）。\n\n【一般治疗及生活指导】\n1. 复温处理：将冻伤肢体置于38~42℃温水中快速复温20~30分钟，至皮肤转红、感觉恢复为止；严禁用雪搓、火烤、冷水浸泡或暴力揉搓，以免加重组织损伤。\n2. 保暖与休息：复温后患肢抬高制动、卧床休息，环境温度保持20~22℃，局部棉垫保暖包扎，避免再次受冻及受压摩擦；Ⅱ度以上冻伤患肢避免负重活动。\n3. 饮食：给予高蛋白、高热量、富含维生素C及微量元素的饮食（如瘦肉、蛋奶、新鲜蔬果），加强营养支持促进组织修复。\n4. 禁忌：严格戒烟酒（尼古丁致血管痉挛、乙醇加速热量散失），避免辛辣刺激饮食；水疱保持完整勿自行挑破，避免搔抓。\n\n【随诊要求】\n1. 复温后24~48小时复诊1次，评估冻伤分度及组织活力变化，重新判定伤情。\n2. 创面换药期间每2~3天复诊换药，观察创面渗液、坏死及感染征象；出现发热、创面红肿加剧、脓性分泌物或坏疽扩大时随时就诊。\n3. 2~4周复诊评估创面愈合、感觉及运动功能恢复情况；坏死组织界限清楚者需外科清创或截趾（指）评估。\n4. 伤后1~3个月随访，观察瘢痕挛缩、关节僵硬、神经感觉异常等后遗症，必要时转康复科及整形外科治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":306,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"694b83557a86121074b8ca40d0617ae4f0a75bc1417b68e6586e8618b0b94205","pinyin":"dongshang","initials":"ds","setting":"out","caseName":"门诊病历171","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历171",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5093b5a2e0fbd811be0a","key":"v1-c9ccc21dfe2a3058|templates-5093b5a2e0fbd811be0a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"食物中毒","category":"门诊病历模板","raw":{"name":"食物中毒","category":"门诊病历模板","case":{"case_name":"门诊病历172","templates":{"主诉":"进食后出现恶心、呕吐、腹痛、腹泻6小时。","现病史":"患者于6小时前与家人共同进食外卖（含凉拌菜、隔夜熟食）后约2小时出现上腹部持续性隐痛，阵发性加重，伴恶心，呕吐胃内容物3次，非喷射性，无咖啡样物，腹泻水样便5次，量中等，无黏液脓血，伴头晕、乏力，无发热、寒战，无意识障碍。同餐2人先后出现相似症状。发病以来精神欠佳，未再进食，小便量偏少，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 37.2℃，P 92次/分，R 20次/分，BP 110/70mmHg。神志清楚，精神萎靡，皮肤弹性稍差，口唇稍干。心肺听诊未闻及明显异常。腹平软，上腹部及脐周轻压痛，无反跳痛及肌紧张，肠鸣音活跃（约8次/分）。神经系统检查无阳性体征。","辅助检查":"检查计划：患者6小时前与家人共同进食外卖凉拌菜及隔夜熟食后约2小时出现恶心、呕吐、上腹隐痛及水样便5次，同餐2人先后发病，考虑群体性食物中毒可能，需按《食品安全法》规定及时上报疾控部门并尽快完善病原学检查。查血常规了解白细胞及中性粒细胞比例，明确有无细菌感染及血液浓缩所致的脱水程度；完善大便常规+隐血检查排除细菌性痢疾、侵袭性肠炎等黏液脓血便性疾病，并鉴别病毒性胃肠炎；患者呕吐3次、腹泻5次、小便量偏少，完善电解质检查排除呕吐腹泻所致低钾、低钠血症，以免加重头晕、乏力甚至诱发心律失常，完善肾功能检查评估脱水所致肾前性氮质血症及补液安全；疑似细菌性食物中毒时，留取呕吐物及可疑食物细菌培养明确致病菌，指导抗生素选择；完善大便培养筛查沙门菌、志贺菌、致病性大肠埃希菌等病原，为病因诊断提供病原学依据；脱水明显时查血气分析评估酸碱失衡及组织灌注情况，指导补液与纠酸治疗。治疗期间动态观察腹泻、呕吐变化，必要时复查血常规与电解质，并及时向疾控部门报告。\n\n（检查清单）\n【必做检查】血常规、大便常规+隐血、电解质、肾功能；【其他】呕吐物/可疑食物细菌培养（疑似细菌性食物中毒时）、大便培养、血气分析（脱水明显时）。","初步诊断":"1. 急性胃肠炎（食物中毒可能）\n（注：如有集体发病证据，按《食品安全法》规定及时上报当地疾控部门；病因待病原学检查进一步明确。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":307,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cb529a239b4b1ccba19b9ee6b593c674e0a6c56c839144fb8aad0b0562d92b23","pinyin":"shiwuzhongdu","initials":"swzd","setting":"out","caseName":"门诊病历172","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历172",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ad3a5d3e1c6f2f532e9b","key":"v1-c9ccc21dfe2a3058|templates-ad3a5d3e1c6f2f532e9b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"酒精中毒","category":"门诊病历模板","raw":{"name":"酒精中毒","category":"门诊病历模板","case":{"case_name":"门诊病历173","templates":{"主诉":"大量饮酒后意识模糊、呕吐2小时。","现病史":"患者于2小时前空腹饮用白酒约500ml后渐出现言语不清、步态不稳、恶心，呕吐胃内容物2次，非喷射性，无咖啡样物及血性物，继之意识模糊、呼之能应、答非所问，无四肢抽搐、无大小便失禁，无外伤史。家属发现后急送我院。既往有长期饮酒史。发病以来未进食。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒20年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 100次/分，R 18次/分，BP 130/85mmHg。意识模糊，呼之能应，查体欠合作，呼气有明显酒味。双侧瞳孔等大等圆，直径约3mm，对光反射灵敏。心肺听诊未闻及明显异常。腹平软，无压痛。四肢肌力查体欠合作，肌张力正常，腱反射对称，病理征阴性，共济运动欠稳。","辅助检查":"检查计划：患者空腹饮用白酒约500ml后出现言语不清、步态不稳、呕吐及意识模糊，需尽快完善相关检查明确中毒程度并鉴别其他意识障碍病因。查血乙醇浓度评估急性酒精中毒程度，明确与意识状态是否相符，为促醒及补液治疗提供依据；患者空腹大量饮酒，急诊即刻完善快速血糖检查排除酒精性低血糖所致意识障碍，此为需紧急纠正的危重症；完善电解质检查排除呕吐、酒精代谢所致低钾、低镁血症，以免诱发心律失常或抽搐；完善肝肾功能检查了解酒精对肝脏的急性损伤及肾脏排泄功能，指导用药剂量与补液方案；查心电图排除酒精中毒所致心律失常及QT间期延长，评估有无心肌缺血；患者有呕吐且家属无法确认有无外伤，若意识不恢复、出现神经系统局灶体征或双侧瞳孔不等大，需完善头颅CT检查排除颅内出血、脑挫裂伤等颅脑损伤；呕吐明显或疑有误吸、呼吸抑制时，完善血气分析评估酸碱失衡与通气功能，明确有无代谢性酸中毒及缺氧。诊疗期间密切监测意识、瞳孔及生命体征，必要时动态复查血乙醇浓度与血糖。\n\n（检查清单）\n【必做检查】血乙醇浓度、血糖（快速）、电解质、肝肾功能、心电图；【其他】头颅CT（疑头部外伤、意识障碍不对称或神经系统局灶体征时）、血气分析。","初步诊断":"1. 急性酒精中毒\n（注：需与低血糖、颅脑损伤、药物中毒等鉴别；必要时请急诊科会诊。）","处理方案":"【药物治疗】\n根据病情紧急处理，具体用药根据诊断和生命体征决定。\n\n【一般治疗及生活指导】\n卧床休息，密切监测生命体征，保持呼吸道通畅，建立静脉通路。\n\n【随诊要求】\n根据病情决定是否住院或留观，如症状加重立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":308,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"19a46d60d984eb147db9541e3f579b47686027542b901dc8cbf0946c2906e431","pinyin":"jiujingzhongdu","initials":"jjzd","setting":"out","caseName":"门诊病历173","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历173",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e5088507d0c0482ba1ae","key":"v1-c9ccc21dfe2a3058|templates-e5088507d0c0482ba1ae","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"药物过敏","category":"门诊病历模板","raw":{"name":"药物过敏","category":"门诊病历模板","case":{"case_name":"门诊病历174","templates":{"主诉":"服药后全身皮疹、瘙痒伴发热6小时。","现病史":"患者于6小时前服用解热镇痛药或中成药后出现全身皮肤瘙痒、红斑样皮疹，渐增多融合，伴发热（体温最高38.9℃），有口唇眼睑水肿，无呼吸困难、无胸闷、无腹痛、无关节痛。有无药物过敏史：无。停药情况：已停用可疑药物。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.9℃，P96次/分，R20次/分，BP112/70mmHg，SpO2 97%。神志清楚。躯干四肢可见弥漫性红斑皮疹，可融合成片，压之褪色，无渗出。口唇、眼睑水肿，咽部充血，呼吸音清。心率96次/分，律齐。","辅助检查":"【必做】血常规（嗜酸性粒细胞可升高）、CRP、肝功能（药物性肝损伤筛查）；【其他】IgE、过敏原检测（病因明确后可免）、肾功能。","初步诊断":"1. 药物过敏反应（药疹，与中成药相关）\n（注：首要处理：立即停用可疑致敏药物，多饮水促进排泄；轻症：抗组胺药（氯雷他定10mg qd或西替利嗪10mg qd）+外涂炉甘石洗剂，必要时短期口服泼尼松30mg/d×3~5天；若出现呼吸困难、喉头水肿、血压下降（过敏性休克）立即肌注肾上腺素0.3~0.5mg并急诊抢救；重型药疹（Stevens-Johnson综合征或中毒性表皮坏死松解症，皮疹伴黏膜糜烂、大疱、Nikolsky征阳性）为皮肤科急症，需住院大剂量激素+免疫球蛋白；病历中永久记录过敏药物。）","处理方案":"【药物治疗】\n1. 立即停用一切可疑致敏药物及结构相似的交叉过敏药物；抗组胺药：氯雷他定片10mg口服 qd×7天，或西替利嗪片10mg口服 qd×7天，瘙痒明显者可加用苯海拉明片25mg口服 tid×3天。\n2. 糖皮质激素（皮损广泛、症状较重者）：泼尼松片30mg口服 qd×5~7天，症状缓解后每2~3天减量5mg至停药，总疗程不超过14天；皮疹面积大或伴渗出者，可加用0.1%糠酸莫米松乳膏外用 bid，用至皮损消退后3天。\n3. 促进药物排泄与辅助抗过敏：维生素C片0.2g口服 tid×7天，同时多饮水（每日1500~2000ml）促进致敏药物代谢排出。\n4. 钙剂（瘙痒剧烈、皮疹进行性增多者）：10%葡萄糖酸钙注射液10ml+5%葡萄糖注射液20ml缓慢静注（>5分钟）qd×3天，用药前后监测心率与血压。\n【一般治疗及生活指导】\n1. 立即停用可疑致敏药物并永久记录于病历及个人过敏史档案，此后就医、用药、注射前须主动告知医务人员药物过敏史，避免再次使用该药及同类交叉过敏药物（如青霉素类与头孢菌素类）。\n2. 饮食宜清淡易消化，忌辛辣刺激、海鲜、牛羊肉、酒精及咖啡浓茶等易诱发或加重过敏的食物；多饮水促进药物排泄。\n3. 皮疹瘙痒时避免搔抓、热水烫洗，穿宽松棉质衣物，保持皮肤清洁干燥；洗澡水温以32~37℃为宜，浴后及时外涂保湿剂修复皮肤屏障。\n4. 禁忌：未经医生评估不得自行再次服用可疑致敏药物；若出现全身皮疹迅速扩散、唇舌或喉部肿胀、声音嘶哑、胸闷气促、头晕、心悸、血压下降等，提示严重过敏反应，须立即至急诊科就诊。\n【随诊要求】\n1. 用药后3~5天复诊，评估皮疹消退及瘙痒缓解情况，据此调整抗组胺药与糖皮质激素用量及疗程。\n2. 治疗期间若症状无缓解或加重，或出现发热、关节痛、黏膜糜烂（口唇、眼、外阴）、大疱等重症药疹表现，须立即复诊或急诊就医。\n3. 皮疹完全消退后1~2周建议至变态反应（过敏）科就诊，行斑贴试验或药物激发试验明确致敏药物，更新药物过敏信息，获取终身禁用药物清单。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":309,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ab8466e577b075fbda7d326c49499d410030d999a95a6c3dadbf602702e18674","pinyin":"yaowuguomin","initials":"ywgm","setting":"out","caseName":"门诊病历174","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历174",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0ccbdd04103d02249434","key":"v1-c9ccc21dfe2a3058|templates-0ccbdd04103d02249434","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"中暑","category":"门诊病历模板","raw":{"name":"中暑","category":"门诊病历模板","case":{"case_name":"门诊病历175","templates":{"主诉":"高温环境后头晕、乏力、恶心2小时，意识模糊30分钟。","现病史":"患者于2小时前在高温（>35℃）高湿环境中作业或活动后出现头晕、头痛、乏力、口渴、大汗，重症时汗少，恶心呕吐3次，肌肉痉挛（腓肠肌等），渐出现意识模糊、反应迟钝，无抽搐。既往有无心脏病、高血压、糖尿病及出汗功能障碍（皮肤病、服药）史：无。现场有无通风降温处理：有，已转移至阴凉通风处并补充含盐饮料。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T40.5℃（核心温度），P126次/分，R28次/分，BP96/60mmHg。意识模糊，皮肤潮红、干燥无汗（符合热射病表现），瞳孔等大等圆、对光反射存在。心肺听诊：心律齐，双肺呼吸音清，未闻及明显干湿性啰音。四肢肌张力正常，病理征阴性。","辅助检查":"【必做】电解质（低钠低钾常见）、肾功能、肝功能、心肌酶、凝血功能（重症需筛查DIC）、血气分析、尿常规（肌红蛋白尿提示横纹肌溶解）；【其他】心电图、头颅CT（持续意识障碍者用以排除脑血管意外）。","初步诊断":"1. 中暑（热射病）\n（注：热射病（核心体温>40℃+中枢神经系统异常，如意识障碍）是致命性急症，须立即急诊抢救：快速降温（蒸发降温或冰毯，目标30分钟内降至39℃以下）、静脉补液、纠正电解质紊乱、防治脑水肿及多器官衰竭（收入ICU）；热痉挛或热衰竭：转移至阴凉通风处、物理降温、口服或静脉补液（含盐）、休息，多数可缓解；避免高温时段作业，出现症状及时脱离热环境。）","处理方案":"【药物治疗】\n1. 藿香正气口服液（太极）10ml po tid×3～5天：解表化湿、和中止呕，为门诊先兆及轻症中暑首选；伴恶心呕吐者含服效果更佳。\n2. 口服补液盐Ⅲ（博叶）1袋溶于250ml温水中，少量多次分服，每日总量1000～1500ml，连用2～3天：补充因大汗丢失的水分和电解质。\n3. 十滴水 2～5ml po（温水送服），每日1～2次，用于头晕、头痛、恶心明显者；症状缓解即停。注意：中暑高热系环境热蓄积所致，非体温调节中枢调定点上移，禁用阿司匹林、对乙酰氨基酚等解热镇痛药（无效且可加重肝损伤及热射病出血倾向）。\n\n【一般治疗及生活指导】\n1. 立即脱离高温高湿环境，转移至阴凉通风处（空调房），平卧休息、解开衣领，用湿毛巾或冰袋冷敷额部、颈部、腋下及腹股沟等大血管走行处，配合扇风促进散热；体温＞38.5℃者予温水擦浴，体温＜38℃后可停止物理降温。\n2. 少量多次饮用含盐清凉饮料（淡盐水、绿豆汤、西瓜汁等），饮食宜清淡易消化，忌辛辣油腻及生冷；避免剧烈活动及再受烈日暴晒，保证充分休息与睡眠；高温时段（11:00～16:00）尽量避免外出及户外劳作，外出做好遮阳防晒，及时补水。\n\n【随诊要求】\n1. 经上述处理后症状多于24～48小时内缓解，可暂不复诊；若出现持续高热（体温＞39℃且物理降温后不降）、意识障碍、抽搐、谵妄、皮肤灼热干燥无汗，或恶心呕吐剧烈致无法进食进水，应立即至急诊就诊（警惕热射病）。\n2. 老年人、儿童、孕产妇及合并心脑血管疾病、糖尿病、慢性肾病等基础病者，症状缓解后建议3～5天内门诊复诊，复查血电解质、肝肾功能，评估有无横纹肌溶解等迟发损伤。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":310,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"be83abfe87ea940650e9267a6d75a5f39a1532bd857824c2730b79347e1f108b","pinyin":"zhongshu","initials":"zs","setting":"out","caseName":"门诊病历175","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历175",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9172a11bc6592c261afa","key":"v1-c9ccc21dfe2a3058|templates-9172a11bc6592c261afa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淹溺","category":"门诊病历模板","raw":{"name":"淹溺","category":"门诊病历模板","case":{"case_name":"门诊病历176","templates":{"主诉":"溺水后意识不清、呛水30分钟，经现场复苏后意识恢复。","现病史":"患者于30分钟前不慎溺水（淡水，溺水时间约3分钟），被救起时意识不清，口鼻有泡沫及水，呼吸急促，经现场心肺复苏后呼吸、意识恢复，现诉胸闷、咳嗽，咳粉红色泡沫痰，无呕吐。既往有无癫痫、心脏病、饮酒等溺水易患因素：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P112次/分，R28次/分，BP105/65mmHg，SpO2 88%。神志清楚，皮肤湿冷，口唇发绀，口鼻可见泡沫状分泌物。双肺可闻及广泛湿啰音，心率112次/分，律齐。腹膨隆。四肢末梢冷。","辅助检查":"【必做】血气分析（低氧血症、代谢性酸中毒，为核心评估内容）、血常规、电解质、肝肾功能、心肌酶、凝血功能；【影像学】胸部X线片或CT（肺水肿、吸入性肺炎、ARDS评估）；【其他】心电图、头颅CT（意识障碍者用以排除脑损伤）。","初步诊断":"1. 淹溺（淡水，中度）\n（注：淹溺后即使意识恢复也应急诊留观至少24小时（警惕迟发性肺水肿、ARDS）；核心治疗：氧疗或机械通气纠正低氧、防治ARDS（必要时PEEP）、纠正酸中毒及电解质紊乱、复温（低体温者）、抗感染（吸入性肺炎）；昏迷者注意脑保护；出院后随访肺功能及神经系统。）","处理方案":"【药物治疗】\n1. 预防及治疗吸入性肺炎：阿莫西林克拉维酸钾片（安灭菌）0.375g tid 口服 ×5-7天，覆盖口腔及水中常见需氧/厌氧菌；青霉素过敏者改用盐酸莫西沙星片 0.4g qd 口服 ×5天。\n2. 祛痰、减轻气道炎症：盐酸氨溴索片（沐舒坦）30mg tid 口服 ×5-7天，稀释痰液促进排出；咳嗽剧烈者加用复方甲氧那明胶囊 2粒 tid 口服 ×3-5天。\n3. 减轻肺水肿（仍有咳嗽、胸闷、肺部湿啰音者）：呋塞米片 20mg qd 口服 ×2-3天，同时口服氯化钾缓释片 0.5g bid 预防低钾血症，用药期间监测体重及血钾、尿量。\n4. 缓解气道痉挛（伴喘息、呼吸音粗者）：硫酸沙丁胺醇气雾剂 1-2喷 按需吸入，每日不超过8喷。\n【一般治疗及生活指导】\n1. 充分休息1周，避免剧烈运动及游泳、潜水、水上作业等活动，防止再次溺水并减轻心肺负担；恢复期循序渐进，以不引起气促为度。\n2. 密切自我观察48-72小时，警惕迟发性淹溺：若出现进行性呼吸困难、咳粉红色泡沫痰、发热、胸痛、口唇发绀或嗜睡，立即急诊就医，不可延误。\n3. 饮食清淡易消化、富含优质蛋白，适量饮温水，忌生冷、辛辣刺激食物及饮酒；注意保暖，避免受凉诱发呼吸道感染。\n4. 保持呼吸道通畅，睡眠时取侧卧位或垫高上半身；家中备指脉血氧仪，静息血氧饱和度低于95%或较前明显下降时及时就诊。\n【随诊要求】\n1. 3-5天后复诊，复查血常规、C反应蛋白、胸部X线（必要时胸部CT），评估肺部渗出及感染吸收情况。\n2. 用药期间如出现发热≥38.5℃、咳嗽咳痰加重、呼吸困难、咯血或胸痛，随时急诊就诊，不可等待预约复诊。\n3. 症状缓解后2周内再次随访，复查胸片及心电图，评估心肺功能恢复情况；原有心肺基础疾病（冠心病、慢性阻塞性肺疾病、心功能不全）者建议完善超声心动图及肺功能检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":311,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"14af7d34fae87f38d0615ad359b1a68d52dd6de66ed1f5782a6ce590c0ff6b54","pinyin":"yanni","initials":"yn","setting":"out","caseName":"门诊病历176","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历176",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-735fa877505d9194fbea","key":"v1-c9ccc21dfe2a3058|templates-735fa877505d9194fbea","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性支气管炎","category":"门诊病历模板","raw":{"name":"慢性支气管炎","category":"门诊病历模板","case":{"case_name":"门诊病历177","templates":{"主诉":"咳嗽、咳痰伴喘息、气短3天。","现病史":"患者吸烟30年，20支/日。于10年前开始反复出现咳嗽、咳痰，每年发作累计超过3个月、连续3年以上，多于冬春季及受凉后加重，咳白色泡沫样痰，晨起为著，无咯血，无夜间阵发性呼吸困难。3天前受凉后咳嗽咳痰加重，痰量增多呈黄脓色，伴喘息、气短，无发热。有无粉尘接触史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟30年，20支/日；不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P88次/分，R22次/分，BP125/78mmHg，SpO2 94%。神志清楚，呼吸稍促，桶状胸（-），双肺呼吸音减低，可闻及干啰音，呼气相延长，无发绀。心率88次/分，律齐。双下肢无水肿。","辅助检查":"【必做】血常规、CRP、胸部X线片（排除肺炎、肺结核、肺癌等）；【其他】肺功能（确诊慢性支气管炎或COPD及评估严重度，FEV1/FVC<70%提示气流受限）、痰培养（急性加重脓痰时）。","初步诊断":"1. 慢性支气管炎（急性加重期/稳定期）\n（注：稳定期戒烟为最重要措施、预防感染（流感/肺炎疫苗）、呼吸锻炼；急性加重期：控制感染（脓痰或发热：阿莫西林克拉维酸/头孢呋辛/左氧氟沙星5~7天）、祛痰（氨溴索30mg tid）、解痉平喘（沙丁胺醇气雾剂按需/茶碱缓释片0.1g bid）；反复加重或气流受限持续者按COPD规范管理（吸入支气管扩张剂（噻托溴铵）±吸入激素），康复期肺功能随访。）","处理方案":"【药物治疗】\n1. 抗感染（急性加重期）：阿莫西林胶囊0.5g tid×5～7天（青霉素过敏者改用左氧氟沙星片0.5g qd×5～7天，或头孢呋辛酯片0.5g bid×5～7天）。\n2. 祛痰镇咳：盐酸氨溴索片30mg tid×7～14天；痰液黏稠者加用乙酰半胱氨酸泡腾片600mg qd，疗程2周。\n3. 平喘解痉（伴喘息或气道高反应者）：茶碱缓释片0.1g bid，或吸入沙丁胺醇气雾剂100～200μg（1～2喷）按需吸入，每日不超过8喷，同时监测心率。\n【一般治疗及生活指导】\n1. 戒烟，避免吸入粉尘、烟雾、油烟及冷空气等刺激性气体，室内保持通风、空气湿润。\n2. 急性期注意休息、避免劳累，注意保暖防受凉，避免去人群密集场所预防呼吸道感染。\n3. 饮食清淡易消化、富营养，多饮水（每日1500～2000ml）以稀释痰液，忌辛辣油腻、忌烟酒。\n4. 缓解期坚持呼吸功能锻炼（缩唇呼吸、腹式呼吸），每年接种流感疫苗及肺炎球菌疫苗，减少急性发作次数。\n【随诊要求】\n1. 用药后1周内复诊，评估咳嗽、咳痰改善情况及药物疗效与不良反应。\n2. 若症状持续不缓解或出现发热、脓痰增多、呼吸困难、口唇发绀等，应立即复诊或急诊就诊。\n3. 缓解期每3～6个月随诊1次，每年复查胸片，动态评估病情及肺功能变化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":312,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a8f1fa5342e56b388ff705080b367dd96d1dbf892cb94e72b9271bf5d5be33e6","pinyin":"manxingzhiqiguanyan","initials":"mxzqgy","setting":"out","caseName":"门诊病历177","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历177",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6eccfcfdd9373239b012","key":"v1-c9ccc21dfe2a3058|templates-6eccfcfdd9373239b012","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"支气管哮喘","category":"门诊病历模板","raw":{"name":"支气管哮喘","category":"门诊病历模板","case":{"case_name":"门诊病历178","templates":{"主诉":"反复发作性喘息伴胸闷、咳嗽3天。","现病史":"患者于10年前诊断支气管哮喘，其后反复发作喘息，多于接触冷空气后发作，发作时喘息、胸闷、咳嗽，呼气性呼吸困难，可自行缓解或经用药缓解。近3天受凉后再次发作，夜间及凌晨为著，影响睡眠，自用沙丁胺醇气雾剂2喷/次，效果不佳。有无过敏性鼻炎、湿疹史及哮喘家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P108次/分，R24次/分，BP118/72mmHg，SpO2 93%。神志清楚，可闻及喘息声，端坐呼吸（-），口唇无发绀，双肺可闻及广泛呼气相哮鸣音，呼气相延长，心率108次/分，律齐。无三凹征（如有提示重度）。","辅助检查":"【必做】肺功能（发作期FEV1下降、支气管舒张试验阳性，即FEV1改善≥12%且增加≥200ml支持哮喘诊断）、血常规（嗜酸性粒细胞）、胸部X线片（排除其他疾病）；【其他】过敏原检测（皮肤点刺或血清特异性IgE）、呼出气一氧化氮（FeNO，气道炎症评估）。","初步诊断":"1. 支气管哮喘（急性发作期，中度）\n（注：急性发作处理：吸入速效β2受体激动剂（沙丁胺醇气雾剂2~4喷，20分钟可重复）+吸入糖皮质激素（布地奈德）；轻中度可门诊治疗（口服泼尼松30~40mg/d×5~7天短程）；重度发作（静息时仍气促、单字说话、端坐呼吸、SpO2<90%、心率>120）需急诊：吸氧、反复雾化沙丁胺醇+异丙托溴铵、静脉糖皮质激素（甲泼尼龙40~80mg）、必要时无创或有创通气；缓解期规范吸入激素（布地奈德或氟替卡松）±长效β2激动剂，控制过敏性鼻炎，避免诱因；制定书面哮喘行动计划，定期肺功能随访。）","处理方案":"【药物治疗】\n1. 吸入性糖皮质激素+长效β2受体激动剂（ICS+LABA）复方制剂：布地奈德福莫特罗粉吸入剂160μg/4.5μg，每次1吸，bid（早晚各1次），长期规律吸入维持控制，疗程至少3个月，症状控制后遵医嘱逐步减量；\n2. 短效β2受体激动剂（SABA）缓解用药：沙丁胺醇气雾剂100μg，急性症状发作时按需吸入1-2吸，每日不超过8吸；若每周按需使用超过2次提示控制不佳，需及时复诊调整方案；\n3. 白三烯受体拮抗剂：孟鲁司特钠片10mg，qn（每晚睡前1次），用于控制气道炎症、减少夜间及运动诱发症状，疗程4-8周；\n4. 若伴呼吸道感染征象（脓痰、发热、CRP升高）：阿莫西林克拉维酸钾片0.457g，tid×5-7天；青霉素过敏者改用左氧氟沙星片0.5g，qd×5-7天。\n\n【一般治疗及生活指导】\n1. 环境管理：保持居室通风干燥，勤换洗床单被套、清洗空调滤网，避免接触尘螨、花粉、动物皮毛、烟雾及刺激性气味等已知过敏原与诱因；\n2. 戒烟限酒：严格戒烟并避免被动吸烟，少食海鲜、坚果等易致敏食物，避免辛辣生冷饮食刺激；\n3. 适度活动：缓解期进行散步、慢跑、太极拳等有氧运动，运动前先吸入缓解药物预防运动诱发哮喘发作，避免剧烈运动及熬夜、情绪激动；\n4. 自我监测：每日记录呼气峰流速（PEF），掌握吸入装置正确使用方法并注意用后漱口，PEF较个人最佳值下降>20%或需频繁使用缓解药时及时就医。\n\n【随诊要求】\n1. 治疗后2-4周复诊，评估症状控制水平（ACT评分≥20分为控制良好）及吸入技术掌握情况，调整维持治疗方案；\n2. 控制良好者每1-3个月复诊1次，复查肺功能（FEV1、PEF变异率），每年至少复查1次；\n3. 出现夜间憋醒、活动受限、按需用药每周超过2次或PEF明显下降时，立即复诊；出现持续加重的呼吸困难、言语断续、发绀等重度发作表现时，即刻急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":313,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"77e3acb7e0db719310f1dd3d1d7e4e4e8685a377a706d0d42dbe55ac7bb4d561","pinyin":"zhiqiguanxiaochuan","initials":"zqgxc","setting":"out","caseName":"门诊病历178","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历178",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ff257edabd4f45702179","key":"v1-c9ccc21dfe2a3058|templates-ff257edabd4f45702179","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胸腔积液","category":"门诊病历模板","raw":{"name":"胸腔积液","category":"门诊病历模板","case":{"case_name":"门诊病历179","templates":{"主诉":"活动后气短、胸闷伴咳嗽3天。","现病史":"患者于2周前渐出现活动后气短、胸闷，伴咳嗽、患侧胸痛，无发热、盗汗、乏力、食欲减退及体重下降，无下肢水肿、夜间阵发性呼吸困难及端坐呼吸，无咯血。既往有无结核病、肿瘤、心力衰竭、肝硬化、肾病综合征病史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P96次/分，R24次/分，BP118/74mmHg，SpO2 93%。神志清楚。气管向左侧移位（大量积液时向健侧移位），右肺呼吸运动减弱，语颤减低，叩诊实音，呼吸音减低或消失，积液上方可闻及支气管呼吸音。心率96次/分。双下肢无水肿。","辅助检查":"检查计划：患者近2周出现活动后气短、胸闷，伴咳嗽及患侧胸痛，初步考虑右侧胸腔积液，性质待查，需系统完善病因学检查。完善胸部X线片或CT检查明确积液量、肋膈角变钝及液平面情况，同时了解有无肺内病变及胸膜增厚，判断是否需要穿刺引流；完善胸腔超声检查明确积液范围并定位，为胸腔穿刺选择最佳进针点并引导穿刺；行诊断性胸腔穿刺，完善胸水常规检查了解胸水颜色、比重、细胞数及分类，完善胸水生化及LDH检查，按Light标准鉴别渗出液与漏出液；胸水ADA检查明确有无结核性胸膜炎，结核性常高于45U/L；胸水脱落细胞学检查排除肿瘤性胸腔积液，胸水细菌培养明确有无细菌感染并指导抗生素选择；查血常规、血沉、CRP评估感染与炎症状态；查肝肾功能、白蛋白及BNP排除心力衰竭、肝硬化、肾病综合征等所致漏出液。根据检查结果决定抗结核、抗感染或抗肿瘤治疗，大量积液压迫症状明显者行治疗性抽液，病因不明者考虑内科胸腔镜或胸膜活检明确。\n\n（检查清单）\n【必做】胸部X线片或CT（肋膈角变钝、液平面，用以确定积液及量）、胸腔超声（定位、估量、引导穿刺）；【其他】诊断性胸腔穿刺：胸水常规（颜色、比重、细胞数及分类）、生化（蛋白、LDH，按Light标准区分渗出液与漏出液）、胸水ADA（结核性常>45U/L）、脱落细胞学（肿瘤性）、细菌培养；同时查血常规、血沉、CRP、肝肾功能、白蛋白、BNP（心衰性）。","初步诊断":"1. 胸腔积液（右侧，渗出性，性质待查）\n（注：漏出性常见于心衰、肝硬化、肾病，治疗以原发病治疗加利尿为主；渗出性常见结核性胸膜炎（抗结核治疗4HRZE方案+胸水引流）、细菌性（抗感染+引流）、恶性（原发肿瘤治疗+胸膜固定术）；大量积液压迫症状明显者治疗性胸腔穿刺抽液（首次<700ml防复张性肺水肿）；病因不明持续存在者内科胸腔镜或胸膜活检明确。）","处理方案":"【药物治疗】\n1.结核性胸膜炎（渗出液、ADA升高、T-SPOT阳性者）：异烟肼片0.3g qd+利福平胶囊0.45g qd+吡嗪酰胺片0.5g tid+乙胺丁醇片0.75g qd，晨起空腹顿服，强化期2个月，继以异烟肼+利福平巩固4个月，总疗程6个月；同时口服维生素B6片10mg tid预防周围神经炎。\n2.类肺炎性胸腔积液（合并肺炎、发热者）：莫西沙星片0.4g qd×10～14天，或左氧氟沙星片0.5g qd×7～14天；脓胸者加用甲硝唑片0.4g tid，并尽早住院行胸腔穿刺引流。\n3.胸痛明显者：布洛芬缓释胶囊0.3g bid，饭后服用，连用不超过5天；或对乙酰氨基酚片0.5g 必要时口服。\n\n【一般治疗及生活指导】\n1.急性期卧床休息，取患侧卧位或半卧位以减轻胸痛及呼吸困难；症状缓解后逐步下床活动，避免剧烈运动及重体力劳动3个月。\n2.给予高蛋白、高热量、富含维生素饮食（如鸡蛋、瘦肉、鱼类、新鲜蔬菜），保证充足饮水；结核性胸膜炎者戒烟酒。\n3.注意保暖，避免受凉及呼吸道感染，不去人群密集场所；室内保持通风，必要时戴口罩防护。\n4.每日自测体温，记录体重及胸闷、呼吸情况变化，出现异常及时就医。\n\n【随诊要求】\n1.抗结核治疗者每2周复查肝肾功能、血尿酸，每月复查胸部X线或超声观察积液吸收情况；疗程中发热不退、积液增多或胸闷加重者随时复诊。\n2.类肺炎性积液者治疗后7～14天复查胸部CT或超声评估积液吸收；积液未完全吸收者1～3个月复查直至影像学稳定。\n3.大量胸腔穿刺抽液（首次不超过800ml）后注意观察胸痛、头晕、心悸，必要时门诊复查电解质及胸片；反复或大量积液者需进一步行胸膜活检或胸腔镜检查明确病因。\n4.出现咯血、剧烈胸痛、呼吸困难加重或口唇发绀者立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":314,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"577193cf4af06faada2a7c227fab6a0b5bfaddaca49adbbaab02d65e0a03d909","pinyin":"xiongqiangjiye","initials":"xqjy","setting":"out","caseName":"门诊病历179","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历179",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-90549063120557f46090","key":"v1-c9ccc21dfe2a3058|templates-90549063120557f46090","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"气胸","category":"门诊病历模板","raw":{"name":"气胸","category":"门诊病历模板","case":{"case_name":"门诊病历180","templates":{"主诉":"咳嗽、咳痰伴胸闷3天。","现病史":"患者于3小时前静息状态下突发右侧胸痛，为针刺样，伴胸闷、气短、呼吸困难，咳嗽及深呼吸时加重，无发热，无咳痰咯血。既往无慢性阻塞性肺疾病、肺结核、肺癌、马方综合征病史及气胸发作史。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P104次/分，R26次/分，BP122/76mmHg，SpO2 92%。神志清楚，急性痛苦面容，呼吸急促。气管向左侧（健侧）移位（张力性气胸时向对侧移位），患侧胸廓饱满，呼吸运动减弱，语颤减低，叩诊鼓音，呼吸音减低或消失。心率104次/分。无皮下气肿（颈部、胸壁无握雪感）。","辅助检查":"【必做】胸部X线片（可见压缩肺边缘及无肺纹理区，即气胸线，评估肺压缩比例）；【影像学】胸部CT（少量气胸或复杂性气胸，用于肺大疱评估）；【其他】血气分析（呼吸困难明显时）、心电图（排除心肌梗死）。","初步诊断":"1. 自发性气胸（右侧，肺压缩约50%）\n（注：少量气胸（<20%）且无症状可保守观察（吸氧促进吸收）；中大量或症状明显行胸腔穿刺抽气或胸腔闭式引流（锁骨中线第2肋间）；反复发作、肺大疱明显者行胸腔镜肺大疱切除+胸膜固定术；张力性气胸（进行性呼吸困难、发绀、休克、气管移位）为致命急症，立即患侧第2肋间穿刺减压后行闭式引流；出院后1个月内避免剧烈运动、提重物、乘坐飞机、潜水。）","处理方案":"【药物治疗】\n1. 吸氧：鼻导管吸氧2～4L/min，每日持续或间断吸氧，促进胸腔内气体吸收，肺压缩＜20%的少量气胸可经单纯吸氧自行吸收。\n2. 镇咳：咳嗽明显者予氢溴酸右美沙芬片15mg po tid×5～7天，或复方甲氧那明胶囊2粒 po tid×5～7天，避免剧烈咳嗽加重气体外漏。\n3. 止痛：胸痛明显者予布洛芬缓释胶囊0.3g po bid×3～5天，餐后服用。\n4. 通便：乳果糖口服溶液15ml po qd，保持大便通畅，防止用力排便致胸腔压力骤增、气胸加重或复发。\n\n【一般治疗及生活指导】\n1. 休息：气胸未完全吸收前以卧床或半卧位休息为主，减少说话及走动，避免长时间站立、负重。\n2. 活动：避免剧烈运动、跑步、跳跃、举重、游泳及潜水等增加胸腔内压的活动；气体完全吸收后1～2周内仍应避免剧烈活动。\n3. 禁忌：严格戒烟并避免二手烟；避免用力咳嗽、打喷嚏、屏气及用力排便；气胸未完全吸收前避免乘坐飞机、潜水及高空作业。\n4. 饮食：清淡易消化饮食，多食蔬菜、水果等高纤维食物，保证饮水，保持大便通畅；忌辛辣刺激及暴饮暴食。\n\n【随诊要求】\n1. 每周门诊复查胸部X线片，评估气胸吸收情况及肺复张程度，直至气体完全吸收。\n2. 若出现胸闷、气促进行性加重、胸痛加剧、发绀或晕厥，须立即急诊就医，警惕张力性气胸。\n3. 气胸完全吸收后3～6个月复查胸部CT，评估肺大疱情况，必要时转胸外科评估胸腔镜手术指征。\n4. 首次发作后复发率约30%，恢复期及以后应避免上述诱发因素；如反复发作，建议胸外科就诊进一步治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":315,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4016c7fac29cc90cd91bbfacccffadfb875e8dccc8cb7827c244efd8c816b012","pinyin":"qixiong","initials":"qx","setting":"out","caseName":"门诊病历180","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历180",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-724af4855db9a8b4d399","key":"v1-c9ccc21dfe2a3058|templates-724af4855db9a8b4d399","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺气肿","category":"门诊病历模板","raw":{"name":"肺气肿","category":"门诊病历模板","case":{"case_name":"门诊病历181","templates":{"主诉":"反复咳嗽、咳痰20年，活动后气短进行性加重5年。","现病史":"患者吸烟30年，20支/日。于20年前渐出现咳嗽、咳白色泡沫痰，晨起为著，逐年加重；近5年出现活动后气短，起初快走时明显，渐加重至平地行走亦气促，伴桶状胸进行性加重，无咯血，无夜间阵发性呼吸困难。3天前受凉后咳嗽咳痰加重，痰呈黄脓色，气促加重，无发热。有无粉尘接触史及家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟25年，20支/日；已戒酒3年。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P92次/分，R24次/分，BP126/78mmHg，SpO2 92%。神志清楚，呼吸稍促，胸廓前后径增大呈桶状胸，肋间隙增宽，语颤减弱，双肺叩诊过清音，肺下界下移，呼吸音减低，呼气相延长，可闻及干啰音，无发绀。心率92次/分，律齐。双下肢无水肿。","辅助检查":"检查计划：患者吸烟30年、20支/日，反复咳嗽咳痰20年、活动后气短进行性加重5年，桶状胸渐明显，3天前受凉后咳嗽咳痰加重，痰呈黄脓色伴气促加重，考虑肺气肿急性加重，需完善检查评估感染、气流受限程度及有无呼吸衰竭。查血常规、CRP、降钙素原检查了解白细胞、中性粒细胞及炎症指标水平，明确急性加重是否由细菌感染诱发，指导是否启用抗感染治疗；完善胸部X线片或胸部CT检查明确肺气肿程度及有无肺大疱、肺炎、气胸等并发症，并排除其他导致气促加重的肺部病变；因痰呈黄脓色，完善痰培养+药敏检查明确致病菌，指导抗生素选择；气促明显或血氧下降时完善血气分析检查评估氧合与二氧化碳潴留情况，明确有无呼吸衰竭及是否需要长期家庭氧疗；病情稳定后完善肺功能检查，必要时加做支气管舒张试验，了解气流受限程度并分级，指导支气管舒张剂及家庭氧疗方案。嘱患者戒烟并接种疫苗，定期复查肺功能与血气分析了解病情演变。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肺气肿\n（注：肺气肿为病理学诊断，临床常与慢性支气管炎并存构成COPD；戒烟为最重要干预，接种疫苗预防感染；肺功能评估气流受限程度；稳定期呼吸功能锻炼（缩唇呼吸、腹式呼吸），必要时长期家庭氧疗（PaO2≤55mmHg时）；急性加重期抗感染、祛痰、解痉平喘治疗。）","处理方案":"【药物治疗】\n1.支气管舒张剂（长期维持首选）：噻托溴铵粉雾剂18μg qd吸入；若症状控制不佳，联用沙美特罗替卡松粉吸入剂250/50μg bid吸入，或布地奈德福莫特罗粉吸入剂160/4.5μg bid吸入。\n2.祛痰治疗：盐酸氨溴索片30mg tid，疗程视痰液情况而定，一般7～14天。\n3.急性加重期（有脓痰、发热或感染征象时）加用抗菌药物：阿莫西林克拉维酸钾片0.375g tid×5～7天，或左氧氟沙星片0.5g qd×5天。\n4.急性加重期短期口服糖皮质激素：醋酸泼尼松片30mg qd×5～7天，症状缓解后尽快减停，长期使用者需注意骨质疏松等不良反应。\n\n【一般治疗及生活指导】\n1.戒烟为最根本措施，避免粉尘、烟雾及有害气体吸入；注意保暖，预防呼吸道感染，每年接种流感疫苗及23价肺炎球菌多糖疫苗。\n2.坚持呼吸功能锻炼：缩唇呼吸、腹式呼吸，每日2次、每次10～15分钟；循序渐进行走等有氧活动，以不引起明显气促为度。\n3.饮食宜高蛋白、高维生素、易消化，少量多餐，避免过饱加重腹胀影响呼吸；保证每日饮水1500～2000ml以利痰液稀释排出。\n4.家庭氧疗指征者（静息PaO2≤55mmHg或SpO2≤88%）应坚持长期氧疗，每日吸氧≥15小时，氧流量1～2L/min。\n\n【随诊要求】\n1.稳定期每3个月门诊复诊1次，评估呼吸困难程度、咳嗽咳痰情况及药物依从性，必要时调整吸入方案。\n2.定期复查肺功能（每6～12个月1次）、血氧饱和度及胸部影像；长期口服激素者监测血糖、血压及骨密度。\n3.出现呼吸困难进行性加重、痰量增多或脓性痰、发热、口唇发绀等急性加重征象时，应立即就诊；家庭氧疗者每3个月复测血气分析评估氧疗效果。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":316,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4cff39b66fde38d99dce02c2c91e0193263c58bb5b1a28d1cdcc785bbd1334c5","pinyin":"feiqizhong","initials":"fqz","setting":"out","caseName":"门诊病历181","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历181",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-11b3f3700ebc0f369019","key":"v1-c9ccc21dfe2a3058|templates-11b3f3700ebc0f369019","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性阻塞性肺疾病","category":"门诊病历模板","raw":{"name":"慢性阻塞性肺疾病","category":"门诊病历模板","case":{"case_name":"门诊病历182","templates":{"主诉":"慢性咳嗽、咳痰伴喘息10年，急性加重伴气促3天。","现病史":"患者吸烟30年，20支/日。于10年前渐出现慢性咳嗽、咳痰，冬春季或受凉后加重，伴活动后气促进行性加重，肺功能曾提示FEV1/FVC<70%（COPD确诊依据）。3天前受凉后咳嗽加重，痰量增多呈黄脓色，喘息、气促加重，轻微活动即气短，无发热，体温最高37.2℃，无咯血，无胸痛。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟30年，20支/日，已戒烟5年；偶有饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P98次/分，R24次/分，BP128/76mmHg，SpO2 90%。神志清楚，呼吸急促，可闻及喘息声，桶状胸，双肺叩诊过清音，呼吸音减低，可闻及呼气相哮鸣音，呼气相延长，口唇轻度发绀。心率98次/分，律齐，颈静脉无怒张，双下肢无水肿。","辅助检查":"【必做】血常规、CRP、胸部X线片或CT（肺气肿征象、排除肺炎等）、血气分析（急性加重评估氧合及二氧化碳潴留）；【其他】痰培养（脓痰时）、心电图（右心受累，用于肺心病评估）。","初步诊断":"1. 慢性阻塞性肺疾病（急性加重期，Ⅱ级）\n（注：急性加重治疗：氧疗（目标SpO2 88%~92%）、支气管扩张剂（雾化沙丁胺醇+异丙托溴铵）、糖皮质激素（泼尼松30~40mg/d×5~7天或静脉甲泼尼龙）、抗感染（脓痰增多或需机械通气时：阿莫西林克拉维酸或头孢或呼吸喹诺酮，疗程5~7天）、祛痰；Ⅱ型呼衰（PaCO2升高）者慎用高浓度氧，考虑无创通气；稳定期规范吸入治疗（长效抗胆碱能药噻托溴铵±吸入激素+长效β2激动剂）、肺康复、戒烟、疫苗接种。）","处理方案":"【药物治疗】\n1. 支气管扩张剂：首选LAMA/LABA联合治疗，如茚达特罗/格隆溴铵吸入粉雾剂110/50μg，每次1吸，每日1次；或噻托溴铵粉吸入剂18μg，每次1吸，每日1次，长期维持。\n2. 吸入性糖皮质激素联合制剂：反复急性加重或血嗜酸粒细胞≥300/μL者，加用布地奈德/福莫特罗吸入粉雾剂160/4.5μg，每次2吸，每日2次；必要时布地奈德/格隆溴铵/福莫特罗三联吸入，每次2吸，每日2次。\n3. 祛痰药：黏液分泌增多者加用乙酰半胱氨酸泡腾片600mg，每日1次，疗程4周；或盐酸氨溴索片30mg，每日3次，连用7-14天。\n4. 口服糖皮质激素（急性加重期）：中重度急性加重且无禁忌者，泼尼松片30-40mg，每日1次，晨顿服，疗程5天，不推荐超过14天。\n\n【一般治疗及生活指导】\n1. 立即戒烟并避免二手烟、粉尘及油烟等有害气体吸入；戒烟是延缓肺功能进行性下降最有效的措施，必要时予尼古丁替代或药物辅助戒烟。\n2. 坚持呼吸功能锻炼：缩唇呼吸与腹式呼吸训练，每日2次、每次10-15分钟；每周至少3次有氧运动（如快走、太极拳、呼吸操），以不引起明显气促为度。\n3. 饮食宜高蛋白、高维生素、易消化，少量多餐，避免过饱加重腹胀影响呼吸；注意保暖、预防感冒，每年接种流感疫苗及肺炎球菌疫苗。\n4. 家庭氧疗：静息SpO2≤88%或PaO2≤55mmHg者行长期家庭氧疗，每日吸氧≥15小时，氧流量1-2L/min，吸氧浓度28%-30%为宜。\n\n【随诊要求】\n1. 治疗后4-6周门诊复诊，评估症状（CAT评分）、活动耐量及吸入装置操作掌握情况，及时调整方案。\n2. 稳定期每3-6个月复诊1次，每年复查肺功能以评估病情进展及疗效。\n3. 出现气促加重、痰量增多、脓性痰、发热或下肢水肿等急性加重征象时，尽早就诊，必要时急诊处理，避免延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":317,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a8bfafc30812b36429a1c944c16d512d5a26df18209ad00f2150c2a2915ea6bc","pinyin":"manxingzusexingfeijibing","initials":"mxzsxfjb","setting":"out","caseName":"门诊病历182","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历182",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-55b665c733ecce6c9074","key":"v1-c9ccc21dfe2a3058|templates-55b665c733ecce6c9074","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺心病","category":"门诊病历模板","raw":{"name":"肺心病","category":"门诊病历模板","case":{"case_name":"门诊病历183","templates":{"主诉":"慢性咳喘10年，加重伴双下肢水肿、心悸2周。","现病史":"患者有慢性阻塞性肺疾病（慢支肺气肿）病史10年，反复咳喘。近2周受凉后咳喘加重，痰量增多呈黄脓色，渐出现双下肢水肿（晨轻暮重）、心悸、腹胀、食欲减退、尿量减少，夜间不能平卧，无咯血，无胸痛。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.2℃，P108次/分，R24次/分，BP120/76mmHg，SpO2 88%。神志清楚，口唇发绀（+），颈静脉怒张（+），桶状胸，双肺呼吸音减低，可闻及干湿啰音，呼气相延长。心率108次/分，律齐，肺动脉瓣第二心音亢进（+），三尖瓣区可闻及收缩期杂音。腹软，肝肋下2cm（肿大，压痛），肝颈静脉回流征（+），双下肢凹陷性水肿。","辅助检查":"【必做】心电图（肺型P波、右室肥大、右束支传导阻滞）、胸部X线片（右下肺动脉干扩张、右室增大）、血气分析（低氧血症、高碳酸血症）、血常规（继发性红细胞增多）、肝肾功能；【影像学】超声心动图（右室扩大、右室壁增厚、肺动脉压升高，为肺心病诊断依据）；【其他】BNP（鉴别左心衰）、痰培养。","初步诊断":"1. 慢性肺源性心脏病（右心功能不全期）\n（注：急性加重期：控制感染（广谱抗菌药物）、持续低流量氧疗、改善通气（支气管扩张剂、祛痰）、纠正呼衰（无创通气）；右心衰处理：利尿（螺内酯20mg qd+呋塞米20mg，小剂量、防电解质紊乱及痰液黏稠）、扩血管（酚妥拉明）、必要时强心（洋地黄易中毒需慎用，小剂量）；缓解期治疗原发病、预防感染、长期家庭氧疗；出现意识障碍（肺性脑病）者需急诊住院。）","处理方案":"【药物治疗】\n1. 抗感染（控制呼吸道感染为肺心病急性发作期核心治疗）：阿莫西林克拉维酸钾片 0.457g po tid×7天；青霉素过敏者改左氧氟沙星片 0.5g po qd×7天。痰培养及药敏后针对性调整。\n2. 支气管扩张（改善通气）：氨茶碱缓释片 0.1g po bid；联合异丙托溴铵气雾剂 40μg（2喷）吸入 tid，必要时加沙丁胺醇气雾剂 100μg（1喷）按需吸入。\n3. 祛痰：盐酸氨溴索片 30mg po tid×7天，配合生理盐水雾化吸入 bid 稀释痰液。\n4. 利尿消肿（右心衰竭伴下肢水肿时）：氢氯噻嗪片 25mg po qd 晨服 + 螺内酯片 20mg po qd，连用3~5天，注意监测血钾及电解质；强心药仅在利尿、氧疗后心衰未纠正时由医师评估后小剂量使用。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，取半卧位以减轻回心血量及心脏负荷；缓解期注意劳逸结合，避免过度劳累。\n2. 饮食：低盐低脂饮食，每日食盐<5g，伴水肿者<3g；高蛋白、高维生素、易消化食物，少量多餐，避免饱餐加重心脏负担。\n3. 活动：缓解期坚持呼吸功能锻炼（缩唇呼吸、腹式呼吸），每次10~15分钟，每日2次；预防感冒及呼吸道感染，避免去人群密集场所，建议接种流感疫苗及肺炎球菌疫苗。\n4. 禁忌：严格戒烟戒酒；避免用力屏气、情绪激动、剧烈咳嗽屏气动作；慎用镇静催眠药（抑制呼吸中枢）。\n\n【随诊要求】\n每1~2周门诊复诊评估咳嗽咳痰、呼吸困难及水肿改善情况，监测血常规、电解质、肝肾功能；每3~6个月复查心电图、胸部X线/CT、超声心动图及血气分析评估心肺功能。如出现呼吸困难进行性加重、口唇发绀、意识改变、尿量明显减少或体重短期内快速增加，需立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":318,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"04192e2d08084de03e8c4004bfbb70e665deb795f1a45a1fdce07c535f65bc60","pinyin":"feixinbing","initials":"fxb","setting":"out","caseName":"门诊病历183","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历183",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dfb2428156ff392cad01","key":"v1-c9ccc21dfe2a3058|templates-dfb2428156ff392cad01","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"支气管扩张","category":"门诊病历模板","raw":{"name":"支气管扩张","category":"门诊病历模板","case":{"case_name":"门诊病历184","templates":{"主诉":"慢性咳嗽、咳大量脓痰反复发作10年，再发伴咯血3天。","现病史":"患者于10年前（麻疹后）开始反复咳嗽、咳大量脓痰，每日痰量约150ml，晨起及体位变动时咳痰增多（体位引流特征），痰液静置后可分3层，反复肺部感染，3天前咳痰加重伴咯血（量约30ml），无发热，体温最高37.0℃。有无结核病史及异物吸入史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟15年，10支/日；不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P88次/分，R20次/分，BP118/72mmHg，SpO2 94%。神志清楚，口唇无发绀。右肺下叶可闻及固定而持久的局限性湿啰音，杵状指（趾）（+）。心率88次/分，律齐。双下肢无水肿。","辅助检查":"【必做】胸部高分辨率CT（HRCT，显示支气管柱状或囊状扩张，为诊断金标准）、血常规、CRP、痰培养+药敏；【影像学】胸部X线片（肺纹理粗乱、卷发样阴影）；【其他】痰抗酸染色（排除结核）、肺功能、血气分析（反复感染致肺功能损害评估）、支气管镜检查（咯血定位、排除异物或肿瘤）。","初步诊断":"1. 支气管扩张症（右肺下叶，急性加重期）\n（注：急性加重：抗感染（据痰培养药敏；经验用阿莫西林克拉维酸或呼吸喹诺酮，疗程10~14天）、体位引流+祛痰（氨溴索、雾化）、咯血处理（小量咯血：垂体后叶素慎用（冠心病者禁用）、酚磺乙胺；大量咯血（>100ml/次或>500ml/24h）为急症，需急诊支气管动脉栓塞或手术）；稳定期排痰训练、免疫调节、预防接种；大咯血窒息是主要死因，需警惕。）","处理方案":"【药物治疗】\n1. 抗感染（急性加重期，门诊轻中度）：阿莫西林克拉维酸钾片 0.625g po tid×7天；对青霉素过敏或考虑铜绿假单胞菌感染风险者，选用左氧氟沙星片 0.5g po qd×7天（或环丙沙星片 0.5g po bid×7天），疗程7~14天，视痰性状及体温好转情况调整。\n2. 祛痰：盐酸氨溴索片 30mg po tid×7~14天；或乙酰半胱氨酸泡腾片 600mg po qd（溶于温开水后服用）×14天；痰液黏稠者加用雾化吸入乙酰半胱氨酸溶液，300mg/次 雾化吸入 bid。\n3. 支气管舒张剂（合并气流受限或咳嗽、喘息明显者）：吸入用布地奈德福莫特罗粉吸入剂（160/4.5μg）1吸 bid 规律吸入，缓解咳喘症状，改善排痰；不合并气流受限者不建议常规使用。\n4. 大咯血或咯血风险者：明确禁忌自行使用抗凝药及阿司匹林等抗血小板药物；痰中带血者可加用云南白药胶囊 0.5g po tid，咯血量增多时需立即就诊。\n\n【一般治疗及生活指导】\n1. 体位引流与排痰：根据病变部位取相应体位（患侧肺叶在上）行体位引流，每日2~3次，每次15~20分钟，配合手掌叩背，引流后行有效咳嗽咳痰，晨起及睡前各1次为佳。\n2. 戒烟，避免烟雾、粉尘及刺激性气体吸入，注意保暖、预防上呼吸道感染，每年接种流感疫苗，并接种23价肺炎球菌多糖疫苗（每5年复种1次）。\n3. 加强营养：高蛋白、高维生素、易消化饮食，每日饮水量1500~2000ml（无心力衰竭者），保持呼吸道痰液稀释，避免辛辣刺激食物。\n4. 适当进行呼吸康复锻炼（缩唇呼吸、腹式呼吸、呼吸操），量力而行，避免剧烈运动及劳累受凉；活动后气促明显者应减少活动量。\n\n【随诊要求】\n1. 急性加重治疗3~5天后复诊评估疗效，观察体温、痰量及痰性状变化，必要时复查血常规、CRP；治疗结束后复查胸部CT评估病灶变化。\n2. 稳定期每3~6个月门诊随访1次，每年复查肺功能及胸部CT，动态评估病情进展与肺功能下降速度。\n3. 出现以下情况应及时复诊或急诊就诊：咯血量增多或反复咯血、呼吸困难明显加重、发热持续不退、黄脓痰增多或痰液恶臭、体重明显下降伴盗汗（需排查结核等感染）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":319,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0431732cb97e7541b9c4454f2ad363515c28d5cb091a7ae4a82cc6a20a442534","pinyin":"zhiqiguankuozhang","initials":"zqgkz","setting":"out","caseName":"门诊病历184","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历184",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1ea059516c0dc36ceaf5","key":"v1-c9ccc21dfe2a3058|templates-1ea059516c0dc36ceaf5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肺脓肿","category":"门诊病历模板","raw":{"name":"肺脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历185","templates":{"主诉":"高热、咳嗽、咳大量脓臭痰2周。","现病史":"患者于2周前醉酒误吸后出现高热（体温最高39.5℃，弛张热型）、畏寒，伴咳嗽、咳痰，初为黏液痰，后转为大量脓性臭痰（每日300ml），静置后分层，伴胸痛、乏力、盗汗、食欲减退，体重下降约3kg，无咯血。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟10年，20支/日；偶有饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.5℃，P96次/分，R22次/分，BP118/74mmHg，SpO2 92%。神志清楚，急性热病容，口臭。右下肺叩诊浊音，呼吸音减低，可闻及湿啰音，语颤增强。心率96次/分，律齐。杵状指（如有，见于慢性期）。","辅助检查":"【必做】胸部X线片或CT（早期大片浓密模糊阴影，脓腔形成后可见液平空洞，为诊断依据）、血常规（白细胞显著升高）、CRP、血沉、痰涂片及培养+药敏（含厌氧菌培养）、血培养（高热时）；【其他】支气管镜（引流、取样培养、排除阻塞性因素，如异物或肿瘤），痰找抗酸杆菌。","初步诊断":"1. 肺脓肿（吸入性型）\n（注：治疗以抗菌为主+体位引流：吸入性厌氧菌为主用大剂量青霉素（320万U静滴q6h）或克林霉素0.6g q8h；血源性金黄色葡萄球菌用苯唑西林或万古霉素（MRSA）等；疗程长（6~8周至X线空洞闭合或稳定）；加强体位引流、营养支持；内科治疗3个月无效、大咯血或疑肿瘤阻塞者手术（肺叶切除）；疗效判断以影像吸收为据。）","处理方案":"【药物治疗】\n1. 阿莫西林克拉维酸钾片（1g/片）1片 po bid，疗程4～6周（青霉素皮试阴性后使用），为首选经验性方案，覆盖需氧菌与厌氧菌。\n2. 莫西沙星片0.4g po qd，疗程4～6周；用于青霉素过敏者，或与甲硝唑联用。\n3. 甲硝唑片0.4g po tid；与β-内酰胺类联用以覆盖厌氧菌（肺脓肿常见致病菌），疗程同主方案。\n4. 氨溴索片30mg po tid；配合体位引流促进排痰，痰稠难咳者可用乙酰半胱氨酸泡腾片0.6g po qd。\n【一般治疗及生活指导】\n1. 休息：急性期及发热期间卧床休息，保证充足睡眠；症状缓解后循序渐进恢复日常活动，避免剧烈运动及劳累。\n2. 体位引流：晨起及睡前各1次，患侧卧位并抬高床脚15～30cm，每次15～20分钟；引流前先口服祛痰药或雾化以稀释痰液，引流后漱口。\n3. 饮食：高蛋白、高维生素、易消化饮食，多饮水（每日2000～2500ml）以稀释痰液利于咳出，少食多餐。\n4. 禁忌：绝对戒烟戒酒，避免辛辣刺激及过甜油腻食物；保持口腔清洁，积极治疗牙周炎等口腔感染灶（常见诱因）；注意保暖，避免受凉及上呼吸道感染。\n【随诊要求】\n1. 治疗2周后门诊复查胸部CT或胸片，评估病灶变化及疗效，必要时调整方案。\n2. 疗程（4～6周）结束后复查胸部CT，评价脓腔闭合及病灶吸收情况；未完全吸收者延长疗程并定期复查。\n3. 治疗期间若出现持续发热超过1周、脓痰增多、咯血或胸痛加重，应立即复诊。\n4. 疗程结束后1个月、3个月门诊随访复查胸部影像，直至病灶稳定吸收。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":320,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1a9aa8df765803a555841e63bcbe2060e58af533792f637ea5462a5e9a7438a1","pinyin":"feinongzhong","initials":"fnz","setting":"out","caseName":"门诊病历185","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历185",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05b4dafeee17d0113657","key":"v1-c9ccc21dfe2a3058|templates-05b4dafeee17d0113657","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"间质性肺病","category":"门诊病历模板","raw":{"name":"间质性肺病","category":"门诊病历模板","case":{"case_name":"门诊病历186","templates":{"主诉":"进行性活动后气短、干咳6月，伴乏力。","现病史":"患者于6月前无明显诱因渐出现活动后气短、干咳，无发热，无胸痛，无咯血，伴乏力、食欲减退，体重下降约3kg，无关节痛、皮疹、口干眼干及雷诺现象。无职业粉尘或有机粉尘接触史、无特殊用药史（胺碘酮、甲氨蝶呤等）、无吸烟史，家族史无特殊。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R22次/分，BP120/76mmHg，SpO2 92%（静息），活动后SpO2 88%。神志清楚，呼吸稍促。双下肺可闻及Velcro啰音（细湿啰音，为特征性表现），无干啰音，无杵状指。心率88次/分，律齐。双下肢无水肿。","辅助检查":"检查计划：患者6月来出现进行性活动后气短、干咳，伴乏力、食欲减退及体重下降约3kg，无关节痛、皮疹、口干眼干及雷诺现象，无职业粉尘接触史及特殊用药史，初步考虑间质性肺疾病，需完善检查明确类型及病因。完善胸部高分辨率CT检查明确双下肺、胸膜下网格影、磨玻璃影及蜂窝影，了解是否符合UIP型，为抗纤维化治疗及肺移植评估提供依据；完善肺功能检查了解限制性通气障碍程度及FVC、DLCO下降情况，评估病情严重程度并动态监测；完善血气分析检查明确有无低氧血症及二氧化碳潴留，评估是否需要长期氧疗；查自身抗体谱及结缔组织病相关检查排除风湿免疫病相关间质性肺病，因此类患者激素及免疫抑制剂治疗有效；详细追问职业粉尘、有机粉尘接触史及胺碘酮、甲氨蝶呤等特殊用药史，必要时完善相关药物不良反应筛查以排除外源性及药物性因素；鉴于体重下降明显，查血常规、炎性指标、肝肾功能及肿瘤标志物排除感染与肿瘤性疾病；HRCT表现不典型时，完善支气管肺泡灌洗液检查或经支气管冷冻肺活检、外科肺活检明确病理诊断。\n\n（检查清单）\n【必做】胸部高分辨率CT（HRCT，可见双下肺、胸膜下网格影、磨玻璃影、蜂窝肺，为特发性肺纤维化（UIP）特征）、肺功能（限制性通气障碍：FVC、DLCO下降）、血气分析；【其他】自身抗体谱（风湿免疫病相关间质性肺病筛查）、结缔组织病相关检查、支气管肺泡灌洗液检查、肺活检（HRCT不典型时经支气管冷冻肺活检或外科肺活检确诊）。","初步诊断":"1. 间质性肺疾病（特发性肺纤维化型，待明确）\n（注：ILD病因繁多，需系统排查（职业环境、药物、结缔组织病）；特发性肺纤维化：抗纤维化治疗（吡非尼酮0.2g tid渐增量 或 尼达尼布150mg bid）、长期氧疗（低氧时）、肺康复、肺移植评估（年轻患者）；结缔组织病相关ILD治疗原发病（激素±免疫抑制剂）；急性加重（短期内气促加重、新发磨玻璃影）需住院大剂量激素冲击治疗；尽早转呼吸或风湿专科。）","处理方案":"【药物治疗】\n1. 抗纤维化治疗：尼达尼布软胶囊150mg bid，餐时服用，或吡非尼酮胶囊按200mg tid起始，每周递增200mg/次，渐增至维持量600mg tid，餐后服用，长期用药并监测肝功能。\n2. 糖皮质激素（炎症性ILD，如非特异性间质性肺炎、隐源性机化性肺炎）：泼尼松片0.5~1mg/kg/d（成人常用30~40mg/d）晨起顿服，4~8周病情稳定后每2~4周减量5mg，维持量5~10mg/d，疗程至少6个月，减量或停药宜缓慢，防止复发。\n3. 抗氧化对症辅助：乙酰半胱氨酸泡腾片600mg qd，溶解后口服；咳嗽明显者加用复方甲氧那明胶囊2粒tid；合并胃食管反流者加用质子泵抑制剂（如奥美拉唑肠溶胶囊20mg qd）。\n4. 合并感染时：莫西沙星片0.4g qd×5~7天，或阿莫西林克拉维酸钾片0.625g tid×5~7天，并据痰培养及药敏调整。\n\n【一般治疗及生活指导】\n1. 严格戒烟，避免吸入粉尘、油烟、二手烟、化学气体及宠物毛屑等有害刺激物，雾霾天气减少外出、佩戴口罩。\n2. 保证充足休息，避免劳累和剧烈活动；适当进行肺康复锻炼（缩唇呼吸、腹式呼吸及散步等，以不诱发气促为度）。\n3. 加强营养，予高蛋白、富含维生素易消化饮食，少食多餐；预防呼吸道感染，每年接种流感疫苗，适时接种肺炎球菌疫苗。\n4. 静息状态下血氧饱和度≤88%时予长期家庭氧疗，氧流量1~2L/min，每日吸氧时间≥15小时，注意用氧安全。\n\n【随诊要求】\n1. 治疗开始后每1~3个月门诊复诊，复查肺功能（FVC、DLCO）、动脉血气、6分钟步行试验，评估疾病进展及疗效。\n2. 每3~6个月复查胸部高分辨率CT（HRCT）及血常规、肝肾功能、心肌酶，监测药物不良反应（肝毒性、胃肠反应、光敏等）。\n3. 用药期间如出现气促加重、咳嗽咳痰增多、发热或咯血，需立即就诊；新发或加重的呼吸困难提示病情进展或急性加重，及时住院评估。\n4. 病情稳定者遵医嘱缓慢减量激素，切勿自行停药或增减剂量；出现皮疹、光敏、消化道出血等药物不良反应时随时复诊调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":321,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"47673cd95708ff92fca56773e727ab5df286798401ad1b336ca526e229d90392","pinyin":"jianzhixingfeibing","initials":"jzxfb","setting":"out","caseName":"门诊病历186","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历186",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d1b0f341396e75878d9d","key":"v1-c9ccc21dfe2a3058|templates-d1b0f341396e75878d9d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结节病","category":"门诊病历模板","raw":{"name":"结节病","category":"门诊病历模板","case":{"case_name":"门诊病历187","templates":{"主诉":"干咳、胸闷、乏力伴双侧肺门淋巴结肿大3月。","现病史":"患者于3月前渐出现干咳、胸闷、活动后气短、乏力、低热（体温波动于37.3~38℃）、盗汗、食欲减退、体重下降约4kg，无皮疹（结节性红斑）、无关节痛、无眼红眼痛及视力下降，无浅表淋巴结肿大。体检及影像发现双侧肺门及纵隔淋巴结肿大。无结核接触史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P86次/分，R20次/分，BP118/72mmHg。神志清楚，查体合作。双肺呼吸音清。心率86次/分，律齐。颈及腋窝浅表淋巴结肿大，双下肢可见结节性红斑。肝脾肋下未触及。眼部检查未见葡萄膜炎征象。","辅助检查":"检查计划：患者干咳、胸闷、乏力3月，伴低热、盗汗、食欲减退及体重下降约4kg，影像发现双侧肺门及纵隔淋巴结肿大，初步诊断结节病Ⅱ期，需完善检查明确分期、活动性及有无肺外受累。完善胸部X线片或CT检查明确双侧肺门及右侧气管旁淋巴结肿大及肺实质浸润情况，作为分期依据并了解有无肺纤维化；查血常规、血沉、CRP了解炎症活动程度，评估病情活动性；查血清血管紧张素转化酶检查，活动期常升高，可作为诊断参考及疗效监测指标；查肝肾功能为治疗前评估基础状态，指导泼尼松用药及减量；查血钙、尿钙检查排除结节病特征性高钙血症及其所致肾脏损害；确诊需完善支气管镜纵隔淋巴结穿刺活检或纵隔镜淋巴结活检，明确非干酪样坏死性肉芽肿，同时排除结核与肿瘤；完善肺功能检查评估通气功能受损程度，查心电图排除心脏结节病，完善眼科检查明确有无葡萄膜炎等眼部受累，因其均影响治疗指征与方案制定。\n\n（检查清单）\n【必做】胸部X线片或CT（双侧肺门及右侧气管旁淋巴结肿大（1-2-3征）、肺实质浸润，为分期依据）、血常规、血沉、CRP、血清血管紧张素转化酶（ACE，活动期升高）、肝肾功能、血钙尿钙（高钙血症为结节病特征）；【确诊】支气管镜纵隔淋巴结穿刺活检（EBUS-TBNA）或纵隔镜淋巴结活检（非干酪样坏死性肉芽肿）；【其他】肺功能、心电图、眼科检查。","初步诊断":"1. 结节病（Ⅱ期，活动性）\n（注：多数结节病有自限性（约2/3自行缓解），无症状Ⅰ期可观察随访；需治疗指征：明显肺部症状或肺功能下降、高钙血症、眼或心脏或神经受累：口服泼尼松0.5mg/kg/d起始渐减，疗程6~24个月；心脏结节病、神经结节病需专科处理；停药后复发常见，需长期随访（胸片或CT、肺功能、血钙）。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选）：泼尼松片30mg（0.5mg/kg）qd po，晨起顿服，连用4~6周后根据症状及胸部影像改善情况每2~4周减量5mg，维持量5~10mg/d，总疗程6~12个月。适用于有症状的肺内病变（咳嗽、气促、肺功能下降）或重要脏器受累（心脏、眼部、神经系统受累、高钙血症）。\n2. 免疫抑制剂（激素减量期或激素不耐受/疗效不佳者）：甲氨蝶呤片7.5~15mg qw po，每周固定1次服用，服药后24~48小时加服叶酸片5mg qd；或硫唑嘌呤片50mg bid po，需定期监测血常规及肝肾功能。\n3. 皮肤受累或高钙血症者：羟氯喹片200mg bid po，疗程3~6个月，用药前及此后每6个月行眼底检查监测视网膜毒性。\n4. 对症处理：干咳明显者加用复方甲氧那明胶囊2粒 tid po；骨量减少/骨质疏松风险者加用钙剂及维生素D（高钙血症者禁用）。\n【一般治疗及生活指导】\n1. 戒烟，避免粉尘、化学刺激物及二手烟环境，保持居室通风，减少职业及环境抗原暴露。\n2. 高钙血症或高尿钙者避免日光暴晒及紫外线照射，停用钙剂和维生素D制剂，每日多饮水（2000ml以上）以促进钙排泄。\n3. 规律作息，保证充足睡眠，避免过度劳累及熬夜；病情稳定期可进行散步、太极拳等轻度有氧活动，急性期或明显气促者避免剧烈运动。\n4. 注意保暖、预防呼吸道感染（感染可诱发或加重病情）；如需接种疫苗（如流感、肺炎球菌疫苗）建议在病情稳定期进行。\n【随诊要求】\n1. 治疗初期每2~4周门诊复诊1次，评估症状、肺部影像及肺功能变化，监测激素不良反应（血糖、血压、血钾、体重、骨质疏松），据此调整激素剂量。\n2. 治疗期间每1~3个月复查胸部CT、肺功能、血钙及血/尿钙，每1~3个月监测血常规、肝肾功能及炎症指标。\n3. 眼部受累者定期至眼科随访，用药期间按医嘱复查眼底；停药后建议每6~12个月随访1次，至少随访2~3年，注意观察复发及新发脏器受累。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":322,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6b9f4d31a8c66bfc26b4759ec6374af2a7d027e72e8f255c7bd999ab5145b7ce","pinyin":"jiejiebing","initials":"jjb","setting":"out","caseName":"门诊病历187","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历187",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5effb7846d32fac4fcd3","key":"v1-c9ccc21dfe2a3058|templates-5effb7846d32fac4fcd3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扁桃体炎","category":"门诊病历模板","raw":{"name":"扁桃体炎","category":"门诊病历模板","case":{"case_name":"门诊病历188","templates":{"主诉":"咽痛伴吞咽痛、发热2天。","现病史":"患者于2天前受凉后出现咽痛，吞咽时加重，伴发热（体温最高38.8℃）、畏寒、乏力，无声音嘶哑，无咳嗽，无呼吸困难，无张口受限。既往无反复扁桃体炎发作史，无扁桃体肥大（打鼾）史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.8℃，P96次/分，R20次/分，BP116/74mmHg。神志清楚，急性病容。咽部充血，双侧扁桃体Ⅱ度肿大，表面可见脓点，腭弓及咽后壁充血，下颌角淋巴结肿大压痛。双肺呼吸音清。","辅助检查":"检查计划：患者2天前受凉后出现咽痛，吞咽时加重，伴发热最高38.8℃、畏寒、乏力，无声音嘶哑、咳嗽及呼吸困难，初步诊断急性扁桃体炎，需完善检查明确感染性质、范围及有无并发症。查血常规了解白细胞总数及中性粒细胞比例，明确细菌性感染还是病毒性感染，指导是否使用青霉素类等抗生素；完善耳镜检查排除急性中耳炎等伴发感染灶，明确发热及耳部症状的来源；患者无鼻塞流涕，完善鼻内镜检查排除鼻窦炎及鼻后滴漏所致咽部刺激；完善喉镜检查排除急性喉炎、会厌炎等喉部病变，以免漏诊气道梗阻风险；若咽痛加重伴张口受限、语音含糊或疑有扁桃体周围脓肿、鼻窦并发症，完善鼻窦CT、颞骨CT检查进一步明确；完善颈部超声检查明确颈部淋巴结反应性肿大及有无脓肿形成，必要时引导穿刺；患者目前无耳闷、听力下降及眩晕，必要时完善纯音测听、声导抗检查了解中耳及听力情况，完善前庭功能检查鉴别前庭性眩晕。治疗期间密切观察病情，必要时复查血常规。\n\n（检查清单）\n【必做检查】\n血常规、耳镜检查、鼻内镜检查、喉镜检查\n\n【影像学检查】\n鼻窦CT、颞骨CT、颈部超声\n\n【其他检查】\n纯音测听、声导抗、前庭功能检查","初步诊断":"1. 急性扁桃体炎\n（注：细菌性（A群链球菌常见）予青霉素类（阿莫西林0.5g tid×5~7天，青霉素过敏用阿奇霉素0.5g qd×3天或头孢类），对症：解热镇痛（布洛芬/对乙酰氨基酚）、盐水漱口、多饮休息；注意休息、隔离（链球菌传染）；若一侧咽痛加剧伴张口受限、语音含糊提示扁桃体周围脓肿，需耳鼻喉科处理；反复急性发作（每年≥5次）或扁桃体肥大影响呼吸睡眠者考虑扁桃体切除。）","处理方案":"【药物治疗】\n1. 阿莫西林胶囊 0.5g，口服，每日3次，连用5-7天（青霉素皮试阴性后使用；对青霉素过敏者改用头孢呋辛酯片 0.25g，每日2次，连用5-7天；头孢类亦过敏者选用阿奇霉素片 0.5g，每日1次，连用3天）。\n2. 复方氯己定含漱液 10ml，含漱，每日3-4次，饭后及睡前使用。\n3. 对乙酰氨基酚片 0.5g，口服，必要时（体温≥38.5℃或咽痛明显时），每日不超过4次，间隔至少4-6小时。\n\n【一般治疗及生活指导】\n1. 急性期注意休息，避免劳累及熬夜，保证充足睡眠；多饮温开水，每日饮水量2000ml以上，促进毒素排泄。\n2. 饮食以清淡、易消化的流质或半流质为主（如稀粥、烂面条、蛋羹），忌辛辣、油炸、过烫及坚硬粗糙食物，戒烟酒。\n3. 注意口腔卫生，可用温盐水或复方氯己定含漱液勤漱口；避免大声喊叫、过度用声，保持居室通风、湿度适宜。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效，复查血常规；若发热超过3天不退、咽痛加重、出现张口困难、颈部包块或呼吸困难，立即就医。\n2. 抗生素需足量足疗程（一般5-7天），症状缓解后不可自行停药，疗程结束前复查血常规及咽部体征。\n3. 反复急性发作（1年内≥5次或2年内≥7次）者，建议转耳鼻喉科评估，根据患者具体情况制定个体化方案考虑扁桃体切除术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":323,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b809041eb981dd664578bc8d7ccf4391897739eee317be1f7d3d8942a5529e17","pinyin":"biantaotiyan","initials":"btty","setting":"out","caseName":"门诊病历188","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历188",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-095f2f23a50e58e6c7ee","key":"v1-c9ccc21dfe2a3058|templates-095f2f23a50e58e6c7ee","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"喉炎","category":"门诊病历模板","raw":{"name":"喉炎","category":"门诊病历模板","case":{"case_name":"门诊病历189","templates":{"主诉":"声音嘶哑伴喉部不适、干咳3天。","现病史":"患者于3天前受凉后用声过度出现声音嘶哑，渐加重，伴喉部干痒、异物感、干咳、咳少量黏痰，无发热，无呼吸困难、无喉鸣。无职业用声及烟酒史，无反酸烧心等胃食管反流症状。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P84次/分，R18次/分，BP116/74mmHg。神志清楚，发音嘶哑。间接喉镜或电子喉镜：喉黏膜及声带弥漫性充血、水肿，声带运动正常，闭合欠佳，无新生物。咽部充血。心肺听诊未见异常。","辅助检查":"【必做】喉镜检查为主；【其他】血常规（发热或疑感染时）、喉动态镜（评估声带运动功能，适用于嘶哑迁延者）。","初步诊断":"1. 急性喉炎\n（注：声带休息（禁声，避免耳语）、雾化吸入（布地奈德混悬液1mg bid减轻水肿）、祛痰、多饮温水；细菌感染征象时用抗菌药物；戒烟酒、忌辛辣；合并反流者抗反流治疗（质子泵抑制剂）；声音嘶哑>2周持续不缓解需喉镜复查排除声带息肉、小结或肿瘤；出现呼吸困难、喉鸣为喉梗阻征象需急诊。）","处理方案":"【药物治疗】\n1. 局部抗炎（首选）：吸入用布地奈德混悬液1mg+生理盐水2ml 雾化吸入 bid，疗程3~5天；声嘶、喉水肿明显者可联用糜蛋白酶4000U 雾化吸入 qd，以稀释分泌物。\n2. 抗菌治疗（有脓性分泌物、发热或血象升高等细菌感染证据者）：阿莫西林胶囊0.5g tid 口服，疗程5~7天；青霉素过敏者改阿奇霉素片0.5g qd 口服，疗程3天。\n3. 对症治疗：金嗓开音丸或黄氏响声丸口服，一次6粒 tid；声带充血明显者加西瓜霜润喉片含服，一次2片 tid。\n4. 止咳祛痰（咳嗽明显者）：复方甘草口服液10ml tid 口服，或盐酸氨溴索片30mg tid，疗程3~5天。\n\n【一般治疗及生活指导】\n1. 声带休息：急性期禁声3~5天，尽量少说话，禁止耳语、高声喊叫及长时间交谈，避免加重声带充血水肿。\n2. 饮食：多饮温水，进食清淡、温凉的流质或半流质饮食，忌辛辣、过烫、过冷及刺激性食物，禁烟酒。\n3. 环境与防护：保持室内空气湿润（可加湿器），避免粉尘、烟雾、油烟及化学气体刺激，注意保暖、避免受凉。\n4. 避免用力咳嗽、频繁清嗓及用力擤鼻，减少对喉部黏膜的机械损伤。\n\n【随诊要求】\n1. 治疗3~5天后症状无缓解或加重者，及时复诊调整治疗。\n2. 声音嘶哑持续超过2周不缓解者，应行电子喉镜检查，排除声带息肉、小结及喉部新生物等器质性病变。\n3. 若出现犬吠样咳嗽、吸气性呼吸困难、喉喘鸣或三凹征等喉梗阻表现，应立即急诊就诊，以防窒息。\n4. 急性喉炎反复发作（每年≥3次）或迁延为慢性喉炎者，建议耳鼻喉科门诊系统诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":324,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c33df1d468f3105033667a27a912bb96be381a1f8a63f2b8fbb38b977e5039c2","pinyin":"houyan","initials":"hy","setting":"out","caseName":"门诊病历189","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历189",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e14000e3a4c140b81b3e","key":"v1-c9ccc21dfe2a3058|templates-e14000e3a4c140b81b3e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"冠心病","category":"门诊病历模板","raw":{"name":"冠心病","category":"门诊病历模板","case":{"case_name":"门诊病历190","templates":{"主诉":"发作性胸骨后闷痛3月，加重7天","现病史":"患者于3月前开始于快步行走、上楼、饱餐、情绪激动时出现胸骨后闷痛及压榨感，范围约手掌大小，可向左肩、左臂放射，伴气短、出汗，休息或含服硝酸甘油后3分钟缓解，每次持续约5分钟。近7天发作频率增加（每日3次），含服硝酸甘油效果欠佳。有高血压病史5年、糖尿病病史3年、血脂异常，吸烟20年（20支/日），无早发冠心病家族史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP142/86mmHg。神志清楚，查体合作，体型超重。双肺呼吸音清，无干湿啰音。心率78次/分，律齐，心界不大，心音低钝，各瓣膜听诊区未闻及病理性杂音。双下肢无水肿。","辅助检查":"【必做】心电图（静息及发作时对比ST-T改变）、心肌损伤标志物（肌钙蛋白，排除心梗）、血常规、空腹血糖、血脂、肝肾功能；【影像学】超声心动图（室壁运动及心功能）、运动负荷试验（疑冠心病评估）、冠状动脉CT血管成像（评估冠脉狭窄程度）；【确诊】冠状动脉造影（金标准）。","初步诊断":"1. 冠状动脉粥样硬化性心脏病（稳定型心绞痛）\n（注：规范二级预防：抗血小板（阿司匹林100mg qd）、他汀强化降脂（阿托伐他汀20mg qd，LDL-C目标<1.8mmol/L）、控制血压血糖、戒烟；抗心绞痛：硝酸酯（发作时硝酸甘油0.5mg舌下含服，预防用单硝酸异山梨酯）、β受体阻滞剂（美托洛尔，心率控制55~60次/分）、CCB；冠脉造影评估介入（PCI）或搭桥指征；若静息痛、发作加重或肌钙蛋白升高提示急性冠脉综合征，需急诊。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片 100mg qd 晨服，长期口服；不能耐受或过敏者改用氯吡格雷片 75mg qd。已行冠脉支架植入者采用双联抗血小板治疗：阿司匹林肠溶片 100mg qd + 氯吡格雷片 75mg qd（或替格瑞洛片 90mg bid），疗程12个月，勿擅自停药。\n2. 调脂稳定斑块：阿托伐他汀钙片 20mg qn（或瑞舒伐他汀钙片 10mg qn），长期口服；每3-6个月复查血脂、肝功能、肌酸激酶，LDL-C目标值<1.8mmol/L（反复心血管事件者<1.4mmol/L），不达标者可联合依折麦布片 10mg qd。\n3. 抗心绞痛治疗：单硝酸异山梨酯缓释片 40mg qd（心绞痛频繁者可 bid，早晚各1次），疗程视症状控制情况调整；劳力型心绞痛及心率偏快者加用琥珀酸美托洛尔缓释片 47.5mg qd，逐渐加量至静息心率55-60次/分，需长期维持。\n4. 改善预后治疗（合并高血压、心功能不全或心梗后）：培哚普利片 4mg qd（或氯沙坦钾片 50mg qd），长期口服，注意监测血压、血钾及肾功能；合并糖尿病者控制空腹血糖<7.0mmol/L，HbA1c<7.0%。\n\n【一般治疗及生活指导】\n1. 休息与活动：心绞痛发作期卧床休息，避免劳累、剧烈运动及情绪激动；稳定期坚持规律中等强度有氧运动（如快走、太极拳、八段锦），每周3-5次、每次30分钟，以运动时无心绞痛发作为度，运动前可预防性含服硝酸甘油。\n2. 饮食控制：低盐低脂饮食，每日食盐摄入<5g，减少饱和脂肪及反式脂肪（肥肉、油炸食品、糕点），多食蔬菜、水果及全谷物，控制总热量，避免暴饮暴食；戒烟、限酒，避免二手烟。\n3. 危险因素管理：控制体重（BMI 18.5-24kg/m²），血压<140/90mmHg（合并糖尿病<130/80mmHg），血脂、血糖达标，规律作息，保持大便通畅。\n4. 禁忌及急救指导：避免寒冷刺激、用力排便、饱餐后立即活动等诱发因素；随身携带硝酸甘油片，心绞痛发作时立即舌下含服0.5mg，5分钟不缓解可重复1次，最多3次，仍不缓解或伴大汗、濒死感者立即拨打120急诊就医。\n\n【随诊要求】\n1. 定期门诊复诊：稳定期每1-3个月复诊1次，评估心绞痛发作频次、血压、心率、血脂血糖达标情况并复查心电图；每3-6个月复查血脂、肝功能、肾功能、心肌酶及糖化血红蛋白。\n2. 出现以下情况及时复诊：心绞痛发作频繁、程度加重、静息状态下发作或持续时间延长，新发心悸、晕厥、呼吸困难、下肢水肿，或服药期间出现肌痛、黑便、皮肤瘀斑等不良反应。\n3. 冠脉支架植入者遵医嘱坚持双联抗血小板治疗，术后1、3、6、12个月按时复查（心电图、心脏超声及必要时冠脉CTA或造影），任何检查、拔牙、手术前医师抗血小板用药史，不得自行停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":325,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f0d5dacfd7e643c1642341573a25b8d5f4055b36988db360e73041b4282105f7","pinyin":"guanxinbing","initials":"gxb","setting":"out","caseName":"门诊病历190","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历190",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1cb6c9d57696c3b38cb7","key":"v1-c9ccc21dfe2a3058|templates-1cb6c9d57696c3b38cb7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心绞痛","category":"门诊病历模板","raw":{"name":"心绞痛","category":"门诊病历模板","case":{"case_name":"门诊病历191","templates":{"主诉":"发作性胸痛6月，再发加重3天。","现病史":"患者于6月前开始反复出现胸痛，为胸骨后压榨样，多于活动时发作，每次持续3~5分钟，向左肩、左臂放射，伴出汗、气短，休息或含服硝酸甘油后缓解。近3天发作更频繁、持续时间延长或静息时发作，含服硝酸甘油效果欠佳，无晕厥。危险因素：高血压病史8年、糖尿病病史5年、血脂异常、吸烟20年、家族史。今日来我院急诊或门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分，R18次/分，BP150/90mmHg。神志清楚，平时面容。双肺呼吸音清。心率82次/分，律齐，心音低钝，可闻及第四心音。双下肢无水肿。","辅助检查":"【必做】心电图（发作时ST段压低/抬高（变异型）、T波改变）、心肌肌钙蛋白（动态监测鉴别心梗）、血脂血糖肝肾功能、凝血功能；【影像学】超声心动图；【其他】动态心电图（捕捉发作）、冠脉CT或冠脉造影。","初步诊断":"1. 心绞痛（不稳定型）\n（注：稳定型按冠心病二级预防+抗心绞痛药物规范治疗；不稳定型心绞痛属急性冠脉综合征，应收住院：抗血小板（阿司匹林+氯吡格雷或替格瑞洛双抗）、抗凝（低分子肝素）、他汀、硝酸酯、β受体阻滞剂，尽早冠脉造影及介入（PCI）；变异型与冠脉痉挛有关，用钙通道阻滞剂（地尔硫卓）治疗、禁烟；胸痛持续>20分钟含服硝酸甘油不缓解需立即急诊排除急性心肌梗死。）","处理方案":"【药物治疗】\n1. 抗血小板聚集：阿司匹林肠溶片100mg qd po，长期口服（无禁忌证者首选，必要时联合氯吡格雷75mg qd）；\n2. β受体阻滞剂：琥珀酸美托洛尔缓释片47.5mg qd po（或富马酸比索洛尔片5mg qd），使静息心率降至55～60次/分，无禁忌证者长期维持；\n3. 调脂稳定斑块：阿托伐他汀钙片20mg qn po（或瑞舒伐他汀钙片10mg qn），长期服用，LDL-C目标＜1.8mmol/L（必要时加倍剂量）；\n4. 硝酸酯类：心绞痛发作时硝酸甘油片0.5mg舌下含服，若5分钟不缓解可重复1次，最多连用3次；缓解期可加用单硝酸异山梨酯缓释胶囊50mg qd po（注意留出8～12小时无药间期以防耐药）。\n\n【一般治疗及生活指导】\n1. 休息与活动：发作期卧床休息，减少心肌耗氧；缓解期在症状控制后逐步进行低-中等强度有氧运动（如快走、太极拳，每周3～5次、每次30分钟），避免剧烈运动及饱餐后、寒冷天气下运动；\n2. 饮食：低盐低脂饮食，每日食盐＜5g，减少饱和脂肪及反式脂肪摄入，多食蔬菜水果及粗粮，戒烟限酒，控制体重（BMI＜24kg/m²）；\n3. 避免诱因：避免情绪激动、过度劳累、用力排便及寒冷刺激，保持大便通畅，必要时使用缓泻剂；\n4. 危险因素管理：严格控制血压＜130/80mmHg、空腹血糖及血脂达标，规律作息、保证充足睡眠。\n\n【随诊要求】\n1. 1～2周后门诊复诊，评估心绞痛发作频率、程度及活动耐量改善情况，调整药物剂量；\n2. 每月复查血脂、肝功能、肌酸激酶，监测阿托伐他汀及β受体阻滞剂不良反应，用药期间监测静息心率、血压；\n3. 建议近期完善冠脉CTA或择期冠状动脉造影，评估冠脉病变程度以决定是否介入或外科治疗；\n4. 宣教警示症状：若胸痛发作频率增加、程度加重、持续时间延长或静息时发作（恶化型劳力性心绞痛），或含服硝酸甘油无效，应立即急诊就诊，警惕急性心肌梗死。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":326,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"90e4568f00128148a2d55be194381750eeb62a78e23790fc0dcfc23278806c88","pinyin":"xinjiaotong","initials":"xjt","setting":"out","caseName":"门诊病历191","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历191",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6b3d9c4baa6940044fe6","key":"v1-c9ccc21dfe2a3058|templates-6b3d9c4baa6940044fe6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心肌梗死","category":"门诊病历模板","raw":{"name":"心肌梗死","category":"门诊病历模板","case":{"case_name":"门诊病历192","templates":{"主诉":"持续性胸骨后压榨样剧痛2小时，伴大汗、濒死感。","现病史":"患者于2小时前安静时突发胸骨后压榨样剧烈疼痛，范围广泛，向左肩、左臂及下颌放射，持续不缓解，含服硝酸甘油无效，伴大汗淋漓、恐惧濒死感、恶心、呕吐2次、气短，无晕厥、无黑矇。发病前无劳累、饱餐、情绪激动等诱因。危险因素：高血压病史10年、糖尿病病史6年、吸烟、血脂异常。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.2℃，P102次/分（可增快或减慢），R24次/分，BP96/64mmHg。神志清楚，痛苦面容，皮肤湿冷，面色苍白。双肺呼吸音清，未闻及湿啰音（肺水肿或心衰时可闻及湿啰音）。心率102次/分，律齐（可有心律失常），心音低钝，可闻及奔马律、心包摩擦音（梗死后心包炎时）。","辅助检查":"检查计划：患者2小时前安静时突发胸骨后压榨样剧痛，向左肩、左臂及下颌放射，持续不缓解，含服硝酸甘油无效，伴大汗、濒死感、恶心呕吐及气短，既往高血压10年、糖尿病6年，吸烟及血脂异常，考虑急性ST段抬高型心肌梗死。急诊即刻完善18导联心电图明确有无ST段弓背向上抬高及ST-T动态演变，决定再灌注策略；完善心肌肌钙蛋白检查明确心肌坏死，动态复查评估梗死范围及再灌注效果；查心肌酶检查排除急性心肌损伤并了解演变过程；查血常规、凝血功能排除贫血及凝血异常，为急诊PCI及双联抗血小板治疗做术前准备；查血脂、血糖及肝肾功能了解危险因素与代谢状况，指导他汀及降糖方案调整；患者呕吐、大汗，完善电解质检查排除低钾等电解质紊乱所致恶性心律失常，完善血气分析了解氧合及酸碱状态；床旁超声心动图检查在急诊完成，了解节段性室壁运动异常、射血分数及瓣膜情况，评估有无室间隔穿孔、乳头肌断裂、心包积液等机械并发症；持续剧痛不缓解且肌钙蛋白升高，应尽快完善冠脉造影明确梗死相关血管，并急诊行PCI开通血管。住院期间定期复查心电图及心肌损伤标志物观察动态演变。\n\n（检查清单）\n【必做】心电图（ST段弓背向上抬高，提示STEMI；ST-T动态演变）、心肌肌钙蛋白（升高，为诊断金标准；动态复查）、心肌酶、血常规、凝血功能、血脂血糖肝肾功能、血气分析；【影像学】床旁超声心动图（节段性室壁运动异常、心功能、并发症，如室间隔穿孔、乳头肌断裂、心包积液）；【其他】冠脉造影（急诊PCI）。","初步诊断":"1. 急性ST段抬高型心肌梗死（前壁）\n（注：心肌梗死是极危重急症，须立即急诊救治：卧床、心电监护、吸氧、阿司匹林300mg嚼服+替格瑞洛180mg负荷、吗啡镇痛、硝酸甘油（下壁或右室梗死慎用）、尽早再灌注治疗：发病12小时内首选急诊PCI（<90分钟），无条件则溶栓（<30分钟给药）；防治并发症（心律失常、心衰、心源性休克）；收入CCU，后续二级预防（双抗、他汀、ACEI或ARB、β受体阻滞剂）及心脏康复。）","处理方案":"【药物治疗】\n1. 抗血小板治疗：阿司匹林肠溶片100mg qd口服，联合氯吡格雷片75mg qd（或替格瑞洛片90mg bid），双联抗血小板治疗至少12个月，植入支架者按医嘱延长；如无禁忌，长期单用阿司匹林维持。\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn（或瑞舒伐他汀钙片10mg qn）口服，长期服用，定期复查血脂，LDL-C目标值<1.4mmol/L或较基线降低≥50%。\n3. β受体阻滞剂抗缺血：琥珀酸美托洛尔缓释片23.75～47.5mg qd口服，目标静息心率55～60次/分，根据心率、血压逐步调整剂量。\n4. 肾素-血管紧张素系统抑制剂：培哚普利叔丁胺片4mg qd口服（或缬沙坦胶囊80mg qd），逐渐加至耐受剂量；若左室射血分数（LVEF）≤40%且血钾、肾功能允许，加用螺内酯片20mg qd。\n【一般治疗及生活指导】\n1. 休息与活动：急性期后1～2周以静养为主，避免劳累、情绪激动、用力排便；病情稳定后在医师指导下循序渐进进行有氧运动（如平地步行、慢速骑车），每周3～5次，每次20～40分钟，以运动时不诱发胸闷、心悸为度；6个月内避免重体力劳动和剧烈运动。\n2. 饮食：低盐（每日<5g）、低脂、低胆固醇饮食，控制总热量，少食多餐避免饱餐，多食新鲜蔬菜、水果及全谷物，戒烟并避免二手烟，严格限酒。\n3. 监测与控制危险因素：每日自测血压，控制血压<130/80mmHg，监测血糖、血脂，控制体重（BMI<24kg/m²），按时规律服药，禁止自行停药或减量，尤其是抗血小板及他汀类药物。\n4. 禁忌：避免受凉、感染及各种应激诱发因素；如有便秘可适当使用缓泻剂，避免用力屏气；避免泡热水澡、桑拿等引起血流动力学波动。\n【随诊要求】\n1. 诊断或出院后1～2周门诊复诊1次，之后第1、3、6、12个月定期随诊，此后遵医嘱长期随访；每次复诊复查心电图、血压、心率。\n2. 定期复查心脏彩色多普勒超声（评估心功能及室壁运动）、血脂、肝肾功能、血常规、凝血功能（监测抗血小板及他汀用药安全）。\n3. 如出现胸痛、胸闷、气促、黑矇、晕厥或心功能不全表现，立即急诊就诊，不得等待预约复诊。\n4. 按医嘱完成冠脉CTA或冠脉造影复查及心脏康复（二期康复）评估，调整药物及康复运动方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":327,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6d378d22425bb543d5dde8a35acef5524bf0f29c7ff62710a9ca0d4acdd406f2","pinyin":"xinjigengsi","initials":"xjgs","setting":"out","caseName":"门诊病历192","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历192",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-005177211b00ec7d9fbb","key":"v1-c9ccc21dfe2a3058|templates-005177211b00ec7d9fbb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心肌病","category":"门诊病历模板","raw":{"name":"心肌病","category":"门诊病历模板","case":{"case_name":"门诊病历193","templates":{"主诉":"活动后气短、乏力6月，伴心悸2周。","现病史":"患者于6月前渐出现活动后气短、乏力、耐力下降，2周来伴心悸、胸闷，夜间需高枕，无胸痛、无晕厥、无黑矇、无双下肢水肿。无心肌病家族史、无近期病毒感染史、无长期大量饮酒史，无围产期（妊娠后期/产后）病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P96次/分，R20次/分，BP106/68mmHg。神志清楚，查体合作。颈静脉怒张（右心衰时可见）。双肺呼吸音清，未闻及湿啰音。心率96次/分，律齐，心界向左下扩大（扩张型心肌病表现），心音低钝，可闻及奔马律。双下肢水肿（+）。","辅助检查":"【必做】心电图（左室肥大、ST-T改变、异常Q波、心律失常）、超声心动图（心室腔大小、室壁厚度、射血分数，为心肌病分型核心依据：扩张型或肥厚型或限制型）、心肌损伤标志物、BNP、肝肾功能电解质；【影像学】心脏MRI（心肌纤维化或浸润，为心肌病评估金标准）；【其他】动态心电图（恶性心律失常筛查）、基因检测（家族性心肌病）、冠脉造影（排除缺血性心肌病）。","初步诊断":"1. 心肌病（扩张型）\n（注：扩张型心肌病：心衰规范治疗（ACEI或ARB或ARNI、β受体阻滞剂、螺内酯、利尿剂）、抗凝（房颤或血栓者）；肥厚型心肌病：β受体阻滞剂（普萘洛尔）或非二氢吡啶CCB（维拉帕米）、避免剧烈运动及脱水（防猝死，评估植入ICD指征）、流出道梗阻严重者手术（室间隔切除或酒精消融）；限制型治疗原发病；心力衰竭、恶性心律失常（室速或室颤）或晕厥者需专科住院并评估心脏移植。）","处理方案":"【药物治疗】\n1. 沙库巴曲缬沙坦钠片（诺欣妥）50mg bid po，起始剂量，据血压及耐受情况每2-4周滴定至100-200mg bid（ARNI，替代ACEI/ARB用于HFrEF期心肌病，抑制心室重构）。\n2. 琥珀酸美托洛尔缓释片 23.75mg qd po，晨起顿服，据静息心率（目标55-60次/分）每1-2周加量，最大47.5-95mg qd，长期维持（β受体阻滞剂，减慢心率、改善心功能）。\n3. 螺内酯片 20mg qd po，长期口服，服药期间定期复查电解质及肾功能，警惕高钾血症（醛固酮受体拮抗剂，降低心肌纤维化及死亡率）；伴明显水肿/肺淤血者加用呋塞米片20mg qd po，水肿消退后根据患者具体情况制定个体化方案减停（利尿剂，仅按需间歇使用，避免过度利尿）。\n4. 达格列净片10mg qd po，长期口服（SGLT2抑制剂，改善心衰预后，注意多饮水，监测泌尿系感染）。\n\n【一般治疗及生活指导】\n1. 休息：心功能不全（NYHA III-IV级）及急性加重期卧床休息，取半卧位减轻肺淤血；症状缓解、心功能稳定后保证充足睡眠，避免劳累及熬夜。\n2. 饮食：低盐饮食（每日食盐<3g），限水（每日入量1500ml左右，心衰期尿量+500ml），少食多餐，低脂优质蛋白饮食，戒烟限酒，避免浓茶、咖啡等兴奋性饮品。\n3. 活动：心功能稳定期循序渐进进行散步等低-中等强度有氧运动，每次20-30分钟，以不引起气促、心悸为度；严禁剧烈运动、竞技性运动及负重锻炼（尤其肥厚型心肌病有猝死风险，避免突然用力、屏气动作如搬重物、用力排便）。\n4. 禁忌：避免呼吸道感染及劳累诱发心衰加重，感冒流行季节减少聚集、必要时接种流感及肺炎疫苗；避免自行服用影响心肌或致心律失常药物（如非甾体抗炎药、部分抗心律失常药、减肥药），避免妊娠（围生期心肌病、重度心衰者）。\n\n【随诊要求】\n1. 病情稳定者每2-4周门诊复诊，监测血压、心率、体重（每日晨起排尿后称重，3天内增加>2kg提示液体潴留，及时复诊调整利尿剂）。\n2. 每3-6个月复查心电图、超声心动图（评估左室大小及射血分数变化）、BNP/NT-proBNP；每3个月复查电解质、肝肾功能、血常规，服用螺内酯及ARNI期间重点监测血钾及肌酐。\n3. 有晕厥、胸痛、心悸或晕厥前兆者，需完善24小时动态心电图及心脏磁共振等进一步评估；有猝死家族史或LVEF≤35%者，评估ICD植入指征并转诊心脏专科。\n4. 出现夜间阵发性呼吸困难、端坐呼吸、双下肢水肿加重、体重骤增或血压明显波动时，立即就近就诊，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":328,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ab435ef822d95ad8d4bfb13ae312ee7417dbd55e8a1e1c6bf18ec8087685d8d7","pinyin":"xinjibing","initials":"xjb","setting":"out","caseName":"门诊病历193","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历193",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-969fd8764f54c713d4bc","key":"v1-c9ccc21dfe2a3058|templates-969fd8764f54c713d4bc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心包炎","category":"门诊病历模板","raw":{"name":"心包炎","category":"门诊病历模板","case":{"case_name":"门诊病历194","templates":{"主诉":"胸痛伴发热7天，坐位前倾减轻。","现病史":"患者于7天前上呼吸道感染后出现胸痛，位于胸骨后，呈锐痛，深呼吸、咳嗽、平卧时加重，坐位前倾位减轻，可放射至左肩、颈部，伴发热（体温最高38.6℃）、乏力、心悸。无近期心肌梗死、心脏手术、结核、肿瘤、尿毒症及自身免疫病史。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P98次/分，R20次/分，BP118/74mmHg。神志清楚，可闻及心包摩擦音（胸骨左缘第3~4肋间，前倾位明显，呈抓刮样，为急性心包炎特征性体征），心率98次/分，律齐，心音低钝（大量积液时），颈静脉无怒张，双肺呼吸音清，双下肢无水肿。","辅助检查":"【必做】心电图（弥漫性ST段弓背向下抬高及PR段压低，为急性心包炎特征；大量积液时低电压）、血常规、CRP、血沉、心肌肌钙蛋白（排除心肌炎或心梗）、肝肾功能；【影像学】超声心动图（心包积液，为诊断关键，评估有无心脏压塞）、胸部X线片（心影增大呈烧瓶样，见于大量积液）；【其他】心包穿刺（积液性质：渗出或漏出、ADA（结核）、细胞学（肿瘤）、细菌培养）。","初步诊断":"1. 急性心包炎\n（注：非特异性或病毒性心包炎：NSAIDs（布洛芬600~800mg tid）为一线抗炎镇痛，可联用秋水仙碱0.5mg bid（减少复发）；糖皮质激素用于NSAIDs无效、自身免疫性等（可能增加复发，慎用）；疗程至症状缓解、CRP正常后渐减；大量心包积液或出现心脏压塞表现（低血压、颈静脉怒张、奇脉、心音遥远，即Beck三联征）需急诊心包穿刺引流；病因明确者（结核、肿瘤、尿毒症）治疗原发病。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（急性心包炎一线抗炎镇痛）：布洛芬缓释胶囊0.3g bid po，餐后服用，疗程1~2周，胸痛及炎症指标缓解后逐渐减量停用；消化道溃疡或出血史者慎用，可加用质子泵抑制剂护胃。\n2. 秋水仙碱（尽早联用，预防复发）：0.5mg qd po（体重<70kg）或0.5mg bid po（体重≥70kg），疗程3个月，疗程结束后遵医嘱逐渐减停；肝肾功能不全者减量，服药期间出现腹泻、恶心等不耐受表现立即停药复诊。\n3. 病因治疗：确诊结核性心包炎者，予异烟肼0.3g qd+利福平0.45g qd+吡嗪酰胺1.5g qd+乙胺丁醇0.75g qd，强化期2个月，续贯巩固期至少4个月，全程由专科指导并监测肝功；尿毒症性心包炎加强透析，避免使用抗凝药物。疑为化脓性心包炎者，依据药敏选用敏感抗生素足量足疗程并转诊。\n\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，直至胸痛消失、体温及血沉/CRP恢复正常（一般1~2周）；恢复期避免重体力劳动及剧烈运动，建议症状缓解后2~4周再逐步恢复日常活动。\n2. 饮食宜清淡、易消化、低盐，保证充足饮水，戒烟限酒，避免浓茶、咖啡等刺激性饮品，保持大便通畅。\n3. 避免剧烈咳嗽、用力排便及外伤碰撞，防止心包摩擦加重；避免使用阿司匹林等抗血小板/抗凝药物（除非专科评估需要）。\n4. 警惕心包压塞征象：若出现呼吸困难进行性加重、端坐呼吸、发绀、血压下降、心音遥远或胸痛再次加剧，立即急诊就诊，切勿延误。\n\n【随诊要求】\n1. 服药后1周复诊，复查血常规、血沉、C反应蛋白、心电图及心脏超声，评估心包积液变化及药物疗效与不良反应。\n2. 症状未完全缓解者每2~4周门诊随访一次，直至症状消失、炎症指标正常；症状缓解后复查心脏超声1次确认积液吸收。\n3. 停药须遵医嘱逐渐减量，不可骤停；若减药或停药后胸痛复发，及时复诊调整方案。\n4. 反复发作、积液量持续增多或疑诊缩窄性心包炎者，转心内科专科长期随访，必要时行心包穿刺或心包切除评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":329,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"11470286ad1c973bf90977dd01bd2ce9e697de853fb064971d8340ee320d94c2","pinyin":"xinbaoyan","initials":"xby","setting":"out","caseName":"门诊病历194","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历194",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05f5b3324afa49a806c6","key":"v1-c9ccc21dfe2a3058|templates-05f5b3324afa49a806c6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心脏瓣膜病","category":"门诊病历模板","raw":{"name":"心脏瓣膜病","category":"门诊病历模板","case":{"case_name":"门诊病历195","templates":{"主诉":"活动后气短、乏力6年，伴心悸、胸闷。","现病史":"患者于6年前渐出现活动后气短、乏力、心悸，无夜间阵发性呼吸困难、端坐呼吸及双下肢水肿等心衰表现，无发热、关节痛、皮疹等风湿活动表现，无晕厥、胸痛。既往有无风湿热（关节红肿热痛/舞蹈病）史、感染性心内膜炎史及瓣膜手术史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R20次/分，BP118/76mmHg。神志清楚，二尖瓣面容（+），颧部潮红，提示重度二尖瓣狭窄。心率88次/分，律齐。心尖区可闻及舒张期隆隆样杂音，符合二尖瓣狭窄；主动脉瓣区未闻及收缩期喷射样杂音及舒张期叹气样杂音，即未闻及主动脉瓣狭窄或关闭不全杂音。双肺呼吸音清，未闻及湿啰音。双下肢无水肿。","辅助检查":"【必做】超声心动图（瓣膜形态、狭窄或关闭不全程度（瓣口面积、反流程度）、心腔大小及功能，为诊断金标准）、心电图（左房或左室肥大、房颤）、胸部X线片（心影形态、肺淤血）；【其他】心导管检查（术前评估）、风湿活动指标（ASO、血沉、CRP，疑风湿性者查）。","初步诊断":"1. 心脏瓣膜病（二尖瓣狭窄伴关闭不全，重度）\n（注：轻度无症状者定期复查超声心动图；有症状或重度瓣膜病变：二尖瓣狭窄行经皮球囊扩张术（PBMV）或瓣膜置换，关闭不全行瓣膜成形或置换；主动脉瓣狭窄（重度有症状者预后差，出现症状即应手术（TAVR或SAVR））、关闭不全行手术置换或成形；房颤者抗凝（华法林或新型口服抗凝药）；预防感染性心内膜炎（口腔操作前预防性抗生素，高危者用）、风湿性者预防链球菌感染（长效青霉素）；心衰者规范抗心衰治疗。）","处理方案":"【药物治疗】\n1.感染性心内膜炎预防：高危患者（人工瓣膜置换术后、既往感染性心内膜炎史、复杂发绀型先天性心脏病）行牙科、口腔或呼吸道有创操作前0.5～1小时口服阿莫西林胶囊2g单次；青霉素过敏者改用克林霉素胶囊600mg口服单次。低危患者无需常规预防用药。\n2.心力衰竭治疗：有症状或心功能不全者，呋塞米片20mg qd～bid口服（晨起服用，根据尿量及体重调整）；联合螺内酯片20mg qd；症状明显者加用培哚普利叔丁胺片2mg qd或缬沙坦胶囊80mg qd起始，1～2周后逐渐加量，注意监测血压、肾功能及血钾。\n3.心房颤动抗凝：合并房颤且CHA₂DS₂-VASc评分≥2分、无禁忌者，华法林钠片2.5～3mg qd起始，按INR调整剂量维持2.0～3.0；或利伐沙班片20mg qd（肌酐清除率15～49ml/min者15mg qd）长期口服。机械瓣置换术后需终身华法林抗凝，INR维持2.5～3.5。\n4.感染性心内膜炎治疗：出现不明原因持续发热、新发或加重的心脏杂音、栓塞表现者，应采血培养后立即转住院治疗，按血培养及药敏结果选用敏感抗生素（如青霉素类、头孢曲松、万古霉素等），疗程4～6周，门诊不做经验性抗菌治疗。\n【一般治疗及生活指导】\n1.休息与活动：NYHA心功能Ⅰ～Ⅱ级者可进行散步等轻度有氧活动，每次20～30分钟，避免剧烈运动、重体力劳动及竞技性运动；Ⅲ～Ⅳ级或症状明显者以休息为主，活动以不引起胸闷、气促为宜。\n2.饮食：低盐饮食（每日食盐<5g，心衰者<3g），心衰者限制液体入量每日1500～2000ml，保证优质蛋白摄入，控制体重，戒烟限酒，避免浓茶咖啡。\n3.预防感染：注意保暖，避免感冒及呼吸道感染，每年接种流感疫苗，适时接种肺炎球菌疫苗；保持口腔卫生，定期口腔检查，牙科治疗前患者瓣膜病史并按医嘱预防性用药。\n4.禁忌与特殊人群：避免擅自使用非甾体抗炎药、减肥药及麦角类药物；育龄期女性避孕，拟妊娠者先行心外科及产科联合妊娠风险评估。\n【随诊要求】\n1.定期复查：每6～12个月复查心电图、胸片及超声心动图；中重度或进行性病变、心衰或房颤者每3～6个月复查超声心动图，每1～3个月心内科门诊复诊。\n2.药物监测：服用华法林者定期监测INR（初始每周1次，稳定后每2～4周1次）；长期服利尿剂者定期复查电解质、肾功能、肝功。\n3.紧急就诊指征：出现胸痛、心悸加重、活动后气促明显加重、晕厥、咯血、下肢水肿加重或不明原因发热，应及时就诊；突发肢体无力、言语不清等栓塞表现者急诊就医。\n4.手术时机评估：有症状的重度瓣膜狭窄/关闭不全或伴左心室功能下降者，及时转心外科评估瓣膜成形、置换或TAVR等手术时机，勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":330,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cd01aa5dfb65aeafc0f2d5a95639619d011dd31e8de483450a19094d6f40c194","pinyin":"xinzangbanmobing","initials":"xzbmb","setting":"out","caseName":"门诊病历195","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历195",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-df74eaeab0a4ad039ce5","key":"v1-c9ccc21dfe2a3058|templates-df74eaeab0a4ad039ce5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"先天性心脏病","category":"门诊病历模板","raw":{"name":"先天性心脏病","category":"门诊病历模板","case":{"case_name":"门诊病历196","templates":{"主诉":"活动后心悸、气短反复发作10年，再发3天。","现病史":"患者自幼体检发现心脏杂音，曾诊断房间隔缺损；无反复呼吸道感染、活动耐力差及发绀史，未行手术治疗。近3天活动后心悸气短加重，无发绀加重、晕厥、咯血及蹲踞。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P92次/分，R22次/分，BP105/65mmHg，SpO2 96%。神志清楚，口唇及甲床无发绀、无杵状指（趾），不支持发绀型先心病。胸骨左缘第2肋间可闻及收缩期杂音，肺动脉瓣第二心音固定分裂，未触及震颤。双肺呼吸音清。","辅助检查":"【必做】超声心动图（缺损部位、大小、分流方向及心腔改变、肺动脉压力，为诊断及随访核心）、心电图（房室肥大、电轴改变）、胸部X线片（肺血多少、心影形态）；【影像学】心脏MRI或CT（复杂畸形）；【其他】心导管检查（肺动脉压力精确测定、术前评估）、血常规（红细胞增多，发绀型代偿）。","初步诊断":"1. 先天性心脏病（房间隔缺损，肺动脉高压轻度）\n（注：小缺损无血流动力学意义者可随访观察（部分可自发闭合）；有症状或分流量大者应手术矫治（介入封堵（ASD或VSD或PDA）或外科手术），最佳矫治时机多在学龄前；合并重度肺动脉高压（艾森曼格综合征，出现反向分流）者已失去手术机会，以药物治疗（波生坦或西地那非）加肺移植评估；并发感染性心内膜炎者治疗并预防（牙科操作前抗生素）；心衰者抗心衰治疗。）","处理方案":"【药物治疗】\n1.心力衰竭治疗：首选血管紧张素转换酶抑制剂，如培哚普利叔丁胺片4mg qd口服，或血管紧张素Ⅱ受体拮抗剂厄贝沙坦片150mg qd；联合β受体阻滞剂琥珀酸美托洛尔缓释片47.5mg qd，根据心率及血压耐受情况每2-4周调整剂量；有液体潴留、水肿或肺淤血者加用呋塞米片20mg qd（间断用药，避免长期利尿过度），定期监测血钾、肾功能。\n2.抗栓治疗：合并心房颤动、人工机械瓣膜置换术后或Fontan术后患者，予华法林钠片口服，起始剂量2.5mg qd，维持INR 2.0-3.0（人工机械瓣膜者维持2.5-3.5），定期监测INR并据此调整剂量；不能耐受华法林且无机械瓣者，可予阿司匹林肠溶片100mg qd口服。\n3.感染性心内膜炎预防：需行拔牙、口腔洁治、呼吸道、消化道或泌尿生殖道侵入性操作者，于操作前1小时口服阿莫西林胶囊2.0g单剂；青霉素过敏者改为克林霉素胶囊600mg操作前1小时口服；日常一般诊疗操作不主张常规抗生素预防。\n4.肺动脉高压靶向治疗（合并肺动脉高压者）：予西地那非片20mg tid口服，或波生坦片62.5mg bid起始（第4周后可加量至125mg bid），需经专科评估后启用，用药期间随访肝功能及心功能。\n\n【一般治疗及生活指导】\n1.休息与活动：按心功能分级决定活动量，NYHAⅠ-Ⅱ级可进行快走、游泳等中等强度有氧运动，每周3-5次、每次20-30分钟，避免竞技性运动及举重、憋气等等长运动；NYHAⅢ-Ⅳ级或合并重度肺动脉高压者以休息为主，避免任何剧烈活动。\n2.饮食：低盐低脂饮食，每日食盐摄入<5g，合并心衰或水肿者<2-3g，适当控制液体入量；戒烟限酒，避免浓茶、咖啡等兴奋性饮品，保证优质蛋白及富含维生素饮食。\n3.预防感染：按时接种流感疫苗和肺炎球菌疫苗，注意口腔卫生，勤刷牙、定期口腔检查，避免感冒及呼吸道感染，出现发热、咳嗽及时就医。\n4.禁忌：禁止吸烟及二手烟暴露；避免进入高原、潜水及剧烈竞技运动；紫绀型或合并重度肺动脉高压患者避免妊娠，育龄期女性应严格避孕并在专科评估后再计划妊娠；服用华法林者避免自行加用布洛芬、阿司匹林等非甾体抗炎药及含活血成分的中成药。\n\n【随诊要求】\n1.每3-6个月于心内科（成人先心病专科）门诊复查，包括心电图、经胸心脏超声及心功能（NYHA分级、BNP/NT-proBNP）评估，病情稳定者可每6-12个月复查。\n2.服用华法林者起始每周监测INR，稳定后每2-4周复查，据INR调整剂量并记录。\n3.每年复查血常规、肝肾功能、电解质、铁代谢及血氧饱和度（紫绀型患者应监测血红蛋白及红细胞压积，警惕红细胞增多症），必要时复查心脏磁共振或右心导管。\n4.出现心悸、胸闷、胸痛、紫绀或发绀加重、咯血、晕厥、发热（警惕感染性心内膜炎）或新发水肿时，应立即就诊，勿自行调整药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":331,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"69d1a17b73e6dc8acf2e102d842cc63b47748ceb5df08672083c045e062de89d","pinyin":"xiantianxingxinzangbing","initials":"xtxxzb","setting":"out","caseName":"门诊病历196","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历196",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6fe4246eba1099e67de3","key":"v1-c9ccc21dfe2a3058|templates-6fe4246eba1099e67de3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"主动脉夹层","category":"门诊病历模板","raw":{"name":"主动脉夹层","category":"门诊病历模板","case":{"case_name":"门诊病历197","templates":{"主诉":"突发胸背部撕裂样剧痛6小时，伴血压升高。","现病史":"患者于6小时前情绪激动后突发胸部及背部撕裂样剧烈疼痛，由前胸向后背、腰部延伸，疼痛剧烈难忍、含服硝酸甘油无效，伴大汗、烦躁、恶心，无晕厥、肢体麻木无力、腹痛及血尿等分支血管受累表现，血压升高达170/98mmHg。既往有无高血压史（控制情况）、马凡综合征、主动脉疾病及家族史：无。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟30年，20支/日；偶有饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P102次/分（可增快），R22次/分，左上肢BP170/98mmHg，右上肢BP146/86mmHg（双上肢血压差>20mmHg提示累及锁骨下动脉），双下肢BP150/90mmHg。神志清楚。双侧桡动脉搏动对称，颈静脉无怒张，心肺听诊未闻及主动脉瓣关闭不全杂音，腹部无压痛、未触及搏动性包块，双下肢皮温正常、动脉搏动可及。","辅助检查":"【必做】主动脉CTA（胸腹主动脉全程，确诊金标准：可见内膜片及真假腔）、心电图（排除心肌梗死）、心肌肌钙蛋白、D-二聚体（可升高）、血常规、肝肾功能；【影像学】经食管超声心动图（TEE，病情不稳定者床旁快速评估）；【其他】胸片（纵隔增宽）。","初步诊断":"1. 主动脉夹层（Stanford A型，DeBakeyⅠ型）\n（注：主动脉夹层是极高危心血管急症，死亡率极高，需立即急诊抢救：绝对卧床、镇静止痛（吗啡）、控制心率（β受体阻滞剂：艾司洛尔静滴，目标心率60次/分以下）及血压（硝普钠或尼卡地平，目标收缩压100~120mmHg）、建立静脉通路；Stanford A型（累及升主动脉）需急诊外科手术（升主动脉置换）；B型（仅降主动脉）先药物保守，有并发症（破裂先兆、脏器或肢体缺血、难控疼痛或血压）者行腔内修复术（TEVAR）；转心血管外科或介入中心。）","处理方案":"【药物治疗】\n（主动脉夹层属心血管致命性急症，门诊疑似或确诊后应立即转急诊/心内科住院，药物以\"镇痛＋控制心率＋控制血压\"为核心，成人常规剂量如下）\n1. 镇痛：吗啡注射液 5～10mg 皮下或静脉注射，胸背剧痛时立即给药，必要时4～6小时可重复1次，用药期间监测呼吸频率及意识（警惕呼吸抑制）。\n2. 控制心率（首选）：琥珀酸美托洛尔缓释片 47.5mg 口服 qd，或酒石酸美托洛尔片 25～50mg 口服 bid，将心率控制在55～65次/分；病情急重者予艾司洛尔静脉负荷量0.5mg/kg后按50～200μg/(kg·min)持续泵入。\n3. 控制血压：在上述β受体阻滞剂使心率达标后加用硝普钠静脉泵入，起始0.5μg/(kg·min)，根据血压调整至2～5μg/(kg·min)，目标收缩压100～120mmHg；β受体阻滞剂禁忌（哮喘、COPD、严重心动过缓）者改用非二氢吡啶类钙通道阻滞剂，地尔硫卓片 30～60mg 口服 tid，或地尔硫卓静脉泵入5～15mg/h，疗程以血压心率平稳达标、病情稳定为准，全程心电血压监护。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息，避免一切增加主动脉壁剪切力的动作（用力排便、剧烈咳嗽、屏气用力、提重物、剧烈运动），保持情绪平稳，避免紧张、激动及劳累；密切观察有无新发胸背痛、声音嘶哑、吞咽困难、腹痛、肢体麻木或脉搏减弱等夹层扩展表现。\n2. 饮食：低盐低脂、易消化软食，少量多餐，避免过饱及刺激性饮食；保持大便通畅，便秘者予乳果糖口服溶液 15～30ml qd 通便，切忌用力排便；每日定时测量双侧上肢血压并记录。\n\n【随诊要求】\n主动脉夹层进展凶险，疑似或确诊患者一律收入院治疗（Stanford A型尽早急诊外科手术，B型住院强化内科药物治疗），严禁门诊留观拖延；出院后严格遵医嘱规律服药，每日自测血压、心率，维持血压100～120/60～80mmHg、心率55～65次/分；出院后1个月、3个月于心内科门诊复查，此后每3～6个月复查主动脉CTA或经食管超声，评估假腔血流及主动脉管径变化；一旦出现突发胸背痛、血压剧烈波动、晕厥或下肢缺血等表现，立即急诊就医，不得等待预约。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":332,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d91d932c027f4f326ebac823d4e4802dce7268026f58a49c56df8ed66f5eca75","pinyin":"zhudongmaijiaceng","initials":"zdmjc","setting":"out","caseName":"门诊病历197","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历197",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d488e77748089e8ccb28","key":"v1-c9ccc21dfe2a3058|templates-d488e77748089e8ccb28","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"深静脉血栓","category":"门诊病历模板","raw":{"name":"深静脉血栓","category":"门诊病历模板","case":{"case_name":"门诊病历198","templates":{"主诉":"左下肢肿胀、疼痛、皮温升高3天。","现病史":"患者于3天前出现左下肢进行性肿胀、胀痛，皮肤绷紧发亮，皮温升高，活动后加重，平卧抬高患肢可稍减轻，无发热。发病前有无长期卧床、制动（术后/骨折）、长途旅行、妊娠/产后、口服避孕药、恶性肿瘤及既往血栓史等危险因素：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P84次/分，R18次/分，BP124/78mmHg。神志清楚，查体合作。左下肢明显肿胀（较对侧周径：大腿3cm、小腿2cm），皮肤张力增高、皮温升高、颜色发红，浅静脉显露，Homans征（+），足背屈曲牵拉小腿后侧疼痛，股三角及小腿压痛（+），足背动脉搏动正常，末梢感觉运动正常。","辅助检查":"【必做】下肢静脉彩色多普勒超声（加压超声，可明确血栓部位及范围，无创首选）、D-二聚体（升高，正常可排除，敏感性高）；【其他】血常规、凝血功能、肿瘤筛查（无明显诱因血栓者）、易栓症筛查（年轻或反复血栓者：蛋白C或蛋白S、抗磷脂抗体等）。","初步诊断":"1. 下肢深静脉血栓形成（左下肢，近端）\n（注：抗凝为基本治疗：低分子肝素（依诺肝素1mg/kg q12h皮下，按体重）桥接华法林或直接口服抗凝药（利伐沙班15mg bid×3周后20mg qd，或达比加群）；总疗程：手术或一过性因素3个月、无明确诱因或复发者延至6~12个月以上；急性期抬高患肢、抗凝后尽早下地活动（防血栓蔓延及肺栓塞）；巨大髂股静脉血栓（股青肿）或抗凝禁忌者考虑导管溶栓、取栓或下腔静脉滤器；警惕肺栓塞（突发胸痛、咯血、呼吸困难，需立即急诊）。）","处理方案":"【药物治疗】\n1. 直接口服抗凝药（首选）：利伐沙班片15mg bid 口服，连续21天后改为20mg qd 口服，总疗程3～6个月；或达比加群酯胶囊150mg bid 口服（须先经肠外抗凝≥5天），疗程同前。\n2. 维生素K拮抗剂（不能耐受或无法获取NOACs时）：华法林钠片起始2.5～5mg qd 口服，与低分子肝素重叠至少5天，据INR调整剂量，维持INR 2.0～3.0，疗程3～6个月。\n3. 静脉活性药物（辅助缓解患肢肿胀、沉重感）：地奥司明片0.45g bid 口服，餐时服用，疗程4～8周。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息1～2周，患肢抬高20～30cm（高于心脏水平），严禁按摩、挤压、热敷患肢，以防血栓脱落致肺栓塞。\n2. 症状缓解后白天穿戴II级压力梯度医用弹力袜，夜间睡眠时可脱下，坚持使用至少3～6个月以减轻肿胀、预防血栓后综合征。\n3. 抗凝期间避免久站久坐、跷二郎腿及剧烈运动，多饮水促进循环，戒烟限酒，注意低盐低脂饮食。\n4. 注意出血防范：勤观察皮肤黏膜有无瘀斑、牙龈出血、血尿、黑便，避免磕碰及有创操作，勿擅自联用阿司匹林等抗血小板药或活血化瘀中药。\n\n【随诊要求】\n1. 用药3周后复诊，评估症状改善及出血风险，调整抗凝方案；服用华法林者每周复查凝血功能（INR），稳定后可延长间隔，维持INR 2.0～3.0。\n2. 抗凝治疗满3个月复查下肢静脉彩色多普勒超声，评估血栓再通及静脉瓣膜功能，决定是否延长抗凝至6个月或更久。\n3. 治疗期间如出现胸痛、呼吸困难、咯血、晕厥等，立即急诊就医排查肺栓塞；若出现活动性出血，即刻停药并急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":333,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"240ec4b0fa95811e82b37fa86f659ccd2edc9721cf806fa87184eeb6dbaec990","pinyin":"shenjingmaixueshuan","initials":"sjmxs","setting":"out","caseName":"门诊病历198","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历198",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0c9bdb1f1f56eb41dd72","key":"v1-c9ccc21dfe2a3058|templates-0c9bdb1f1f56eb41dd72","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"雷诺病","category":"门诊病历模板","raw":{"name":"雷诺病","category":"门诊病历模板","case":{"case_name":"门诊病历199","templates":{"主诉":"双手遇冷后苍白、青紫伴麻木2年，加重2周","现病史":"患者于2年前开始于寒冷刺激或情绪激动后出现双手（手指）皮肤颜色三相变化（先苍白、后青紫、再潮红），伴手指麻木、冰冷、刺痛感，保暖后缓解，冬季及晨起多发，无指端溃疡、坏死（如有需警惕继发性），无关节痛、无皮疹、无吞咽困难。有无结缔组织病（系统性硬化症、SLE）、职业震动（电钻等）、药物（β受体阻滞剂、麦角类）等因素：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP112/70mmHg。神志清楚，查体合作。双手皮肤温度低，手指颜色正常，无指端溃疡、凹陷性瘢痕，甲周毛细血管无扩张，桡动脉搏动正常，Allen试验正常。面部皮肤无紧绷、无硬化。","辅助检查":"【必做】一般临床诊断；【其他】抗核抗体谱（排除结缔组织病，为雷诺现象继发性筛查）、冷激发试验（复温时间延长）、甲襞微循环检查、血沉及CRP；继发性者查原发病相关指标。","初步诊断":"1. 雷诺病（原发性）\n（注：原发性（雷诺病）治疗：保暖（重中之重，戴手套、避免寒冷及情绪激动）、戒烟（尼古丁致血管痉挛）、避免β受体阻滞剂；症状明显或发作频繁：钙通道阻滞剂（硝苯地平缓释片30mg qd）为一线扩血管药，疗效不佳可加用前列环素类似物（伊洛前列素）或磷酸二酯酶5抑制剂（西地那非）；继发性（尤其伴指端溃疡、结缔组织病表现）需治疗原发病并转风湿免疫科；出现指端溃疡或坏死者及时专科处理。）","处理方案":"【药物治疗】\n1. 钙通道阻滞剂（首选）：硝苯地平缓释片30mg，口服，每日1次（或10mg，每日3次）；疗程4～12周，症状缓解后维持小剂量。注意监测血压、心率，警惕头晕、面部潮红、踝部水肿等不良反应。\n2. 改善微循环：己酮可可碱缓释片0.4g，口服，每日2～3次，疗程4～8周；适用于发作频繁或伴指端麻木者。\n3. α受体阻滞剂（备选/联合）：盐酸哌唑嗪片0.5～1mg，口服，每日2～3次，首次服药睡前或卧位服用以防体位性低血压；用于钙拮抗剂疗效欠佳者。\n4. 重症伴指端溃疡者：前列地尔注射液10μg加入0.9%氯化钠注射液100ml静脉滴注，每日1次，连用10～14天；或西洛他唑片100mg，口服，每日2次，疗程2～4周。\n\n【一般治疗及生活指导】\n1. 保暖为最重要措施：冬季外出戴保暖手套、穿厚袜，避免冷水洗手、游泳及冷环境作业；局部冷刺激发作时立即将手置于37～40℃温水中复温。\n2. 严格戒烟，避免饮咖啡、浓茶等含咖啡因饮品，避免情绪紧张激动及精神刺激，以减少血管痉挛发作。\n3. 避免手指外伤和振动性操作（如长期使用电钻、振动工具），避免提拎重物和紧握冰冷物体；保持规律作息，适度有氧运动促进末梢循环。\n4. 慎用缩血管药物及拟交感药物（如麦角制剂、β受体阻滞剂、拟麻黄碱类感冒药），避免在凉风、空调直吹环境下久留。\n\n【随诊要求】\n1. 用药后2～4周复诊，评估发作频率、持续时间及程度改善情况，复查血压、心率，监测药物不良反应。\n2. 若症状无缓解或加重、出现指端皮肤苍白持续不退、发绀、疼痛或溃疡坏疽，应立即复诊或急诊就诊，必要时完善抗核抗体谱、冷球蛋白等检查以排查继发性雷诺现象。\n3. 病情稳定者每3～6个月门诊随访1次，长期用药者定期复查肝肾功能、血糖及血脂。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":334,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c2d2e7de49b675447b04a59ba0ace0d5e5f9976430f3f7c5cb7ad10506801a59","pinyin":"leinuobing","initials":"lnb","setting":"out","caseName":"门诊病历199","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历199",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-42b9f318033b4279bf67","key":"v1-c9ccc21dfe2a3058|templates-42b9f318033b4279bf67","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃食管反流","category":"门诊病历模板","raw":{"name":"胃食管反流","category":"门诊病历模板","case":{"case_name":"门诊病历200","templates":{"主诉":"反酸、烧心反复发作12月，加重1周。","现病史":"患者于12月前开始反复出现反酸、烧心（胸骨后烧灼感），多于餐后、平卧、弯腰或夜间发作，伴嗳气、上腹胀，无胸痛、吞咽困难、吞咽痛、慢性咳嗽、声音嘶哑及哮喘样发作等食管外症状，自服抑酸药可缓解。有无食管裂孔疝、肥胖、吸烟饮酒及长期服用NSAIDs史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP120/76mmHg，BMI23.5kg/m²。神志清楚，查体合作。上腹部轻压痛（+），无肌紧张反跳痛，心肺听诊未见明显异常。","辅助检查":"【必做】胃镜（食管炎分级（洛杉矶分级）、Barrett食管、排除食管肿瘤，有报警症状（吞咽困难、消瘦、黑便、贫血）者必查）；【其他】24小时食管pH-阻抗监测（诊断金标准，PPI试验阴性或不典型症状者查）、食管测压（抗反流手术前评估）。","初步诊断":"1. 胃食管反流病（非糜烂性）\n（注：生活方式干预（减重、抬高床头15~20cm、睡前3小时不进食、避免高脂辛辣及烟酒咖啡）；药物治疗：质子泵抑制剂（奥美拉唑20mg bid或埃索美拉唑20mg bid，疗程4~8周，维持按需或长期）、促动力药（莫沙必利5mg tid）辅助；疗效不佳或难治性反流：复查胃镜、双倍剂量PPI；长期并发症（食管狭窄、Barrett食管）监测随访；巨大食管裂孔疝或药物难控者抗反流手术（胃底折叠术）评估。）","处理方案":"【药物治疗】\n1. 质子泵抑制剂（PPI，首选一线用药）：奥美拉唑肠溶胶囊 20mg qd，早餐前30分钟空腹口服，疗程4-8周；症状严重或内镜下反流性食管炎LA-B级及以上者，可加倍至20mg bid，疗程8周。\n2. 促胃肠动力药（伴胃排空延迟、反流频繁者联用）：枸橼酸莫沙必利分散片 5mg tid，餐前15-30分钟口服，疗程4周。\n3. 黏膜保护剂/抗酸剂（症状发作时或餐后烧心明显者加用）：铝碳酸镁咀嚼片 0.5g tid，餐后1小时及睡前嚼服，症状发作时可临时加服0.5g，餐后症状控制后即可停用。\n\n【一般治疗及生活指导】\n1. 饮食：少食多餐、七八分饱，避免高脂、油炸、甜食、咖啡、浓茶、巧克力、辛辣刺激食物及碳酸饮料；睡前3小时不再进食。\n2. 体位与活动：餐后保持坐位或散步20-30分钟，避免餐后立即平卧、弯腰持重；夜间卧床时将床头抬高15-20cm（垫高上半身），采取左侧卧位，以减轻夜间反流。\n3. 体重与禁忌：超重/肥胖者应减重（目标BMI<24kg/m²）；戒烟、戒酒，避免穿过紧腰带及紧身衣物，避免久坐。\n4. 用药禁忌：避免自行长期服用降低食管下括约肌压力的药物（如硝酸酯类、钙通道阻滞剂、茶碱、地西泮等），确需使用者请心内科等专科医师评估调整。\n\n【随诊要求】\n1. 用药2-4周复诊，评估烧心、反流等核心症状缓解程度，疗效不佳者调整治疗方案。\n2. 完成4-8周足疗程后复查胃镜，评估食管炎愈合及Barrett食管有无进展；难治性（PPI双倍剂量治疗8周症状无缓解）者建议行24小时食管pH-阻抗监测及高分辨率食管测压明确诊断。\n3. 治疗期间新出现吞咽困难、吞咽痛、进行性体重下降、呕血或黑便、贫血等报警症状者，须立即复诊。\n4. 需长期维持治疗者每3-6个月复诊，定期复查血常规、肝肾功能及血清铁、维生素B12、血镁，监测PPI长期患者相关不良反应。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":335,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e77057f5df0a35b1cce28480450c4403757c5df963e89dfbe3b0f84f11967df2","pinyin":"weishiguanfanliu","initials":"wsgfl","setting":"out","caseName":"门诊病历200","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历200",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-43a6f86fc7e3becc8ebc","key":"v1-c9ccc21dfe2a3058|templates-43a6f86fc7e3becc8ebc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"溃疡性结肠炎","category":"门诊病历模板","raw":{"name":"溃疡性结肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历201","templates":{"主诉":"反复黏液脓血便伴腹泻、腹痛8月，加重1周。","现病史":"患者于8月前开始反复腹泻（每日5次，黏液脓血便，便血为主），伴左下腹阵发性疼痛（便前加重、便后缓解）、里急后重，1周来加重，便次增多至每日9次，伴发热（体温最高38.2℃）、乏力、食欲减退、体重下降约4kg。有无关节痛、口腔溃疡、皮疹及眼部症状（肠外表现）及家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP106/66mmHg。神志清楚，慢性病容，贫血貌（+）。腹平软，左下腹轻压痛，无反跳痛肌紧张，肠鸣音活跃，肝脾肋下未触及。直肠指诊指套染血。双下肢无水肿。","辅助检查":"【必做】大便常规+隐血及培养（排除感染性肠炎，如细菌、阿米巴）、血常规（贫血、白细胞）、CRP、血沉、肝肾功能、白蛋白、电解质；【影像学】结肠镜+活检（连续弥漫性黏膜充血水肿、糜烂溃疡、隐窝脓肿，为诊断金标准，注意重症暂缓以防穿孔）、腹部CT或钡灌肠（重症或结肠镜禁忌时）；【其他】粪钙卫蛋白（炎症活动评估）、抗中性粒细胞胞浆抗体（p-ANCA，辅助诊断）。","初步诊断":"1. 溃疡性结肠炎（慢性复发型，中度）\n（注：轻中度：5-氨基水杨酸制剂（美沙拉嗪1g tid口服+美沙拉嗪栓剂或灌肠剂局部）+美沙拉嗪维持缓解（≥2年）；重度或激素依赖：糖皮质激素（泼尼松40~60mg/d短期）、免疫抑制剂（硫唑嘌呤）、生物制剂（抗TNF：英夫利昔单抗，用于中重度诱导缓解）；支持（补液、营养、纠正贫血）；出现中毒性巨结肠、穿孔、大出血为外科急症需急诊手术；定期结肠镜监测癌变（病程>8~10年）；转消化内科专科管理。）","处理方案":"【药物治疗】\n1.氨基水杨酸制剂（轻中度活动期首选）：美沙拉嗪肠溶片1.0g 口服 qid（或美沙拉嗪缓释颗粒2g bid），诱导缓解疗程4-8周；症状缓解后改维持剂量1.0g bid，长期维持治疗。\n2.糖皮质激素（中重度活动期或5-ASA无效者）：泼尼松片40mg 口服 qd（按0.75-1mg/kg/d），症状缓解后每1-2周减量5mg，减至20mg/d后每2周减2.5mg，总疗程8-12周；不用于维持治疗。\n3.免疫抑制剂（激素依赖或激素无效者）：硫唑嘌呤片50-100mg 口服 qd（1.5-2.5mg/kg/d），用药前及用药后每2-4周监测血常规、肝功能，必要时行TPMT基因型检测。\n4.局部治疗（直肠型或左半结肠型）：美沙拉嗪灌肠液4g 保留灌肠 qn，或美沙拉嗪栓剂1g 纳肛 qn，疗程4-8周；可联合口服美沙拉嗪增强疗效。\n\n【一般治疗及生活指导】\n1.活动期注意休息、保证睡眠，避免劳累和精神紧张、焦虑；病情缓解后可适度活动，避免剧烈运动和久坐。\n2.饮食：活动期予少渣流质或半流质饮食，忌生冷、辛辣、油腻及高纤维食物（粗粮、韭菜、芹菜、豆类），避免乳制品；缓解期均衡营养，少量多餐，补充优质蛋白及叶酸、钙剂。\n3.严格戒烟戒酒；避免服用非甾体抗炎药（NSAIDs）、抗生素滥用及其他可能诱发或加重病情的药物。\n4.保持肛周清洁干燥，注意观察大便次数、性状、便血及腹痛情况，出现高热、剧烈腹痛、腹胀或便血加重时立即就医。\n\n【随诊要求】\n1.诱导缓解治疗期间每2-4周门诊复诊，评估症状缓解情况并监测药物不良反应：美沙拉嗪定期复查肾功能，糖皮质激素监测血糖、血压及电解质，硫唑嘌呤定期复查血常规、肝功能。\n2.症状缓解后每1-3个月复诊1次，维持治疗至少2年；定期复查血常规、肝肾功能、C反应蛋白、粪钙卫蛋白等评估病情活动度。\n3.病程≥8年且病变广泛（累及全结肠或左半结肠）者，建议每1-2年行结肠镜检查并多部位活检，筛查异型增生及结直肠癌；如治疗效果不佳、反复发作或怀疑癌变，及时复诊评估调整方案或转诊上级医院。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":336,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c7fc5e002eed341622e9595d632e2c1169067398198853d68406640ed04b53e8","pinyin":"kuiyangxingjiechangyan","initials":"kyxjcy","setting":"out","caseName":"门诊病历201","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历201",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-55205480f83f5bd03e44","key":"v1-c9ccc21dfe2a3058|templates-55205480f83f5bd03e44","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"克罗恩病","category":"门诊病历模板","raw":{"name":"克罗恩病","category":"门诊病历模板","case":{"case_name":"门诊病历202","templates":{"主诉":"反复腹痛、腹泻伴体重下降6月，加重2周。","现病史":"患者于6月前开始反复右下腹及脐周阵发性疼痛，餐后加重，伴腹泻（每日4次，糊状便，无黏液血便）、乏力、发热（低热为主，体温最高37.8℃），体重下降约5kg。无肛周病变（肛瘘、肛周脓肿），无肠外表现（口腔溃疡、关节痛、结节性红斑、眼病）。有无吸烟史及家族史：无。今日来我院门诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P88次/分，R20次/分，BP112/70mmHg。神志清楚，慢性病容，消瘦，贫血貌（+）。腹部右下腹压痛（+），可及腹块（炎性包块），无反跳痛肌紧张，肠鸣音正常。肛周检查未见肛瘘、肛裂及脓肿。","辅助检查":"【必做】血常规（贫血、白细胞）、CRP、血沉、白蛋白（降低，提示营养状态）、大便常规+隐血及培养、粪钙卫蛋白；【影像学】结肠镜+活检（纵行溃疡、鹅卵石样改变、节段性分布、非干酪样肉芽肿，为诊断依据；疑小肠受累行胶囊内镜或小肠镜或MRE（小肠磁共振造影））；【其他】腹部CT小肠造影（评估并发症：狭窄、瘘管、脓肿）。","初步诊断":"1. 克罗恩病（炎症型，中度）\n（注：活动期诱导缓解：美沙拉嗪疗效有限，轻中度可布地奈德（回盲部）或泼尼松（中重度短期），免疫调节剂（硫唑嘌呤或甲氨蝶呤）维持，生物制剂（英夫利昔单抗或阿达木单抗，用于中重度、瘘管型）；营养支持（肠内营养，儿童首选或术前优化）；戒烟至关重要；并发症（肠狭窄、肠瘘、腹腔脓肿、肠梗阻、穿孔、大出血）需外科手术；硫唑嘌呤用药前查TPMT；定期内镜或影像随访及癌变监测，转消化内科IBD专科管理。）","处理方案":"【药物治疗】\n1.氨基水杨酸类（轻中度回结肠型）：美沙拉嗪缓释颗粒1.0g po tid，症状缓解后改1.0g po bid维持，疗程6-12个月；长期服用者定期复查肝肾功能。\n2.糖皮质激素（中重度活动期或5-ASA疗效不佳者）：泼尼松片30-40mg（0.75-1mg/kg）晨起顿服，症状明显缓解（约2-4周）后每周减量5mg，总疗程8-12周；治疗期间同时补充钙剂及维生素D，监测血糖、血压。\n3.免疫抑制剂（激素依赖或维持缓解）：硫唑嘌呤片50mg po qd起始，2-4周后根据血常规及耐受情况增至1.5-2.5mg/kg/d，维持1-2年；用药前及用药期间定期复查血常规、肝肾功能。\n4.生物制剂（中重度活动期、瘘管型或激素抵抗/依赖者）：英夫利西单抗5mg/kg静脉滴注，第0、2、6周诱导缓解，之后每8周1次维持治疗；用药前常规筛查结核、乙肝、EB病毒，滴注期间监测过敏反应。\n【一般治疗及生活指导】\n1.活动期注意休息、减少活动，病情缓解后可适当运动（散步、太极拳等），避免剧烈运动及劳累。\n2.饮食：活动期予低渣、高蛋白、易消化饮食，少量多餐；避免辛辣刺激、油炸油腻、粗纤维食物（粗粮、韭菜、芹菜等）；合并乳糖不耐受者避免乳制品；缓解期均衡营养，适当补充叶酸、维生素B12、铁剂及钙剂。\n3.戒烟戒酒：吸烟可加重病情、增加复发及手术风险，必须戒烟。\n4.注意肛周清洁卫生，每日温水坐浴，观察有无肛患者肿、疼痛、流脓；保持情绪平稳，规律作息，避免精神紧张。\n【随诊要求】\n1.使用糖皮质激素者每2-4周复诊，评估疗效、减量情况及不良反应（血糖、血压、骨质疏松）；使用免疫抑制剂者用药初期每2周复查血常规、肝肾功能，稳定后每1-3个月复查1次；生物制剂治疗者每8周按疗程复诊输注并评估疗效。\n2.每3-6个月复诊评估疾病活动度（CDAI评分、粪钙卫蛋白、CRP/ESR），缓解期每6-12个月复查结肠镜评估黏膜愈合情况；病程超过8年者每年行结肠镜检查筛查结直肠癌变。\n3.如出现腹痛加重、发热、血便、频繁呕吐、腹部膨隆、停止排气排便等提示肠梗阻、穿孔、大出血、中毒性巨结肠等并发症表现，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":337,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e059171992481bf451f6fb1014da12dc41178ff04565b9a0d2243f2db231c5aa","pinyin":"keluoenbing","initials":"kleb","setting":"out","caseName":"门诊病历202","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历202",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c487698cce6ccaa2374f","key":"v1-c9ccc21dfe2a3058|templates-c487698cce6ccaa2374f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝硬化","category":"门诊病历模板","raw":{"name":"肝硬化","category":"门诊病历模板","case":{"case_name":"门诊病历203","templates":{"主诉":"反酸、嗳气1周。","现病史":"患者1周前饮食不当后出现肝硬化相关症状，伴反酸嗳气，进食后加重，空腹缓解，无呕血黑便，无恶心呕吐。自服「奥美拉唑」症状稍缓解，今日来诊。发病以来饮食减少，睡眠可，大小便正常。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒15年，约3两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，上腹部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反酸、嗳气1周为主诉，进食后加重、空腹缓解，初步诊断肝硬化，既往体健，需重点评估门静脉高压及其并发症。查血常规以了解有无脾功能亢进所致白细胞、血小板减少及贫血；肝硬化患者食管胃底静脉曲张破裂出血风险高，查便常规+潜血以排除消化道隐性出血；查肝功能（含转氨酶、胆红素、白蛋白）以评估肝细胞损伤程度及肝脏合成功能；患者反酸嗳气、进食后加重，查淀粉酶、脂肪酶以排除胰腺病变所致的上腹不适；查腹部超声以了解肝脏形态、门静脉内径、脾大及腹水情况，属无创首选；患者有反酸嗳气等上消化道症状且为肝硬化，需行胃镜了解食管胃底静脉曲张程度并排除消化性溃疡，肠道症状明显时行肠镜排除结直肠病变；腹部CT（必要时增强）以明确有无肝内占位性病变、排除肝细胞癌及了解侧支循环情况；查幽门螺杆菌检测（C13/C14呼气试验）以明确有无幽门螺杆菌感染、指导抑酸及根除方案；查凝血功能以评估肝脏合成凝血因子能力，为有创检查及用药安全提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 肝硬化\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 病因治疗：乙肝肝硬化者予恩替卡韦片0.5mg qd长期口服抗病毒（或富马酸丙酚替诺福韦片25mg qd）；酒精性肝硬化须绝对戒酒。丙肝肝硬化者可评估DAA抗病毒治疗。\n2. 保肝抗炎：多烯磷脂酰胆碱胶囊456mg tid口服×4～8周（或水飞蓟宾胶囊70mg tid口服）；转氨酶明显升高者短期联用异甘草酸镁注射液，恢复后改口服维持。\n3. 抗肝纤维化：扶正化瘀胶囊1.5g tid口服×6个月（或复方鳖甲软肝片2.0g tid口服×6个月），每3个月复查评估。\n4. 并发症防治：腹水者螺内酯片20mg qd口服起始，必要时联合呋塞米片20mg qd口服，按体重及尿量调整剂量（螺内酯:呋塞米约100:40mg）；预防食管胃底静脉曲张出血者予普萘洛尔片10mg tid口服起始，根据静息心率（目标55～60次/分）逐渐加量，最大剂量160mg/d，注意监测血压心率；有肝性脑病倾向者予乳果糖口服液15ml bid口服，保持每日2～3次软便。\n【一般治疗及生活指导】\n1. 休息：肝功能失代偿期以卧床休息为主，减轻肝脏负担；代偿期避免过劳、熬夜及重体力劳动，保证充足睡眠。\n2. 饮食：高热量、高维生素、适量优质蛋白（1.0～1.2g/kg/d）；低盐饮食（每日钠摄入<2g，腹水明显者<1.5g）；肝性脑病倾向或肝功能严重受损者限制蛋白质并进低脂软食；禁食粗糙、坚硬、辛辣刺激性食物（如坚果、油炸物、带骨刺鱼肉类），以防食管静脉曲张破裂出血。\n3. 活动与禁忌：可进行散步等温和活动，避免剧烈运动、提重物、用力排便等增加腹压的动作；绝对禁酒；避免使用肝毒性药物（对乙酰氨基酚、部分中草药及偏方）及非甾体抗炎药，用药前咨询医师。\n【随诊要求】\n1. 每1～3个月门诊复查肝功能、凝血功能、血常规、甲胎蛋白；每6个月行腹部超声+甲胎蛋白筛查肝癌。\n2. 每年行胃镜检查评估食管胃底静脉曲张程度，已行套扎或硬化治疗者每6～12个月复查；脾大脾功能亢进者监测血常规。\n3. 出现呕血、黑便、意识行为异常、腹胀迅速加重、发热、黄疸加深、少尿等表现时立即就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":338,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0ab550bdecd153d322d9d1848fd410d1d24c1c65ff2876d4e9a1ad4ea2f51cbe","pinyin":"ganyinghua","initials":"gyh","setting":"out","caseName":"门诊病历203","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历203",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-065ebba3108a218ee38e","key":"v1-c9ccc21dfe2a3058|templates-065ebba3108a218ee38e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂肪肝","category":"门诊病历模板","raw":{"name":"脂肪肝","category":"门诊病历模板","case":{"case_name":"门诊病历204","templates":{"主诉":"反酸、嗳气1周。","现病史":"患者1周前无明显诱因出现脂肪肝相关症状，伴反酸嗳气，进食后加重，空腹缓解，无呕血黑便，无恶心呕吐。自服「奥美拉唑」症状稍缓解，今日来诊。发病以来饮食减少，睡眠可，大小便正常。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒15年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，上腹部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反酸、嗳气1周为主诉，进食后加重、空腹缓解，初步诊断脂肪肝，既往体健，需评估脂肪性肝病程度及其代谢相关危险因素。查血常规以了解有无贫血、感染及血小板减少等肝脏受累征象；患者主诉反酸嗳气，长期胃部症状需警惕消化道出血，查便常规+潜血以排除消化道出血；查肝功能（含转氨酶、胆红素、白蛋白）以明确有无脂肪性肝炎所致的转氨酶升高及肝功能受损程度；进食后上腹不适加重，查淀粉酶、脂肪酶以排除胰腺疾病；查腹部超声以了解肝脏回声改变、脂肪浸润程度及有无胆囊结石，是脂肪肝诊断与分级的首选影像检查；患者有反酸嗳气，需查幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染、指导治疗；中老年脂肪肝患者需警惕恶性病变，行腹部CT以明确肝脏形态及排除肝内占位性病变，胃镜、肠镜必要时进行以排除消化道器质性病变；查凝血功能以评估肝脏合成功能，为后续诊疗安全提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 脂肪肝\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 保肝抗炎类：多烯磷脂酰胆碱胶囊（易善复）456mg po tid，疗程4～8周，转氨酶未恢复正常者可延长至12周。\n2. 抗氧化类：水飞蓟宾胶囊（水林佳）105mg po tid，疗程8～12周，可配合维生素E软胶囊100mg po bid（非酒精性脂肪性肝炎、无糖尿病及出血倾向者），疗程6～12个月。\n3. 代谢调节类：合并2型糖尿病或胰岛素抵抗者加用二甲双胍片0.5g po bid；合并血脂异常者加用阿托伐他汀钙片20mg po qn，疗程据血脂及肝功能复查结果调整，用药期间监测肝酶及肌酶。\n【一般治疗及生活指导】\n1. 饮食：低脂、低糖、高蛋白饮食，控制每日总热量，减少精制碳水及含糖饮料摄入，增加蔬菜、全谷物及不饱和脂肪酸（橄榄油、深海鱼）摄入，戒烟。\n2. 严格戒酒：酒精性脂肪肝必须完全戒酒，乙醇摄入是肝损伤持续进展的关键因素，应终身忌酒并避免含酒精的饮品及食物。\n3. 运动：每周至少150分钟中等强度有氧运动（快走、慢跑、游泳、骑车），分5次、每次约30分钟，并配合每周2次抗阻训练（哑铃、深蹲）；避免久坐，每坐1小时起身活动5～10分钟。\n4. 体重管理：超重/肥胖者以体重下降5%～10%为目标，减重速度宜每月1～2kg，避免快速节食减肥（可诱发脂肪性肝炎急性加重）；规律作息，避免熬夜。\n【随诊要求】\n1. 每1～3个月复查肝功能、血脂、空腹血糖（必要时OGTT）、腹部超声，观察脂肪肝程度及转氨酶变化。\n2. 减重及生活方式干预者每3～6个月评估体重、腰围、血压及代谢指标；建议每年行肝脏瞬时弹性成像（FibroScan）评估肝纤维化程度。\n3. 转氨酶持续升高超过3个月、出现黄疸或肝纤维化进展者，转肝病专科进一步诊治，必要时行肝穿刺活检明确病理分级。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":339,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bddfbad5c763c2169fb10fea19b336f4cd8423c9a5d5f70b6a804fecf9a25f37","pinyin":"zhifanggan","initials":"zfg","setting":"out","caseName":"门诊病历204","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历204",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-aedf95901d3e8c725ff5","key":"v1-c9ccc21dfe2a3058|templates-aedf95901d3e8c725ff5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"酒精性肝病","category":"门诊病历模板","raw":{"name":"酒精性肝病","category":"门诊病历模板","case":{"case_name":"门诊病历205","templates":{"主诉":"反酸、嗳气1周。","现病史":"患者1周前无明显诱因出现酒精性肝病相关症状，伴反酸嗳气，进食后加重，空腹缓解，无呕血黑便，无恶心呕吐。自服「奥美拉唑」症状稍缓解，今日来诊。发病以来饮食减少，睡眠可，大小便正常。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒10年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，上腹部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反酸、嗳气1周为主诉，进食后加重、空腹缓解，初步诊断酒精性肝病，长期饮酒者多伴胃黏膜损伤及营养不良，需系统评估肝脏损伤与并发症。查血常规以了解有无酒精相关大细胞性贫血、脾功能亢进所致血小板减少；酒精性肝病易合并消化道出血，查便常规+潜血以排除消化道出血；查肝功能（含转氨酶、胆红素、白蛋白、谷氨酰转肽酶）以评估酒精性肝损伤程度及肝脏合成功能；患者长期饮酒易合并胰腺损伤，且进食后上腹不适加重，查淀粉酶、脂肪酶以排除酒精性胰腺炎；查腹部超声以了解肝脏形态、有无肝硬化及脂肪变、有无腹水及脾大，为无创首选；患者有反酸嗳气症状，需行胃镜了解有无食管胃底静脉曲张及酒精性胃黏膜病变，必要时行肠镜排除结直肠病变；腹部CT（必要时增强）以排除肝内占位性病变、了解肝硬化及门静脉高压情况；查幽门螺杆菌检测（C13/C14呼气试验）以明确有无幽门螺杆菌感染、指导抑酸方案；查凝血功能以评估肝脏合成凝血因子能力，为有创操作及用药安全提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 酒精性肝病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 保肝抗炎：多烯磷脂酰胆碱胶囊228mg tid（随餐口服），疗程4-12周；或水飞蓟宾胶囊70-140mg tid，疗程8-12周，用于减轻肝细胞损伤及脂肪沉积。\n2. 抗炎保肝：甘草酸二铵肠溶胶囊150mg tid，或复方甘草酸苷片2片 tid，疗程4-8周，注意监测血压及血钾，高血压、低钾血症者慎用。\n3. 营养支持：复合维生素B片2片 tid，维生素E软胶囊100mg qd，补充因酒精摄入导致的B族维生素缺乏及氧化应激消耗。\n4. 合并酒精戒断综合征者：地西泮片5mg qn（必要时临时5-10mg，短期使用，不超过1周），并予维生素B1注射液100mg im qd×3天预防韦尼克脑病；肝功能严重异常者减量并监测肝功。\n\n【一般治疗及生活指导】\n1. 绝对戒酒：终身戒除所有含酒精饮料、含酒精药品及食品（如酒心巧克力、藿香正气水等），家属协助监督，必要时转诊戒酒门诊/心理科。\n2. 休息：急性期及肝功能明显异常（转氨酶升高、黄疸）时卧床休息，避免劳累和熬夜，保证充足睡眠。\n3. 饮食：高蛋白、高维生素、低脂、易消化饮食，每日总热量25-35kcal/kg，蛋白摄入1.0-1.5g/(kg·d)；少食多餐，避免暴饮暴食及油炸、腌制食物。\n4. 活动与体重：恢复期可进行散步等中等强度活动，避免剧烈运动；超重/肥胖者逐步减重（每周0.5-1kg），减轻肝脏脂肪沉积，控制血糖血脂。\n\n【随诊要求】\n1. 每2-4周复查肝功能、凝血功能、血常规及电解质，直至肝功能稳定；稳定后每3个月复查1次。\n2. 每3-6个月复查腹部超声，评估肝脏脂肪变程度；每年行瞬时弹性成像（FibroScan）或血清肝纤维化指标评估肝纤维化进展。\n3. 一旦出现乏力加重、黄疸加深、腹胀、呕血、黑便、意识改变等，立即急诊就诊；坚持肝病专科门诊随访，监测肝硬化及肝癌发生风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":340,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"80d799944dccf1c53cea21ef81ccd3d398e5e06fcf9db79ce3e9a4cd47b43ddd","pinyin":"jiujingxingganbing","initials":"jjxgb","setting":"out","caseName":"门诊病历205","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历205",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ad4d9f97deb49b2839d9","key":"v1-c9ccc21dfe2a3058|templates-ad4d9f97deb49b2839d9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"药物性肝损伤","category":"门诊病历模板","raw":{"name":"药物性肝损伤","category":"门诊病历模板","case":{"case_name":"门诊病历206","templates":{"主诉":"反酸、嗳气1周。","现病史":"患者1周前饮食不当后出现药物性肝损伤相关症状，伴反酸嗳气，进食后加重，空腹缓解，无呕血黑便，无恶心呕吐。自服「奥美拉唑」症状稍缓解，今日来诊。发病以来饮食减少，睡眠可，大小便正常。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，上腹部轻度压痛，无反跳痛，肝脾肋下未触及，肠鸣音正常。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反酸、嗳气1周为主诉，进食后加重、空腹缓解，初步诊断药物性肝损伤，近期有明确用药史（自服奥美拉唑），需评估肝损伤程度并排除其他病因。查血常规以了解有无感染、贫血及药物所致嗜酸性粒细胞增多、血小板减少；患者疑有药物相关消化道反应，查便常规+潜血以排除消化道出血；查肝功能（含转氨酶、胆红素、白蛋白）以明确肝细胞损伤类型、胆红素升高程度，是判断药物性肝损伤分型与严重程度的核心；进食后上腹不适加重，查淀粉酶、脂肪酶以排除药物相关胰腺损伤；查腹部超声以了解肝脏形态、有无胆道梗阻及脂肪变，为无创首选；药物性肝损伤需与病毒性肝炎、自身免疫性肝病鉴别，故完善腹部CT了解肝脾形态并排除肝内占位性病变，胃镜、肠镜必要时进行以排除消化道病变；查幽门螺杆菌检测（C13/C14呼气试验）以明确反酸病因、指导是否继续抑酸治疗；查凝血功能以评估肝脏合成功能、警惕急性肝衰竭，并为有创检查提供安全依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 药物性肝损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 保肝抗炎类：复方甘草酸苷片（美能）2片 tid，或甘草酸二铵肠溶胶囊150mg tid，饭后口服，疗程4～8周。\n2. 解毒抗氧化类：还原型谷胱甘肽片0.4g tid，或乙酰半胱氨酸片600mg qd，口服，疗程4周。\n3. 利胆退黄类（胆汁淤积型/胆红素升高）：熊去氧胆酸胶囊250mg tid，或丁二磺酸腺苷蛋氨酸肠溶片500mg bid，疗程4～8周。\n4. 辅助降酶类：水飞蓟宾胶囊（水林佳）70mg tid，或双环醇片25mg tid，口服，疗程4周。\n【一般治疗及生活指导】\n1. 立即停用可疑致肝损伤药物（含中草药、保健品、偏方），避免使用同类或交叉反应药物，所服其他慢病用药需由医师评估后决定是否调整。\n2. 急性期卧床休息为主，避免劳累和熬夜，保证每日睡眠7～8小时，直至乏力、纳差等症状明显缓解。\n3. 清淡、易消化、低脂饮食，保证优质蛋白（鱼、蛋、瘦肉、豆制品）和新鲜蔬果摄入，补充维生素B族、C、E；严格戒酒，忌油炸、辛辣、腌制及霉变食物。\n4. 治疗期间避免自行服用任何其他药物、保健品或草药，合并用药需在医师指导下进行，防止再次肝损伤。\n【随诊要求】\n1. 治疗开始后每1～2周门诊复查肝功能（ALT、AST、GGT、ALP、TBil、DBil），直至转氨酶降至正常上限2倍以下。\n2. 胆红素明显升高或凝血功能异常者，建议每周复查肝功能及凝血酶原时间，必要时住院治疗，警惕急性肝衰竭。\n3. 停药后仍异常者，每2～4周复查肝功能，随访至各项指标恢复正常；恢复正常后3个月内建议每月复查1次，观察有无复发。\n4. 若出现黄疸进行性加深、腹胀、牙龈出血、意识异常等，立即急诊就诊，不可等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":341,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5d4e6996f62e15a0a4f7b1bc584d5d6e23819f77ec8a37e8c9d663958c3fb193","pinyin":"yaowuxinggansunshang","initials":"ywxgss","setting":"out","caseName":"门诊病历206","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历206",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-688c66432bd055c4941a","key":"v1-c9ccc21dfe2a3058|templates-688c66432bd055c4941a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膀胱炎","category":"门诊病历模板","raw":{"name":"膀胱炎","category":"门诊病历模板","case":{"case_name":"门诊病历207","templates":{"主诉":"尿频、尿急、尿痛伴血尿2天。","现病史":"患者1周前劳累后出现膀胱炎相关症状，伴下腹部坠胀，无肉眼血尿，无腰痛，无发热。自服「左氧氟沙星」效果欠佳。今日症状加重，来我院门诊查尿常规提示白细胞升高，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。双肾区无叩击痛。腹平软，下腹部轻度压痛，无反跳痛。外生殖器未见异常。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以尿频、尿急、尿痛伴血尿2天为主诉，劳累后起病，下腹部坠胀，自服左氧氟沙星效果欠佳，门诊尿常规已提示白细胞升高，初步诊断膀胱炎，需明确病原并排除上尿路病变及结石梗阻。查尿常规以明确尿白细胞、红细胞及亚硝酸盐情况，为诊断提供依据；查尿培养+药敏以明确致病菌并指导抗生素调整，因经验性用药效果欠佳；查肾功能以了解肾小球滤过功能、评估感染及用药对肾脏的影响；查电解质以了解有无因进食减少或感染所致的水电解质紊乱；男性患者需查前列腺特异性抗原以排除前列腺增生、前列腺癌等导致下尿路症状及反复感染的病因；查泌尿系超声以了解膀胱壁情况、有无结石、残余尿及上尿路积水；查KUB平片以初步筛查泌尿系阳性结石，排除结石所致血尿；CT尿路成像以进一步明确有无结石、肿瘤及上尿路解剖异常，为鉴别血尿来源提供依据；尿流动力学检查了解膀胱排尿功能、排除膀胱过度活动或梗阻所致症状；经规范抗感染后症状仍反复者行膀胱镜以排除膀胱肿瘤、间质性膀胱炎；必要时查前列腺液常规以排除前列腺炎。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 膀胱炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 磷霉素氨丁三醇散3g，睡前排空膀胱后单次口服（急性单纯性膀胱炎首选，单剂即可）。\n2. 呋喃妥因肠溶片100mg，bid，餐后口服，疗程5天（肾功能正常者适用，对大肠埃希菌敏感）。\n3. 左氧氟沙星片0.5g，qd，口服，疗程3天（适用于当地大肠埃希菌耐药率＜10%者，备选）。\n4. 碳酸氢钠片1.0g，tid，口服，碱化尿液、缓解尿路刺激症状（症状明显者加用，疗程3天）。\n\n【一般治疗及生活指导】\n1. 多饮水，每日饮水量2000ml以上，勤排尿、勿憋尿，以冲洗尿道、稀释细菌。\n2. 注意会阴部清洁卫生，每日清洗、勤换内裤，性生活后排尿一次；避免盆浴、紧身不透气内裤。\n3. 清淡饮食，忌辛辣刺激食物及饮酒、咖啡、浓茶，以免加重尿路刺激症状。\n4. 急性期注意休息，避免劳累及受凉，暂避免性生活。\n\n【随诊要求】\n1. 用药3天后症状无缓解或加重（持续高热、腰痛、血尿）应立即复诊，必要时调整抗感染方案。\n2. 疗程结束后3～7天复查尿常规，评估治愈情况；症状未愈者复查尿培养+药敏。\n3. 反复发作（6个月内≥2次或1年内≥3次）者，建议泌尿外科进一步检查（泌尿系超声、残余尿测定），排除解剖或功能异常。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":342,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"32ba53c7eb17c99b160a1cf67863333337f08ffd5d7e0dc568c211c42e948e32","pinyin":"pangguangyan","initials":"pgy","setting":"out","caseName":"门诊病历207","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历207",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c809f7ed39e9cf1304cc","key":"v1-c9ccc21dfe2a3058|templates-c809f7ed39e9cf1304cc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿道炎","category":"门诊病历模板","raw":{"name":"尿道炎","category":"门诊病历模板","case":{"case_name":"门诊病历208","templates":{"主诉":"尿频、尿急、尿痛伴腰痛2天。","现病史":"患者1周前无明显诱因出现尿道炎相关症状，伴下腹部坠胀，无肉眼血尿，无腰痛，无发热。自服「左氧氟沙星」效果欠佳。今日症状加重，来我院门诊查尿常规提示白细胞升高，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。双肾区无叩击痛。腹平软，下腹部轻度压痛，无反跳痛。外生殖器未见异常。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以尿频、尿急、尿痛伴腰痛2天为主诉，起病无明显诱因，自服左氧氟沙星效果欠佳，门诊尿常规提示白细胞升高，初步诊断尿道炎，需明确感染部位与病原、排除上尿路受累及邻近器官病变。查血常规以了解有无全身感染及炎症反应程度；查尿常规以明确尿白细胞、红细胞及有无脓尿，是尿道炎诊断的基础；查便常规以排除消化道感染及肠道病变所致不适；查肝肾功能以评估用药前的脏器基础功能，避免抗生素加重肝肾负担；查血糖以排除糖尿病等易感因素所致反复泌尿系感染；查血脂以了解基础代谢状况；查电解质以了解有无水电解质紊乱；查心电图以评估心脏基础情况，为抗菌药物选择提供参考；查胸部X线片以排除肺部感染等发热、感染来源；因患者伴腰痛，查腹部超声以了解肾、输尿管、膀胱情况，排除结石、积水及上尿路感染；必要时根据病情选择相应检查以进一步明确病原及鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 尿道炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗菌治疗（首选经验性方案）：非淋菌性尿道炎（衣原体/支原体感染为主）选用多西环素片0.1g bid po×7天，或阿奇霉素片1.0g单次顿服；淋菌性尿道炎选用头孢曲松钠1g单次肌注（头孢过敏者改用大观霉素2g单次肌注）；病原菌不明或疑混合感染时予头孢曲松钠1g单次肌注＋多西环素片0.1g bid po×7天。\n2. 碱化尿液、缓解尿痛：碳酸氢钠片1.0g tid po，疗程3-5天，以减轻排尿灼痛及尿道刺激症状。\n3. 对症止痛（尿痛明显时）：布洛芬缓释胶囊0.3g bid po，症状缓解后即停，一般不超过3天；剧烈尿痛者避免使用阿托品类解痉药以免加重尿潴留。\n【一般治疗及生活指导】\n1. 充分饮水：每日饮水量2000ml以上，勤排尿、避免憋尿，利用尿液冲刷尿道以减轻刺激并助细菌排出。\n2. 饮食清淡，忌辛辣、煎炸及刺激性食物，戒烟戒酒，少饮浓茶、咖啡，避免诱发或加重尿道刺激症状。\n3. 治疗期间及症状完全消失前禁止性生活，配偶或性伴侣应同时接受检查和治疗，防止交叉感染及\"乒乓效应\"反复感染。\n4. 注意个人卫生：勤换内裤，内裤用开水烫洗后在阳光下暴晒，保持外阴清洁干燥，便后从前向后擦拭，避免逆行感染。\n【随诊要求】\n1. 用药3天后症状无缓解或出现发热、腰痛、肉眼血尿等表现，应及时复诊调整治疗方案。\n2. 完成全疗程后1-2周复诊，复查尿常规及尿道分泌物涂片、病原学培养，连续两次病原学检查转阴方可视为治愈。\n3. 症状消失后亦不可自行停药，须遵医嘱完成足量足疗程治疗，避免因疗程不足导致复发或转为慢性尿道炎。\n4. 性伴侣同治后建议双方同时复查病原学，均转阴后方可恢复性生活。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":343,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"20d2b3dc4864bd22e053beb84aeb012e8db78e37f3b0d6e9486c108ec0484d8d","pinyin":"niaodaoyan","initials":"ndy","setting":"out","caseName":"门诊病历208","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历208",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0d566c88d112d08fa6aa","key":"v1-c9ccc21dfe2a3058|templates-0d566c88d112d08fa6aa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾盂肾炎","category":"门诊病历模板","raw":{"name":"肾盂肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历209","templates":{"主诉":"尿频、尿急、尿痛伴发热2天。","现病史":"患者1周前饮食不当后出现肾盂肾炎相关症状，伴下腹部坠胀，无肉眼血尿，无腰痛，无发热。自服「左氧氟沙星」效果欠佳。今日症状加重，来我院门诊查尿常规提示白细胞升高，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。双肾区无叩击痛。腹平软，下腹部轻度压痛，无反跳痛。外生殖器未见异常。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以尿频、尿急、尿痛伴发热2天为主诉，起病急、有全身感染表现，门诊尿常规提示白细胞升高，初步诊断肾盂肾炎，需明确感染病原、评估肾实质受累并排除尿路梗阻等易感因素。查尿常规以明确脓尿、血尿及白细胞管型，支持上尿路感染诊断；查尿微量白蛋白以了解肾小球及肾小管早期损伤程度；查24小时尿蛋白定量以评估肾实质受损及蛋白尿水平，为判断病情及疗效提供依据；查肾功能以评估肾小球滤过功能、警惕感染所致急性肾损伤；查电解质以了解有无因发热、进食减少所致水电解质紊乱；查血常规以明确白细胞及中性粒细胞升高程度，评估感染严重度；查肝功能以评估用药前肝脏基础功能，为抗生素选择提供依据；查凝血功能以评估有无凝血异常，为有创检查提供安全依据；查泌尿系超声以明确有无结石、积水、梗阻及肾周脓肿，是首选的影像学检查；经规范抗感染治疗效果欠佳或影像提示不典型病变时行肾脏穿刺以明确病理诊断、排除其他肾实质疾病；自身抗体检查必要时进行，以排除系统性红斑狼疮等自身免疫性疾病所致肾损害。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 肾盂肾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 喹诺酮类（首选）：左氧氟沙星片 0.5g 口服 每日1次×7～14天（门诊成人常规剂量，肾功能不全者按肌酐清除率调整）。\n2. 头孢菌素类：头孢克肟胶囊 0.2g 口服 每日2次×7～14天；或头孢呋辛酯片 0.25g 口服 每日2次×7～14天（对喹诺酮过敏或不耐受者选用）。\n3. 青霉素类：阿莫西林克拉维酸钾片 0.625g 口服 每日3次×14天（非产酶或产酶菌感染、对上述药物耐药或妊娠期患者可选用，用药前须青霉素皮试）。\n4. 对症治疗：发热者予布洛芬缓释胶囊 0.3g 口服 每日2次（体温≥38.5℃时临时加用，不超过3天）；有恶心、呕吐或脱水者适当补液并注意水电解质平衡。\n\n【一般治疗及生活指导】\n1. 休息：急性期应卧床休息至体温正常、腰痛及尿路刺激症状明显缓解，症状消失后仍需避免劳累1～2周，以防复发。\n2. 饮食：多饮水，每日饮水量2000～2500ml，勤排尿、不憋尿，以稀释尿液、冲刷尿路细菌；饮食宜清淡、易消化、富含维生素，避免辛辣刺激食物、浓茶、咖啡及饮酒。\n3. 个人卫生：注意会阴部清洁，勤换内裤，排便后从前向后擦拭，治疗期间避免盆浴、性生活及游泳，防止交叉感染与逆行感染。\n4. 禁忌：治疗期间禁用肾毒性药物（如氨基糖苷类、非甾体抗炎药长期使用），避免自行停药或减量，监测体温及腰痛变化。\n\n【随诊要求】\n1. 完成抗感染疗程后48～72小时复查尿常规及清洁中段尿细菌培养+药敏，之后每1～2周复查1次尿培养，连续2次阴性方可认为治愈。\n2. 治疗后2周复查血常规、肾功能及泌尿系超声，评估肾实质恢复情况。\n3. 治疗48小时症状无改善或持续高热、腰痛加重、出现寒战者，应及时复诊，必要时收住院静脉抗感染治疗。\n4. 反复发作（6个月内≥2次）或合并尿路梗阻、结石、糖尿病、免疫低下者，建议行泌尿系CT或静脉肾盂造影排除解剖异常，并转肾内科或泌尿外科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":344,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e60f43494c177dab0ceb7354cc2978e6605a446f4dde73d98cf138defd48c781","pinyin":"shenyushenyan","initials":"sysy","setting":"out","caseName":"门诊病历209","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历209",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3e239bdfdc276835b4d6","key":"v1-c9ccc21dfe2a3058|templates-3e239bdfdc276835b4d6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾囊肿","category":"门诊病历模板","raw":{"name":"肾囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历210","templates":{"主诉":"尿频、尿急、尿痛伴腰痛2天。","现病史":"患者1周前饮食不当后出现肾囊肿相关症状，伴下腹部坠胀，无肉眼血尿，无腰痛，无发热。自服「左氧氟沙星」效果欠佳。今日症状加重，来我院门诊查尿常规提示白细胞升高，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。双肾区无叩击痛。腹平软，下腹部轻度压痛，无反跳痛。外生殖器未见异常。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以尿频、尿急、尿痛伴腰痛2天为主诉，起病无明显诱因，门诊尿常规提示白细胞升高，初步诊断肾囊肿，需评估囊肿对肾功能及尿路的影响，并排除囊肿合并感染、出血及恶性变。查尿常规以明确有无血尿、脓尿，排除囊肿压迫或合并感染、结石所致尿路刺激症状；查尿微量白蛋白以了解早期肾小球损伤情况；查24小时尿蛋白定量以评估肾脏受损程度，为判断囊肿是否影响肾功能提供依据；查肾功能以了解肾小球滤过功能，评估囊肿对肾实质的压迫程度；查电解质以了解有无水电解质紊乱；查泌尿系超声以明确囊肿的部位、大小、数目、有无分隔及钙化，是肾囊肿诊断与随访的首选检查；腹部CT（必要时增强）以进一步明确囊肿性质、了解有无囊壁增厚、强化等恶性征象，并排除肾积水及结石；囊肿性质不典型、疑有恶性变或需明确病理类型时，可行肾脏穿刺以明确诊断，穿刺前需评估凝血功能及血压；查血常规以了解有无感染、贫血及出血征象；查肝功能以评估肝脏有无多囊改变，为多囊肾等遗传性疾病鉴别提供依据；查凝血功能以评估穿刺及手术安全性；自身抗体检查必要时进行，以排除自身免疫性疾病所致肾损害；另需查癌胚抗原等肿瘤标志物以协助排除恶性病变。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 肾囊肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 无症状、无并发症的单纯性肾囊肿（Bosniak Ⅰ类）以定期随访观察为主，无需药物治疗；囊肿直径≥4cm 伴压迫症状或反复囊内感染者，建议转泌尿外科行超声引导下囊肿穿刺抽液+硬化治疗。\n2. 合并囊内感染时：头孢呋辛酯片 0.25g po bid×7天；或左氧氟沙星片 0.5g po qd×7天，用药期间多饮水，疗程结束后复查尿常规及肾功能。\n3. 囊肿较大引起腰部胀痛时：布洛芬缓释胶囊 0.3g po bid，疼痛缓解后即停，连续使用不超过5天；胃溃疡病史者慎用。\n4. 合并高血压者：苯磺酸氨氯地平片 5mg po qd，目标血压＜130/80mmHg，每2周监测血压评估疗效并调整剂量。\n\n【一般治疗及生活指导】\n1. 避免剧烈运动、重体力劳动及腹部碰撞，防止囊肿破裂出血；囊肿较大者尤须注意。\n2. 每日饮水1500～2000ml以稀释尿液，避免憋尿；饮食清淡低盐，少食辛辣刺激食物，戒烟限酒。\n3. 避免长期使用肾毒性药物（如非甾体抗炎药、氨基糖苷类抗生素、含马兜铃酸中草药等），确需用药时遵医嘱并监测肾功能。\n4. 定期自测血压，出现腰部持续性钝痛、肉眼血尿、发热或腹部触及包块时及时就诊。\n\n【随诊要求】\n1. 囊肿直径＜4cm 且无症状者，每年复查泌尿系超声1次；囊肿直径≥4cm 或随访中较前增大者，每3～6个月复查超声，动态观察囊肿大小及形态变化。\n2. 随访中出现囊肿快速增大、囊壁增厚/分隔/钙化（Bosniak ⅡF类及以上）、肉眼血尿或持续腰痛者，需进一步行增强CT或MRI检查，必要时转泌尿外科评估介入或手术治疗。\n3. 每6～12个月复查血肌酐、尿素氮、eGFR及尿常规，评估肾功能；合并高血压者同步监测血压、控制达标并缩短随访间隔。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":345,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b22a79c066f364881f3a1c235c6727e8e883717bfb0435b2ffba4a9235c914e9","pinyin":"shennangzhong","initials":"snz","setting":"out","caseName":"门诊病历210","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历210",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b32f63dee72147c38a97","key":"v1-c9ccc21dfe2a3058|templates-b32f63dee72147c38a97","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"遗尿症","category":"门诊病历模板","raw":{"name":"遗尿症","category":"门诊病历模板","case":{"case_name":"门诊病历211","templates":{"主诉":"尿频、尿急、尿痛伴腰痛2天。","现病史":"患者1周前无明显诱因出现遗尿症相关症状，伴下腹部坠胀，无肉眼血尿，无腰痛，无发热。自服「左氧氟沙星」效果欠佳。今日症状加重，来我院门诊查尿常规提示白细胞升高，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。双肾区无叩击痛。腹平软，下腹部轻度压痛，无反跳痛。外生殖器未见异常。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者尿频、尿急、尿痛伴腰痛2天，外院尿常规提示白细胞升高，自服左氧氟沙星效果欠佳，首先完善尿常规检查明确尿路感染严重程度并复查白细胞变化；查血常规检查排除感染、贫血及血液系统异常所致；患者自服抗菌药物后排便情况需评估，查便常规检查排除消化道感染及消化道出血；住院期间抗感染药物需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导用药剂量调整；患者有多饮多尿、体重下降表现，完善血糖检查明确有无糖代谢异常，查血脂检查了解血脂水平并评估心血管危险因素；患者尿路感染伴下腹部坠胀，完善电解质检查排除电解质紊乱，复查心电图检查排除心律失常及心肌缺血；患者尿频尿急伴腰痛，完善胸部X线片检查排除肺部感染等合并症，查腹部超声检查了解泌尿系有无结石、积水及腹腔脏器情况；若腰痛持续加重或出现发热，及时完善泌尿系超声及尿培养进一步明确致病菌并指导抗感染方案。上述检查入院即刻完成血、尿、便常规及心电图，其余项目于入院24小时内完成，病情稳定后定期复查尿常规及肝肾功能。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 遗尿症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 醋酸去氨加压素片（弥凝）0.2mg 睡前口服 qn×3个月，夜间尿量增多型首选；若效果不理想可增至0.4mg qn，见效后维持有效剂量至少3个月再逐渐减量停药。\n2. 盐酸奥昔布宁片 5mg 睡前口服 qn×4周，适用于伴白天尿频、尿急等下尿路症状或膀胱过度活动表现者，症状缓解后维持2-3个月；用药期间监测口干、便秘等抗胆碱能不良反应。\n3. 盐酸丙咪嗪片 25mg 睡前口服 qn×4周，用于上述治疗无效的顽固性遗尿，可根据患者具体情况制定个体化方案增至50mg qn，不推荐作为一线用药，停药需逐步减量。\n【一般治疗及生活指导】\n1. 睡前2-3小时限制液体摄入（晚餐后少饮水），睡前禁食含咖啡因及利尿作用的饮料（浓茶、咖啡、可乐、西瓜等）。\n2. 睡前务必排空膀胱，可配合\"定时唤醒排尿\"（入睡后2-3小时唤醒排尿1次），并记录排尿日记（饮水量、排尿时间及夜间遗尿次数）以评估疗效。\n3. 进行膀胱功能训练：白天适当憋尿延长排尿间隔，练习中断排尿以增强括约肌控制力，但勿过度憋尿导致泌尿系感染。\n4. 注意保暖，避免受凉及睡前剧烈活动；保持床单干燥，尿湿后及时更换，避免心理压力，勿责备患儿，建立信心。\n【随诊要求】\n1. 用药2周后复诊，评估夜尿及遗尿次数改善情况，调整药物剂量。\n2. 用药期间每月复诊1次，复查尿常规排除尿路感染，连续监测排尿日记评估疗效。\n3. 症状完全控制3个月以上可尝试停药，停药后1个月复诊观察有无复发；若停药后复发或药物治疗3个月无效，需转诊进一步行尿动力学检查、泌尿系超声等评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":346,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0fef39c8fd7903c97adda6f69a4810b206f3f7f7a8b0b7e8231a775b2a1cb34e","pinyin":"yiniaozheng","initials":"ynz","setting":"out","caseName":"门诊病历211","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历211",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-753bdfb714dc3b6720f6","key":"v1-c9ccc21dfe2a3058|templates-753bdfb714dc3b6720f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺结节","category":"门诊病历模板","raw":{"name":"甲状腺结节","category":"门诊病历模板","case":{"case_name":"门诊病历212","templates":{"主诉":"发现血压升高伴多饮1月。","现病史":"患者1周前受凉后出现甲状腺结节相关症状，伴多饮多尿，体重近1月下降约3kg，无明显多食，无肢体麻木。今日来我院门诊查空腹血糖8.5mmol/L，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。甲状腺未触及肿大。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双下肢无水肿。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现血压升高伴多饮1月，近1月体重下降约3kg，门诊查空腹血糖8.5mmol/L，完善空腹血糖及餐后2小时血糖检查明确糖代谢异常程度并指导降糖方案；查糖化血红蛋白检查了解近3个月平均血糖控制水平，完善胰岛素释放试验及C肽检查评估胰岛β细胞分泌功能并鉴别糖尿病分型；患者发现甲状腺结节，完善甲状腺功能检查明确结节是否伴甲状腺功能亢进或减退，必要时完善甲状腺超声检查了解结节大小、边界、血流及有无钙化，评估恶性风险；患者多饮多尿伴体重下降，完善尿微量白蛋白检查明确有无早期糖尿病肾病，查肝肾功能检查排除肝肾功能不全并指导用药，查血脂检查了解血脂水平并评估心血管危险因素，完善电解质检查排除电解质紊乱；患者血压升高伴体重下降，必要时查肾上腺CT检查排除肾上腺病变所致继发性高血压，病情需要时完善其他相关检查，定期复查血糖及甲状腺功能观察动态变化。\n\n（检查清单）\n【必做检查】\n空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素释放试验、C肽\n\n【影像学检查】\n甲状腺超声（必要时）、肾上腺CT（必要时）\n\n【其他检查】\n甲状腺功能、尿微量白蛋白、肝肾功能、血脂、电解质","初步诊断":"1. 甲状腺结节\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 甲状腺功能正常且无压迫症状的良性结节：无需药物干预，以定期随访观察为主，避免盲目服用\"散结\"中成药。\n2. 合并甲状腺功能减退（如桥本甲状腺炎所致）：左甲状腺素钠片（优甲乐）25μg qd，晨起空腹顿服，服药后半小时再进食；每4-6周复查甲状腺功能，根据TSH水平逐渐调整剂量，维持TSH在正常参考范围。\n3. 合并甲状腺功能亢进：甲巯咪唑片（赛治）10mg bid，口服；服药期间每2-4周监测甲状腺功能、血常规及肝功能，症状控制后遵医嘱减量，勿自行停药。\n4. 合并桥本甲状腺炎伴甲状腺过氧化物酶抗体（TPOAb）升高者：可加用硒酵母片100μg bid，口服，疗程3-6个月。\n\n【一般治疗及生活指导】\n1. 饮食：甲状腺功能正常者正常含碘饮食即可，避免长期大量食用海带、紫菜、海蜇等高碘食物；伴甲亢者严格低碘饮食，忌用加碘盐及海产品；桥本甲状腺炎伴甲减者避免过量补碘。\n2. 休息与活动：规律作息，避免熬夜及过度劳累，保持情绪平稳，避免紧张焦虑；可正常从事日常活动及轻中度运动，无需绝对卧床。\n3. 禁忌：避免不必要的颈部X线或CT照射；勿自行服用含碘保健品及来源不明的\"散结\"偏方；避免反复触摸、按压或揉搓结节及颈前区，以免刺激结节。\n4. 监测：学会自我观察颈前有无肿块迅速增大、声音嘶哑、吞咽或呼吸困难等变化，发现异常及时就诊。\n\n【随诊要求】\n1. 超声提示TI-RADS 3类及以下、直径≤1cm的良性结节：每6-12个月复查甲状腺彩超，观察大小及形态变化。\n2. 超声提示TI-RADS 4类及以上，或结节6个月内直径增大≥2mm且体积增加≥50%，或新出现声音嘶哑、吞咽困难、颈部压迫感者：及时返院复诊，必要时行细针穿刺活检（FNA）明确性质。\n3. 服用左甲状腺素者：调整剂量期间每4-6周复查甲状腺功能，剂量稳定后每6-12个月复查；服用甲巯咪唑者每2-4周复查血常规、肝功能及甲状腺功能。\n4. 恶性或可疑恶性结节术后患者：按专科医师要求定期复查甲状腺功能、甲状腺彩超及肿瘤标志物，术后第1年内每3-6个月复查1次。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":347,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0b4bea2ee822b3a534695e7393b714eeb6f160cbb49b165f8ef0c9478703a28a","pinyin":"jiazhuangxianjiejie","initials":"jzxjj","setting":"out","caseName":"门诊病历212","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历212",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-38ff99109156937fbc6d","key":"v1-c9ccc21dfe2a3058|templates-38ff99109156937fbc6d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"垂体瘤","category":"门诊病历模板","raw":{"name":"垂体瘤","category":"门诊病历模板","case":{"case_name":"门诊病历213","templates":{"主诉":"发现体重变化伴乏力1月。","现病史":"患者1周前饮食不当后出现垂体瘤相关症状，伴多饮多尿，体重近1月下降约3kg，无明显多食，无肢体麻木。今日来我院门诊查空腹血糖8.5mmol/L，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。甲状腺未触及肿大。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双下肢无水肿。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现体重变化伴乏力1月，伴多饮多尿，近1月体重下降约3kg，门诊查空腹血糖8.5mmol/L，首先完善血常规检查排除感染、贫血所致乏力；患者存在垂体功能减退可能，完善肝肾功能检查排除肝肾功能不全并指导后续用药，查电解质检查排除电解质紊乱所致乏力及多尿；拟行影像学检查及必要时手术，完善凝血功能检查评估凝血状态以排除出血风险，查肿瘤标志物检查协助鉴别肿瘤性质及来源；患者头痛、视力视野改变等颅内占位表现需明确，完善头颅CT检查了解鞍区骨质及有无出血钙化，查头颅MRI检查明确肿瘤大小、部位及与视交叉、海绵窦的关系，为手术方案提供依据；为排除全身其他部位原发灶及转移灶，必要时完善PET-CT检查，查甲状腺、腹部超声检查了解相应脏器有无异常；为明确病理性质，必要时完善病理活检、免疫组化及基因检测指导后续治疗，若怀疑垂体卒中或合并血液系统疾病，可完善骨髓穿刺（必要时）检查进一步明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 垂体瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 泌乳素瘤（首选）：溴隐亭片起始1.25mg每晚睡前口服，3～5天后增至2.5mg bid，此后据血泌乳素水平每2～4周调整，常用维持量2.5mg bid～tid，长期维持；或卡麦角林片0.25mg每周1次口服，必要时增至0.5mg每周2次，连用≥3个月后复查泌乳素调整剂量。\n2. 生长激素腺瘤（术后残留、复发或不宜手术者）：奥曲肽注射液100μg皮下注射tid；或奥曲肽微球20mg肌注每4周1次，持续3～6个月复查GH/IGF-1以调整剂量；亦可用兰瑞肽autogel 60～120mg深部皮下注射每4周1次。\n3. 促肾上腺皮质激素腺瘤（库欣病药物控制）：帕瑞肽注射液600μg皮下注射bid；或酮康唑片200mg bid～tid口服（用药期间监测肝功能），以降低皮质醇水平。\n4. 垂体功能减退替代治疗：醋酸泼尼松片2.5～5mg每日晨8时前顿服；左甲状腺素钠片25～50μg每日晨起空腹口服（须先服用糖皮质激素1～3天后再启用，以防诱发肾上腺危象）；男性患者加用十一酸睾酮胶丸40mg bid，女性按需行雌孕激素序贯治疗。\n\n【一般治疗及生活指导】\n1. 规律作息，避免熬夜、过度劳累及剧烈运动，防止诱发垂体卒中（突发剧烈头痛、视力骤降、恶心呕吐时应立即急诊就诊）。\n2. 保持情绪稳定、避免应激；遇感染、发热、手术、外伤等应激情况时，糖皮质激素替代剂量需临时加量（如泼尼松增至日常剂量2～3倍）并尽快就医，不可自行停药或减量。\n3. 均衡饮食，适量补充优质蛋白、钙剂及维生素D；库欣病合并高血压、高血糖者应低盐、低脂、低糖饮食，每日监测血压、血糖及体重。\n4. 观察尿量、口渴及体重变化，出现多饮多尿提示尿崩症可能；定期自测双眼视力并对比视野，发现视野缺损、复视或单眼视力下降及时复诊。\n\n【随诊要求】\n1. 服药患者每1～3个月复查血泌乳素（泌乳素瘤）或GH/IGF-1（肢端肥大症）、血皮质醇节律（库欣病），据此调整药物剂量。\n2. 每3～6个月复查鞍区增强MRI评估肿瘤大小及有无囊变出血；曾有视交叉受压者每6～12个月复查视力、视野及眼底。\n3. 长期激素替代治疗者每3～6个月复查甲状腺功能、电解质、肝肾功能、血糖及血脂，定期测骨密度；有生育需求者孕前于内分泌科专科评估并制定监测方案。\n4. 术后患者于术后3、6、12个月规律复查，此后每年复查1次；出现新发头痛、视力障碍、多饮多尿或性腺功能减退表现时随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":348,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b47e948db1fe994f6e18bf0905c8af90dbb63923dac8b7d637ef9c7cf5e7b724","pinyin":"chuitiliu","initials":"ctl","setting":"out","caseName":"门诊病历213","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历213",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1d6d4fbeb4b0531a59d5","key":"v1-c9ccc21dfe2a3058|templates-1d6d4fbeb4b0531a59d5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾上腺疾病","category":"门诊病历模板","raw":{"name":"肾上腺疾病","category":"门诊病历模板","case":{"case_name":"门诊病历214","templates":{"主诉":"发现血糖升高伴多饮1月。","现病史":"患者1周前劳累后出现肾上腺疾病相关症状，伴多饮多尿，体重近1月下降约3kg，无明显多食，无肢体麻木。今日来我院门诊查空腹血糖8.5mmol/L，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。甲状腺未触及肿大。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双下肢无水肿。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现血糖升高伴多饮1月，伴多饮多尿及体重下降，需评估肾上腺与肾脏功能，首先完善尿常规检查明确有无血尿、蛋白尿及尿路感染；患者多饮多尿，完善尿微量白蛋白及24小时尿蛋白定量检查明确有无早期肾损伤及蛋白尿程度，查肾功能检查评估肾小球滤过功能并指导用药；患者肾上腺疾病常伴电解质紊乱及血压异常，完善电解质检查排除低钾血症等电解质紊乱所致血压及心律异常；患者血压升高需明确有无肾上腺占位，完善泌尿系超声检查了解肾上腺及双肾形态，必要时完善肾上腺CT等进一步影像学检查，若存在难以解释的肾性蛋白尿或肾功能进行性下降，必要时完善肾脏穿刺（必要时）检查明确病理类型；为保障后续检查及治疗安全，完善血常规检查排除感染、贫血，查肝功能检查排除肝功能不全，查凝血功能检查排除凝血异常所致出血风险；若怀疑自身免疫性疾病累及肾脏或肾上腺，必要时完善自身抗体（必要时）检查进一步明确诊断，病情稳定后定期复查肾功能、电解质及尿蛋白。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 肾上腺疾病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素替代治疗（肾上腺皮质功能减退症）：氢化可的松片20mg晨起口服、10mg午后口服（或泼尼松片5mg晨起口服、2.5mg午后口服），维持最小有效剂量；盐皮质激素缺乏者加用氟氢可的松片0.05～0.1mg qd。\n2. 原发性醛固酮增多症：螺内酯片20mg qd起始，每2～4周加量，最大100mg/d，分2～3次口服；血压控制不佳时联合氨氯地平片5mg qd或硝苯地平控释片30mg qd。\n3. 嗜铬细胞瘤术前准备：酚苄明片10mg bid起始，每2～3天增加10mg，至血压<140/90mmHg后加用美托洛尔片12.5～25mg bid控制心率；β受体阻滞剂必患者α受体充分阻滞后（至少4～5天）方可使用。\n4. 库欣综合征药物治疗（手术禁忌或等待手术者）：酮康唑片200mg bid起始，渐加至400mg bid，每月复查肝功能及血皮质醇调整剂量；或美替拉酮片250mg bid。\n【一般治疗及生活指导】\n1. 肾上腺皮质功能减退者：避免劳累、感染、情绪激动等应激，保证充足睡眠；饮食高蛋白、高热量、高盐（每日食盐5～10g），随身携带糖皮质激素应急药物及\"激素使用卡\"，遇发热、呕吐、腹泻、手术外伤等应激时按医嘱加倍激素并尽早就诊，切忌自行停药或减量。\n2. 嗜铬细胞瘤患者：避免剧烈运动、情绪激动、用力排便及腹部挤压按摩；忌咖啡、浓茶、酒精及高酪胺食物（奶酪、腌制品、香蕉、巧克力）；每日监测血压，出现阵发性头痛、心悸、大汗时立即安静卧床并测血压。\n3. 库欣综合征患者：低盐、低脂、低碳水饮食，限制总热量以控制体重；适当补钾（多吃柑橘、香蕉等）；补充钙剂及维生素D防治骨质疏松，监测血糖血压，注意个人卫生预防感染。\n4. 原发性醛固酮增多症患者：低盐饮食（每日食盐<5g），多食富钾食物；监测血压及血钾，避免使用噻嗪类利尿剂及甘草制剂，防止低钾诱发心律失常。\n【随诊要求】\n1. 每1～3个月门诊复诊，复查血压、血电解质（钾、钠）、空腹血糖、肝肾功能及血皮质醇、ACTH，据此调整激素及降压药物剂量。\n2. 嗜铬细胞瘤患者每2～4周复诊调整α/β受体阻滞剂，血压稳定≥2周、心率<80次/分后及时转诊泌尿外科/内分泌科评估手术；术后每3～6个月复查血、尿儿茶酚胺及其代谢产物。\n3. 库欣综合征及原发性醛固酮增多症患者每3个月复查激素水平（血皮质醇昼夜节律、ACTH、醛固酮/肾素比值）及肾上腺影像学（CT/MRI），评估疗效并筛查糖脂代谢、骨质疏松、心脑血管等并发症。\n4. 出现发热、恶心呕吐、腹痛、血压骤升骤降、心悸大汗、意识改变等异常，立即就近就诊，勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":349,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0ccf1d6c244ec0f7a99c79c03a5409bf88a2fb184cc135aa6019228415fd3399","pinyin":"shenshangxianjibing","initials":"ssxjb","setting":"out","caseName":"门诊病历214","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历214",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05a971508f154dc197fb","key":"v1-c9ccc21dfe2a3058|templates-05a971508f154dc197fb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"代谢综合征","category":"门诊病历模板","raw":{"name":"代谢综合征","category":"门诊病历模板","case":{"case_name":"门诊病历215","templates":{"主诉":"发现血压升高伴多饮1月。","现病史":"患者1周前劳累后出现代谢综合征相关症状，伴多饮多尿，体重近1月下降约3kg，无明显多食，无肢体麻木。今日来我院门诊查空腹血糖8.5mmol/L，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。甲状腺未触及肿大。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双下肢无水肿。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现血压升高伴多饮1月，伴多饮多尿、体重下降约3kg，门诊查空腹血糖8.5mmol/L，完善血常规检查排除感染、贫血所致代谢紊乱；查尿常规检查明确有无尿糖、蛋白尿及尿路感染，查便常规检查排除消化道出血及感染；患者存在血糖升高及血压升高，用药需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导降糖降脂药物选择；完善血糖检查明确糖代谢异常程度，查血脂检查了解血脂水平并指导调脂方案，查电解质检查排除电解质紊乱；患者血压升高、代谢异常需评估心血管及靶器官损害，完善心电图检查排除心肌缺血及心律失常，查胸部X线片检查排除心肺合并症，查腹部超声检查了解有无脂肪肝、胰腺及肾脏病变；根据病情需要选择相应检查，必要时完善糖化血红蛋白、胰岛素释放试验及尿微量白蛋白检查评估靶器官损害，病情稳定后定期复查血糖、血脂及肝肾功能。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 代谢综合征\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 盐酸二甲双胍片0.5g bid po（餐中或餐后服），疗程至少3个月，改善胰岛素抵抗、辅助降糖减重（eGFR<45ml/min或急性缺氧状态者禁用，注意胃肠道反应）\n2. 伴血压升高（≥130/85mmHg）者首选血管紧张素Ⅱ受体拮抗剂，如氯沙坦钾片50mg qd po，血压目标<130/80mmHg，兼具代谢保护作用；不耐受或效果不佳者加用或换用钙拮抗剂（苯磺酸氨氯地平片5mg qd）\n3. 伴血脂异常者：LDL-C升高或合并ASCVD风险者用阿托伐他汀钙片20mg qn po，LDL-C目标按心血管风险分层（高危<1.8mmol/L）；若甘油三酯≥5.6mmol/L，改用或联用非诺贝特胶囊200mg qd，警惕肌痛、肝酶升高，定期复查\n\n【一般治疗及生活指导】\n1. 饮食运动减重：控制总热量摄入，减少精制米面及含糖饮料，增加蔬菜、全谷物及优质蛋白，每日限盐<5g、严格限酒；每周≥150min中等强度有氧运动（快走、游泳、骑车）联合每周2~3次抗阻训练，3~6个月内使体重下降5%~10%，腰围达标（男性<90cm，女性<85cm），并每日记录体重与腰围\n2. 戒烟及作息管理：完全戒烟并避免二手烟，规律作息、避免熬夜与久坐（每1小时起身活动），每日自测血压、每周自测空腹血糖，如有视物模糊、多饮多尿、胸闷心悸等异常及时就诊\n\n【随诊要求】\n每2~4周复诊1次，评估血压、空腹及餐后2小时血糖、体重腰围变化及药物耐受性；每3个月复查血脂、糖化血红蛋白（HbA1c）、肝肾功能及肌酸激酶；每6~12个月进行心血管总体风险评估，完善颈动脉超声、尿微量白蛋白、眼底检查，筛查糖尿病及心脑血管并发症，必要时转诊内分泌科、心内科协同管理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":350,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1de8236b9e2d25131db79f72fe315cb58467a7270adb47271a5d131b80e48131","pinyin":"daixiezonghezheng","initials":"dxzhz","setting":"out","caseName":"门诊病历215","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历215",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b7326a7ec1a05b146b5b","key":"v1-c9ccc21dfe2a3058|templates-b7326a7ec1a05b146b5b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高尿酸血症","category":"门诊病历模板","raw":{"name":"高尿酸血症","category":"门诊病历模板","case":{"case_name":"门诊病历216","templates":{"主诉":"发现血压升高伴多汗1月。","现病史":"患者1周前无明显诱因出现高尿酸血症相关症状，伴多饮多尿，体重近1月下降约3kg，无明显多食，无肢体麻木。今日来我院门诊查空腹血糖8.5mmol/L，为进一步诊治来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。甲状腺未触及肿大。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。双下肢无水肿。生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现血压升高伴多汗1月，伴多饮多尿、体重下降，门诊查空腹血糖8.5mmol/L，完善血常规检查排除感染、贫血，并了解白细胞及血小板情况；患者需明确尿酸水平及肾脏排泄情况，查尿常规检查了解尿液酸碱度及有无尿路结石、感染，查便常规检查排除消化道出血及感染；患者血糖及尿酸升高，长期用药需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全并指导降尿酸药物剂量调整；完善血糖检查明确糖代谢异常程度，查血脂检查了解血脂水平并指导综合调脂治疗，查电解质检查排除电解质紊乱；患者血压升高伴代谢异常，完善心电图检查排除心肌缺血及心律失常，查胸部X线片检查排除心肺合并症，查腹部超声检查了解肾脏有无结石、有无脂肪肝；根据病情需要选择相应检查，必要时完善血尿酸、24小时尿尿酸及关节超声检查明确尿酸沉积情况，病情稳定后定期复查血尿酸、肝肾功能及尿常规。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 高尿酸血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.降尿酸治疗（长期维持）：首选抑制尿酸生成药别嘌醇片：起始50mg bid，每2-4周递增剂量，最大剂量300mg/d，分2-3次口服；用药前行HLA-B*5801基因检测（汉族人群阳性率高，阳性者禁用），治疗目标为血尿酸<360μmol/L（有痛风石或频繁发作者<300μmol/L），达标后长期维持。若别嘌醇不耐受或基因阳性，改用非布司他片20mg qd起始，2-4周后血尿酸未达标可增至40mg qd，最大80mg qd。\n2.急性关节炎发作期（如出现关节红肿热痛）：秋水仙碱片首剂1.0mg，1小时后0.5mg，12小时后改为0.5mg bid，连用3-5天；或塞来昔布胶囊200mg qd，症状缓解后停药（禁用于活动性消化道溃疡及肾功能不全者）；单药效果不佳时可短期联用泼尼松片30mg qd，疗程≤7天。\n3.碱化尿液（合并尿酸结石或尿尿酸排泄增多者）：碳酸氢钠片1.0g tid，监测尿pH，维持在6.2-6.9之间，根据尿pH调整剂量，一般疗程2-4周后复查再评估。\n【一般治疗及生活指导】\n1.饮食控制：避免动物内脏、浓肉汤、海产品（贝类、沙丁鱼等）、啤酒及含果糖饮料；每日肉类摄入控制在100-150g以内，鸡蛋、牛奶、新鲜蔬菜可正常食用，豆制品（豆腐、豆浆）可适量食用。\n2.大量饮水：无心肾功能不全者每日饮水量2000-3000ml，分次饮用，可饮白开水或淡茶水，促进尿酸经肾排泄；避免含糖饮料及果汁。\n3.生活方式：超重或肥胖者控制体重，使BMI维持在18.5-23.9kg/m²；戒烟，严格限酒（禁啤酒及白酒）；规律进行中低强度有氧运动（快走、游泳、慢跑等），每周≥150分钟，避免剧烈运动及关节扭伤、受凉。\n4.合并疾病管理：合并高血压、糖尿病、血脂异常者积极控制血压、血糖、血脂；避免长期使用噻嗪类利尿剂、小剂量阿司匹林、环孢素等可升高尿酸的药物，如确需使用应监测血尿酸。\n【随诊要求】\n1.开始降尿酸治疗后2-4周复诊，复查血尿酸、肝肾功能、血常规及尿常规；服用别嘌醇者注意观察皮疹、发热、瘙痒等超敏反应（用药后1-2月内尤需警惕），出现异常立即停药就诊。\n2.血尿酸未达标者每4周复诊调整剂量；达标后每3个月复查1次血尿酸，长期服药者每3-6个月复查血尿酸、肝肾功能及尿常规，每年复查1次肾脏彩超。\n3.急性发作期每周复诊至关节症状缓解，缓解后2周复诊评估降尿酸药物启用时机（急性发作缓解2周后开始降尿酸治疗）；出现关节红肿热痛、发热、少尿、浮肿等及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":351,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"465d171e8f834c387cb9467e41e9ac6260a9befcf0d8d6cd90bc59a214fee6c1","pinyin":"gaoniaosuanxuezheng","initials":"gnsxz","setting":"out","caseName":"门诊病历216","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历216",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9304ae3497646ae9c478","key":"v1-c9ccc21dfe2a3058|templates-9304ae3497646ae9c478","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑血管病","category":"门诊病历模板","raw":{"name":"脑血管病","category":"门诊病历模板","case":{"case_name":"门诊病历217","templates":{"主诉":"反复头晕伴失眠1周。","现病史":"患者1周前无明显诱因出现脑血管病相关症状，呈搏动性，劳累后加重，休息后稍缓解，伴恶心，无呕吐，无肢体活动障碍。自服「布洛芬」可暂时缓解，今日再次发作，来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。神经系统检查：生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复头晕伴失眠1周，症状呈搏动性、劳累后加重，需评估脑血管病危险因素，完善血常规检查排除感染、贫血所致头晕；查生化全项检查了解肝肾功能、血糖及电解质情况，排除代谢异常及电解质紊乱所致眩晕；患者脑梗死风险高，完善凝血功能检查评估凝血状态并指导抗栓治疗，查血糖及血脂检查明确糖尿病、脂代谢异常等危险因素，完善同型半胱氨酸检查了解有无高同型半胱氨酸血症这一独立危险因素；为明确颅内病变性质，完善头颅CT/MRI检查排除脑出血并明确有无急性脑梗死及病灶部位，完善颈动脉超声检查了解颈部血管有无斑块及狭窄，查经颅多普勒检查评估颅内血流速度及有无血管狭窄；为排查心源性栓子来源，完善心电图检查排除心房颤动及心肌缺血，查心脏超声（排查栓子来源）了解心腔有无附壁血栓、瓣膜情况；若怀疑颅内感染或蛛网膜下腔出血而影像学不典型，必要时完善腰椎穿刺（必要时）检查进一步明确诊断，病情稳定后定期复查血脂、血糖及颈部血管超声。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 脑血管病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗血小板聚集：阿司匹林肠溶片100mg qd po，餐后服，长期服用；近期（7天内）发生缺血性卒中或TIA者，首日负荷量300mg后改为100mg qd po；阿司匹林过敏或不能耐受者改用氯吡格雷片75mg qd po。\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn po（或瑞舒伐他汀钙片10mg qn po），长期服用，LDL-C目标值＜1.8mmol/L；服药期间注意监测肝功及肌酸激酶。\n3. 控制血压：血压≥140/90mmHg者予氨氯地平片5mg qd po（或缬沙坦胶囊80mg qd po），血压目标＜140/90mmHg，合并糖尿病或慢性肾病者目标＜130/80mmHg，平稳降压，避免波动过大。\n4. 改善脑循环、营养神经：伴头晕、肢体麻木者加用银杏叶片19.2mg tid po，或尼莫地平片30mg tid po；伴认知功能障碍者加用胞磷胆碱钠胶囊0.2g tid po，疗程4-8周。\n\n【一般治疗及生活指导】\n1. 休息与活动：急性期注意休息，避免劳累、用力排便、猛然起坐及突然改变体位；病情稳定后循序渐进进行康复锻炼，包括肢体功能训练、语言训练，每日适量有氧运动（如散步30分钟/日）。\n2. 饮食：低盐低脂低糖饮食，每日食盐摄入＜5g，少食动物内脏、肥肉、油炸及腌制食品，多食新鲜蔬菜、水果、全谷物及富含不饱和脂肪酸食物（深海鱼等），戒烟、限制饮酒。\n3. 危险因素管理：规律监测并记录血压、血糖，遵医嘱长期服药，切勿自行停药、减量或随意换药；控制体重（BMI＜24），保持情绪平稳，避免激动、紧张及熬夜。\n4. 禁忌：避免剧烈运动和重体力劳动，避免便秘时屏气用力，防止血压骤升诱发再发；发病后6个月内暂不宜驾车、高空作业及重体力工作，是否恢复需经医师评估。\n\n【随诊要求】\n1. 门诊治疗后2-4周复诊，复查血压、血脂、血糖及肝肾功能、肌酸激酶，评估药物疗效与不良反应，据此调整用药方案。\n2. 病情稳定者每3-6个月门诊复诊一次，每6-12个月复查颈动脉超声、头颅CT或MRI，评估血管病变进展情况。\n3. 若出现一过性肢体麻木无力、言语不清、口角歪斜、视物模糊、剧烈头痛、恶心呕吐或头晕较前明显加重等新发症状，应立即就近急诊就诊，不可等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":352,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c062de5bb54e5bd11079acfddb1df88b20546f5a756741706c1d33340ce03ffc","pinyin":"naoxueguanbing","initials":"nxgb","setting":"out","caseName":"门诊病历217","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历217",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7d4aa1b3582a8c342408","key":"v1-c9ccc21dfe2a3058|templates-7d4aa1b3582a8c342408","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"焦虑症","category":"门诊病历模板","raw":{"name":"焦虑症","category":"门诊病历模板","case":{"case_name":"门诊病历218","templates":{"主诉":"反复头晕伴恶心1周。","现病史":"患者1周前受凉后出现焦虑症相关症状，呈搏动性，劳累后加重，休息后稍缓解，伴恶心，无呕吐，无肢体活动障碍。自服「布洛芬」可暂时缓解，今日再次发作，来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。神经系统检查：生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、肝肾功能、甲状腺功能、血糖、电解质\n\n【影像学检查】\n心电图、头颅CT/MRI（排除器质性病变）\n\n【其他检查】\n心理评估量表（PHQ-9、GAD-7、PANSS等）、药物浓度监测\n","初步诊断":"1. 焦虑症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.SSRI类一线首选：艾司西酞普兰片10mg qd晨服，首周以5mg qd起始减轻胃肠道不适，第2周加至10mg qd，连用4-8周评估疗效，显效后维持6-12个月，停药前缓慢减量。\n2.SNRI类：盐酸文拉法辛缓释胶囊75mg qd早餐后顿服，2周后疗效不佳可加量至150mg qd，对伴躯体症状者疗效更佳，疗程6-12个月。\n3.短期联用苯二氮䓬类：劳拉西泮片0.5mg qn（焦虑明显者可0.5mg bid），仅用于急性期焦虑显著或伴入睡困难者，疗程不超过2-4周，症状缓解后逐渐减量停药，防止依赖。\n4.非苯二氮䓬类抗焦虑药：盐酸丁螺环酮片5mg tid，用于不能耐受SSRI/SNRI或需长期服药者，起效较慢（1-2周起效、2-4周显效），无依赖性。\n\n【一般治疗及生活指导】\n1.建议联合认知行为治疗（CBT），每周1次、每次50分钟、至少12次，学习识别并纠正灾难化思维，掌握腹式呼吸、渐进性肌肉放松等放松训练。\n2.规律作息：保证每晚7-8小时睡眠，固定上床与起床时间；避免浓茶、咖啡及含咖啡因饮料（下午3点后禁饮），戒酒戒烟。\n3.适度有氧运动：每周3-5次快走、慢跑或游泳，每次30-45分钟，有助于缓解焦虑、改善睡眠。\n4.减少应激：避免熬夜、过度劳累及精神刺激，练习正念冥想，学会情绪表达与减压，必要时与家人沟通获得支持。\n\n【随诊要求】\n1.首次服药后2周复诊，评估疗效与不良反应（注意SSRI初期可能出现的焦虑加重、恶心、失眠）；此后急性期每2-4周复诊1次。\n2.用药初期2周内需家属监护，警惕情绪恶化或自伤风险（尤其合并抑郁者）；出现皮疹、胸闷、头晕、性功能障碍等不良反应及时就诊。\n3.起效后（约4-8周）复诊评估疗效并根据患者具体情况制定个体化方案调整剂量；症状完全缓解后继续巩固治疗至少6-12个月，停药患者医生指导下缓慢减量（4-8周渐减），切勿自行停药以防撤药综合征或复发。\n4.妊娠期、哺乳期及拟生育者复诊时告知医生以调整方案；合并心血管病、癫痫等躯体疾病者需专科随诊评估用药安全性。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":353,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0ec4b04c1869d234109311845ec5da7f055d201077e0b4f7f2a5e68caaf39a3b","pinyin":"jiaolvzheng","initials":"jlz","setting":"out","caseName":"门诊病历218","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历218",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-93d3fb5dd059001eb062","key":"v1-c9ccc21dfe2a3058|templates-93d3fb5dd059001eb062","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"抑郁症","category":"门诊病历模板","raw":{"name":"抑郁症","category":"门诊病历模板","case":{"case_name":"门诊病历219","templates":{"主诉":"反复眩晕伴失眠1周。","现病史":"患者1周前受凉后出现抑郁症相关症状，呈搏动性，劳累后加重，休息后稍缓解，伴恶心，无呕吐，无肢体活动障碍。自服「布洛芬」可暂时缓解，今日再次发作，来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。神经系统检查：生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、肝肾功能、甲状腺功能、血糖、电解质\n\n【影像学检查】\n心电图、头颅CT/MRI（排除器质性病变）\n\n【其他检查】\n心理评估量表（PHQ-9、GAD-7、PANSS等）、药物浓度监测\n","初步诊断":"1. 抑郁症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. SSRIs类抗抑郁药（一线首选）：艾司西酞普兰片10mg qd晨服，起始剂量5mg qd×1周，逐渐增至10mg qd，必要时可加至20mg qd，足量足疗程（≥6-8周）后评估疗效，有效者维持治疗6-12个月。\n2. SSRIs类替代：舍曲林片50mg qd口服，1-2周后渐增至100mg qd，最大剂量200mg qd，疗程同前（至少6-8周起效评估，缓解后维持6-12个月），注意餐后服药减轻胃肠道反应。\n3. 伴明显失眠或焦虑者：短期联用苯二氮䓬类，如艾司唑仑片1mg qn睡前口服，疗程不超过4周，症状缓解后渐减停，避免长期依赖。\n4. 足量足疗程（4-6周）疗效不佳者：复诊评估后调整方案，可换用SNRIs类如文拉法辛缓释胶囊75mg qd口服（最大225mg qd），或遵医嘱联合用药；禁止自行加量、减量或突然停药。\n【一般治疗及生活指导】\n1. 规律作息：保证每晚7-8小时睡眠，避免熬夜及昼夜颠倒；每日白天进行户外活动，散步、慢跑等有氧运动每周3-5次、每次30分钟，有助于改善情绪。\n2. 均衡饮食：保证优质蛋白、B族维生素及新鲜蔬果摄入，避免高糖高脂饮食；戒烟限酒，下午及夜间避免咖啡、浓茶等刺激性饮品。\n3. 坚持规律服药，不得自行停药或减量；治疗初期（尤其伴嗜睡、乏力时）避免驾驶、高空作业及精密操作等危险活动。\n4. 加强家庭支持与陪伴，鼓励参加社交活动；密切观察情绪与行为，若出现消极观念加重、自伤自杀言行或冲动行为，立即就近就医或拨打心理援助热线。\n【随诊要求】\n1. 首次用药后2-4周复诊，评估疗效及不良反应（恶心、头晕、嗜睡、口干、性功能障碍等），由医师调整剂量；急性期每1-2周复诊1次。\n2. 病情稳定后每4-8周复诊1次，定期评估抑郁症状量表（如PHQ-9/HAMD）及药物依从性；全程治疗至少6-12个月，复发者建议维持治疗2年以上。\n3. 停药必医师指导下缓慢减量（数周至数月），禁止突然停药以防撤药反应；若出现情绪低落、兴趣减退、睡眠食欲改变等复发迹象，及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":354,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"68a16cae42b49d2b0cc0792f9cdeb16461198fc80e7ee91d05629332a1771e6e","pinyin":"yiyuzheng","initials":"yyz","setting":"out","caseName":"门诊病历219","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历219",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bee63734f4728b1d352d","key":"v1-c9ccc21dfe2a3058|templates-bee63734f4728b1d352d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"强迫症","category":"门诊病历模板","raw":{"name":"强迫症","category":"门诊病历模板","case":{"case_name":"门诊病历220","templates":{"主诉":"反复眩晕伴失眠1周。","现病史":"患者1周前无明显诱因出现强迫症相关症状，呈搏动性，劳累后加重，休息后稍缓解，伴恶心，无呕吐，无肢体活动障碍。自服「布洛芬」可暂时缓解，今日再次发作，来诊。发病以来精神可，饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清。心率80次/分，律齐。腹平软，无压痛。神经系统检查：生理反射存在，病理反射未引出。生理反射存在，病理反射未引出。","辅助检查":"【必做检查】\n血常规、肝肾功能、甲状腺功能、血糖、电解质\n\n【影像学检查】\n心电图、头颅CT/MRI（排除器质性病变）\n\n【其他检查】\n心理评估量表（PHQ-9、GAD-7、PANSS等）、药物浓度监测\n","初步诊断":"1. 强迫症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 选择性5-羟色胺再摄取抑制剂（SSRIs）：舍曲林片（如左洛复）50mg qd 起始，早餐后口服，1周后渐增至100~200mg/d，分1~2次服用；足量足疗程（至少4周足量、总疗程8~12周）疗效不佳可换用氟西汀20~60mg/d或帕罗西汀20~60mg/d，疗程8~12周。SSRI通常2~4周起效。\n2. 氯米帕明（氯丙咪嗪）25mg qd 起始，渐增至75~150mg/d（最大不超过250mg/d），分2~3次口服，疗程8~12周；适用于SSRI疗效欠佳者，用药前后及疗程中监测心电图（QTc）、血压，注意抗胆碱能及镇静不良反应，禁与SSRI联用。\n3. 增效治疗：SSRI足量足疗程效果不佳时，可联用非典型抗精神病药增效，如阿立哌唑5~10mg qd 或喹硫平25~100mg qn，疗程4~8周后评估，注意监测锥体外系反应、体重及血糖血脂。\n4. 短期辅助：伴显著焦虑、失眠时，可予艾司唑仑1mg qn 或劳拉西泮0.5mg qn 短期（不超过2周）改善睡眠与焦虑，不宜长期使用，避免依赖。\n\n【一般治疗及生活指导】\n1. 心理治疗：认知行为治疗（CBT）及暴露与反应阻止（ERP）为一线心理治疗，建议每周1~2次，与药物联合疗效优于单一治疗。\n2. 生活方式：保持规律作息与充足睡眠，每日进行30分钟左右中等强度有氧运动（快走、慢跑、游泳等）以缓解焦虑；减少咖啡、浓茶、酒精及尼古丁等兴奋性物质的摄入。\n3. 心理调适：学会接纳症状而非对抗，减少反复检查、洗手、计数等强迫行为以阻断强化循环；家人避免过度迁就或指责，可鼓励患者记录症状及诱发情境日记。\n4. 禁忌：禁止自行停药、增减剂量或更换药物；避免过度劳累、熬夜及重大生活应激，工作学习中适当降低对\"完美\"的要求。\n\n【随诊要求】\n1. 开始用药后2~4周复诊，评估疗效、耐受性及不良反应（恶心、失眠、性功能障碍、体重、QT间期等），必要时调整剂量；症状改善后每4~8周复诊1次，总疗程一般需1~2年。\n2. 治疗期间出现自伤、自杀意念或冲动行为，或出现锥体外系反应、明显便秘、心悸、晕厥等，应立即就诊。\n3. 病情稳定后减量或停药必医师指导下缓慢进行，避免骤停引起撤药综合征及症状复发；育龄期女性用药期间避孕，妊娠或备孕前需复诊评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":355,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"48549ee5f59d78451386a5d212ca14a75b3d2d447448181477797c91a93bda5a","pinyin":"qiangpozheng","initials":"qpz","setting":"out","caseName":"门诊病历220","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历220",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);